  BabyRecipe(id: 'b17v00', title: 'Fırında sebzeli mücver', age: '12+', category: 'Fırın', ingredient: 'yumurta', vegetable: 'kabak', ingredients: ['1 orta boy sebze (seçtiğiniz), rendelenmiş', '1 yumurta', '2 yemek kaşığı un', '2 yemek kaşığı ufalanmış lor', '1 yemek kaşığı ince kıyılmış dereotu'], steps: ['Fırını 190 °C\'ye ısıtın; muffin kalıbını yağlayın veya tepsiye kâğıt serin.', 'Rendelenmiş sebzenin suyunu tülbentle iyice sıkın.', 'Tüm malzemeyi karıştırın.', 'Karışımı kalıplara veya kaşıkla tepsiye yassı yuvarlaklar hâlinde paylaştırın.', '20–22 dakika, üzeri kızarıp ortası sertleşene kadar pişirin; ılıtıp verin.'], variants: ['kabak', 'havuç', 'patates'], tips: ['Kızartma yerine fırın kullanmak yağ oranını azaltır.'], storage: 'Buzdolabında 48 saat; dondurulabilir.'),
  BabyRecipe(id: 'b18v00', title: 'Sebzeli omlet', age: '12+', category: 'Yumurta', ingredient: 'yumurta', vegetable: 'kırmızı biber', ingredients: ['1 yumurta', '1 yemek kaşığı süt', '2 yemek kaşığı ince doğranmış sebze (seçtiğiniz)', '1 çay kaşığı tereyağı'], steps: ['Tereyağını tavada eritip sebzeyi 3–4 dakika yumuşatın.', 'Yumurtayı sütle çırpıp tavaya dökün.', 'Kapağı kapatıp kısık ateşte 3–4 dakika, üst yüzey tamamen katılaşana kadar pişirin.', 'Ters çevirip 1 dakika daha pişirin, ılıyınca şeritler hâlinde kesin.', 'Yumurtayı akı ve sarısı tamamen katılaşana kadar pişirin; akışkan bırakmayın.'], tips: ['Mantarı çok ince doğrayın; kaygan dokusu boğazda takılabilir.'], storage: 'Hemen tüketin.'),
  BabyRecipe(id: 'b19v00', title: 'Meyveli yoğurt kasesi', age: '12+', category: 'Yoğurt', ingredient: 'yoğurt', vegetable: 'muz', ingredients: ['4 yemek kaşığı tam yağlı sade yoğurt', '3 yemek kaşığı ezilmiş veya küçük doğranmış meyve (seçtiğiniz)', '1 yemek kaşığı ince yulaf ezmesi', '1 tutam tarçın (isteğe bağlı)'], steps: ['Meyveyi yıkayın; muz ve armudu çatalla ezin, çileği ve şeftaliyi küçük parçalara bölün.', 'Yaban mersinlerini ikiye veya dörde bölün.', 'Yoğurdu kaseye alın, meyveyi ve yulafı ekleyin.', 'Tarçın serpip hemen servis edin.', 'Hemen servis edin; kalanını saklamayın.'], tips: ['Yuvarlak küçük meyveleri (yaban mersini, üzüm) daima bölerek verin.', 'Bal eklemeyin; 12 aydan sonra bile şekersiz alışkanlık önerilir.'], storage: 'Hemen tüketin.'),
  BabyRecipe(id: 'b20v00', title: 'Patatesli sebze ezmesi', age: '8+', category: 'Sebze', ingredient: 'patates', vegetable: 'brokoli', ingredients: ['1 orta boy patates', 'Yarım su bardağı sebze (seçtiğiniz)', '1 çay kaşığı tereyağı', '2 yemek kaşığı süt veya anne sütü/mama'], steps: ['Patatesi soyup küp küp doğrayın, 10 dakika haşlayın.', 'Sebzeyi ekleyip 8 dakika daha, ikisi de yumuşayana kadar pişirin.', 'Süzün, tereyağı ve sütle birlikte çatalla ezin.', 'Yaşa göre hafif taneli ya da pürüzsüz bırakıp ılık verin.', 'Ilıtıp sıcaklığı bileğinizin iç kısmına damlatarak kontrol edin; ılık olmalı, sıcak değil.'], tips: ['12 aydan önce inek sütünü içecek olarak vermeyin; yemeklerde az miktarda kullanılabilir.'], storage: 'Buzdolabında 24 saat.'),
  BabyRecipe(id: 'b21v00', title: 'Sebzeli irmik lapası', age: '9+', category: 'Tahıl', ingredient: 'irmik', vegetable: 'havuç', ingredients: ['1 yemek kaşığı irmik', '2 yemek kaşığı rendelenmiş sebze (seçtiğiniz)', '1 su bardağı içme suyu', '1 çay kaşığı tereyağı'], steps: ['Sebzeyi suyla 7–8 dakika yumuşayana kadar pişirin.', 'İrmiği yağmur gibi serperek ve sürekli karıştırarak ekleyin.', 'Topaklanmaması için karıştırmaya devam ederek 4–5 dakika koyulaşana kadar pişirin.', 'Tereyağını ekleyip ılıtın.', 'Ilıtıp sıcaklığı bileğinizin iç kısmına damlatarak kontrol edin; ılık olmalı, sıcak değil.'], tips: ['İrmik buğdaydan yapılır, gluten içerir.'], storage: 'Hemen tüketin; bekleyince sertleşir.'),
  BabyRecipe(id: 'b22v00', title: 'Sebzeli kuskus', age: '12+', category: 'Tahıl', ingredient: 'kuskus', vegetable: 'kabak', ingredients: ['3 yemek kaşığı kuskus', 'Yarım su bardağı ince doğranmış sebze (seçtiğiniz)', 'Yarım su bardağı sıcak su', '1 tatlı kaşığı zeytinyağı'], steps: ['Zeytinyağında sebzeyi 5–6 dakika yumuşayana kadar soteleyin.', 'Kuskusu ekleyip 1 dakika çevirin.', 'Sıcak suyu ilave edin, kapağı kapatıp ocağı kapatın.', '10 dakika demlendirin, çatalla taneleri ayırın ve ılık servis edin.', 'Kalanını kapalı kapta buzdolabında 2 gün saklayın; yalnızca bir kez ısıtın.'], tips: ['Kuskus buğday içerir.'], storage: 'Buzdolabında 24 saat.'),
  BabyRecipe(id: 'b23v00', title: 'Sebzeli kinoa', age: '10+', category: 'Tahıl', ingredient: 'kinoa', vegetable: 'kabak', ingredients: ['2 yemek kaşığı kinoa', 'Yarım su bardağı ince doğranmış sebze (seçtiğiniz)', '1 su bardağı içme suyu', '1 çay kaşığı zeytinyağı'], steps: ['Kinoayı acılığını gidermek için ince süzgeçte bol suyla ovarak yıkayın.', 'Kinoa ve suyu tencereye alın, kaynayınca kısık ateşte 10 dakika pişirin.', 'Sebzeyi ekleyip 8–10 dakika daha, su çekilip taneler yumuşayana kadar pişirin.', 'Zeytinyağını ekleyin, yaşa göre ezin.', 'Kalanını kapalı kapta buzdolabında 2 gün saklayın; yalnızca bir kez ısıtın.'], tips: ['Kinoa glutensizdir; çeşitlendirme için iyi bir tahıl alternatifidir.'], storage: 'Buzdolabında 48 saat.'),
  BabyRecipe(id: 'b24v00', title: 'Tavuklu sebze çorbası', age: '9+', category: 'Çorba', ingredient: 'tavuk', vegetable: 'havuç', ingredients: ['50 g tavuk göğsü veya but', '1 küçük patates', 'Yarım su bardağı doğranmış sebze (seçtiğiniz)', '1 tatlı kaşığı pirinç veya arpa şehriye', '2 su bardağı içme suyu'], steps: ['Tavuğu suyla haşlayın; kaynayınca köpüğünü alın ve 20 dakika pişirin.', 'Tavuğu çıkarıp ince ince didikleyin.', 'Suya patates, sebze ve pirinci ekleyip 20 dakika pişirin.', 'Tavuğu geri ekleyin; yaşa göre blenderdan geçirin veya parçalı bırakın.', 'Ilıtarak servis edin.'], variants: ['havuç', 'kabak', 'patates', 'kereviz', 'balkabağı'], tips: ['Çorbayı bebeğe vermeden önce bileğinizin iç kısmında sıcaklığını kontrol edin.'], storage: 'Buzdolabında 24 saat; 1 ay dondurulabilir.'),
  BabyRecipe(id: 'b25v00', title: 'Kırmızı mercimek çorbası', age: '8+', category: 'Çorba', ingredient: 'kırmızı mercimek', vegetable: 'havuç', ingredients: ['3 yemek kaşığı kırmızı mercimek', '1 küçük sebze (seçtiğiniz)', '1 yemek kaşığı ince kıyılmış soğan', '2 su bardağı içme suyu', '1 çay kaşığı tereyağı'], steps: ['Mercimeği yıkayıp süzün; sebzeyi küçük doğrayın.', 'Tereyağında soğanı 2 dakika yumuşatın.', 'Mercimek, sebze ve suyu ekleyip kaynayınca kısık ateşte 25 dakika pişirin.', 'Blenderdan geçirip kıvamını kaynamış suyla ayarlayın.', 'Ilık servis edin.'], variants: ['havuç', 'kabak', 'balkabağı', 'patates'], tips: ['Bir yaşından büyük çocuklarda servis ederken birkaç damla limon ekleyebilirsiniz.'], storage: 'Buzdolabında 48 saat; dondurulabilir.'),
  BabyRecipe(id: 'b26v00', title: 'Sebzeli yumurta muffin', age: '12+', category: 'Fırın', ingredient: 'yumurta', vegetable: 'ıspanak', ingredients: ['2 yumurta', '3 yemek kaşığı çok ince doğranmış sebze (seçtiğiniz)', '2 yemek kaşığı lor peyniri', '1 yemek kaşığı süt'], steps: ['Fırını 180 °C\'ye ısıtın; 6\'lı mini muffin kalıbını yağlayın.', 'Yumurtaları sütle çırpın; sebze ve loru ekleyin.', 'Karışımı kalıplara üçte iki oranında doldurun.', '15–18 dakika, kürdan batırınca temiz çıkana kadar pişirin.', 'Kalıpta 5 dakika bekletip çıkarın, ılık verin.'], variants: ['ıspanak', 'kabak', 'kırmızı biber', 'brokoli'], tips: ['Parmak yiyecek olarak bebeğin kendi kendine yemesini destekler.'], storage: 'Buzdolabında 48 saat; dondurulabilir.'),
  BabyRecipe(id: 'b27v00', title: 'Sebzeli erişte', age: '12+', category: 'Makarna', ingredient: 'erişte', vegetable: 'havuç', ingredients: ['Yarım su bardağı ev yapımı veya hazır erişte', 'Yarım su bardağı ince doğranmış sebze (seçtiğiniz)', '1 tatlı kaşığı tereyağı', '1 yemek kaşığı süzme yoğurt'], steps: ['Erişteyi tuzsuz suda 10–12 dakika yumuşayana kadar haşlayın.', 'Sebzeyi tereyağında kapağı kapalı 6–7 dakika pişirin.', 'Süzülmüş erişteyi sebzeyle karıştırın.', 'Ilıyınca yoğurtla servis edin; uzun erişteleri küçük parçalara kesin.', 'Kalanını kapalı kapta buzdolabında 2 gün saklayın; yalnızca bir kez ısıtın.'], tips: ['Uzun makarnaları kesmek boğulma riskini azaltır.'], storage: 'Buzdolabında 24 saat.'),
  BabyRecipe(id: 'b28v00', title: 'Fırında sebzeli tavuk köftesi', age: '12+', category: 'Et', ingredient: 'tavuk kıyma', vegetable: 'havuç', ingredients: ['100 g tavuk kıyması', '3 yemek kaşığı ince rendelenmiş sebze (seçtiğiniz), suyu sıkılmış', '2 yemek kaşığı yulaf ezmesi', '1 tatlı kaşığı zeytinyağı', '1 tutam kimyon'], steps: ['Fırını 190 °C\'ye ısıtın.', 'Tüm malzemeyi yoğurup 10 dakika buzdolabında dinlendirin.', 'Islak elle küçük yassı köfteler şekillendirip kâğıt serili tepsiye dizin.', '18–20 dakika, içi tamamen beyazlayana kadar pişirin.', 'Ilıtıp bebeğin tutabileceği büyüklükte servis edin.'], variants: ['havuç', 'kabak', 'brokoli'], tips: ['Tavuk kıymasının içi mutlaka iyice pişmelidir.'], storage: 'Buzdolabında 48 saat; 1 ay dondurulabilir.'),
  BabyRecipe(id: 'b29v00', title: 'Yulaflı sebze köftesi', age: '12+', category: 'Fırın', ingredient: 'yulaf', vegetable: 'havuç', ingredients: ['4 yemek kaşığı yulaf ezmesi', '3 yemek kaşığı rendelenmiş sebze (seçtiğiniz)', '2 yemek kaşığı ezilmiş haşlanmış nohut', '1 yumurta', '1 yemek kaşığı ince kıyılmış maydanoz'], steps: ['Fırını 190 °C\'ye ısıtın.', 'Sebzenin suyunu sıkın, tüm malzemeyle karıştırıp 10 dakika bekletin.', 'Ceviz büyüklüğünde yassı köfteler yapın.', 'Kâğıt serili tepside 20 dakika, iki yüzü hafif kızarana kadar pişirin (10. dakikada çevirin).', 'Ilıtıp servis edin.'], variants: ['havuç', 'kabak', 'tatlı patates'], tips: ['Etsiz günler için iyi bir protein ve lif kaynağıdır.'], storage: 'Buzdolabında 48 saat.'),
  BabyRecipe(id: 'ozgun001', title: 'Avokado ve muz ezmesi', age: '6+', category: 'Meyve', ingredient: 'avokado', vegetable: 'muz', ingredients: ['2 yemek kaşığı olgun avokado', '2 yemek kaşığı olgun muz'], steps: ['Ellerinizi, kesme tahtasını ve kapları sıcak sabunlu suyla yıkayın.', 'Avokado ve muzu soyun; ölçülü miktarları kâseye alın.', 'Çatalla topak kalmayana kadar ezin.', 'Kıvam koyuysa 1 kaşık anne sütü ya da mama ekleyin.', '6–7. aylarda pürüzsüz, 8. aydan sonra çatalla hafif pütürlü bırakın.', 'Tuz, şeker ve bal eklemeyin; 1 yaş altı bebeklere uygun değildir.', 'Hemen servis edin; kalanını saklamayın.']),
  BabyRecipe(id: 'ozgun002', title: 'Armut püresi', age: '6+', category: 'Meyve', ingredient: 'armut', vegetable: 'armut', ingredients: ['1 küçük olgun armut', 'Gerekirse az miktarda içme suyu'], steps: ['Ellerinizi, kesme tahtasını ve kapları sıcak sabunlu suyla yıkayın.', 'Armudu yıkayıp soyun, çekirdek evini çıkarıp küçük doğrayın.', 'Çok olgun ve yumuşaksa pişirmeden ezin; sertse 2–3 kaşık suyla kapağı kapalı 5–6 dakika pişirin.', 'Çatalla kolayca eziliyorsa pişmiştir.', 'Blender ya da çatalla ezin; kıvamı ayarlamak için haşlama suyunu kaşık kaşık ekleyin.', 'Tuz, şeker ve bal eklemeyin; 1 yaş altı bebeklere uygun değildir.', 'Ilıtıp sıcaklığı bileğinizin iç kısmına damlatarak kontrol edin; ılık olmalı, sıcak değil.', 'Kalanını bebeğin ağzı değmemiş kaşıkla ayırıp kapalı kapta buzdolabında 24 saat saklayın; tekrar ısıtmayı bir kez yapın.']),
  BabyRecipe(id: 'ozgun003', title: 'Elmalı yulaf lapası', age: '6+', category: 'Tahıl', ingredient: 'yulaf', vegetable: 'elma', ingredients: ['2 yemek kaşığı ince yulaf', 'Yarım elma', 'İçme suyu'], steps: ['Ellerinizi, kesme tahtasını ve kapları sıcak sabunlu suyla yıkayın.', 'Elmayı soyup çekirdeğini çıkarın ve ince rendeleyin.', 'Yulafı, elmayı ve yaklaşık yarım su bardağı içme suyunu küçük tencereye alın.', 'Kısık ateşte sürekli karıştırarak 5–6 dakika, yulaf iyice yumuşayana kadar pişirin.', 'Blender ya da çatalla ezin; kıvamı ayarlamak için haşlama suyunu kaşık kaşık ekleyin.', 'Tuz, şeker ve bal eklemeyin; 1 yaş altı bebeklere uygun değildir.', 'Ilıtıp sıcaklığı bileğinizin iç kısmına damlatarak kontrol edin; ılık olmalı, sıcak değil.', 'Kalanını bebeğin ağzı değmemiş kaşıkla ayırıp kapalı kapta buzdolabında 24 saat saklayın; tekrar ısıtmayı bir kez yapın.']),
  BabyRecipe(id: 'ozgun006', title: 'İyi pişmiş yumurtalı avokado ezmesi', age: '6+', category: 'Yumurta', ingredient: 'yumurta', vegetable: 'avokado', ingredients: ['1 adet tamamen pişmiş yumurta', '2 yemek kaşığı olgun avokado'], steps: ['Ellerinizi, kesme tahtasını ve kapları sıcak sabunlu suyla yıkayın.', 'Yumurtayı kaynar suya koyup 10 dakika haşlayın.', 'Yumurtayı akı ve sarısı tamamen katılaşana kadar pişirin; akışkan bırakmayın.', 'Soğuk suya alıp kabuğunu soyun.', 'Avokadoyu kaşıkla alıp yumurtayla birlikte çatalla iyice ezin.', 'Kıvam koyuysa anne sütü ya da mamayla inceltin.', 'Yumurta sık görülen bir alerjendir; ilk kez veriyorsanız az miktarla başlayıp 3 gün gözlemleyin.', 'Hemen servis edin; kalanını saklamayın.']),
  BabyRecipe(id: 'ozgun013', title: 'Mercimekli sebze köftesi', age: '9+', category: 'Baklagil', ingredient: 'mercimek', vegetable: 'havuç', ingredients: ['3 yemek kaşığı iyi pişmiş kırmızı mercimek', '2 yemek kaşığı pişmiş havuç', '1 yemek kaşığı ince yulaf'], steps: ['Fırını 180°C’ye ısıtın; tepsiye yağlı kâğıt serin.', 'Ellerinizi, kesme tahtasını ve kapları sıcak sabunlu suyla yıkayın.', 'Mercimek, havuç ve yulafı çatalla iyice ezip karıştırın.', 'Islak elle bebeğin avucuna sığacak küçük yassı köfteler oluşturun.', 'Tepsiye dizip 15 dakika pişirin; çevirip 5 dakika daha pişirin.', 'İçi tamamen ısınmış ve dıştan hafif kurumuş olmalı; sertleşmemeli.', 'Tuz, şeker ve bal eklemeyin; 1 yaş altı bebeklere uygun değildir.', 'Bebek yerken mutlaka yanında, dik oturur durumda olsun; ağzına sığmayacak büyüklükte parçalar verin.', 'Kalanını bebeğin ağzı değmemiş kaşıkla ayırıp kapalı kapta buzdolabında 24 saat saklayın; tekrar ısıtmayı bir kez yapın.']),
  BabyRecipe(id: 'ozgun014', title: 'Yoğurtlu yulaf ve şeftali', age: '9+', category: 'Yoğurt', ingredient: 'yoğurt', vegetable: 'şeftali', ingredients: ['2 yemek kaşığı sade pastörize yoğurt', '2 yemek kaşığı pişmiş yulaf', 'Yarım olgun şeftali'], steps: ['Ellerinizi, kesme tahtasını ve kapları sıcak sabunlu suyla yıkayın.', 'Yulafı suyla küçük tencerede 5–6 dakika iyice yumuşayana kadar pişirip soğutun.', 'Şeftaliyi soyup çekirdeğini çıkarın; çatalla çok iyi ezin.', 'Yoğurdu buzdolabından 10 dakika önce çıkarın; çok soğuk vermeyin.', 'Yulaf, şeftali ve yoğurdu karıştırın.', 'Tuz, şeker ve bal eklemeyin; 1 yaş altı bebeklere uygun değildir.', 'Hemen servis edin; kalanını saklamayın.']),
  BabyRecipe(id: 'ozgun020', title: 'Elmalı tarçınlı yumuşak pankek', age: '12+', category: 'Kahvaltı', ingredient: 'yulaf', vegetable: 'elma', ingredients: ['1 yumurta', '3 yemek kaşığı ince yulaf', 'Yarım rendelenmiş elma', 'İsteğe bağlı çok az tarçın'], steps: ['Ellerinizi, kesme tahtasını ve kapları sıcak sabunlu suyla yıkayın.', 'Elmayı soyup ince rendeleyin.', 'Yumurta, yulaf, elma ve isterseniz tarçını pürüzsüz çırpın; 5 dakika bekletin.', 'Yapışmaz tavayı kısık ateşte ısıtın; kaşıkla küçük pankekler dökün.', 'Altı kızarınca çevirip diğer yüzünü 1–2 dakika pişirin.', 'Bir tanesini ortadan bölün: içinde akışkan yumurta kalmamalı.', 'Yumuşak, çocuğun tutabileceği parçalara bölün.', 'Ilıtıp sıcaklığı bileğinizin iç kısmına damlatarak kontrol edin; ılık olmalı, sıcak değil.', 'Kalanını kapalı kapta buzdolabında 2 gün saklayın; yalnızca bir kez ısıtın.']),
  BabyRecipe(id: 'ab18_01', title: 'Mini sebzeli pizza', age: '18+', category: 'Fırın', ingredient: 'lavaş', vegetable: 'mantar', ingredients: ['1 küçük tam buğday lavaş', '2 yemek kaşığı rendelenmiş domates', '2 yemek kaşığı rendelenmiş az tuzlu kaşar', '2 yemek kaşığı ince doğranmış kırmızı biber ve mantar', '1 tutam kekik'], steps: ['Fırını 200 °C\'ye ısıtın.', 'Lavaştan bardak ağzıyla 4–5 yuvarlak kesin.', 'Üzerlerine domates sürün, sebzeleri ve kaşarı paylaştırın, kekik serpin.', '8–10 dakika, peynir eriyip kenarlar kızarana kadar pişirin.', 'Ilıtıp dilimleyerek verin.'], tips: ['Hazır pizza sosu yerine taze domates kullanmak tuz ve şekeri azaltır.'], storage: 'Aynı gün tüketin.'),
  BabyRecipe(id: 'ab18_02', title: 'Etli taze fasulye', age: '18+', category: 'Et', ingredient: 'dana kuşbaşı', vegetable: 'taze fasulye', ingredients: ['60 g küçük doğranmış dana eti', '1 su bardağı doğranmış taze fasulye', '1 küçük domates, rendelenmiş', '1 yemek kaşığı ince doğranmış soğan', '1 su bardağı sıcak su', '1 tatlı kaşığı zeytinyağı'], steps: ['Zeytinyağında eti kapağı kapalı olarak kendi suyunu çekene kadar 10 dakika pişirin.', 'Soğanı ekleyip 2 dakika, ardından domatesi ekleyip 2 dakika çevirin.', 'Fasulyeyi ve sıcak suyu ekleyin; kısık ateşte 35–40 dakika et ve fasulye yumuşayana kadar pişirin.', 'Eti küçük lifler hâlinde ayırın, fasulyeleri 1 cm boyunda kesin.', 'Tuz eklemeyin; 1–3 yaş için günlük tuz 2 g’ı geçmemeli, peynir ve salça zaten tuz içerir.'], tips: ['Eti düdüklü tencerede pişirmek süreyi kısaltır ve daha yumuşak yapar.'], storage: 'Buzdolabında 48 saat.'),
  BabyRecipe(id: 'ab18_03', title: 'Fırında somon ve patates', age: '18+', category: 'Balık', ingredient: 'somon', vegetable: 'patates', ingredients: ['70 g kılçıksız somon fileto', '1 küçük patates, ince dilimlenmiş', '1 tatlı kaşığı zeytinyağı', 'Birkaç dal dereotu', 'Birkaç damla limon suyu'], steps: ['Fırını 190 °C\'ye ısıtın.', 'Patates dilimlerini zeytinyağıyla harmanlayıp tepsiye dizin, 15 dakika pişirin.', 'Somonu patateslerin yanına yerleştirip dereotu ve limon ekleyin.', '12–15 dakika daha, balık opaklaşıp kolayca dağılana kadar pişirin.', 'Kılçık kontrolü yapıp küçük parçalara ayırın.'], tips: ['Haftada 1–2 kez balık önerilir.'], storage: 'Aynı gün tüketin.'),
  BabyRecipe(id: 'ab18_04', title: 'Ispanaklı lorlu börek parmakları', age: '18+', category: 'Fırın', ingredient: 'yufka', vegetable: 'ıspanak', ingredients: ['1 adet yufka', '1 su bardağı ince kıyılmış ıspanak', '3 yemek kaşığı lor peyniri', '1 yumurta', '3 yemek kaşığı süt', '1 tatlı kaşığı zeytinyağı'], steps: ['Fırını 180 °C\'ye ısıtın.', 'Ispanağı zeytinyağında 3 dakika soldurup soğutun, lorla karıştırın.', 'Yumurta ve sütü çırpın; yufkayı 4 üçgene kesip her birine bu karışımdan sürün.', 'Geniş kenarına iç harcı koyup parmak şeklinde sarın, üstlerine kalan karışımdan sürün.', '20–25 dakika, üzerleri kızarana kadar pişirin; ılıtıp verin.'], tips: ['Lor peyniri tuzu düşük bir seçenektir.'], storage: 'Buzdolabında 48 saat; dondurulabilir.'),
  BabyRecipe(id: 'ab18_05', title: 'Mercimekli bulgur köftesi (yumuşak)', age: '18+', category: 'Baklagil', ingredient: 'kırmızı mercimek', vegetable: 'domates', ingredients: ['3 yemek kaşığı kırmızı mercimek', '2 yemek kaşığı ince bulgur', '1 su bardağı su', '1 tatlı kaşığı domates salçası (az tuzlu)', '1 yemek kaşığı ince kıyılmış taze soğan', '1 yemek kaşığı zeytinyağı', 'Birkaç dal maydanoz'], steps: ['Mercimeği suyla 15 dakika, dağılana kadar pişirin.', 'Ocaktan alıp bulguru ekleyin, kapağı kapalı 20 dakika şişmeye bırakın.', 'Zeytinyağında taze soğan ve salçayı 2 dakika çevirip karışıma ekleyin.', 'Maydanozu ekleyip yoğurun, küçük yumuşak köfteler şekillendirin.', 'Marul yaprağında veya tabakta servis edin.'], tips: ['Acı biber ve isot kullanmayın.'], storage: 'Buzdolabında 48 saat.'),
  BabyRecipe(id: 'ab18_06', title: 'Yoğurtlu tavuk ve sebze sote', age: '18+', category: 'Et', ingredient: 'tavuk', vegetable: 'kabak', ingredients: ['80 g tavuk göğsü, küçük küp', 'Yarım kabak ve yarım havuç, küçük doğranmış', '1 tatlı kaşığı zeytinyağı', '2 yemek kaşığı yoğurt', '1 tutam kekik'], steps: ['Zeytinyağında tavuğu 6–7 dakika her yüzü beyazlayana kadar pişirin.', 'Sebzeleri ekleyip kapağı kapalı 10 dakika yumuşatın; gerekirse 2 kaşık su ekleyin.', 'Tavuğun içi tamamen pişince ocaktan alın.', 'Ilıyınca yoğurt ve kekikle servis edin.', 'Tavuk iç sıcaklığı 74°C olmalı; en büyük parçayı bölüp pembe kalmadığını kontrol edin.'], tips: ['Yoğurdu sıcak yemeğe eklemeyin, kesilir.'], storage: 'Yoğurtsuz hâli buzdolabında 24 saat.'),
  BabyRecipe(id: 'ab18_07', title: 'Muzlu yulaf pankek', age: '18+', category: 'Kahvaltı', ingredient: 'yulaf', vegetable: 'muz', ingredients: ['1 olgun muz', '1 yumurta', '4 yemek kaşığı ince yulaf ezmesi', '1 tutam tarçın', '1 çay kaşığı tereyağı'], steps: ['Muzu çatalla iyice ezin; yumurta, yulaf ve tarçınla karıştırın.', 'Karışımı 5 dakika dinlendirin.', 'Yapışmaz tavayı tereyağıyla hafifçe yağlayıp yemek kaşığıyla küçük yuvarlaklar dökün.', 'Kısık ateşte her yüzünü 2 dakika, ortası pişene kadar pişirin.', 'Ilıtıp servis edin.'], tips: ['Muzun tatlılığı yeterlidir; şeker veya bal eklemeyin.'], storage: 'Buzdolabında 24 saat; dondurulabilir.'),
  BabyRecipe(id: 'ab18_08', title: 'Sebzeli tavuk pilavı', age: '18+', category: 'Tahıl', ingredient: 'pirinç', vegetable: 'bezelye', ingredients: ['3 yemek kaşığı pirinç', '50 g haşlanmış ve didiklenmiş tavuk', '2 yemek kaşığı bezelye', '2 yemek kaşığı küçük doğranmış havuç', '1 su bardağı tavuk haşlama suyu', '1 tatlı kaşığı tereyağı'], steps: ['Pirinci 20 dakika ılık suda bekletip süzün.', 'Tereyağında havuç ve bezelyeyi 3 dakika çevirin.', 'Pirinci ekleyip 1 dakika kavurun; sıcak haşlama suyunu ilave edin.', 'Kısık ateşte 15 dakika suyunu çekene kadar pişirin, tavuğu ekleyip 10 dakika demlendirin.', 'Yuvarlak ve sert parçaları (bezelye, nohut, üzüm gibi) ezin ya da dörde bölün.'], tips: ['Bezelyeleri hafifçe ezerek boğulma riskini azaltın.'], storage: 'Hızla soğutup buzdolabında 24 saat.'),
  BabyRecipe(id: 'ab18_09', title: 'Fırında sebzeli patates kroket', age: '18+', category: 'Fırın', ingredient: 'patates', vegetable: 'havuç', ingredients: ['2 orta boy haşlanmış patates', '2 yemek kaşığı rendelenmiş havuç', '2 yemek kaşığı rendelenmiş kaşar', '1 yumurta sarısı', '3 yemek kaşığı galeta unu'], steps: ['Fırını 200 °C\'ye ısıtın.', 'Patatesleri ezin; havuç, kaşar ve yumurta sarısıyla karıştırın.', 'Karışımdan parmak kalınlığında kroketler yapıp galeta ununa bulayın.', 'Kâğıt serili tepside 20 dakika, yarısında çevirerek altın rengi olana kadar pişirin.', 'Buz kalıplarında dondurup 1 ay saklayabilirsiniz; buzdolabında çözdürüp bir kez ısıtın.'], tips: ['Kızartmak yerine fırınlamak daha hafif bir seçenektir.'], storage: 'Buzdolabında 48 saat.'),
  BabyRecipe(id: 'ab18_10', title: 'Elmalı tarçınlı sütlaç', age: '18+', category: 'Tatlı', ingredient: 'pirinç', vegetable: 'elma', ingredients: ['2 yemek kaşığı pirinç', '1,5 su bardağı süt', 'Yarım su bardağı su', '1 küçük elma, rendelenmiş', '1 tutam tarçın'], steps: ['Pirinci suyla 15 dakika yumuşayana kadar pişirin.', 'Sütü ve rendelenmiş elmayı ekleyin.', 'Kısık ateşte sürekli karıştırarak 15–20 dakika koyulaşana kadar pişirin.', 'Kaselere paylaştırıp soğutun, servis ederken tarçın serpin.', 'Şeker eklemeyin; tatlılığı olgun meyveden gelsin.'], tips: ['Elma tatlılık sağlar; şeker eklemenize gerek yoktur.'], storage: 'Buzdolabında 48 saat.'),
  BabyRecipe(id: 'ab24_01', title: 'Kıymalı ıspanak yemeği', age: '24+', category: 'Et', ingredient: 'dana kıyma', vegetable: 'ıspanak', ingredients: ['60 g az yağlı dana kıyma', '2 su bardağı doğranmış ıspanak', '1 yemek kaşığı pirinç', '1 yemek kaşığı ince doğranmış soğan', '1 tatlı kaşığı domates salçası', 'Yarım su bardağı sıcak su', '1 tatlı kaşığı zeytinyağı'], steps: ['Zeytinyağında soğanı 2 dakika, ardından kıymayı ezerek 5 dakika kavurun.', 'Salçayı ekleyip 1 dakika çevirin.', 'Ispanak, pirinç ve sıcak suyu ekleyin; kapağı kapalı kısık ateşte 20 dakika pişirin.', 'Yoğurtla birlikte servis edin.', 'Kıymada pembe kalmadığını kontrol edin.'], tips: ['Ispanağı birkaç suda iyice yıkayarak toprağını giderin.'], storage: 'Buzdolabında 24 saat.'),
  BabyRecipe(id: 'ab24_02', title: 'Tavuk şiş (fırında)', age: '24+', category: 'Et', ingredient: 'tavuk göğsü', vegetable: 'kırmızı biber', ingredients: ['100 g tavuk göğsü, 2 cm küpler', '2 yemek kaşığı yoğurt', '1 tatlı kaşığı zeytinyağı', '1 tutam kekik ve tatlı toz biber', 'Yarım kırmızı biber, iri doğranmış'], steps: ['Tavuğu yoğurt, zeytinyağı ve baharatla karıştırıp en az 30 dakika buzdolabında bekletin.', 'Fırını 200 °C\'ye ısıtın.', 'Tavuk ve biberi tepsiye dizin (çocuklar için şiş çubuğu kullanmayın).', '18–20 dakika, tavuğun içi tamamen beyazlayana kadar pişirin.', 'Küçük parçalara bölerek bulgur pilavı ile servis edin.'], tips: ['Sivri şiş çubukları çocuk tabağına koymayın.'], storage: 'Buzdolabında 48 saat.'),
  BabyRecipe(id: 'ab24_03', title: 'Zeytinyağlı barbunya', age: '24+', category: 'Baklagil', ingredient: 'barbunya', vegetable: 'havuç', ingredients: ['Yarım su bardağı haşlanmış barbunya', '1 küçük havuç, küp doğranmış', '1 küçük patates, küp doğranmış', '1 yemek kaşığı ince doğranmış soğan', '1 küçük domates, rendelenmiş', '1 yemek kaşığı zeytinyağı', '1 su bardağı sıcak su'], steps: ['Zeytinyağında soğanı 3 dakika yumuşatın.', 'Havuç ve patatesi ekleyip 3 dakika çevirin, ardından domatesi ilave edin.', 'Barbunya ve sıcak suyu ekleyin; kısık ateşte 25 dakika pişirin.', 'Tencerede ılımaya bırakın, ılık veya oda sıcaklığında servis edin.', 'Kuru baklagiller bebeklerde gaz yapabilir; ilk kez veriyorsanız az porsiyonla başlayın.'], tips: ['Zeytinyağlılar dinlenince daha lezzetli olur.'], storage: 'Buzdolabında 3 gün.'),
  BabyRecipe(id: 'ab24_04', title: 'Fırında sebzeli makarna', age: '24+', category: 'Makarna', ingredient: 'makarna', vegetable: 'brokoli', ingredients: ['Yarım su bardağı kısa makarna (burgu, kalem)', 'Yarım su bardağı küçük brokoli çiçekleri', '1 su bardağı süt', '1 yemek kaşığı tereyağı', '1 yemek kaşığı un', '3 yemek kaşığı rendelenmiş kaşar'], steps: ['Fırını 190 °C\'ye ısıtın. Makarnayı haşlayın, son 3 dakikada brokoliyi ekleyip birlikte süzün.', 'Tereyağında unu 1 dakika kavurun, sütü azar azar ekleyip koyulaşana kadar karıştırarak beşamel yapın.', 'Makarna ve brokoliyi beşamelle karıştırıp küçük fırın kabına alın.', 'Üzerine kaşar serpip 15 dakika, peynir kızarana kadar pişirin.', 'Biraz ılıtıp servis edin.'], tips: ['Beşamel topaklanırsa telle çırpın.'], storage: 'Buzdolabında 48 saat.'),
  BabyRecipe(id: 'ab24_05', title: 'Sebzeli mercimek köftesi parmakları', age: '24+', category: 'Baklagil', ingredient: 'yeşil mercimek', vegetable: 'havuç', ingredients: ['Yarım su bardağı haşlanmış yeşil mercimek', '3 yemek kaşığı rendelenmiş havuç', '3 yemek kaşığı yulaf ezmesi', '1 yumurta', '1 tutam kimyon', '1 yemek kaşığı ince kıyılmış maydanoz'], steps: ['Fırını 190 °C\'ye ısıtın.', 'Mercimeği çatalla kabaca ezin, diğer malzemeleri ekleyip yoğurun.', 'Karışımdan parmak şeklinde köfteler yapın.', 'Kâğıt serili tepside 20 dakika, yarısında çevirerek pişirin.', 'Yoğurtlu sos ile servis edin.'], tips: ['Çocuğun kendi kendine yemesini destekleyen parmak yiyeceklerdendir.'], storage: 'Buzdolabında 48 saat; dondurulabilir.'),
  BabyRecipe(id: 'ab24_06', title: 'Ev yapımı sebze çorbası (parçalı)', age: '24+', category: 'Çorba', ingredient: 'şehriye', vegetable: 'havuç', ingredients: ['1 küçük havuç', '1 küçük patates', 'Yarım kabak', '1 yemek kaşığı tel şehriye', '1 yemek kaşığı ince doğranmış soğan', '2,5 su bardağı sıcak su', '1 tatlı kaşığı tereyağı'], steps: ['Sebzeleri 1 cm küpler hâlinde doğrayın.', 'Tereyağında soğanı yumuşatıp sebzeleri ekleyin, 3 dakika çevirin.', 'Sıcak suyu ekleyip 15 dakika pişirin.', 'Şehriyeyi ekleyip 8 dakika daha pişirin.', 'Ilıtarak, parçalı şekilde servis edin.'], tips: ['Bu yaşta çorbayı blenderdan geçirmek yerine küçük parçalı vermek çiğnemeyi destekler.'], storage: 'Buzdolabında 48 saat.'),
  BabyRecipe(id: 'ab24_07', title: 'Peynirli omlet rulo', age: '24+', category: 'Kahvaltı', ingredient: 'yumurta', vegetable: 'domates', ingredients: ['2 yumurta', '2 yemek kaşığı süt', '2 yemek kaşığı lor veya beyaz peynir (tuzu alınmış)', '1 yemek kaşığı ince kıyılmış maydanoz', '1 çay kaşığı tereyağı'], steps: ['Yumurta ve sütü çırpın.', 'Geniş tavada tereyağını eritip yumurtayı ince bir tabaka hâlinde dökün.', 'Kapağı kapalı kısık ateşte üstü katılaşana kadar 3–4 dakika pişirin.', 'Peynir ve maydanozu serpip rulo şeklinde sarın, dilimleyerek domates dilimleriyle servis edin.', 'Yumurtayı akı ve sarısı tamamen katılaşana kadar pişirin; akışkan bırakmayın.'], tips: ['Beyaz peyniri 1 saat suda bekleterek tuzunu azaltın.'], storage: 'Hemen tüketin.'),
  BabyRecipe(id: 'ab24_08', title: 'Elmalı havuçlu muffin', age: '24+', category: 'Tatlı', ingredient: 'tam buğday unu', vegetable: 'elma', ingredients: ['1 su bardağı tam buğday unu', '1 çay kaşığı kabartma tozu', '1 olgun muz, ezilmiş', '1 küçük elma ve 1 küçük havuç, rendelenmiş', '1 yumurta', '3 yemek kaşığı zeytinyağı', '1 tatlı kaşığı tarçın'], steps: ['Fırını 180 °C\'ye ısıtın; muffin kalıbına kâğıt kapsüller yerleştirin.', 'Muz, yumurta ve zeytinyağını çırpın.', 'Elma ve havucu ekleyin; un, kabartma tozu ve tarçını eleyerek karıştırın.', 'Kalıpları üçte iki doldurup 20–22 dakika, kürdan temiz çıkana kadar pişirin.', 'Tel ızgarada soğutun.'], tips: ['Şeker yerine olgun muz tatlılık verir.'], storage: 'Hava almayan kapta 2 gün; dondurulabilir.'),
  BabyRecipe(id: 'ab24_09', title: 'Fırında balık köftesi', age: '24+', category: 'Balık', ingredient: 'levrek', vegetable: 'patates', ingredients: ['100 g kılçıksız levrek veya mezgit', '1 haşlanmış patates', '1 yemek kaşığı ince kıyılmış dereotu', '1 yumurta sarısı', '2 yemek kaşığı galeta unu'], steps: ['Fırını 200 °C\'ye ısıtın. Balığı 8 dakika buharda pişirip kılçık kontrolü yapın.', 'Balığı ve patatesi ezin; dereotu ve yumurta sarısını ekleyin.', 'Küçük köfteler şekillendirip galeta ununa bulayın.', 'Kâğıt serili tepside 15–18 dakika kızarana kadar pişirin.', 'Balığı parmaklarınızla yoklayarak tüm kılçıkları ayıklayın; et opaklaşıp kolayca dağılıyorsa pişmiştir.'], tips: ['Kılçık kontrolünü iki kez yapın.'], storage: 'Aynı gün tüketin.'),
  BabyRecipe(id: 'ab24_10', title: 'Yoğurtlu meyve dondurması (şekersiz)', age: '24+', category: 'Tatlı', ingredient: 'yoğurt', vegetable: 'çilek', ingredients: ['1 su bardağı süzme yoğurt', '1 su bardağı dondurulmuş çilek veya şeftali', '1 olgun muz'], steps: ['Tüm malzemeyi blenderda pürüzsüz olana kadar çekin.', 'Karışımı buzluk kalıplarına veya küçük kaplara paylaştırın.', 'En az 4 saat dondurucuda bekletin.', 'Servis etmeden 5 dakika önce çıkarın.', 'Çözülen dondurmayı yeniden dondurmayın.'], tips: ['Sıcak havalarda diş çıkaran çocuklar için de rahatlatıcıdır.'], storage: 'Dondurucuda 1 ay.'),
  BabyRecipe(id: 'ab36_01', title: 'Ev yapımı tavuk nugget (fırında)', age: '36+', category: 'Et', ingredient: 'tavuk göğsü', vegetable: 'mısır gevreği', ingredients: ['200 g tavuk göğsü, parmak büyüklüğünde', '3 yemek kaşığı yoğurt', '1 su bardağı ezilmiş şekersiz mısır gevreği', '2 yemek kaşığı rendelenmiş kaşar', '1 tutam kekik ve tatlı toz biber'], steps: ['Tavuğu yoğurtla karıştırıp 30 dakika buzdolabında bekletin.', 'Fırını 200 °C\'ye ısıtın; mısır gevreği, kaşar ve baharatı karıştırın.', 'Tavuk parçalarını bu karışıma iyice bulayın, kâğıt serili tepsiye dizin.', '18–20 dakika, yarısında çevirerek içi tamamen pişene kadar pişirin.', 'Yoğurtlu dereotlu sosla servis edin.'], tips: ['Paneyi çocukla birlikte yapmak yemeğe ilgisini artırır.'], storage: 'Buzdolabında 48 saat; pişmeden dondurulabilir.'),
  BabyRecipe(id: 'ab36_02', title: 'Sebzeli pide', age: '36+', category: 'Fırın', ingredient: 'un', vegetable: 'kırmızı biber', ingredients: ['1 su bardağı un', 'Yarım çay kaşığı instant maya', 'Yarım su bardağı ılık su', '1 yemek kaşığı zeytinyağı', '3 yemek kaşığı rendelenmiş kaşar', '3 yemek kaşığı ince doğranmış kırmızı biber, mantar ve domates'], steps: ['Un, maya, su ve zeytinyağını yoğurup üzerini örterek 40 dakika mayalandırın.', 'Fırını 220 °C\'ye ısıtın; hamuru 2 parçaya bölüp kayık şeklinde açın.', 'Ortasına sebze ve kaşarı paylaştırıp kenarlarını kıvırın.', '12–15 dakika, kenarlar kızarana kadar pişirin.', 'Dilimleyerek servis edin.'], tips: ['Çocuğun kendi pidesini süslemesine izin verin.'], storage: 'Aynı gün tüketin.'),
  BabyRecipe(id: 'ab36_03', title: 'Kıymalı patates oturtma', age: '36+', category: 'Et', ingredient: 'dana kıyma', vegetable: 'patates', ingredients: ['100 g az yağlı dana kıyma', '2 orta boy patates, halka dilimlenmiş', '1 küçük soğan, ince doğranmış', '1 domates, rendelenmiş', '1 tatlı kaşığı domates salçası', '1 su bardağı sıcak su', '1 yemek kaşığı zeytinyağı'], steps: ['Fırını 190 °C\'ye ısıtın; patatesleri zeytinyağıyla harmanlayıp 15 dakika fırınlayın.', 'Soğanı ve kıymayı kavurun, salça ve domatesi ekleyip 5 dakika pişirin.', 'Patatesleri fırın kabına dizin, kıymalı harcı üzerine yayın.', 'Sıcak suyu ekleyip üzerini kapatarak 25 dakika pişirin.', 'Yoğurtla servis edin.'], tips: ['Az tuz kullanın; çocuklar için günlük tuz sınırı yetişkinlerden düşüktür.'], storage: 'Buzdolabında 48 saat.'),
  BabyRecipe(id: 'ab36_04', title: 'Zeytinyağlı pırasa', age: '36+', category: 'Sebze', ingredient: 'pırasa', vegetable: 'havuç', ingredients: ['2 pırasa (beyaz ve açık yeşil kısımları)', '1 havuç', '1 yemek kaşığı pirinç', '2 yemek kaşığı zeytinyağı', '1 su bardağı sıcak su', 'Birkaç damla limon suyu'], steps: ['Pırasaları ikiye yarıp aralarını bol suda yıkayın, 2 cm halkalar hâlinde doğrayın.', 'Zeytinyağında havucu 2 dakika, pırasayı 5 dakika çevirin.', 'Pirinci ve sıcak suyu ekleyip kapağı kapalı kısık ateşte 25 dakika pişirin.', 'Limon suyunu ekleyip tencerede soğumaya bırakın.', 'Tuz eklemeyin ya da çok az ekleyin; 1–3 yaşta günlük tuz 2 g’ı, 4–6 yaşta 3 g’ı geçmemeli.'], tips: ['Çocuklara yeni sebzeleri tanıdık bir yiyecek yanında sunun.'], storage: 'Buzdolabında 3 gün.'),
  BabyRecipe(id: 'ab36_05', title: 'Fırında köfte ve sebze tepsisi', age: '36+', category: 'Et', ingredient: 'dana kıyma', vegetable: 'kabak', ingredients: ['150 g dana kıyma', '2 yemek kaşığı galeta unu', '1 yemek kaşığı rendelenmiş soğan', '1 tutam kimyon', '1 kabak, 1 havuç ve 1 patates, iri doğranmış', '1 yemek kaşığı zeytinyağı'], steps: ['Fırını 200 °C\'ye ısıtın.', 'Kıyma, galeta unu, soğan ve kimyonu yoğurup küçük köfteler yapın.', 'Sebzeleri zeytinyağıyla harmanlayıp tepsiye yayın, 15 dakika pişirin.', 'Köfteleri sebzelerin arasına yerleştirip 20 dakika daha, içleri pişene kadar pişirin.', 'Köfte iç sıcaklığı 71°C olmalı; bir köfteyi ortadan bölün: içi pembe kalmamalı, suyu berrak akmalı.'], tips: ['Tek tepside pişen yemekler yoğun günlerde zaman kazandırır.'], storage: 'Buzdolabında 48 saat.'),
  BabyRecipe(id: 'ab36_06', title: 'Mercimek çorbası (aile usulü)', age: '36+', category: 'Çorba', ingredient: 'kırmızı mercimek', vegetable: 'havuç', ingredients: ['Yarım su bardağı kırmızı mercimek', '1 küçük havuç', '1 küçük patates', '1 küçük soğan', '1 tatlı kaşığı tereyağı', '4 su bardağı sıcak su', '1 tutam kimyon'], steps: ['Soğanı tereyağında 3 dakika yumuşatın.', 'Doğranmış havuç, patates ve yıkanmış mercimeği ekleyip 2 dakika çevirin.', 'Sıcak suyu ekleyip kısık ateşte 30 dakika pişirin.', 'Blenderdan geçirin, kimyon ekleyip 2 dakika daha kaynatın.', 'Limon ve kıtır ekmekle servis edin.'], tips: ['Ailece aynı yemeği yemek, çocuğun yeni tatları kabulünü kolaylaştırır.'], storage: 'Buzdolabında 3 gün; dondurulabilir.'),
  BabyRecipe(id: 'ab36_07', title: 'Yulaflı fıstık ezmeli toplar', age: '36+', category: 'Tatlı', ingredient: 'yulaf', vegetable: 'hurma', ingredients: ['1 su bardağı yulaf ezmesi', '3 yemek kaşığı şekersiz fıstık ezmesi', '4 adet çekirdeksiz hurma, ince kıyılmış', '1 yemek kaşığı kakao', '2 yemek kaşığı süt'], steps: ['Hurmaları 10 dakika sıcak suda bekletip süzün ve ezin.', 'Tüm malzemeyi karıştırın; gerekirse süt ekleyerek şekil alacak kıvama getirin.', 'Fındık büyüklüğünde toplar yapın.', 'En az 30 dakika buzdolabında bekletip servis edin.', 'Yer fıstığı alerjisi açısından ilk kez veriyorsanız az miktarla başlayıp gözlemleyin.'], tips: ['Yer fıstığı alerjisi açısından ilk denemede az miktarda verin.', 'Topları küçük ve yumuşak tutun.'], storage: 'Buzdolabında kapalı kapta 5 gün.'),
  BabyRecipe(id: 'ab36_08', title: 'Sebzeli tavuk dürüm', age: '36+', category: 'Et', ingredient: 'lavaş', vegetable: 'marul', ingredients: ['1 tam buğday lavaş', '60 g ızgara veya haşlanmış tavuk, ince dilim', '2 yemek kaşığı rendelenmiş havuç', '1 yaprak marul, ince kıyılmış', '1 yemek kaşığı yoğurt', '1 yemek kaşığı rendelenmiş kaşar'], steps: ['Lavaşı tavada 30 saniye ısıtıp yumuşatın.', 'Ortasına yoğurt sürün; tavuk, havuç, marul ve kaşarı yerleştirin.', 'Alt kısmını katlayıp sıkıca sarın.', 'Ortadan ikiye veya 3 cm dilimlere keserek servis edin.', 'Çocuk yerken yanında olun; dik otursun, yürürken ya da koşarken yemesin.'], tips: ['Okul/kreş beslenme çantası için uygundur.'], storage: 'Hemen tüketin.'),
  BabyRecipe(id: 'ab36_09', title: 'Fırında sebzeli kumpir', age: '36+', category: 'Fırın', ingredient: 'patates', vegetable: 'mısır', ingredients: ['1 büyük patates', '1 tatlı kaşığı tereyağı', '2 yemek kaşığı rendelenmiş kaşar', '2 yemek kaşığı haşlanmış mısır', '2 yemek kaşığı ince doğranmış salatalık ve havuç', '1 yemek kaşığı yoğurt'], steps: ['Fırını 200 °C\'ye ısıtın. Patatesi yıkayıp çatalla birkaç yerinden delin.', '50–60 dakika, şiş kolayca batana kadar fırında pişirin.', 'Ortadan yarıp içini tereyağı ve kaşarla çatalla karıştırın.', 'Mısır, sebzeler ve yoğurtla doldurup servis edin.', 'Mısır taneleri boğulma riski taşır; ince kıyın ya da hafifçe ezin.'], tips: ['Mısır taneleri küçük çocuklarda boğulma riski taşıyabilir; çocuğunuzun çiğneme becerisine göre ezin.'], storage: 'Hemen tüketin.'),
  BabyRecipe(id: 'ab36_10', title: 'Ev yapımı granola bar', age: '36+', category: 'Kahvaltı', ingredient: 'yulaf', vegetable: 'kuru kayısı', ingredients: ['1,5 su bardağı yulaf ezmesi', '2 olgun muz, ezilmiş', '4 adet kuru kayısı, ince doğranmış', '2 yemek kaşığı tahin', '1 tatlı kaşığı tarçın'], steps: ['Fırını 180 °C\'ye ısıtın; 20×20 cm kabı pişirme kâğıdıyla kaplayın.', 'Tüm malzemeyi iyice karıştırın.', 'Karışımı kaba bastırarak düzgünce yayın.', '20–25 dakika, kenarları kızarana kadar pişirin.', 'Tamamen soğuduktan sonra bar şeklinde kesin.'], tips: ['Bütün kuruyemiş yerine ince doğranmış kuru meyve kullanılmıştır; 4 yaş altında bütün kuruyemiş vermeyin.'], storage: 'Hava almayan kapta 4 gün.'),
  BabyRecipe(id: 'bb6_01', title: 'Tatlı patates püresi', age: '6+', category: 'Sebze', ingredient: 'tatlı patates', vegetable: 'tatlı patates', ingredients: ['1 küçük tatlı patates (yaklaşık 100 g)', '2–4 yemek kaşığı içme suyu veya anne sütü/mama'], steps: ['Tatlı patatesi yıkayıp soyun ve küp doğrayın.', 'Buharda 12–15 dakika, çatal kolayca batana kadar pişirin.', 'Blender veya çatalla ezin.', 'Su ya da anne sütüyle akışkan kıvama getirin.', 'Ilıtıp servis edin.'], tips: ['İlk tadımlar için tatlımsı tadı sayesinde kolay kabul edilir.'], storage: 'Buzdolabında 24 saat; buz kalıbında 1 ay dondurulabilir.'),
  BabyRecipe(id: 'bb6_02', title: 'Kabak püresi', age: '6+', category: 'Sebze', ingredient: 'kabak', vegetable: 'kabak', ingredients: ['1 küçük kabak (yaklaşık 120 g)', '1 çay kaşığı zeytinyağı'], steps: ['Ellerinizi, kesme tahtasını ve kapları sıcak sabunlu suyla yıkayın.', 'Kabağı yıkayıp kabuğunu soyun ve küçük küp doğrayın.', 'Tencereye 2 parmak su koyup buhar sepetini yerleştirin; su kaynayınca sebzeyi sepete alıp kapağı kapatın.', 'Buhar sepetinde 8–10 dakika pişirin.', 'Çatalla kolayca eziliyorsa pişmiştir.', 'Blender ya da çatalla ezin; kıvamı ayarlamak için haşlama suyunu kaşık kaşık ekleyin.', 'Zeytinyağını ekleyip karıştırın.', 'Tuz, şeker ve bal eklemeyin; 1 yaş altı bebeklere uygun değildir.', 'Ilıtıp sıcaklığı bileğinizin iç kısmına damlatarak kontrol edin; ılık olmalı, sıcak değil.', 'Kalanını bebeğin ağzı değmemiş kaşıkla ayırıp kapalı kapta buzdolabında 24 saat saklayın; tekrar ısıtmayı bir kez yapın.', 'Buz kalıplarında dondurup 1 ay saklayabilirsiniz; buzdolabında çözdürüp bir kez ısıtın.'], tips: ['Kabak sulu olduğundan ek suya gerek kalmaz.'], storage: 'Buzdolabında 24 saat; buz kalıbında 1 ay dondurulabilir.'),
  BabyRecipe(id: 'bb6_03', title: 'Havuç püresi', age: '6+', category: 'Sebze', ingredient: 'havuç', vegetable: 'havuç', ingredients: ['1 orta boy havuç', '2–3 yemek kaşığı içme suyu'], steps: ['Ellerinizi, kesme tahtasını ve kapları sıcak sabunlu suyla yıkayın.', 'Havucu soyup ince halkalar halinde doğrayın; ince doğranırsa daha çabuk pişer.', 'Tencereye 2 parmak su koyup buhar sepetini yerleştirin; su kaynayınca sebzeyi sepete alıp kapağı kapatın.', 'Buhar sepetinde 15 dakika pişirin.', 'Çatalla kolayca eziliyorsa pişmiştir.', 'Blender ya da çatalla ezin; kıvamı ayarlamak için haşlama suyunu kaşık kaşık ekleyin.', 'Tuz, şeker ve bal eklemeyin; 1 yaş altı bebeklere uygun değildir.', 'Ilıtıp sıcaklığı bileğinizin iç kısmına damlatarak kontrol edin; ılık olmalı, sıcak değil.', 'Kalanını bebeğin ağzı değmemiş kaşıkla ayırıp kapalı kapta buzdolabında 24 saat saklayın; tekrar ısıtmayı bir kez yapın.', 'Buz kalıplarında dondurup 1 ay saklayabilirsiniz; buzdolabında çözdürüp bir kez ısıtın.'], tips: ['Havuç pişince doğal tatlılığı artar.'], storage: 'Buzdolabında 24 saat; buz kalıbında 1 ay dondurulabilir.'),
  BabyRecipe(id: 'bb6_04', title: 'Balkabağı püresi', age: '6+', category: 'Sebze', ingredient: 'balkabağı', vegetable: 'balkabağı', ingredients: ['150 g balkabağı', '1 çay kaşığı tereyağı'], steps: ['Ellerinizi, kesme tahtasını ve kapları sıcak sabunlu suyla yıkayın.', 'Balkabağını soyup çekirdeklerini ayıklayın, küçük küp doğrayın.', 'Tencereye 2 parmak su koyup buhar sepetini yerleştirin; su kaynayınca sebzeyi sepete alıp kapağı kapatın.', 'Buhar sepetinde 12 dakika pişirin.', 'Çatalla kolayca eziliyorsa pişmiştir.', 'Blender ya da çatalla ezin; kıvamı ayarlamak için haşlama suyunu kaşık kaşık ekleyin.', 'Tereyağını sıcakken ekleyip eritin.', 'Tuz, şeker ve bal eklemeyin; 1 yaş altı bebeklere uygun değildir.', 'Ilıtıp sıcaklığı bileğinizin iç kısmına damlatarak kontrol edin; ılık olmalı, sıcak değil.', 'Kalanını bebeğin ağzı değmemiş kaşıkla ayırıp kapalı kapta buzdolabında 24 saat saklayın; tekrar ısıtmayı bir kez yapın.', 'Buz kalıplarında dondurup 1 ay saklayabilirsiniz; buzdolabında çözdürüp bir kez ısıtın.'], tips: ['Fırında pişirmek tadı yoğunlaştırır.'], storage: 'Buzdolabında 24 saat; buz kalıbında 1 ay dondurulabilir.'),
  BabyRecipe(id: 'bb6_05', title: 'Brokoli ve patates püresi', age: '6+', category: 'Sebze', ingredient: 'patates', vegetable: 'brokoli', ingredients: ['1 küçük patates', '4–5 küçük brokoli çiçeği', '2–4 yemek kaşığı haşlama suyu'], steps: ['Ellerinizi, kesme tahtasını ve kapları sıcak sabunlu suyla yıkayın.', 'Patatesi soyup küp doğrayın; brokoliyi küçük çiçeklere ayırıp yıkayın.', 'Patatesi kaynar suda 8 dakika haşlayın; brokoliyi ekleyip 6 dakika daha pişirin.', 'Çatalla kolayca eziliyorsa pişmiştir.', 'Blender ya da çatalla ezin; kıvamı ayarlamak için haşlama suyunu kaşık kaşık ekleyin.', 'Tuz, şeker ve bal eklemeyin; 1 yaş altı bebeklere uygun değildir.', 'Ilıtıp sıcaklığı bileğinizin iç kısmına damlatarak kontrol edin; ılık olmalı, sıcak değil.', 'Kalanını bebeğin ağzı değmemiş kaşıkla ayırıp kapalı kapta buzdolabında 24 saat saklayın; tekrar ısıtmayı bir kez yapın.'], tips: ['Patates brokolinin yoğun tadını yumuşatır.'], storage: 'Buzdolabında 24 saat; buz kalıbında 1 ay dondurulabilir.'),
  BabyRecipe(id: 'bb6_06', title: 'Elma püresi (pişmiş)', age: '6+', category: 'Meyve', ingredient: 'elma', vegetable: 'elma', ingredients: ['1 elma', '3 yemek kaşığı içme suyu'], steps: ['Ellerinizi, kesme tahtasını ve kapları sıcak sabunlu suyla yıkayın.', 'Elmayı yıkayıp soyun, çekirdek evini çıkarıp küçük küp doğrayın.', 'Elma ve suyu küçük tencereye alın; kapağı kapalı kısık ateşte 8 dakika yumuşayana kadar pişirin.', 'Çatalla kolayca eziliyorsa pişmiştir.', 'Blender ya da çatalla ezin; kıvamı ayarlamak için haşlama suyunu kaşık kaşık ekleyin.', 'Tuz, şeker ve bal eklemeyin; 1 yaş altı bebeklere uygun değildir.', 'Ilıtıp sıcaklığı bileğinizin iç kısmına damlatarak kontrol edin; ılık olmalı, sıcak değil.', 'Kalanını bebeğin ağzı değmemiş kaşıkla ayırıp kapalı kapta buzdolabında 24 saat saklayın; tekrar ısıtmayı bir kez yapın.', 'Buz kalıplarında dondurup 1 ay saklayabilirsiniz; buzdolabında çözdürüp bir kez ısıtın.'], tips: ['İlk aylarda elmayı pişirerek vermek sindirimi kolaylaştırır.'], storage: 'Buzdolabında 24 saat; buz kalıbında 1 ay dondurulabilir.'),
  BabyRecipe(id: 'bb6_07', title: 'Muz ezmesi', age: '6+', category: 'Meyve', ingredient: 'muz', vegetable: 'muz', ingredients: ['Yarım olgun muz', '1–2 yemek kaşığı anne sütü veya mama (isteğe bağlı)'], steps: ['Ellerinizi, kesme tahtasını ve kapları sıcak sabunlu suyla yıkayın.', 'Kabuğunda kahverengi benekler olan olgun bir muz seçin; daha tatlı ve yumuşaktır.', 'Muzu soyup yarısını temiz bir kâseye alın.', 'Çatalla topak kalmayana kadar ezin.', 'Kıvam koyuysa 1–2 kaşık anne sütü ya da mamayla inceltin.', '6–7. aylarda pürüzsüz, 8. aydan sonra çatalla hafif pütürlü bırakın.', 'Tuz, şeker ve bal eklemeyin; 1 yaş altı bebeklere uygun değildir.', 'Hemen servis edin; kalanını saklamayın.'], tips: ['Çok olgun muz daha kolay ezilir.'], storage: 'Hazırlandıktan hemen sonra tüketin.'),
  BabyRecipe(id: 'bb6_08', title: 'Şeftali püresi', age: '6+', category: 'Meyve', ingredient: 'şeftali', vegetable: 'şeftali', ingredients: ['1 olgun şeftali'], steps: ['Şeftalinin kabuğunu çizip kaynar suda 30 saniye bekletin.', 'Kabuğunu soyup çekirdeğini çıkarın.', 'Doğrayıp çatalla ezin.', 'Sertse 3 dakika buharda yumuşatın.', 'Servis edin.'], tips: ['Kabuğu soymak boğulma riskini azaltır.'], storage: 'Buzdolabında 24 saat; buz kalıbında 1 ay dondurulabilir.'),
  BabyRecipe(id: 'bb6_09', title: 'Avokado ezmesi (bebek)', age: '6+', category: 'Meyve', ingredient: 'avokado', vegetable: 'avokado', ingredients: ['Çeyrek olgun avokado', '1–2 yemek kaşığı anne sütü veya mama'], steps: ['Ellerinizi, kesme tahtasını ve kapları sıcak sabunlu suyla yıkayın.', 'Avokadoyu ikiye kesip çekirdeğini çıkarın; çeyreğini kaşıkla alın.', 'Çatalla pürüzsüz olana kadar ezin.', 'Anne sütü ya da mamayla bebeğin kaşıktan alabileceği kıvama getirin.', '6–7. aylarda pürüzsüz, 8. aydan sonra çatalla hafif pütürlü bırakın.', 'Kalan avokadoyu çekirdeğiyle birlikte streç filmle sarıp buzdolabında 1 gün saklayın.', 'Hemen servis edin; kalanını saklamayın.'], tips: ['Sağlıklı yağlar açısından zengindir.'], storage: 'Hazırlandıktan hemen sonra tüketin.'),
  BabyRecipe(id: 'bb6_10', title: 'Pirinç lapası (sebzeli)', age: '6+', category: 'Tahıl', ingredient: 'pirinç', vegetable: 'havuç', ingredients: ['2 yemek kaşığı pirinç', 'Yarım havuç', '1,5 su bardağı içme suyu'], steps: ['Ellerinizi, kesme tahtasını ve kapları sıcak sabunlu suyla yıkayın.', 'Pirinci suyu berraklaşana kadar yıkayın; havucu soyup ince rendeleyin.', 'Pirinç, havuç ve suyu küçük tencereye alıp kaynatın.', 'Kısık ateşte ara ara karıştırarak 25 dakika, pirinç dağılana kadar pişirin.', 'Blender ya da çatalla ezin; kıvamı ayarlamak için haşlama suyunu kaşık kaşık ekleyin.', 'Koyulaşırsa kaynamış su ya da anne sütü ekleyin.', 'Tuz, şeker ve bal eklemeyin; 1 yaş altı bebeklere uygun değildir.', 'Ilıtıp sıcaklığı bileğinizin iç kısmına damlatarak kontrol edin; ılık olmalı, sıcak değil.', 'Kalanını bebeğin ağzı değmemiş kaşıkla ayırıp kapalı kapta buzdolabında 24 saat saklayın; tekrar ısıtmayı bir kez yapın.'], tips: ['Pirinci her gün değil, diğer tahıllarla dönüşümlü verin.'], storage: 'Buzdolabında 24 saat; buz kalıbında 1 ay dondurulabilir.'),
  BabyRecipe(id: 'bb6_11', title: 'Yulaf lapası (elmalı, bebek)', age: '6+', category: 'Tahıl', ingredient: 'yulaf', vegetable: 'elma', ingredients: ['2 yemek kaşığı ince yulaf', 'Yarım elma (rendelenmiş)', '1 su bardağı içme suyu'], steps: ['Ellerinizi, kesme tahtasını ve kapları sıcak sabunlu suyla yıkayın.', 'Elmayı soyup çekirdek evini çıkarın ve ince rendeleyin.', 'Yulaf ve suyu küçük tencerede kaynatın.', 'Elmayı ekleyin.', 'Kısık ateşte sürekli karıştırarak 6–7 dakika pişirin.', 'Blender ya da çatalla ezin; kıvamı ayarlamak için haşlama suyunu kaşık kaşık ekleyin.', 'Tuz, şeker ve bal eklemeyin; 1 yaş altı bebeklere uygun değildir.', 'Ilıtıp sıcaklığı bileğinizin iç kısmına damlatarak kontrol edin; ılık olmalı, sıcak değil.', 'Kalanını bebeğin ağzı değmemiş kaşıkla ayırıp kapalı kapta buzdolabında 24 saat saklayın; tekrar ısıtmayı bir kez yapın.'], tips: ['Glutene hassasiyet şüphesinde doktorunuza danışın.'], storage: 'Hazırlandıktan hemen sonra tüketin.'),
  BabyRecipe(id: 'bb6_12', title: 'Bezelye püresi', age: '6+', category: 'Sebze', ingredient: 'bezelye', vegetable: 'bezelye', ingredients: ['Yarım su bardağı bezelye', '2–3 yemek kaşığı haşlama suyu'], steps: ['Ellerinizi, kesme tahtasını ve kapları sıcak sabunlu suyla yıkayın.', 'Taze bezelyeyi ayıklayın; dondurulmuşsa çözdürmeden kullanın.', 'Bezelyeyi az suda kapağı kapalı 8 dakika haşlayın.', 'Çatalla kolayca eziliyorsa pişmiştir.', 'Blender ya da çatalla ezin; kıvamı ayarlamak için haşlama suyunu kaşık kaşık ekleyin.', 'Kabuklar boğaza takılmasın diye püreyi ince süzgeçten geçirin.', 'Tuz, şeker ve bal eklemeyin; 1 yaş altı bebeklere uygun değildir.', 'Ilıtıp sıcaklığı bileğinizin iç kısmına damlatarak kontrol edin; ılık olmalı, sıcak değil.', 'Kalanını bebeğin ağzı değmemiş kaşıkla ayırıp kapalı kapta buzdolabında 24 saat saklayın; tekrar ısıtmayı bir kez yapın.', 'Buz kalıplarında dondurup 1 ay saklayabilirsiniz; buzdolabında çözdürüp bir kez ısıtın.'], tips: ['Süzmek kabuk parçalarını giderir.'], storage: 'Buzdolabında 24 saat; buz kalıbında 1 ay dondurulabilir.'),
  BabyRecipe(id: 'bb6_13', title: 'Armut ve yulaf lapası', age: '6+', category: 'Tahıl', ingredient: 'yulaf', vegetable: 'armut', ingredients: ['2 yemek kaşığı ince yulaf', 'Yarım olgun armut', '1 su bardağı içme suyu'], steps: ['Ellerinizi, kesme tahtasını ve kapları sıcak sabunlu suyla yıkayın.', 'Armudu soyup çekirdek evini çıkarın ve küçük doğrayın.', 'Yulaf, armut ve suyu küçük tencereye alın.', 'Kısık ateşte sürekli karıştırarak 7 dakika, armut yumuşayana kadar pişirin.', 'Blender ya da çatalla ezin; kıvamı ayarlamak için haşlama suyunu kaşık kaşık ekleyin.', 'Tuz, şeker ve bal eklemeyin; 1 yaş altı bebeklere uygun değildir.', 'Ilıtıp sıcaklığı bileğinizin iç kısmına damlatarak kontrol edin; ılık olmalı, sıcak değil.', 'Kalanını bebeğin ağzı değmemiş kaşıkla ayırıp kapalı kapta buzdolabında 24 saat saklayın; tekrar ısıtmayı bir kez yapın.'], tips: ['Armut sindirimi destekler.'], storage: 'Hazırlandıktan hemen sonra tüketin.'),
  BabyRecipe(id: 'bb6_14', title: 'Karnabahar ve havuç püresi', age: '6+', category: 'Sebze', ingredient: 'karnabahar', vegetable: 'havuç', ingredients: ['4 karnabahar çiçeği', 'Yarım havuç', '1 çay kaşığı zeytinyağı'], steps: ['Ellerinizi, kesme tahtasını ve kapları sıcak sabunlu suyla yıkayın.', 'Karnabaharı küçük çiçeklere ayırıp yıkayın; havucu soyup ince halka doğrayın.', 'Tencereye 2 parmak su koyup buhar sepetini yerleştirin; su kaynayınca sebzeyi sepete alıp kapağı kapatın.', 'Önce havucu buhar sepetinde 5 dakika, ardından karnabaharı ekleyip 7 dakika daha pişirin.', 'Çatalla kolayca eziliyorsa pişmiştir.', 'Blender ya da çatalla ezin; kıvamı ayarlamak için haşlama suyunu kaşık kaşık ekleyin.', 'Zeytinyağını ekleyip karıştırın.', 'Tuz, şeker ve bal eklemeyin; 1 yaş altı bebeklere uygun değildir.', 'Ilıtıp sıcaklığı bileğinizin iç kısmına damlatarak kontrol edin; ılık olmalı, sıcak değil.', 'Kalanını bebeğin ağzı değmemiş kaşıkla ayırıp kapalı kapta buzdolabında 24 saat saklayın; tekrar ısıtmayı bir kez yapın.'], tips: ['Karnabahar gaz yapabilir; az miktarla başlayın.'], storage: 'Buzdolabında 24 saat; buz kalıbında 1 ay dondurulabilir.'),
  BabyRecipe(id: 'bb6_15', title: 'Kırmızı mercimek püresi (sade)', age: '8+', category: 'Baklagil', ingredient: 'kırmızı mercimek', vegetable: 'havuç', ingredients: ['2 yemek kaşığı kırmızı mercimek', 'Yarım havuç', '1 su bardağı içme suyu', '1 çay kaşığı tereyağı'], steps: ['Ellerinizi, kesme tahtasını ve kapları sıcak sabunlu suyla yıkayın.', 'Mercimeği suyu berraklaşana kadar yıkayın; havucu soyup ince rendeleyin.', 'Mercimek, havuç ve suyu küçük tencereye alıp kaynatın; köpüğünü alın.', 'Kısık ateşte ara ara karıştırarak 20 dakika, mercimek dağılana kadar pişirin.', 'Blender ya da çatalla ezin; kıvamı ayarlamak için haşlama suyunu kaşık kaşık ekleyin.', 'Tereyağını ekleyip karıştırın.', 'Tuz, şeker ve bal eklemeyin; 1 yaş altı bebeklere uygun değildir.', 'Ilıtıp sıcaklığı bileğinizin iç kısmına damlatarak kontrol edin; ılık olmalı, sıcak değil.', 'Kalanını bebeğin ağzı değmemiş kaşıkla ayırıp kapalı kapta buzdolabında 24 saat saklayın; tekrar ısıtmayı bir kez yapın.', 'Buz kalıplarında dondurup 1 ay saklayabilirsiniz; buzdolabında çözdürüp bir kez ısıtın.'], tips: ['Demir açısından değerlidir.'], storage: 'Buzdolabında 24 saat; buz kalıbında 1 ay dondurulabilir.'),
  BabyRecipe(id: 'bb6_16', title: 'Tavuklu sebze püresi', age: '8+', category: 'Et', ingredient: 'tavuk', vegetable: 'patates', ingredients: ['30 g tavuk göğsü', '1 küçük patates', 'Yarım havuç', '1 su bardağı içme suyu'], steps: ['Ellerinizi, kesme tahtasını ve kapları sıcak sabunlu suyla yıkayın.', 'Tavuğu ayrı tahtada küçük doğrayın; ardından tahtayı ve ellerinizi yıkayın.', 'Patates ve havucu soyup küp doğrayın.', 'Tavuk, sebzeler ve suyu tencereye alıp kaynatın; köpüğünü alın.', 'Kapağı kapalı kısık ateşte 20 dakika pişirin.', 'Eti ortadan bölüp kontrol edin: içi pembe kalmamalı, suyu berrak akmalı.', 'Blenderda pürüzsüz çekin; haşlama suyuyla kıvamı ayarlayın.', 'Tuz, şeker ve bal eklemeyin; 1 yaş altı bebeklere uygun değildir.', 'Ilıtıp sıcaklığı bileğinizin iç kısmına damlatarak kontrol edin; ılık olmalı, sıcak değil.', 'Kalanını bebeğin ağzı değmemiş kaşıkla ayırıp kapalı kapta buzdolabında 24 saat saklayın; tekrar ısıtmayı bir kez yapın.'], tips: ['Et püresinde topak kalmamalı.'], storage: 'Buzdolabında 24 saat; buz kalıbında 1 ay dondurulabilir.'),
  BabyRecipe(id: 'bb6_17', title: 'Yoğurtlu armut ezmesi', age: '8+', category: 'Yoğurt', ingredient: 'yoğurt', vegetable: 'armut', ingredients: ['2 yemek kaşığı tam yağlı sade yoğurt', 'Yarım olgun armut (pişmiş)'], steps: ['Ellerinizi, kesme tahtasını ve kapları sıcak sabunlu suyla yıkayın.', 'Armudu soyup çekirdek evini çıkarın, küçük doğrayın.', 'Buharda 5 dakika yumuşatın.', 'Çatalla ezip tamamen soğutun.', 'Yoğurdu buzdolabından 10 dakika önce çıkarın; çok soğuk vermeyin.', 'Yoğurtla karıştırın.', 'Tuz, şeker ve bal eklemeyin; 1 yaş altı bebeklere uygun değildir.', 'Hemen servis edin; kalanını saklamayın.'], tips: ['Yoğurdu ısıtmayın.'], storage: 'Hazırlandıktan hemen sonra tüketin.'),
  BabyRecipe(id: 'bb6_18', title: 'Kayısı püresi', age: '6+', category: 'Meyve', ingredient: 'kayısı', vegetable: 'kayısı', ingredients: ['3 olgun kayısı'], steps: ['Ellerinizi, kesme tahtasını ve kapları sıcak sabunlu suyla yıkayın.', 'Kayısıları yıkayıp ikiye bölün ve çekirdeklerini çıkarın.', 'Tencereye 2 parmak su koyup buhar sepetini yerleştirin; su kaynayınca sebzeyi sepete alıp kapağı kapatın.', 'Kayısıları buhar sepetinde 3–4 dakika yumuşatın.', 'Çatalla kolayca eziliyorsa pişmiştir.', 'Blender ya da çatalla ezin; kıvamı ayarlamak için haşlama suyunu kaşık kaşık ekleyin.', 'Kabukları bebeğin boğazına takılmasın diye ayıklayın ya da süzgeçten geçirin.', 'Tuz, şeker ve bal eklemeyin; 1 yaş altı bebeklere uygun değildir.', 'Ilıtıp sıcaklığı bileğinizin iç kısmına damlatarak kontrol edin; ılık olmalı, sıcak değil.', 'Kalanını bebeğin ağzı değmemiş kaşıkla ayırıp kapalı kapta buzdolabında 24 saat saklayın; tekrar ısıtmayı bir kez yapın.'], tips: ['Kuru kayısı kullanılacaksa önce suda bekletip pişirin.'], storage: 'Buzdolabında 24 saat; buz kalıbında 1 ay dondurulabilir.'),
  BabyRecipe(id: 'bb6_19', title: 'Kuru erik püresi', age: '6+', category: 'Meyve', ingredient: 'erik', vegetable: 'erik', ingredients: ['4 kuru erik', 'Yarım su bardağı içme suyu'], steps: ['Ellerinizi, kesme tahtasını ve kapları sıcak sabunlu suyla yıkayın.', 'Kuru erikleri yıkayıp yarım su bardağı içme suyunda 1 saat bekletin.', 'Aynı suyla küçük tencerede 5 dakika kaynatın.', 'Ilıyınca çekirdekleri varsa çıkarın.', 'Blender ya da çatalla ezin; kıvamı ayarlamak için haşlama suyunu kaşık kaşık ekleyin.', 'Kabızlıkta yardımcıdır; günde 1–2 tatlı kaşığıyla başlayın, fazlası ishal yapabilir.', 'Tuz, şeker ve bal eklemeyin; 1 yaş altı bebeklere uygun değildir.', 'Ilıtıp sıcaklığı bileğinizin iç kısmına damlatarak kontrol edin; ılık olmalı, sıcak değil.', 'Kalanını bebeğin ağzı değmemiş kaşıkla ayırıp kapalı kapta buzdolabında 24 saat saklayın; tekrar ısıtmayı bir kez yapın.'], tips: ['Kabızlıkta doktor önerisiyle kullanılabilir.'], storage: 'Buzdolabında 24 saat; buz kalıbında 1 ay dondurulabilir.'),
  BabyRecipe(id: 'bb6_20', title: 'Pancar ve patates püresi', age: '8+', category: 'Sebze', ingredient: 'pancar', vegetable: 'patates', ingredients: ['Çeyrek pancar', '1 küçük patates', '2–3 yemek kaşığı içme suyu'], steps: ['Ellerinizi, kesme tahtasını ve kapları sıcak sabunlu suyla yıkayın.', 'Pancarı ve patatesi soyup küçük küp doğrayın; pancar elinizi boyayabilir, eldiven kullanın.', 'Tencereye 2 parmak su koyup buhar sepetini yerleştirin; su kaynayınca sebzeyi sepete alıp kapağı kapatın.', 'Buhar sepetinde 20 dakika pişirin.', 'Çatalla kolayca eziliyorsa pişmiştir.', 'Blender ya da çatalla ezin; kıvamı ayarlamak için haşlama suyunu kaşık kaşık ekleyin.', 'Pancar idrarı ve kakayı kırmızıya boyayabilir; bu zararsızdır.', 'Tuz, şeker ve bal eklemeyin; 1 yaş altı bebeklere uygun değildir.', 'Ilıtıp sıcaklığı bileğinizin iç kısmına damlatarak kontrol edin; ılık olmalı, sıcak değil.', 'Kalanını bebeğin ağzı değmemiş kaşıkla ayırıp kapalı kapta buzdolabında 24 saat saklayın; tekrar ısıtmayı bir kez yapın.'], tips: ['Pancar dışkıyı kırmızıya boyayabilir; normaldir.'], storage: 'Buzdolabında 24 saat; buz kalıbında 1 ay dondurulabilir.'),
  BabyRecipe(id: 'bb9_01', title: 'Sebzeli bulgur lapası', age: '9+', category: 'Tahıl', ingredient: 'bulgur', vegetable: 'kabak', ingredients: ['2 yemek kaşığı ince bulgur', '2 yemek kaşığı rendelenmiş kabak', '1 su bardağı içme suyu', '1 çay kaşığı zeytinyağı'], steps: ['Ellerinizi, kesme tahtasını ve kapları sıcak sabunlu suyla yıkayın.', 'Kabağı ince rendeleyin.', 'Kabak ve suyu küçük tencerede kaynatın.', 'Bulguru ekleyin; kısık ateşte ara ara karıştırarak 10 dakika yumuşayana kadar pişirin.', 'Ocaktan alıp kapağı kapalı 5 dakika demlendirin.', 'Zeytinyağını ekleyin.', 'Hafif taneli bırakın; çiğnemeyi öğrenmesine yardımcı olur.', 'Tuz, şeker ve bal eklemeyin; 1 yaş altı bebeklere uygun değildir.', 'Ilıtıp sıcaklığı bileğinizin iç kısmına damlatarak kontrol edin; ılık olmalı, sıcak değil.', 'Kalanını bebeğin ağzı değmemiş kaşıkla ayırıp kapalı kapta buzdolabında 24 saat saklayın; tekrar ısıtmayı bir kez yapın.'], tips: ['Taneli kıvam çiğneme becerisini geliştirir.'], storage: 'Buzdolabında 24 saat; buz kalıbında 1 ay dondurulabilir.'),
  BabyRecipe(id: 'bb9_02', title: 'Fırında tatlı patates parmakları', age: '9+', category: 'Sebze', ingredient: 'tatlı patates', vegetable: 'tatlı patates', ingredients: ['1 tatlı patates', '1 çay kaşığı zeytinyağı'], steps: ['Fırını 200 °C\'ye ısıtın.', 'Tatlı patatesi bebeğin tutabileceği kalın parmaklar hâlinde kesin.', 'Zeytinyağıyla harmanlayın.', '25 dakika, içi yumuşayana kadar pişirin.', 'Ilıtıp verin.'], tips: ['Parmak yiyecekler kendi kendine yemeyi destekler.'], storage: 'Buzdolabında 24 saat.'),
  BabyRecipe(id: 'bb9_03', title: 'Mercimekli sebze köftesi (yumuşak)', age: '9+', category: 'Baklagil', ingredient: 'kırmızı mercimek', vegetable: 'havuç', ingredients: ['3 yemek kaşığı pişmiş kırmızı mercimek', '2 yemek kaşığı ince bulgur', '1 yemek kaşığı rendelenmiş havuç', '1 çay kaşığı zeytinyağı'], steps: ['Ellerinizi, kesme tahtasını ve kapları sıcak sabunlu suyla yıkayın.', 'Pişmiş mercimeği sıcakken bulgurla karıştırın; kapağını kapatıp 15 dakika bekletin.', 'Havucu ince rendeleyin; zeytinyağıyla birlikte karışıma ekleyin.', 'Elinizi yakmayacak kadar ılıyınca 2–3 dakika yoğurun.', 'Bebeğin avucuna sığacak küçük yassı köfteler yapın.', 'Köfteler yumuşak olmalı; parmakla bastırınca ezilmeli.', 'Tuz, şeker ve bal eklemeyin; 1 yaş altı bebeklere uygun değildir.', 'Bebek yerken mutlaka yanında, dik oturur durumda olsun; ağzına sığmayacak büyüklükte parçalar verin.', 'Kalanını bebeğin ağzı değmemiş kaşıkla ayırıp kapalı kapta buzdolabında 24 saat saklayın; tekrar ısıtmayı bir kez yapın.'], tips: ['Köfteler yumuşak ve kolay ezilir olmalı.'], storage: 'Buzdolabında 24 saat.'),
  BabyRecipe(id: 'bb9_04', title: 'Yumurtalı ıspanaklı püre', age: '9+', category: 'Yumurta', ingredient: 'yumurta', vegetable: 'ıspanak', ingredients: ['1 haşlanmış yumurta sarısı', '2 yemek kaşığı haşlanmış ıspanak', '1 küçük haşlanmış patates'], steps: ['Ellerinizi, kesme tahtasını ve kapları sıcak sabunlu suyla yıkayın.', 'Yumurtayı kaynar suda 10 dakika haşlayın; sarısını ayırın.', 'Yumurtayı akı ve sarısı tamamen katılaşana kadar pişirin; akışkan bırakmayın.', 'Ispanağı yıkayıp 3 dakika haşlayın ve çok ince kıyın.', 'Patatesle birlikte çatalla ezin.', 'Yumurta sarısını ekleyip karıştırın.', 'Kıvam koyuysa haşlama suyu ekleyin.', 'Tuz, şeker ve bal eklemeyin; 1 yaş altı bebeklere uygun değildir.', 'Ilıtıp sıcaklığı bileğinizin iç kısmına damlatarak kontrol edin; ılık olmalı, sıcak değil.'], tips: ['Yumurta tam pişmiş olmalı.'], storage: 'Hazırlandıktan hemen sonra tüketin.'),
  BabyRecipe(id: 'bb9_05', title: 'Somonlu kabak ezmesi', age: '9+', category: 'Balık', ingredient: 'somon', vegetable: 'kabak', ingredients: ['30 g kılçıksız somon', 'Yarım kabak', '1 çay kaşığı zeytinyağı'], steps: ['Ellerinizi, kesme tahtasını ve kapları sıcak sabunlu suyla yıkayın.', 'Kabağı soyup küçük doğrayın.', 'Tencereye 2 parmak su koyup buhar sepetini yerleştirin; su kaynayınca sebzeyi sepete alıp kapağı kapatın.', 'Kabağı 6 dakika pişirin; somonu ekleyip 8 dakika daha pişirin.', 'Balığı parmaklarınızla yoklayarak tüm kılçıkları ayıklayın; et opaklaşıp kolayca dağılıyorsa pişmiştir.', 'Çatalla ezin; zeytinyağını ekleyin.', 'Tuz, şeker ve bal eklemeyin; 1 yaş altı bebeklere uygun değildir.', 'Ilıtıp sıcaklığı bileğinizin iç kısmına damlatarak kontrol edin; ılık olmalı, sıcak değil.', 'Kalanını bebeğin ağzı değmemiş kaşıkla ayırıp kapalı kapta buzdolabında 24 saat saklayın; tekrar ısıtmayı bir kez yapın.'], tips: ['Haftada 1–2 kez balık önerilir.'], storage: 'Hazırlandıktan hemen sonra tüketin.'),
  BabyRecipe(id: 'bb9_06', title: 'Kıymalı patates ezmesi', age: '9+', category: 'Et', ingredient: 'dana kıyma', vegetable: 'patates', ingredients: ['2 yemek kaşığı az yağlı dana kıyma', '1 küçük patates', '1 yemek kaşığı rendelenmiş domates', 'Yarım su bardağı içme suyu'], steps: ['Ellerinizi, kesme tahtasını ve kapları sıcak sabunlu suyla yıkayın.', 'Patatesi soyup küçük küp doğrayın; domatesi rendeleyin.', 'Kıymayı tencerede kaşıkla ezerek, topaklanmadan rengi tamamen dönene kadar 5 dakika pişirin.', 'Domatesi ekleyip 2 dakika çevirin.', 'Patates ve suyu ekleyin; kapağı kapalı kısık ateşte 15 dakika pişirin.', 'Kıymanın içinde pembe kalmadığını kontrol edin.', 'Çatalla ezin.', 'Tuz, şeker ve bal eklemeyin; 1 yaş altı bebeklere uygun değildir.', 'Ilıtıp sıcaklığı bileğinizin iç kısmına damlatarak kontrol edin; ılık olmalı, sıcak değil.', 'Kalanını bebeğin ağzı değmemiş kaşıkla ayırıp kapalı kapta buzdolabında 24 saat saklayın; tekrar ısıtmayı bir kez yapın.'], tips: ['Kırmızı et demir sağlar.'], storage: 'Buzdolabında 24 saat; buz kalıbında 1 ay dondurulabilir.'),
  BabyRecipe(id: 'bb9_07', title: 'Yoğurtlu kabak ve havuç', age: '9+', category: 'Yoğurt', ingredient: 'yoğurt', vegetable: 'kabak', ingredients: ['Yarım kabak', 'Yarım havuç', '3 yemek kaşığı yoğurt', '1 çay kaşığı zeytinyağı'], steps: ['Ellerinizi, kesme tahtasını ve kapları sıcak sabunlu suyla yıkayın.', 'Kabak ve havucu soyup ince rendeleyin.', 'Tavada zeytinyağıyla 6 dakika, yumuşayana kadar pişirin.', 'Tamamen soğutun.', 'Yoğurdu buzdolabından 10 dakika önce çıkarın; çok soğuk vermeyin.', 'Yoğurtla karıştırın.', 'Tuz, şeker ve bal eklemeyin; 1 yaş altı bebeklere uygun değildir.', 'Hemen servis edin; kalanını saklamayın.'], tips: ['Sebze tamamen soğumalı.'], storage: 'Hazırlandıktan hemen sonra tüketin.'),
  BabyRecipe(id: 'bb9_08', title: 'Avokadolu muzlu ezme', age: '9+', category: 'Meyve', ingredient: 'avokado', vegetable: 'muz', ingredients: ['Çeyrek avokado', 'Yarım muz'], steps: ['Ellerinizi, kesme tahtasını ve kapları sıcak sabunlu suyla yıkayın.', 'Avokado ve muzu soyun.', 'Çatalla ezip karıştırın.', '9. aydan sonra hafif pütürlü bırakın; çiğneme becerisini geliştirir.', 'Tuz, şeker ve bal eklemeyin; 1 yaş altı bebeklere uygun değildir.', 'Hemen servis edin; kalanını saklamayın.'], tips: ['Pütürlü kıvam çiğnemeye geçişi destekler.'], storage: 'Hazırlandıktan hemen sonra tüketin.'),
  BabyRecipe(id: 'bb9_09', title: 'Tavuklu şehriyeli çorba (bebek)', age: '9+', category: 'Çorba', ingredient: 'tavuk', vegetable: 'havuç', ingredients: ['30 g tavuk göğsü', '1 yemek kaşığı arpa şehriye', 'Yarım havuç', '1,5 su bardağı içme suyu'], steps: ['Ellerinizi, kesme tahtasını ve kapları sıcak sabunlu suyla yıkayın.', 'Tavuğu suyla tencereye alıp kaynatın; köpüğünü alın.', 'Kısık ateşte 15 dakika haşlayın.', 'Eti ortadan bölüp kontrol edin: içi pembe kalmamalı, suyu berrak akmalı.', 'Tavuğu çıkarıp çok ince didikleyin.', 'Havucu rendeleyip şehriyeyle birlikte haşlama suyuna ekleyin; 10 dakika pişirin.', 'Tavuğu ekleyip 1 dakika kaynatın.', 'Çatalla hafif ezin.', 'Tuz, şeker ve bal eklemeyin; 1 yaş altı bebeklere uygun değildir.', 'Ilıtıp sıcaklığı bileğinizin iç kısmına damlatarak kontrol edin; ılık olmalı, sıcak değil.', 'Kalanını bebeğin ağzı değmemiş kaşıkla ayırıp kapalı kapta buzdolabında 24 saat saklayın; tekrar ısıtmayı bir kez yapın.'], tips: ['Şehriyeyi iyice pişirin.'], storage: 'Buzdolabında 24 saat; buz kalıbında 1 ay dondurulabilir.'),
  BabyRecipe(id: 'bb9_10', title: 'Nohutlu balkabağı ezmesi', age: '9+', category: 'Baklagil', ingredient: 'nohut', vegetable: 'balkabağı', ingredients: ['2 yemek kaşığı haşlanmış nohut (kabuksuz)', '100 g balkabağı', '1 çay kaşığı zeytinyağı'], steps: ['Ellerinizi, kesme tahtasını ve kapları sıcak sabunlu suyla yıkayın.', 'Balkabağını soyup küp doğrayın; nohutların kabuklarını parmaklarınızla sıyırın.', 'Tencereye 2 parmak su koyup buhar sepetini yerleştirin; su kaynayınca sebzeyi sepete alıp kapağı kapatın.', 'Balkabağını buhar sepetinde 12 dakika pişirin.', 'Çatalla kolayca eziliyorsa pişmiştir.', 'Blender ya da çatalla ezin; kıvamı ayarlamak için haşlama suyunu kaşık kaşık ekleyin.', 'Nohut ve balkabağını birlikte ezin; zeytinyağını ekleyin.', 'Tuz, şeker ve bal eklemeyin; 1 yaş altı bebeklere uygun değildir.', 'Ilıtıp sıcaklığı bileğinizin iç kısmına damlatarak kontrol edin; ılık olmalı, sıcak değil.', 'Kalanını bebeğin ağzı değmemiş kaşıkla ayırıp kapalı kapta buzdolabında 24 saat saklayın; tekrar ısıtmayı bir kez yapın.'], tips: ['Bütün nohut verilmez; mutlaka ezilmeli.'], storage: 'Buzdolabında 24 saat; buz kalıbında 1 ay dondurulabilir.'),
  BabyRecipe(id: 'bb9_11', title: 'Fırında elma dilimleri (yumuşak)', age: '9+', category: 'Meyve', ingredient: 'elma', vegetable: 'elma', ingredients: ['1 elma', '1 tutam tarçın'], steps: ['Fırını 180°C’ye ısıtın; tepsiye yağlı kâğıt serin.', 'Ellerinizi, kesme tahtasını ve kapları sıcak sabunlu suyla yıkayın.', 'Elmayı soyup çekirdek evini çıkarın; bebeğin avucuna sığacak kalın dilimler kesin.', 'Dilimleri tepsiye dizip tarçın serpin.', '20 dakika, parmakla bastırınca kolayca ezilene kadar pişirin.', 'Ilıtıp sıcaklığı bileğinizin iç kısmına damlatarak kontrol edin; ılık olmalı, sıcak değil.', 'Bebek yerken mutlaka yanında, dik oturur durumda olsun; ağzına sığmayacak büyüklükte parçalar verin.'], tips: ['Yumuşak olmalı; damakla ezilebilmeli.'], storage: 'Buzdolabında 24 saat.'),
  BabyRecipe(id: 'bb9_12', title: 'Brokolili peynirli irmik', age: '9+', category: 'Tahıl', ingredient: 'irmik', vegetable: 'brokoli', ingredients: ['1 yemek kaşığı irmik', '2 brokoli çiçeği (haşlanmış, kıyılmış)', '1 yemek kaşığı tuzsuz lor', '1 su bardağı içme suyu'], steps: ['Ellerinizi, kesme tahtasını ve kapları sıcak sabunlu suyla yıkayın.', 'Brokoliyi haşlayıp çok ince kıyın.', 'Suyu kaynatın; irmiği yağmur gibi serperken sürekli karıştırın.', 'Topaklanmadan 4 dakika pişirin.', 'Brokoliyi ekleyip 1 dakika karıştırın.', 'Ocaktan alıp tuzsuz loru karıştırın.', 'Tuz, şeker ve bal eklemeyin; 1 yaş altı bebeklere uygun değildir.', 'Ilıtıp sıcaklığı bileğinizin iç kısmına damlatarak kontrol edin; ılık olmalı, sıcak değil.', 'Kalanını bebeğin ağzı değmemiş kaşıkla ayırıp kapalı kapta buzdolabında 24 saat saklayın; tekrar ısıtmayı bir kez yapın.'], tips: ['Lor tuzsuz olmalı.'], storage: 'Hazırlandıktan hemen sonra tüketin.'),
  BabyRecipe(id: 'bb9_13', title: 'Sebzeli omlet parmakları', age: '10+', category: 'Yumurta', ingredient: 'yumurta', vegetable: 'ıspanak', ingredients: ['1 yumurta', '1 yemek kaşığı ince kıyılmış ıspanak', '1 yemek kaşığı rendelenmiş kabak', '1 çay kaşığı tereyağı'], steps: ['Ellerinizi, kesme tahtasını ve kapları sıcak sabunlu suyla yıkayın.', 'Ispanağı yıkayıp çok ince kıyın; kabağı rendeleyip suyunu sıkın.', 'Yumurtayı sebzelerle çırpın.', 'Küçük tavada tereyağını kısık ateşte eritin; karışımı dökün.', 'Kapağı kapalı 3–4 dakika, üstü katılaşana kadar pişirin.', 'Ters çevirip 1–2 dakika daha pişirin.', 'Yumurtayı akı ve sarısı tamamen katılaşana kadar pişirin; akışkan bırakmayın.', 'Ilıtıp bebeğin tutabileceği şeritler halinde kesin.', 'Bebek yerken mutlaka yanında, dik oturur durumda olsun; ağzına sığmayacak büyüklükte parçalar verin.'], tips: ['Akışkan yumurta kalmamalı.'], storage: 'Hazırlandıktan hemen sonra tüketin.'),
  BabyRecipe(id: 'bb9_14', title: 'Mezgit ve patates ezmesi', age: '10+', category: 'Balık', ingredient: 'mezgit', vegetable: 'patates', ingredients: ['40 g kılçıksız mezgit', '1 küçük patates', '1 çay kaşığı tereyağı'], steps: ['Ellerinizi, kesme tahtasını ve kapları sıcak sabunlu suyla yıkayın.', 'Patatesi soyup küp doğrayın ve kaynar suda 12–15 dakika haşlayın.', 'Tencereye 2 parmak su koyup buhar sepetini yerleştirin; su kaynayınca sebzeyi sepete alıp kapağı kapatın.', 'Mezgiti buhar sepetinde 8 dakika pişirin.', 'Balığı parmaklarınızla yoklayarak tüm kılçıkları ayıklayın; et opaklaşıp kolayca dağılıyorsa pişmiştir.', 'Patates, mezgit ve tereyağını çatalla ezin.', 'Tuz, şeker ve bal eklemeyin; 1 yaş altı bebeklere uygun değildir.', 'Ilıtıp sıcaklığı bileğinizin iç kısmına damlatarak kontrol edin; ılık olmalı, sıcak değil.', 'Kalanını bebeğin ağzı değmemiş kaşıkla ayırıp kapalı kapta buzdolabında 24 saat saklayın; tekrar ısıtmayı bir kez yapın.'], tips: ['Mezgit yumuşak etli, çocuklara uygun bir balıktır.'], storage: 'Hazırlandıktan hemen sonra tüketin.'),
  BabyRecipe(id: 'bb9_15', title: 'Kuskus ve sebze (bebek)', age: '10+', category: 'Tahıl', ingredient: 'kuskus', vegetable: 'havuç', ingredients: ['2 yemek kaşığı ince kuskus', '2 yemek kaşığı rendelenmiş havuç', 'Yarım su bardağı sıcak içme suyu', '1 çay kaşığı tereyağı'], steps: ['Ellerinizi, kesme tahtasını ve kapları sıcak sabunlu suyla yıkayın.', 'Havucu ince rendeleyin.', 'Küçük tencerede tereyağını eritip havucu 3 dakika pişirin.', 'Kuskusu ekleyip karıştırın.', 'Sıcak suyu ekleyip ocağı kapatın; kapağı kapalı 10 dakika demlendirin.', 'Çatalla kabartıp topakları dağıtın.', 'Tuz, şeker ve bal eklemeyin; 1 yaş altı bebeklere uygun değildir.', 'Ilıtıp sıcaklığı bileğinizin iç kısmına damlatarak kontrol edin; ılık olmalı, sıcak değil.'], tips: ['Kuskus buğday içerir.'], storage: 'Buzdolabında 24 saat; buz kalıbında 1 ay dondurulabilir.'),
  BabyRecipe(id: 'bb9_16', title: 'Muzlu yulaf pankek (bebek)', age: '10+', category: 'Kahvaltı', ingredient: 'yulaf', vegetable: 'muz', ingredients: ['Yarım muz', '1 yumurta', '3 yemek kaşığı ince yulaf'], steps: ['Ellerinizi, kesme tahtasını ve kapları sıcak sabunlu suyla yıkayın.', 'Muzu çatalla pürüzsüz ezin.', 'Yumurta ve yulafı ekleyip çırpın; 5 dakika bekletin.', 'Yapışmaz tavayı kısık ateşte ısıtın; kaşıkla küçük pankekler dökün.', 'Altı kızarınca çevirip diğer yüzünü 1–2 dakika pişirin.', 'Bir tanesini ortadan bölün: içinde akışkan yumurta kalmamalı.', 'Ilıtıp bebeğin tutabileceği şeritler halinde kesin.', 'Bebek yerken mutlaka yanında, dik oturur durumda olsun; ağzına sığmayacak büyüklükte parçalar verin.'], tips: ['Şeker eklemeyin; muz yeterli.'], storage: 'Buzdolabında 24 saat; buz kalıbında 1 ay dondurulabilir.'),
  BabyRecipe(id: 'bb9_17', title: 'Etli sebzeli güveç (bebek)', age: '10+', category: 'Et', ingredient: 'dana eti', vegetable: 'kabak', ingredients: ['40 g küçük doğranmış dana eti', 'Yarım kabak', 'Yarım havuç', '1 küçük patates', '1 su bardağı içme suyu'], steps: ['Ellerinizi, kesme tahtasını ve kapları sıcak sabunlu suyla yıkayın.', 'Eti küçük doğrayın; yağ ve sinirlerini ayıklayın.', 'Et ve suyu tencereye alıp kaynatın; köpüğünü alın.', 'Kapağı kapalı kısık ateşte 30 dakika pişirin.', 'Sebzeleri küçük doğrayıp ekleyin; 20 dakika daha pişirin.', 'Eti ortadan bölüp kontrol edin: içi pembe kalmamalı, suyu berrak akmalı.', 'Eti ince didikleyin; sebzelerle birlikte hafif ezin.', 'Tuz, şeker ve bal eklemeyin; 1 yaş altı bebeklere uygun değildir.', 'Ilıtıp sıcaklığı bileğinizin iç kısmına damlatarak kontrol edin; ılık olmalı, sıcak değil.', 'Kalanını bebeğin ağzı değmemiş kaşıkla ayırıp kapalı kapta buzdolabında 24 saat saklayın; tekrar ısıtmayı bir kez yapın.'], tips: ['Et lifleri çok ince olmalı.'], storage: 'Buzdolabında 24 saat; buz kalıbında 1 ay dondurulabilir.'),
  BabyRecipe(id: 'bb9_18', title: 'Pırasalı pirinç (bebek)', age: '10+', category: 'Tahıl', ingredient: 'pirinç', vegetable: 'pırasa', ingredients: ['2 yemek kaşığı pirinç', '2 yemek kaşığı ince doğranmış pırasa', '1 su bardağı içme suyu', '1 çay kaşığı zeytinyağı'], steps: ['Ellerinizi, kesme tahtasını ve kapları sıcak sabunlu suyla yıkayın.', 'Pırasanın beyaz kısmını boyuna yarıp katlarını iyice yıkayın; çok ince doğrayın.', 'Pirinci yıkayın.', 'Küçük tencerede zeytinyağıyla pırasayı 3 dakika yumuşatın.', 'Pirinç ve suyu ekleyin; kısık ateşte 20 dakika çok yumuşak pişirin.', 'Çatalla hafif ezin.', 'Tuz, şeker ve bal eklemeyin; 1 yaş altı bebeklere uygun değildir.', 'Ilıtıp sıcaklığı bileğinizin iç kısmına damlatarak kontrol edin; ılık olmalı, sıcak değil.', 'Kalanını bebeğin ağzı değmemiş kaşıkla ayırıp kapalı kapta buzdolabında 24 saat saklayın; tekrar ısıtmayı bir kez yapın.'], tips: ['Pırasayı iyice yıkayın.'], storage: 'Buzdolabında 24 saat; buz kalıbında 1 ay dondurulabilir.'),
  BabyRecipe(id: 'bb9_19', title: 'Yoğurtlu çilek ezmesi', age: '10+', category: 'Yoğurt', ingredient: 'yoğurt', vegetable: 'çilek', ingredients: ['3 yemek kaşığı yoğurt', '3 çilek'], steps: ['Ellerinizi, kesme tahtasını ve kapları sıcak sabunlu suyla yıkayın.', 'Çilekleri bol suda yıkayıp saplarını ayıklayın.', 'Çatalla iyice ezin.', 'Yoğurdu buzdolabından 10 dakika önce çıkarın; çok soğuk vermeyin.', 'Yoğurtla karıştırın.', 'Çilek bazı bebeklerde ağız çevresinde kızarıklık yapabilir; ilk kez veriyorsanız 3 gün gözlemleyin.', 'Tuz, şeker ve bal eklemeyin; 1 yaş altı bebeklere uygun değildir.', 'Hemen servis edin; kalanını saklamayın.'], tips: ['Çilek bazı bebeklerde kızarıklık yapabilir.'], storage: 'Hazırlandıktan hemen sonra tüketin.'),
  BabyRecipe(id: 'bb9_20', title: 'Sebzeli kinoa ezmesi', age: '10+', category: 'Tahıl', ingredient: 'kinoa', vegetable: 'havuç', ingredients: ['2 yemek kaşığı kinoa', '2 yemek kaşığı rendelenmiş havuç', '1 su bardağı içme suyu'], steps: ['Ellerinizi, kesme tahtasını ve kapları sıcak sabunlu suyla yıkayın.', 'Kinoayı ince süzgeçte bol suyla ovarak yıkayın; acımsı tadı giderir.', 'Havucu ince rendeleyin.', 'Kinoa, havuç ve suyu kaynatın; kısık ateşte 18 dakika pişirin.', 'Ocaktan alıp 5 dakika demlendirin.', 'Çatalla hafif ezin.', 'Tuz, şeker ve bal eklemeyin; 1 yaş altı bebeklere uygun değildir.', 'Ilıtıp sıcaklığı bileğinizin iç kısmına damlatarak kontrol edin; ılık olmalı, sıcak değil.', 'Kalanını bebeğin ağzı değmemiş kaşıkla ayırıp kapalı kapta buzdolabında 24 saat saklayın; tekrar ısıtmayı bir kez yapın.'], tips: ['Kinoa glutensizdir.'], storage: 'Buzdolabında 24 saat; buz kalıbında 1 ay dondurulabilir.'),
  BabyRecipe(id: 'bc12_01', title: 'Sebzeli tavuk köftesi (yumuşak)', age: '12+', category: 'Et', ingredient: 'tavuk kıyma', vegetable: 'kabak', ingredients: ['100 g tavuk kıyma', '2 yemek kaşığı rendelenmiş kabak (suyu sıkılmış)', '2 yemek kaşığı yulaf', '1 yumurta sarısı'], steps: ['Ellerinizi, kesme tahtasını ve kapları sıcak sabunlu suyla yıkayın.', 'Fırını 190°C’ye ısıtın; tepsiye yağlı kâğıt serin.', 'Kabağı rendeleyip avuçlarınızla suyunu iyice sıkın; köfte dağılmaz.', 'Tavuk kıyma, kabak, yulaf ve yumurta sarısını yoğurun; çiğ tavuğa dokunduktan sonra ellerinizi yıkayın.', 'Islak elle küçük yassı köfteler yapıp tepsiye dizin.', '18 dakika pişirin; yarısında çevirin.', 'Tavuk iç sıcaklığı 74°C olmalı; bir köfteyi ortadan bölün: içi pembe kalmamalı, suyu berrak akmalı.', 'Tepside 5 dakika dinlendirip ılıtın.', 'Buz kalıplarında dondurup 1 ay saklayabilirsiniz; buzdolabında çözdürüp bir kez ısıtın.'], tips: ['Tavuk kıyması mutlaka iyi pişmeli.'], storage: 'Buzdolabında 48 saat.'),
  BabyRecipe(id: 'bc12_02', title: 'Peynirli sebzeli makarna (çocuk)', age: '12+', category: 'Makarna', ingredient: 'makarna', vegetable: 'brokoli', ingredients: ['3 yemek kaşığı küçük makarna', '2 brokoli çiçeği', '1 yemek kaşığı rendelenmiş kaşar', '1 çay kaşığı tereyağı'], steps: ['Ellerinizi, kesme tahtasını ve kapları sıcak sabunlu suyla yıkayın.', 'Brokoliyi küçük çiçeklere ayırıp yıkayın.', 'Makarnayı tuzsuz kaynar suda paketteki süreden 2 dakika fazla, parmakla ezilecek kadar yumuşak haşlayın.', 'Brokoliyi makarnanın son 6 dakikasında aynı tencereye ekleyin.', 'Süzüp sıcakken tereyağı ve kaşarı ekleyip kaşar eriyene kadar karıştırın.', 'Brokoliyi küçük parçalara ayırın.', 'Kaşar ve lor pastörize sütten olmalı; tuzlu peyniri 1 saat suda bekletip tuzunu alın.', 'Ilıtıp sıcaklığı bileğinizin iç kısmına damlatarak kontrol edin; ılık olmalı, sıcak değil.', 'Kalanını kapalı kapta buzdolabında 2 gün saklayın; yalnızca bir kez ısıtın.'], tips: ['Kaşar az tuzlu tercih edilmeli.'], storage: 'Buzdolabında 24 saat.'),
  BabyRecipe(id: 'bc12_03', title: 'Muzlu yoğurtlu yulaf kasesi', age: '12+', category: 'Kahvaltı', ingredient: 'yulaf', vegetable: 'muz', ingredients: ['3 yemek kaşığı yulaf', 'Yarım su bardağı süt', 'Yarım muz', '2 yemek kaşığı yoğurt'], steps: ['Ellerinizi, kesme tahtasını ve kapları sıcak sabunlu suyla yıkayın.', 'Yulaf ve sütü küçük tencereye alın.', 'Kısık ateşte sürekli karıştırarak 5 dakika, yulaf yumuşayana kadar pişirin.', 'Ocaktan alıp 5 dakika ılıtın.', 'Muzu çatalla ezip yulafa karıştırın.', 'Yoğurdu buzdolabından 10 dakika önce çıkarın; çok soğuk vermeyin.', 'Yoğurdu üzerine koyup servis edin.', 'Şeker eklemeyin; tatlılığı olgun meyveden gelsin.', 'Ilıtıp sıcaklığı bileğinizin iç kısmına damlatarak kontrol edin; ılık olmalı, sıcak değil.'], tips: ['12 aydan sonra inek sütü kullanılabilir.'], storage: 'Hazırlandıktan hemen sonra tüketin.'),
  BabyRecipe(id: 'bc12_04', title: 'Fırında köfteli patates (çocuk)', age: '12+', category: 'Et', ingredient: 'dana kıyma', vegetable: 'patates', ingredients: ['100 g kıyma', '1 patates', '1 yemek kaşığı galeta unu', '1 domates'], steps: ['Kıyma ve galeta ununu yoğurup küçük köfteler yapın.', 'Patatesi küçük küp doğrayın.', 'Tepsiye köfte, patates ve domates dilimlerini dizin.', '190 °C\'de 25 dakika pişirin.', 'Küçük parçalara bölün.'], tips: ['Köfte içi pembe kalmamalı.'], storage: 'Buzdolabında 48 saat.'),
  BabyRecipe(id: 'bc12_05', title: 'Sebzeli kaşarlı omlet (çocuk)', age: '12+', category: 'Yumurta', ingredient: 'yumurta', vegetable: 'domates', ingredients: ['1 yumurta', '1 yemek kaşığı süt', '1 yemek kaşığı ince doğranmış domates', '1 yemek kaşığı rendelenmiş kaşar', '1 çay kaşığı tereyağı'], steps: ['Ellerinizi, kesme tahtasını ve kapları sıcak sabunlu suyla yıkayın.', 'Domatesin kabuğunu soyup çekirdeklerini ayıklayın ve ince doğrayın.', 'Yumurta ve sütü çırpın; domatesi ekleyin.', 'Tereyağını yapışmaz tavada kısık ateşte eritin; karışımı dökün.', 'Kapağı kapalı 3–4 dakika, üst yüzey tamamen katılaşana kadar pişirin.', 'Kaşarı serpip ikiye katlayın; 1 dakika daha pişirin.', 'Yumurtayı akı ve sarısı tamamen katılaşana kadar pişirin; akışkan bırakmayın.', 'Ilıyınca şeritler halinde kesin.', 'Kaşar ve lor pastörize sütten olmalı; tuzlu peyniri 1 saat suda bekletip tuzunu alın.'], tips: ['Domatesin kabuğunu soyun.'], storage: 'Hazırlandıktan hemen sonra tüketin.'),
  BabyRecipe(id: 'bc12_06', title: 'Mercimek çorbası (çocuk)', age: '12+', category: 'Çorba', ingredient: 'kırmızı mercimek', vegetable: 'havuç', ingredients: ['3 yemek kaşığı kırmızı mercimek', 'Yarım havuç', 'Yarım patates', '1 çay kaşığı tereyağı', '1,5 su bardağı su'], steps: ['Ellerinizi, kesme tahtasını ve kapları sıcak sabunlu suyla yıkayın.', 'Mercimeği suyu berraklaşana kadar yıkayın.', 'Havuç ve patatesi soyup küçük doğrayın.', 'Mercimek, sebzeler ve suyu tencereye alıp kaynatın; köpüğünü alın.', 'Kısık ateşte ara ara karıştırarak 20 dakika, mercimek dağılana kadar pişirin.', 'Blenderdan geçirin; koyuysa sıcak su ekleyin.', 'Tereyağını ekleyip karıştırın.', 'Tuz eklemeyin; 1–3 yaş için günlük tuz 2 g’ı geçmemeli, peynir ve salça zaten tuz içerir.', 'Ilıtıp sıcaklığı bileğinizin iç kısmına damlatarak kontrol edin; ılık olmalı, sıcak değil.', 'Buz kalıplarında dondurup 1 ay saklayabilirsiniz; buzdolabında çözdürüp bir kez ısıtın.'], tips: ['Az kimyon ekleyebilirsiniz.'], storage: 'Buzdolabında 48 saat.'),
  BabyRecipe(id: 'bc12_07', title: 'Fırında kabak mücveri (çocuk, tuzsuz)', age: '12+', category: 'Fırın', ingredient: 'kabak', vegetable: 'kabak', ingredients: ['1 kabak (rendelenmiş, suyu sıkılmış)', '1 yumurta', '2 yemek kaşığı un', '1 yemek kaşığı lor', 'Birkaç dal dereotu'], steps: ['Ellerinizi, kesme tahtasını ve kapları sıcak sabunlu suyla yıkayın.', 'Fırını 190°C’ye ısıtın; tepsiye yağlı kâğıt serin.', 'Kabağı rendeleyip avuçlarınızla suyunu iyice sıkın.', 'Kabak, yumurta, un, lor ve ince kıyılmış dereotunu karıştırın.', 'Kaşıkla tepsiye küçük yuvarlaklar bırakıp hafifçe bastırın.', '20 dakika, üstü hafif kızarıp ortası sertleşene kadar pişirin.', 'Yumurtayı akı ve sarısı tamamen katılaşana kadar pişirin; akışkan bırakmayın.', 'Kaşar ve lor pastörize sütten olmalı; tuzlu peyniri 1 saat suda bekletip tuzunu alın.', 'Tepside 5 dakika dinlendirip ılıtın.', 'Kalanını kapalı kapta buzdolabında 2 gün saklayın; yalnızca bir kez ısıtın.'], tips: ['Kızartma yerine fırın tercih edin.'], storage: 'Buzdolabında 48 saat.'),
  BabyRecipe(id: 'bc12_08', title: 'Ballı yoğurtlu meyve (12 ay+)', age: '12+', category: 'Yoğurt', ingredient: 'yoğurt', vegetable: 'şeftali', ingredients: ['4 yemek kaşığı yoğurt', 'Yarım şeftali (küçük doğranmış)', '1 çay kaşığı bal'], steps: ['Ellerinizi, kesme tahtasını ve kapları sıcak sabunlu suyla yıkayın.', 'Şeftaliyi yıkayıp kabuğunu soyun ve çekirdeğini çıkarın.', 'Çocuğun kolayca çiğneyebileceği küçük parçalara doğrayın.', 'Yoğurdu buzdolabından 10 dakika önce çıkarın; çok soğuk vermeyin.', 'Yoğurtla karıştırın.', 'Balı ekleyip karıştırın.', 'Bal yalnızca 1 yaşını doldurmuş çocuklara verilebilir; günde 1 çay kaşığını geçmeyin.', 'Hemen servis edin; kalanını saklamayın.'], tips: ['Bal ancak 12 aydan sonra verilebilir.'], storage: 'Hazırlandıktan hemen sonra tüketin.'),
  BabyRecipe(id: 'bc12_09', title: 'Sebzeli bulgur pilavı (çocuk)', age: '12+', category: 'Tahıl', ingredient: 'bulgur', vegetable: 'havuç', ingredients: ['3 yemek kaşığı bulgur', '2 yemek kaşığı küçük doğranmış havuç ve bezelye', '1 çay kaşığı tereyağı', 'Yarım su bardağı su'], steps: ['Ellerinizi, kesme tahtasını ve kapları sıcak sabunlu suyla yıkayın.', 'Havucu küçük doğrayın; bulguru yıkayıp süzün.', 'Tereyağını küçük tencerede eritip havuç ve bezelyeyi 3 dakika çevirin.', 'Bulgur ve suyu ekleyin; kaynayınca kısık ateşte kapağı kapalı 12 dakika pişirin.', 'Ocağı kapatıp kapağın altına kâğıt havlu koyarak 10 dakika demlendirin.', 'Yuvarlak ve sert parçaları (bezelye, nohut, üzüm gibi) ezin ya da dörde bölün.', 'Ilıtıp sıcaklığı bileğinizin iç kısmına damlatarak kontrol edin; ılık olmalı, sıcak değil.', 'Kalanını kapalı kapta buzdolabında 2 gün saklayın; yalnızca bir kez ısıtın.'], tips: ['Bezelyeleri hafif ezin.'], storage: 'Buzdolabında 48 saat.'),
  BabyRecipe(id: 'bc12_10', title: 'Elmalı tarçınlı krep (çocuk)', age: '12+', category: 'Kahvaltı', ingredient: 'un', vegetable: 'elma', ingredients: ['1 yumurta', '3 yemek kaşığı un', '4 yemek kaşığı süt', 'Yarım elma (rendelenmiş)', '1 tutam tarçın'], steps: ['Ellerinizi, kesme tahtasını ve kapları sıcak sabunlu suyla yıkayın.', 'Elmayı soyup ince rendeleyin.', 'Yumurta, un, süt, elma ve tarçını pürüzsüz çırpın; 5 dakika dinlendirin.', 'Yapışmaz tavayı kısık ateşte ısıtıp tereyağıyla hafifçe yağlayın.', 'Bir kepçe hamuru döküp tavayı çevirerek yayın; altı kızarınca çevirip 1 dakika daha pişirin.', 'Krepleri rulo yapıp çocuğun tutabileceği küçük parçalara kesin.', 'Şeker eklemeyin; tatlılığı olgun meyveden gelsin.', 'Ilıtıp sıcaklığı bileğinizin iç kısmına damlatarak kontrol edin; ılık olmalı, sıcak değil.', 'Kalanını kapalı kapta buzdolabında 2 gün saklayın; yalnızca bir kez ısıtın.'], tips: ['Şeker gerekmez.'], storage: 'Buzdolabında 24 saat.'),
  BabyRecipe(id: 'bc12_11', title: 'Tavuklu sebzeli pirinç (çocuk)', age: '12+', category: 'Et', ingredient: 'tavuk', vegetable: 'bezelye', ingredients: ['40 g haşlanmış tavuk', '3 yemek kaşığı pirinç', '2 yemek kaşığı bezelye', '1 çay kaşığı tereyağı', 'Yarım su bardağı tavuk suyu (tuzsuz)'], steps: ['Ellerinizi, kesme tahtasını ve kapları sıcak sabunlu suyla yıkayın.', 'Pirinci suyu berraklaşana kadar yıkayıp süzün.', 'Tereyağını küçük tencerede eritip pirinci 1 dakika çevirin.', 'Tavuk suyu ve bezelyeyi ekleyin; kaynayınca kısık ateşte kapağı kapalı 15 dakika pişirin.', 'Haşlanmış tavuğu ince didikleyip ekleyin; ocağı kapatıp 5 dakika demlendirin.', 'Yuvarlak ve sert parçaları (bezelye, nohut, üzüm gibi) ezin ya da dörde bölün.', 'Ilıtıp sıcaklığı bileğinizin iç kısmına damlatarak kontrol edin; ılık olmalı, sıcak değil.', 'Kalanını kapalı kapta buzdolabında 2 gün saklayın; yalnızca bir kez ısıtın.'], tips: ['Hazır et suyu tabletleri tuzludur; kullanmayın.'], storage: 'Buzdolabında 24 saat.'),
  BabyRecipe(id: 'bc12_12', title: 'Somonlu sebzeli makarna (çocuk)', age: '12+', category: 'Balık', ingredient: 'somon', vegetable: 'kabak', ingredients: ['3 yemek kaşığı küçük makarna', '40 g somon', '2 yemek kaşığı rendelenmiş kabak', '1 yemek kaşığı yoğurt'], steps: ['Ellerinizi, kesme tahtasını ve kapları sıcak sabunlu suyla yıkayın.', 'Makarnayı tuzsuz kaynar suda paketteki süreden 2 dakika fazla, parmakla ezilecek kadar yumuşak haşlayın.', 'Somonu buhar sepetinde 8–10 dakika pişirin.', 'Balığı parmaklarınızla yoklayarak tüm kılçıkları ayıklayın; et opaklaşıp kolayca dağılıyorsa pişmiştir.', 'Kabağı tavada 1 kaşık suyla 2 dakika yumuşatın.', 'Makarna, ufalanmış somon ve kabağı karıştırın.', 'Yoğurdu buzdolabından 10 dakika önce çıkarın; çok soğuk vermeyin.', 'Ilıyınca yoğurdu ekleyip servis edin; yoğurdu sıcak yemeğe eklerseniz kesilir.', 'Kalanını kapalı kapta buzdolabında 2 gün saklayın; yalnızca bir kez ısıtın.'], tips: ['Kılçığı iki kez kontrol edin.'], storage: 'Hazırlandıktan hemen sonra tüketin.'),
  BabyRecipe(id: 'bc12_13', title: 'Patatesli peynirli toplar', age: '12+', category: 'Fırın', ingredient: 'patates', vegetable: 'patates', ingredients: ['2 haşlanmış patates', '2 yemek kaşığı rendelenmiş kaşar', '1 yumurta sarısı', '1 yemek kaşığı un'], steps: ['Ellerinizi, kesme tahtasını ve kapları sıcak sabunlu suyla yıkayın.', 'Fırını 190°C’ye ısıtın; tepsiye yağlı kâğıt serin.', 'Haşlanmış patatesleri sıcakken çatalla pürüzsüz ezin.', 'Ilıyınca kaşar, yumurta sarısı ve unu ekleyip yoğurun.', 'Ceviz büyüklüğünde toplar yapıp tepsiye dizin ve hafifçe bastırın.', '20 dakika, altları hafif kızarana kadar pişirin.', 'Kaşar ve lor pastörize sütten olmalı; tuzlu peyniri 1 saat suda bekletip tuzunu alın.', 'Tepside 5 dakika dinlendirip ılıtın.', 'Buz kalıplarında dondurup 1 ay saklayabilirsiniz; buzdolabında çözdürüp bir kez ısıtın.'], tips: ['Bebeğin avucuna sığacak boyutta yapın.'], storage: 'Buzdolabında 48 saat.'),
  BabyRecipe(id: 'bc12_14', title: 'Ispanaklı yumurtalı krep', age: '12+', category: 'Yumurta', ingredient: 'yumurta', vegetable: 'ıspanak', ingredients: ['1 yumurta', '2 yemek kaşığı un', '3 yemek kaşığı süt', '2 yemek kaşığı haşlanmış ıspanak (kıyılmış)'], steps: ['Ellerinizi, kesme tahtasını ve kapları sıcak sabunlu suyla yıkayın.', 'Haşlanmış ıspanağı iyice sıkıp çok ince kıyın.', 'Yumurta, un, süt ve ıspanağı pürüzsüz çırpın; 5 dakika dinlendirin.', 'Yapışmaz tavayı kısık ateşte ısıtıp tereyağıyla hafifçe yağlayın.', 'Bir kepçe hamuru döküp yayın; altı pişince çevirip 1 dakika daha pişirin.', 'Yumurtayı akı ve sarısı tamamen katılaşana kadar pişirin; akışkan bırakmayın.', 'Rulo yapıp küçük parçalara kesin.', 'Ilıtıp sıcaklığı bileğinizin iç kısmına damlatarak kontrol edin; ılık olmalı, sıcak değil.', 'Kalanını kapalı kapta buzdolabında 2 gün saklayın; yalnızca bir kez ısıtın.'], tips: ['Ispanak demir sağlar.'], storage: 'Buzdolabında 24 saat.'),
  BabyRecipe(id: 'bc12_15', title: 'Fırında havuç parmakları', age: '12+', category: 'Sebze', ingredient: 'havuç', vegetable: 'havuç', ingredients: ['2 havuç', '1 çay kaşığı zeytinyağı', '1 tutam kimyon'], steps: ['Ellerinizi, kesme tahtasını ve kapları sıcak sabunlu suyla yıkayın.', 'Fırını 200°C’ye ısıtın; tepsiye yağlı kâğıt serin.', 'Havuçları soyup çocuğun tutabileceği uzunlukta, parmak kalınlığında çubuklar kesin.', 'Zeytinyağı ve kimyonla harmanlayıp tepsiye aralıklı dizin.', '25 dakika pişirin; yarısında çevirin.', 'Parmaklarınızla bastırın: kolayca eziliyorsa hazırdır; sert havuç boğulma riski taşır.', 'Tepside 5 dakika dinlendirip ılıtın.', 'Çocuk yerken yanında olun; dik otursun, yürürken ya da koşarken yemesin.', 'Kalanını kapalı kapta buzdolabında 2 gün saklayın; yalnızca bir kez ısıtın.'], tips: ['Çiğ havuç boğulma riski taşır; pişmiş verin.'], storage: 'Buzdolabında 48 saat.'),
  BabyRecipe(id: 'bc12_16', title: 'Mercimekli bulgur köftesi (yumuşak, çocuk)', age: '12+', category: 'Baklagil', ingredient: 'kırmızı mercimek', vegetable: 'domates', ingredients: ['3 yemek kaşığı kırmızı mercimek', '2 yemek kaşığı ince bulgur', '1 çay kaşığı domates salçası', '1 çay kaşığı zeytinyağı', 'Birkaç dal maydanoz'], steps: ['Ellerinizi, kesme tahtasını ve kapları sıcak sabunlu suyla yıkayın.', 'Mercimeği yıkayıp 1 su bardağı suyla dağılana kadar 15 dakika pişirin.', 'Ocağı kapatıp bulguru ekleyin; kapağı kapalı 15 dakika şişirin.', 'Salça, zeytinyağı ve ince kıyılmış maydanozu ekleyin.', 'Ilıyınca 3–4 dakika yoğurun; çok yumuşaksa 1 kaşık bulgur ekleyip 5 dakika bekletin.', 'Çocuğun avucuna sığacak küçük yassı köfteler yapın.', 'Tuz eklemeyin; 1–3 yaş için günlük tuz 2 g’ı geçmemeli, peynir ve salça zaten tuz içerir.', 'Çocuk yerken yanında olun; dik otursun, yürürken ya da koşarken yemesin.', 'Kalanını kapalı kapta buzdolabında 2 gün saklayın; yalnızca bir kez ısıtın.'], tips: ['Acı biber kullanmayın.'], storage: 'Buzdolabında 48 saat.'),
  BabyRecipe(id: 'bc12_17', title: 'Yoğurtlu makarna (çocuk)', age: '12+', category: 'Makarna', ingredient: 'makarna', vegetable: '—', ingredients: ['3 yemek kaşığı küçük makarna', '3 yemek kaşığı yoğurt', '1 çay kaşığı tereyağı'], steps: ['Ellerinizi, kesme tahtasını ve kapları sıcak sabunlu suyla yıkayın.', 'Makarnayı tuzsuz kaynar suda paketteki süreden 2 dakika fazla, parmakla ezilecek kadar yumuşak haşlayın.', 'Süzüp sıcakken tereyağıyla karıştırın.', 'Yoğurdu buzdolabından 10 dakika önce çıkarın; çok soğuk vermeyin.', 'Makarna ılıyınca yoğurdu ekleyin; sıcakken eklerseniz yoğurt kesilir.', 'İsterseniz üzerine çok az kuru nane serpin.', 'Ilıtıp sıcaklığı bileğinizin iç kısmına damlatarak kontrol edin; ılık olmalı, sıcak değil.', 'Kalanını kapalı kapta buzdolabında 2 gün saklayın; yalnızca bir kez ısıtın.'], tips: ['Sarımsak eklemeyin; bebek midesini rahatsız edebilir.'], storage: 'Hazırlandıktan hemen sonra tüketin.'),
  BabyRecipe(id: 'bc12_18', title: 'Kayısılı yulaf topları', age: '12+', category: 'Kahvaltı', ingredient: 'yulaf', vegetable: 'kayısı', ingredients: ['4 kuru kayısı (ıslatılmış)', '4 yemek kaşığı yulaf', '1 yemek kaşığı tahin'], steps: ['Ellerinizi, kesme tahtasını ve kapları sıcak sabunlu suyla yıkayın.', 'Kuru kayısıları 30 dakika ılık suda bekletip süzün.', 'Kayısıları çok ince kıyın.', 'Yulaf ve tahinle yoğurun; kuru kalırsa 1 kaşık su ekleyin.', 'Fındık büyüklüğünde toplar yapıp avucunuzda yassılaştırın; yuvarlak toplar boğazda takılabilir.', 'Susam alerjisi açısından tahini ilk kez veriyorsanız az miktarla başlayıp gözlemleyin.', 'Çocuk yerken yanında olun; dik otursun, yürürken ya da koşarken yemesin.', 'Kapalı kapta buzdolabında 3 gün saklayın.'], tips: ['Toplar yumuşak olmalı.'], storage: 'Buzdolabında 48 saat.'),
  BabyRecipe(id: 'bc12_19', title: 'Etli sebze çorbası (çocuk)', age: '12+', category: 'Çorba', ingredient: 'dana eti', vegetable: 'patates', ingredients: ['40 g dana eti', '1 küçük patates', 'Yarım havuç', 'Yarım kabak', '2 su bardağı su'], steps: ['Ellerinizi, kesme tahtasını ve kapları sıcak sabunlu suyla yıkayın.', 'Eti küçük doğrayıp yağ ve sinirlerini ayıklayın.', 'Et ve suyu tencereye alıp kaynatın; köpüğünü alın.', 'Kapağı kapalı kısık ateşte 30 dakika pişirin.', 'Patates, havuç ve kabağı küçük doğrayıp ekleyin; 20 dakika daha pişirin.', 'Eti ince didikleyin; içi pembe kalmamalı.', 'Blenderdan geçirmeden çatalla hafif ezin; çiğneme becerisini geliştirir.', 'Tuz eklemeyin; 1–3 yaş için günlük tuz 2 g’ı geçmemeli, peynir ve salça zaten tuz içerir.', 'Ilıtıp sıcaklığı bileğinizin iç kısmına damlatarak kontrol edin; ılık olmalı, sıcak değil.', 'Buz kalıplarında dondurup 1 ay saklayabilirsiniz; buzdolabında çözdürüp bir kez ısıtın.'], tips: ['Çiğneme becerisi için hafif parçalı bırakın.'], storage: 'Buzdolabında 48 saat.'),
  BabyRecipe(id: 'bc12_20', title: 'Muzlu tarçınlı ekmek (çocuk)', age: '12+', category: 'Fırın', ingredient: 'un', vegetable: 'muz', ingredients: ['2 olgun muz', '1 yumurta', '1 su bardağı tam buğday unu', '1 çay kaşığı kabartma tozu', '2 yemek kaşığı zeytinyağı', '1 tutam tarçın'], steps: ['Ellerinizi, kesme tahtasını ve kapları sıcak sabunlu suyla yıkayın.', 'Fırını 175°C’ye ısıtın; küçük kek kalıbına yağlı kâğıt serin.', 'Kabuğu kahverengi benekli olgun muzları çatalla ezin.', 'Yumurta ve zeytinyağını ekleyip çırpın.', 'Un, kabartma tozu ve tarçını ekleyip sadece karışana kadar karıştırın; fazla karıştırmak keki sertleştirir.', 'Kalıba döküp 35 dakika pişirin; ortasına batırdığınız kürdan temiz çıkmalı.', 'Kalıpta 10 dakika, tel ızgarada tamamen soğutun.', 'Şeker eklemeyin; tatlılığı olgun meyveden gelsin.', 'Kapalı kapta 2 gün saklayın ya da dilimleyip 1 ay dondurun.'], tips: ['Şekersizdir; tatlılık muzdan gelir.'], storage: 'Hava almayan kapta 2 gün.'),
  BabyRecipe(id: 'bc12_21', title: 'Sebzeli kinoa köftesi', age: '12+', category: 'Tahıl', ingredient: 'kinoa', vegetable: 'havuç', ingredients: ['4 yemek kaşığı pişmiş kinoa', '2 yemek kaşığı rendelenmiş havuç', '1 yumurta', '2 yemek kaşığı yulaf'], steps: ['Ellerinizi, kesme tahtasını ve kapları sıcak sabunlu suyla yıkayın.', 'Fırını 190°C’ye ısıtın; tepsiye yağlı kâğıt serin.', 'Havucu ince rendeleyin.', 'Pişmiş kinoa, havuç, yumurta ve yulafı yoğurun; 10 dakika dinlendirin.', 'Islak elle küçük yassı köfteler yapıp tepsiye dizin.', '20 dakika pişirin; yarısında çevirin.', 'Yumurtayı akı ve sarısı tamamen katılaşana kadar pişirin; akışkan bırakmayın.', 'Tepside 5 dakika dinlendirip ılıtın.', 'Buz kalıplarında dondurup 1 ay saklayabilirsiniz; buzdolabında çözdürüp bir kez ısıtın.'], tips: ['Glutensiz köfte için yulafı glutensiz seçin.'], storage: 'Buzdolabında 48 saat.'),
  BabyRecipe(id: 'bc12_22', title: 'Fırında elmalı yulaf (çocuk)', age: '12+', category: 'Kahvaltı', ingredient: 'yulaf', vegetable: 'elma', ingredients: ['4 yemek kaşığı yulaf', 'Yarım elma', 'Yarım su bardağı süt', '1 tutam tarçın'], steps: ['Ellerinizi, kesme tahtasını ve kapları sıcak sabunlu suyla yıkayın.', 'Fırını 180°C’ye ısıtın.', 'Elmayı soyup rendeleyin.', 'Yulaf, elma, süt ve tarçını küçük fırın kabında karıştırın.', '20 dakika, üstü hafif kızarıp sıvı çekilene kadar pişirin.', '5 dakika dinlendirin; ortası çok sıcak kalır.', 'Şeker eklemeyin; tatlılığı olgun meyveden gelsin.', 'Ilıtıp sıcaklığı bileğinizin iç kısmına damlatarak kontrol edin; ılık olmalı, sıcak değil.', 'Kalanını kapalı kapta buzdolabında 2 gün saklayın; yalnızca bir kez ısıtın.'], tips: ['Kahvaltıyı önceden hazırlamak için idealdir.'], storage: 'Buzdolabında 24 saat.'),
  BabyRecipe(id: 'bc12_23', title: 'Brokolili peynirli toplar', age: '12+', category: 'Fırın', ingredient: 'brokoli', vegetable: 'brokoli', ingredients: ['1 su bardağı haşlanmış brokoli (kıyılmış)', '2 yemek kaşığı rendelenmiş kaşar', '1 yumurta', '3 yemek kaşığı galeta unu'], steps: ['Ellerinizi, kesme tahtasını ve kapları sıcak sabunlu suyla yıkayın.', 'Fırını 190°C’ye ısıtın; tepsiye yağlı kâğıt serin.', 'Haşlanmış brokoliyi süzüp çok ince kıyın.', 'Brokoli, kaşar, yumurta ve galeta ununu karıştırın; 5 dakika dinlendirin.', 'Ceviz büyüklüğünde toplar yapıp hafifçe yassılaştırın.', '20 dakika pişirin; yarısında çevirin.', 'Yumurtayı akı ve sarısı tamamen katılaşana kadar pişirin; akışkan bırakmayın.', 'Kaşar ve lor pastörize sütten olmalı; tuzlu peyniri 1 saat suda bekletip tuzunu alın.', 'Tepside 5 dakika dinlendirip ılıtın.', 'Buz kalıplarında dondurup 1 ay saklayabilirsiniz; buzdolabında çözdürüp bir kez ısıtın.'], tips: ['Sebze sevmeyen çocuklar için iyi bir yöntemdir.'], storage: 'Buzdolabında 48 saat.'),
  BabyRecipe(id: 'bc12_24', title: 'Pırasalı patates çorbası (çocuk)', age: '12+', category: 'Çorba', ingredient: 'patates', vegetable: 'pırasa', ingredients: ['1 patates', '2 yemek kaşığı pırasa', '1 çay kaşığı tereyağı', '1,5 su bardağı su', '2 yemek kaşığı süt'], steps: ['Ellerinizi, kesme tahtasını ve kapları sıcak sabunlu suyla yıkayın.', 'Pırasanın beyaz kısmını boyuna yarıp katlarını iyice yıkayın; ince doğrayın.', 'Patatesi soyup küçük küp doğrayın.', 'Tereyağını tencerede eritip pırasayı 3 dakika yumuşatın.', 'Patates ve suyu ekleyin; kaynayınca kısık ateşte 15 dakika pişirin.', 'Blenderdan geçirin; sütü ekleyip 1 dakika ısıtın, kaynatmayın.', 'Tuz eklemeyin; 1–3 yaş için günlük tuz 2 g’ı geçmemeli, peynir ve salça zaten tuz içerir.', 'Ilıtıp sıcaklığı bileğinizin iç kısmına damlatarak kontrol edin; ılık olmalı, sıcak değil.', 'Kalanını kapalı kapta buzdolabında 2 gün saklayın; yalnızca bir kez ısıtın.'], tips: ['Kremamsı ve hafif bir çorbadır.'], storage: 'Buzdolabında 48 saat.'),
  BabyRecipe(id: 'bd18_01', title: 'Tavuklu sebzeli sote (çocuk)', age: '18+', category: 'Et', ingredient: 'tavuk', vegetable: 'havuç', ingredients: ['60 g tavuk göğsü', 'Yarım havuç', 'Yarım kabak', '1 yemek kaşığı rendelenmiş domates', '1 çay kaşığı zeytinyağı'], steps: ['Ellerinizi, kesme tahtasını ve kapları sıcak sabunlu suyla yıkayın.', 'Çiğ eti ve tavuğu ayrı tahtada doğrayın; ardından tahtayı ve ellerinizi yıkayın.', 'Tavuğu küçük küp doğrayın; havuç ve kabağı tavuktan küçük doğrayın.', 'Zeytinyağını tavada ısıtıp tavuğu 6–7 dakika, her yüzü beyazlayana kadar pişirin.', 'Sebzeleri ekleyip 2 dakika çevirin; domatesi ilave edin.', 'Kapağı kapalı kısık ateşte 10 dakika pişirin; gerekirse 2 kaşık su ekleyin.', 'Tavuk iç sıcaklığı 74°C olmalı; en büyük parçayı bölüp pembe kalmadığını kontrol edin.', 'Pilavla ılık servis edin.', 'Kalanını kapalı kapta buzdolabında 2 gün saklayın; yalnızca bir kez ısıtın.'], tips: ['Sebzeleri küçük doğrayın.'], storage: 'Buzdolabında 48 saat.'),
  BabyRecipe(id: 'bd18_02', title: 'Fırında sebzeli balık köftesi', age: '18+', category: 'Balık', ingredient: 'mezgit', vegetable: 'patates', ingredients: ['100 g kılçıksız mezgit', '1 haşlanmış patates', '1 yemek kaşığı rendelenmiş havuç', '1 yumurta sarısı', '2 yemek kaşığı galeta unu'], steps: ['Ellerinizi, kesme tahtasını ve kapları sıcak sabunlu suyla yıkayın.', 'Fırını 200°C’ye ısıtın; tepsiye yağlı kâğıt serin.', 'Mezgiti buhar sepetinde 8 dakika pişirin.', 'Balığı parmaklarınızla yoklayarak tüm kılçıkları ayıklayın; et opaklaşıp kolayca dağılıyorsa pişmiştir.', 'Balığı haşlanmış patatesle çatalla ezin; havuç ve yumurta sarısını ekleyip yoğurun.', 'Küçük köfteler yapıp galeta ununa bulayın ve tepsiye dizin.', '15 dakika pişirin; yarısında çevirin.', 'Tepside 5 dakika dinlendirip ılıtın.', 'Buz kalıplarında dondurup 1 ay saklayabilirsiniz; buzdolabında çözdürüp bir kez ısıtın.'], tips: ['Kılçık kontrolünü atlamayın.'], storage: 'Buzdolabında 24 saat.'),
  BabyRecipe(id: 'bd18_03', title: 'Kıymalı ıspanak (çocuk)', age: '18+', category: 'Et', ingredient: 'dana kıyma', vegetable: 'ıspanak', ingredients: ['50 g kıyma', '1 su bardağı doğranmış ıspanak', '1 yemek kaşığı pirinç', '1 çay kaşığı salça', 'Yarım su bardağı su'], steps: ['Ellerinizi, kesme tahtasını ve kapları sıcak sabunlu suyla yıkayın.', 'Ispanağı bol suda birkaç kez yıkayıp ince doğrayın; pirinci yıkayın.', 'Kıymayı kaşıkla dağıtarak 5 dakika, rengi tamamen dönene kadar pişirin.', 'Salçayı ekleyip 1 dakika çevirin.', 'Ispanak, pirinç ve suyu ekleyin; kapağı kapalı kısık ateşte 15 dakika, pirinç yumuşayana kadar pişirin.', 'Kıymada pembe kalmadığını kontrol edin.', 'Yoğurdu buzdolabından 10 dakika önce çıkarın; çok soğuk vermeyin.', 'Ilıyınca yoğurtla servis edin.', 'Tuz eklemeyin; 1–3 yaş için günlük tuz 2 g’ı geçmemeli, peynir ve salça zaten tuz içerir.', 'Kalanını kapalı kapta buzdolabında 2 gün saklayın; yalnızca bir kez ısıtın.'], tips: ['Demir ve C vitamini birlikte emilimi artırır.'], storage: 'Buzdolabında 48 saat.'),
  BabyRecipe(id: 'bd18_04', title: 'Mini sebzeli pizza (lavaştan, çocuk)', age: '18+', category: 'Fırın', ingredient: 'lavaş', vegetable: 'mısır', ingredients: ['1 küçük lavaş', '2 yemek kaşığı rendelenmiş domates', '2 yemek kaşığı rendelenmiş kaşar', '1 yemek kaşığı mısır'], steps: ['Ellerinizi, kesme tahtasını ve kapları sıcak sabunlu suyla yıkayın.', 'Fırını 200°C’ye ısıtın; tepsiye yağlı kâğıt serin.', 'Lavaştan bir bardak yardımıyla küçük daireler kesin.', 'Domatesi rendeleyip suyunu biraz süzün; ıslak harç lavaşı yumuşatır.', 'Daireleri tepsiye dizip domates sürün; kaşar ve mısırı serpin.', 'Mısır taneleri boğulma riski taşır; ince kıyın ya da hafifçe ezin.', '8 dakika, kaşar eriyene kadar pişirin.', 'Ilıtıp çocuğun tutabileceği dilimlere kesin.', 'Kaşar ve lor pastörize sütten olmalı; tuzlu peyniri 1 saat suda bekletip tuzunu alın.'], tips: ['Mısırları hafif ezin.'], storage: 'Aynı gün.'),
  BabyRecipe(id: 'bd18_05', title: 'Etli nohut (çocuk)', age: '18+', category: 'Baklagil', ingredient: 'nohut', vegetable: 'domates', ingredients: ['3 yemek kaşığı haşlanmış nohut (kabuksuz)', '40 g kuşbaşı (küçük)', '1 çay kaşığı salça', '1 su bardağı su', '1 çay kaşığı tereyağı'], steps: ['Ellerinizi, kesme tahtasını ve kapları sıcak sabunlu suyla yıkayın.', 'Çiğ eti ve tavuğu ayrı tahtada doğrayın; ardından tahtayı ve ellerinizi yıkayın.', 'Tereyağını tencerede eritip eti 10 dakika, kendi suyunu çekene kadar kavurun.', 'Salçayı ekleyip 1 dakika çevirin.', 'Nohut ve suyu ekleyin; kapağı kapalı kısık ateşte 30 dakika, et yumuşayana kadar pişirin.', 'Eti ince didikleyin; içi pembe kalmamalı.', 'Nohutları çatalla ezin ya da dörde bölün; bütün nohut boğulma riski taşır.', 'Tuz eklemeyin; 1–3 yaş için günlük tuz 2 g’ı geçmemeli, peynir ve salça zaten tuz içerir.', 'Ilıtıp sıcaklığı bileğinizin iç kısmına damlatarak kontrol edin; ılık olmalı, sıcak değil.', 'Buz kalıplarında dondurup 1 ay saklayabilirsiniz; buzdolabında çözdürüp bir kez ısıtın.'], tips: ['Nohutu ezmek boğulma riskini azaltır.'], storage: 'Buzdolabında 48 saat.'),
  BabyRecipe(id: 'bd18_06', title: 'Sebzeli erişte (çocuk)', age: '18+', category: 'Makarna', ingredient: 'erişte', vegetable: 'havuç', ingredients: ['Yarım su bardağı erişte', '2 yemek kaşığı rendelenmiş havuç', '2 yemek kaşığı bezelye', '1 çay kaşığı tereyağı'], steps: ['Ellerinizi, kesme tahtasını ve kapları sıcak sabunlu suyla yıkayın.', 'Erişteyi tuzsuz kaynar suda 10–12 dakika, iyice yumuşayana kadar haşlayıp süzün.', 'Tereyağını tavada eritip havuç ve bezelyeyi 4–5 dakika yumuşatın; 2 kaşık su ekleyebilirsiniz.', 'Erişteyi ekleyip karıştırın.', 'Uzun erişteleri 2–3 cm boyunda kesin.', 'Yuvarlak ve sert parçaları (bezelye, nohut, üzüm gibi) ezin ya da dörde bölün.', 'Ilıtıp sıcaklığı bileğinizin iç kısmına damlatarak kontrol edin; ılık olmalı, sıcak değil.', 'Kalanını kapalı kapta buzdolabında 2 gün saklayın; yalnızca bir kez ısıtın.'], tips: ['Uzun erişteleri kesin.'], storage: 'Buzdolabında 24 saat.'),
  BabyRecipe(id: 'bd18_07', title: 'Yoğurtlu kabak çorbası (çocuk)', age: '18+', category: 'Çorba', ingredient: 'yoğurt', vegetable: 'kabak', ingredients: ['1 kabak', '1 küçük patates', '3 yemek kaşığı yoğurt', '1,5 su bardağı su', '1 çay kaşığı tereyağı'], steps: ['Ellerinizi, kesme tahtasını ve kapları sıcak sabunlu suyla yıkayın.', 'Kabak ve patatesi soyup küçük doğrayın.', 'Sebzeleri suyla kaynatın; kısık ateşte 15 dakika yumuşayana kadar pişirin.', 'Tereyağını ekleyip blenderdan geçirin.', '5 dakika ılıtın.', 'Yoğurdu buzdolabından 10 dakika önce çıkarın; çok soğuk vermeyin.', 'Yoğurdu birkaç kaşık çorbayla ılıştırıp çorbaya ekleyin; tekrar kaynatmayın, kesilir.', 'Tuz eklemeyin; 1–3 yaş için günlük tuz 2 g’ı geçmemeli, peynir ve salça zaten tuz içerir.', 'Ilıtıp sıcaklığı bileğinizin iç kısmına damlatarak kontrol edin; ılık olmalı, sıcak değil.'], tips: ['Yoğurdu kaynatmayın.'], storage: 'Buzdolabında 24 saat.'),
  BabyRecipe(id: 'bd18_08', title: 'Fırında peynirli patates (çocuk)', age: '18+', category: 'Fırın', ingredient: 'patates', vegetable: 'patates', ingredients: ['2 patates', '3 yemek kaşığı rendelenmiş kaşar', '3 yemek kaşığı süt'], steps: ['Ellerinizi, kesme tahtasını ve kapları sıcak sabunlu suyla yıkayın.', 'Fırını 190°C’ye ısıtın; küçük fırın kabını yağlayın.', 'Patatesleri soyup 3–4 mm inceliğinde dilimleyin; ince dilimler eşit pişer.', 'Dilimleri kaba üst üste binecek şekilde dizin ve sütü dökün.', 'Üzerini folyoyla kapatıp 20 dakika pişirin.', 'Folyoyu açın, kaşarı serpin ve 10 dakika daha, üstü kızarana kadar pişirin.', 'Bıçak patatese kolayca batmalı.', '10 dakika dinlendirip küçük parçalara kesin.', 'Kaşar ve lor pastörize sütten olmalı; tuzlu peyniri 1 saat suda bekletip tuzunu alın.', 'Kalanını kapalı kapta buzdolabında 2 gün saklayın; yalnızca bir kez ısıtın.'], tips: ['Patates graten çocukların sevdiği bir garnitürdür.'], storage: 'Buzdolabında 48 saat.'),
  BabyRecipe(id: 'bd18_09', title: 'Mercimekli sebze çorbası (parçalı)', age: '18+', category: 'Çorba', ingredient: 'yeşil mercimek', vegetable: 'havuç', ingredients: ['3 yemek kaşığı yeşil mercimek', 'Yarım havuç', 'Yarım patates', '1 çay kaşığı salça', '2 su bardağı su'], steps: ['Ellerinizi, kesme tahtasını ve kapları sıcak sabunlu suyla yıkayın.', 'Yeşil mercimeği yıkayıp ayıklayın; 15 dakika ön haşlayıp suyunu süzün.', 'Havuç ve patatesi soyup küçük küp doğrayın.', 'Salçayı tencerede suyla açın; mercimek ve sebzeleri ekleyin.', 'Kapağı kapalı kısık ateşte 20 dakika, mercimek ve sebzeler yumuşayana kadar pişirin.', 'Çatalla hafifçe ezin; küçük parçalar kalabilir.', 'Tuz eklemeyin; 1–3 yaş için günlük tuz 2 g’ı geçmemeli, peynir ve salça zaten tuz içerir.', 'Ilıtıp sıcaklığı bileğinizin iç kısmına damlatarak kontrol edin; ılık olmalı, sıcak değil.', 'Buz kalıplarında dondurup 1 ay saklayabilirsiniz; buzdolabında çözdürüp bir kez ısıtın.'], tips: ['Parçalı doku çiğnemeyi geliştirir.'], storage: 'Buzdolabında 48 saat.'),
  BabyRecipe(id: 'bd18_10', title: 'Tavuk şiş (çubuksuz, fırında)', age: '18+', category: 'Et', ingredient: 'tavuk', vegetable: 'biber', ingredients: ['80 g tavuk göğsü', '1 yemek kaşığı yoğurt', '1 çay kaşığı zeytinyağı', '1 tutam kekik'], steps: ['Ellerinizi, kesme tahtasını ve kapları sıcak sabunlu suyla yıkayın.', 'Çiğ eti ve tavuğu ayrı tahtada doğrayın; ardından tahtayı ve ellerinizi yıkayın.', 'Tavuğu çocuğun çiğneyebileceği küçük küpler halinde doğrayın.', 'Yoğurt, zeytinyağı ve kekikle karıştırıp buzdolabında 30 dakika marine edin.', 'Fırını 200°C’ye ısıtın; tepsiye yağlı kâğıt serin.', 'Tavukları tepsiye aralıklı dizip 15 dakika pişirin; yarısında çevirin.', 'Tavuk iç sıcaklığı 74°C olmalı; en büyük parçayı bölüp pembe kalmadığını kontrol edin.', 'Şiş çubuğu kullanmayın; çocuklar için batma ve boğulma riski taşır.', 'Ilıtıp küçük parçalara bölün.', 'Kalanını kapalı kapta buzdolabında 2 gün saklayın; yalnızca bir kez ısıtın.'], tips: ['Şiş çubuğu kullanmayın.'], storage: 'Buzdolabında 48 saat.'),
  BabyRecipe(id: 'bd18_11', title: 'Peynirli sebzeli muffin (çocuk)', age: '18+', category: 'Fırın', ingredient: 'yumurta', vegetable: 'ıspanak', ingredients: ['2 yumurta', '3 yemek kaşığı yoğurt', '4 yemek kaşığı un', '1 çay kaşığı kabartma tozu', '2 yemek kaşığı kıyılmış ıspanak', '2 yemek kaşığı lor'], steps: ['Ellerinizi, kesme tahtasını ve kapları sıcak sabunlu suyla yıkayın.', 'Fırını 180°C’ye ısıtın; mini muffin kalıbını yağlayın ya da kâğıt kapsül koyun.', 'Haşlanmış ıspanağı iyice sıkıp çok ince kıyın.', 'Yumurta ve yoğurdu çırpın; un ve kabartma tozunu ekleyip sadece karışana kadar karıştırın.', 'Ispanak ve loru ekleyip karıştırın.', 'Kalıpları dörtte üçüne kadar doldurun.', '18 dakika pişirin; ortasına batırılan kürdan temiz çıkmalı.', 'Yumurtayı akı ve sarısı tamamen katılaşana kadar pişirin; akışkan bırakmayın.', 'Kalıpta 5 dakika bekletip ılıtın.', 'Kaşar ve lor pastörize sütten olmalı; tuzlu peyniri 1 saat suda bekletip tuzunu alın.', 'Buz kalıplarında dondurup 1 ay saklayabilirsiniz; buzdolabında çözdürüp bir kez ısıtın.'], tips: ['Kreş beslenme çantası için uygundur.'], storage: 'Hava almayan kapta 2 gün.'),
  BabyRecipe(id: 'bd18_12', title: 'Zeytinyağlı taze fasulye (çocuk)', age: '18+', category: 'Sebze', ingredient: 'taze fasulye', vegetable: 'domates', ingredients: ['1 su bardağı doğranmış taze fasulye', '1 domates', '1 küçük soğan', '1 yemek kaşığı zeytinyağı', 'Yarım su bardağı su'], steps: ['Ellerinizi, kesme tahtasını ve kapları sıcak sabunlu suyla yıkayın.', 'Fasulyelerin uçlarını ve kılçıklarını ayıklayıp yıkayın.', 'Soğanı çok ince doğrayın; domatesi soyup rendeleyin.', 'Zeytinyağında soğanı 3 dakika yumuşatın.', 'Fasulye ve domatesi ekleyip 2 dakika çevirin.', 'Suyu ekleyin; kapağı kapalı kısık ateşte 30 dakika, fasulyeler parmakla ezilecek kadar yumuşayana kadar pişirin.', 'Fasulyeleri 1 cm boyunda kesin; uzun lifli parçalar çiğnemeyi zorlaştırır.', 'Ilıtıp sıcaklığı bileğinizin iç kısmına damlatarak kontrol edin; ılık olmalı, sıcak değil.', 'Kalanını kapalı kapta buzdolabında 2 gün saklayın; yalnızca bir kez ısıtın.'], tips: ['Fasulye çok yumuşak olmalı.'], storage: 'Buzdolabında 48 saat.'),
  BabyRecipe(id: 'bd18_13', title: 'Kakaolu muzlu puding (şekersiz)', age: '18+', category: 'Tatlı', ingredient: 'süt', vegetable: 'muz', ingredients: ['1 su bardağı süt', '1 yemek kaşığı nişasta', '1 tatlı kaşığı kakao', '1 olgun muz (ezilmiş)'], steps: ['Ellerinizi, kesme tahtasını ve kapları sıcak sabunlu suyla yıkayın.', 'Soğuk süt, nişasta ve kakaoyu tencerede topaksız çırpın.', 'Orta ateşte sürekli karıştırarak 6–8 dakika, koyulaşana kadar pişirin.', 'Ocaktan alıp ezilmiş muzu ekleyin ve pürüzsüz karıştırın.', 'Kaselere paylaştırıp yüzeyine streç film değdirerek örtün.', 'Buzdolabında 1 saat soğutup servis edin.', 'Kakao kafein benzeri teobromin içerir; az kullanın ve akşam saatlerinde vermeyin.', 'Şeker eklemeyin; tatlılığı olgun meyveden gelsin.', 'Kalanını kapalı kapta buzdolabında 2 gün saklayın; yalnızca bir kez ısıtın.'], tips: ['Muz şeker ihtiyacını karşılar.'], storage: 'Buzdolabında 48 saat.'),
  BabyRecipe(id: 'bd18_14', title: 'Pırasalı tavuk (çocuk)', age: '18+', category: 'Et', ingredient: 'tavuk', vegetable: 'pırasa', ingredients: ['60 g tavuk göğsü', '1 pırasa (beyaz kısmı)', '1 havuç', '1 yemek kaşığı zeytinyağı', 'Yarım su bardağı su'], steps: ['Ellerinizi, kesme tahtasını ve kapları sıcak sabunlu suyla yıkayın.', 'Çiğ eti ve tavuğu ayrı tahtada doğrayın; ardından tahtayı ve ellerinizi yıkayın.', 'Pırasanın beyaz kısmını boyuna yarıp katlarını iyice yıkayın; ince doğrayın.', 'Havucu soyup küçük küp doğrayın; tavuğu küçük doğrayın.', 'Zeytinyağını tencerede ısıtıp tavuğu 6–7 dakika, beyazlayana kadar pişirin.', 'Pırasa ve havucu ekleyip 2 dakika çevirin.', 'Suyu ekleyin; kapağı kapalı kısık ateşte 15 dakika, sebzeler yumuşayana kadar pişirin.', 'Tavuk iç sıcaklığı 74°C olmalı; en büyük parçayı bölüp pembe kalmadığını kontrol edin.', 'Pilavla ılık servis edin.', 'Kalanını kapalı kapta buzdolabında 2 gün saklayın; yalnızca bir kez ısıtın.'], tips: ['Pırasa yumuşak dokuludur.'], storage: 'Buzdolabında 48 saat.'),
  BabyRecipe(id: 'bd18_15', title: 'Fırında muzlu yulaf bar (çocuk)', age: '18+', category: 'Kahvaltı', ingredient: 'yulaf', vegetable: 'muz', ingredients: ['2 muz', '1 su bardağı yulaf', '2 yemek kaşığı kuru üzüm (ince kıyılmış)', '1 tutam tarçın'], steps: ['Ellerinizi, kesme tahtasını ve kapları sıcak sabunlu suyla yıkayın.', 'Fırını 180°C’ye ısıtın; küçük fırın kabına yağlı kâğıt serin.', 'Olgun muzları çatalla pürüzsüz ezin.', 'Yulaf, çok ince kıyılmış kuru üzüm ve tarçını ekleyip karıştırın; 5 dakika bekletin.', 'Karışımı kaba 1,5 cm kalınlığında bastırarak yayın.', '20 dakika, kenarları kızarana kadar pişirin.', 'Kapta tamamen soğutun, sonra çocuğun tutabileceği çubuklar halinde kesin.', 'Kuru üzümü bütün vermeyin; yapışkan ve boğulma riski taşır.', 'Şeker eklemeyin; tatlılığı olgun meyveden gelsin.', 'Kapalı kapta buzdolabında 3 gün saklayın.'], tips: ['Üzümü kıymak boğulma riskini azaltır.'], storage: 'Hava almayan kapta 3 gün.'),
  BabyRecipe(id: 'bd18_16', title: 'Sebzeli köfteli çorba (çocuk)', age: '18+', category: 'Çorba', ingredient: 'dana kıyma', vegetable: 'havuç', ingredients: ['60 g kıyma', '1 yemek kaşığı pirinç', 'Yarım havuç', 'Yarım patates', '2 su bardağı su'], steps: ['Ellerinizi, kesme tahtasını ve kapları sıcak sabunlu suyla yıkayın.', 'Kıymadan nohut büyüklüğünde yumuşak köfteler yuvarlayın; ardından ellerinizi yıkayın.', 'Havuç ve patatesi soyup küçük küp doğrayın; pirinci yıkayın.', 'Sebzeleri suyla kaynatıp 10 dakika pişirin.', 'Köfte ve pirinci ekleyin; kısık ateşte 15 dakika pişirin.', 'Bir köfteyi ortadan bölün: içi pembe kalmamalı.', 'Köfteleri servis ederken ikiye bölün; yuvarlak ve bütün köfte boğazda takılabilir.', 'Tuz eklemeyin; 1–3 yaş için günlük tuz 2 g’ı geçmemeli, peynir ve salça zaten tuz içerir.', 'Ilıtıp sıcaklığı bileğinizin iç kısmına damlatarak kontrol edin; ılık olmalı, sıcak değil.', 'Buz kalıplarında dondurup 1 ay saklayabilirsiniz; buzdolabında çözdürüp bir kez ısıtın.'], tips: ['Köfteler küçük ve yumuşak olmalı.'], storage: 'Buzdolabında 48 saat.'),
  BabyRecipe(id: 'bd18_17', title: 'Patates püreli köfte tabağı', age: '18+', category: 'Et', ingredient: 'dana kıyma', vegetable: 'patates', ingredients: ['80 g kıyma', '1 yemek kaşığı galeta unu', '2 patates', '2 yemek kaşığı süt', '1 çay kaşığı tereyağı'], steps: ['Kıyma ve galeta ununu yoğurup küçük köfteler yapın.', 'Köfteleri fırında veya tavada pişirin.', 'Patatesleri haşlayıp süt ve tereyağıyla püre yapın.', 'Tabağa dizin.', 'Servis edin.'], tips: ['Köfte içi tamamen pişmeli.'], storage: 'Buzdolabında 24 saat.'),
  BabyRecipe(id: 'bd18_18', title: 'Yoğurtlu meyve smoothie (çocuk)', age: '18+', category: 'İçecek', ingredient: 'yoğurt', vegetable: 'çilek', ingredients: ['3 yemek kaşığı yoğurt', 'Yarım su bardağı süt', '4 çilek', 'Yarım muz'], steps: ['Ellerinizi, kesme tahtasını ve kapları sıcak sabunlu suyla yıkayın.', 'Çilekleri bol suda yıkayıp saplarını ayırın; muzu soyun.', 'Yoğurt, süt, çilek ve muzu blenderda pürüzsüz olana kadar çekin.', 'Bardağa alıp hemen servis edin.', 'Kalanını saklamayın; atın.', 'Çilek bazı çocuklarda ağız çevresinde kızarıklık yapabilir; ilk kez veriyorsanız gözlemleyin.', 'Şeker eklemeyin; tatlılığı olgun meyveden gelsin.'], tips: ['Meyve suyu yerine bütün meyve tercih edin.'], storage: 'Hazırlandıktan hemen sonra tüketin.'),
  BabyRecipe(id: 'bd18_19', title: 'Sebzeli bulgurlu köfte (fırında)', age: '18+', category: 'Tahıl', ingredient: 'bulgur', vegetable: 'kabak', ingredients: ['3 yemek kaşığı ince bulgur', '60 g kıyma', '2 yemek kaşığı rendelenmiş kabak', '1 yumurta sarısı'], steps: ['Ellerinizi, kesme tahtasını ve kapları sıcak sabunlu suyla yıkayın.', 'Fırını 190°C’ye ısıtın; tepsiye yağlı kâğıt serin.', 'Bulguru sıcak suyla ıslatıp 10 dakika şişirin; fazla suyu süzün.', 'Kabağı rendeleyip suyunu iyice sıkın.', 'Bulgur, kıyma, kabak ve yumurta sarısını 3–4 dakika yoğurun; ardından ellerinizi yıkayın.', 'Küçük yassı köfteler yapıp tepsiye dizin; 20 dakika pişirin.', 'Köfte iç sıcaklığı 71°C olmalı; bir köfteyi ortadan bölün: içi pembe kalmamalı, suyu berrak akmalı.', 'Tepside 5 dakika dinlendirip ılıtın.', 'Buz kalıplarında dondurup 1 ay saklayabilirsiniz; buzdolabında çözdürüp bir kez ısıtın.'], tips: ['Bulgur köfteye doku katar.'], storage: 'Buzdolabında 48 saat.'),
  BabyRecipe(id: 'bd18_20', title: 'Elmalı havuçlu kurabiye (şekersiz)', age: '18+', category: 'Tatlı', ingredient: 'yulaf', vegetable: 'elma', ingredients: ['1 elma (rendelenmiş)', '1 havuç (rendelenmiş)', '1 su bardağı yulaf', '1 yumurta', '1 tutam tarçın'], steps: ['Ellerinizi, kesme tahtasını ve kapları sıcak sabunlu suyla yıkayın.', 'Fırını 180°C’ye ısıtın; tepsiye yağlı kâğıt serin.', 'Elma ve havucu soyup ince rendeleyin; elmanın suyunu hafifçe sıkın.', 'Elma, havuç, yulaf, yumurta ve tarçını karıştırıp 10 dakika bekletin.', 'Kaşıkla tepsiye küçük yuvarlaklar bırakıp 1 cm kalınlığa bastırın.', '18 dakika, altları kızarana kadar pişirin.', 'Yumurtayı akı ve sarısı tamamen katılaşana kadar pişirin; akışkan bırakmayın.', 'Tepside 10 dakika soğutun; sıcakken kolay dağılır.', 'Şeker eklemeyin; tatlılığı olgun meyveden gelsin.', 'Kapalı kapta 2 gün saklayın.'], tips: ['Yumuşak kurabiyedir.'], storage: 'Hava almayan kapta 3 gün.'),
  BabyRecipe(id: 'be24_01', title: 'Fırında tavuk baget (çocuk)', age: '24+', category: 'Et', ingredient: 'tavuk', vegetable: 'patates', ingredients: ['2 tavuk baget', '2 yemek kaşığı yoğurt', '1 çay kaşığı tatlı toz biber', '1 tutam kekik', '1 patates'], steps: ['Ellerinizi, kesme tahtasını ve kapları sıcak sabunlu suyla yıkayın.', 'Tavukları yoğurt, toz biber ve kekikle karıştırıp buzdolabında 1 saat marine edin; ardından ellerinizi yıkayın.', 'Fırını 200°C’ye ısıtın; tepsiye yağlı kâğıt serin.', 'Patatesi kabuğuyla iyice yıkayıp elma dilimi şeklinde kesin.', 'Tavuk ve patatesleri tepsiye aralıklı dizip 40 dakika pişirin; yarısında çevirin.', 'Tavuk iç sıcaklığı 74°C olmalı; kemiğe yakın yer pembe kalmamalı.', 'Ilıyınca etleri kemikten tamamen ayırın; küçük kemik ve kıkırdakları kontrol edin.', 'Çocuğun çiğneyebileceği küçük parçalara bölün.', 'Kalanını kapalı kapta buzdolabında 2 gün saklayın; yalnızca bir kez ısıtın.'], tips: ['Çocuğa kemikli vermeyin; eti ayırın.'], storage: 'Buzdolabında 48 saat.'),
  BabyRecipe(id: 'be24_02', title: 'Sebzeli kıymalı makarna (çocuk)', age: '24+', category: 'Makarna', ingredient: 'makarna', vegetable: 'havuç', ingredients: ['Yarım su bardağı kısa makarna', '60 g kıyma', '2 yemek kaşığı rendelenmiş havuç', '2 yemek kaşığı domates sosu'], steps: ['Ellerinizi, kesme tahtasını ve kapları sıcak sabunlu suyla yıkayın.', 'Makarnayı tuzsuz kaynar suda paketteki süreden 2 dakika fazla, parmakla ezilecek kadar yumuşak haşlayın.', 'Kıymayı kaşıkla dağıtarak 5 dakika, rengi tamamen dönene kadar pişirin.', 'Rendelenmiş havucu ekleyip 3 dakika pişirin.', 'Domates sosunu ekleyin; kısık ateşte 5 dakika pişirin.', 'Kıymada pembe kalmadığını kontrol edin.', 'Süzülmüş makarnayla karıştırın.', 'Tuz eklemeyin; 1–3 yaş için günlük tuz 2 g’ı geçmemeli, peynir ve salça zaten tuz içerir.', 'Ilıtıp sıcaklığı bileğinizin iç kısmına damlatarak kontrol edin; ılık olmalı, sıcak değil.', 'Buz kalıplarında dondurup 1 ay saklayabilirsiniz; buzdolabında çözdürüp bir kez ısıtın.'], tips: ['Havuç sosa doğal tatlılık katar.'], storage: 'Buzdolabında 48 saat.'),
  BabyRecipe(id: 'be24_03', title: 'Peynirli tost (çocuk)', age: '24+', category: 'Kahvaltı', ingredient: 'ekmek', vegetable: 'domates', ingredients: ['2 dilim tam buğday ekmeği', '2 dilim kaşar', '2 ince dilim domates'], steps: ['Ellerinizi, kesme tahtasını ve kapları sıcak sabunlu suyla yıkayın.', 'Domatesi ince dilimleyin.', 'Ekmeklerin arasına kaşar ve domatesi yerleştirin.', 'Tost makinesinde 3 dakika, kaşar eriyene kadar pişirin.', 'Erimiş peynir içi çok sıcak kalır; ılıtmadan vermeyin.', '5 dakika ılıtıp dört parçaya kesin.', 'Kaşar ve lor pastörize sütten olmalı; tuzlu peyniri 1 saat suda bekletip tuzunu alın.'], tips: ['Sıcak peynire dikkat; ılıtın.'], storage: 'Hazırlandıktan hemen sonra tüketin.'),
  BabyRecipe(id: 'be24_04', title: 'Sebzeli pirinç çorbası (çocuk)', age: '24+', category: 'Çorba', ingredient: 'pirinç', vegetable: 'havuç', ingredients: ['2 yemek kaşığı pirinç', '1 havuç', '1 küçük kabak', '1 çay kaşığı tereyağı', '3 su bardağı su'], steps: ['Ellerinizi, kesme tahtasını ve kapları sıcak sabunlu suyla yıkayın.', 'Havuç ve kabağı küçük küp doğrayın; pirinci yıkayın.', 'Tereyağını tencerede eritip sebzeleri 3 dakika çevirin.', 'Pirinç ve suyu ekleyin; kısık ateşte 20 dakika, pirinç yumuşayana kadar pişirin.', 'Parçalı bırakın; çiğneme becerisini geliştirir.', 'İsterseniz birkaç damla limon sıkın.', 'Tuz eklemeyin; 1–3 yaş için günlük tuz 2 g’ı geçmemeli, peynir ve salça zaten tuz içerir.', 'Ilıtıp sıcaklığı bileğinizin iç kısmına damlatarak kontrol edin; ılık olmalı, sıcak değil.', 'Buz kalıplarında dondurup 1 ay saklayabilirsiniz; buzdolabında çözdürüp bir kez ısıtın.'], tips: ['Az tuz yeterlidir.'], storage: 'Buzdolabında 48 saat.'),
  BabyRecipe(id: 'be24_05', title: 'Yumurtalı patates (çocuk)', age: '24+', category: 'Yumurta', ingredient: 'yumurta', vegetable: 'patates', ingredients: ['1 patates', '1 yumurta', '1 çay kaşığı tereyağı'], steps: ['Ellerinizi, kesme tahtasını ve kapları sıcak sabunlu suyla yıkayın.', 'Patatesi soyup küçük küp doğrayın.', 'Tereyağını tavada eritip patatesi 2 kaşık suyla kapağı kapalı 10 dakika yumuşatın.', 'Yumurtayı kırıp karıştırarak pişirin.', 'Yumurtayı akı ve sarısı tamamen katılaşana kadar pişirin; akışkan bırakmayın.', 'Patates parmakla ezilecek kadar yumuşak olmalı.', 'Ilıtıp sıcaklığı bileğinizin iç kısmına damlatarak kontrol edin; ılık olmalı, sıcak değil.', 'Tuz eklemeyin; 1–3 yaş için günlük tuz 2 g’ı geçmemeli, peynir ve salça zaten tuz içerir.'], tips: ['Yumurta tam pişmeli.'], storage: 'Hazırlandıktan hemen sonra tüketin.'),
  BabyRecipe(id: 'be24_07', title: 'Fırında somon ve sebzeler (çocuk)', age: '24+', category: 'Balık', ingredient: 'somon', vegetable: 'brokoli', ingredients: ['80 g somon', '4 brokoli çiçeği', '1 havuç', '1 çay kaşığı zeytinyağı', 'Birkaç damla limon (1 çay kaşığı)'], steps: ['Ellerinizi, kesme tahtasını ve kapları sıcak sabunlu suyla yıkayın.', 'Fırını 200°C’ye ısıtın; tepsiye yağlı kâğıt serin.', 'Brokoliyi küçük çiçeklere ayırın; havucu ince çubuklar halinde doğrayın.', 'Sebzeleri zeytinyağıyla harmanlayıp tepsiye yayın; somonu ortalarına koyun.', '15 dakika, somon opaklaşıp kolayca dağılana kadar pişirin.', 'Balığı parmaklarınızla yoklayarak tüm kılçıkları ayıklayın; et opaklaşıp kolayca dağılıyorsa pişmiştir.', 'Limonu gezdirip somonu ufalayın; sebzelerle ılık servis edin.', 'Kalanını kapalı kapta buzdolabında 2 gün saklayın; yalnızca bir kez ısıtın.'], tips: ['Omega-3 beyin gelişimine katkı sağlar.'], storage: 'Hazırlandıktan hemen sonra tüketin.'),
  BabyRecipe(id: 'be24_08', title: 'Barbunya pilaki (çocuk)', age: '24+', category: 'Baklagil', ingredient: 'barbunya', vegetable: 'havuç', ingredients: ['Yarım su bardağı haşlanmış barbunya', '1 havuç', '1 patates', '1 yemek kaşığı zeytinyağı', '1 su bardağı su'], steps: ['Ellerinizi, kesme tahtasını ve kapları sıcak sabunlu suyla yıkayın.', 'Havuç ve patatesi soyup küçük küp doğrayın.', 'Zeytinyağını tencerede ısıtıp sebzeleri 3 dakika çevirin.', 'Haşlanmış barbunya ve suyu ekleyin; kapağı kapalı kısık ateşte 20 dakika pişirin.', 'Sebzeler parmakla ezilecek kadar yumuşamalı.', 'Fasulyeleri çatalla hafif ezin.', 'Kuru baklagiller bebeklerde gaz yapabilir; ilk kez veriyorsanız az porsiyonla başlayın.', 'Tuz eklemeyin; 1–3 yaş için günlük tuz 2 g’ı geçmemeli, peynir ve salça zaten tuz içerir.', 'Ilıtıp sıcaklığı bileğinizin iç kısmına damlatarak kontrol edin; ılık olmalı, sıcak değil.', 'Kalanını kapalı kapta buzdolabında 2 gün saklayın; yalnızca bir kez ısıtın.'], tips: ['Baklagiller lif sağlar.'], storage: 'Buzdolabında 3 gün.'),
  BabyRecipe(id: 'be24_09', title: 'Kıymalı patates püresi (çoban turtası)', age: '24+', category: 'Et', ingredient: 'dana kıyma', vegetable: 'bezelye', ingredients: ['80 g kıyma', '2 yemek kaşığı bezelye ve havuç', '2 patates', '3 yemek kaşığı süt', '1 yemek kaşığı rendelenmiş kaşar'], steps: ['Ellerinizi, kesme tahtasını ve kapları sıcak sabunlu suyla yıkayın.', 'Patatesleri soyup küp doğrayın ve 15 dakika yumuşayana kadar haşlayın.', 'Kıymayı kaşıkla dağıtarak 5 dakika, rengi tamamen dönene kadar pişirin.', 'Bezelye ve havucu ekleyip 5 dakika pişirin; kıymada pembe kalmamalı.', 'Patatesleri süzüp sütle çatalla pürüzsüz ezin.', 'Fırını 200°C’ye ısıtın.', 'Fırın kabına önce kıymalı harcı, üstüne püreyi yayın; kaşarı serpin.', '15 dakika, üstü kızarana kadar pişirin.', '10 dakika dinlendirip küçük kareler halinde kesin.', 'Yuvarlak ve sert parçaları (bezelye, nohut, üzüm gibi) ezin ya da dörde bölün.', 'Buz kalıplarında dondurup 1 ay saklayabilirsiniz; buzdolabında çözdürüp bir kez ısıtın.'], tips: ['Tek kapta tam öğün.'], storage: 'Buzdolabında 48 saat.'),
  BabyRecipe(id: 'be24_10', title: 'Ispanaklı mercimek çorbası (çocuk)', age: '24+', category: 'Çorba', ingredient: 'kırmızı mercimek', vegetable: 'ıspanak', ingredients: ['3 yemek kaşığı kırmızı mercimek', '1 avuç ıspanak', '1 havuç', '1 çay kaşığı tereyağı', '2 su bardağı su'], steps: ['Ellerinizi, kesme tahtasını ve kapları sıcak sabunlu suyla yıkayın.', 'Mercimeği yıkayın; havucu küçük doğrayın.', 'Mercimek, havuç ve suyu kaynatın; köpüğünü alın.', 'Kısık ateşte 20 dakika, mercimek dağılana kadar pişirin.', 'Ispanağı yıkayıp ince doğrayın; ekleyip 3 dakika pişirin.', 'Blenderdan geçirin; tereyağını ekleyin.', 'Tuz eklemeyin; 1–3 yaş için günlük tuz 2 g’ı geçmemeli, peynir ve salça zaten tuz içerir.', 'Ilıtıp sıcaklığı bileğinizin iç kısmına damlatarak kontrol edin; ılık olmalı, sıcak değil.', 'Buz kalıplarında dondurup 1 ay saklayabilirsiniz; buzdolabında çözdürüp bir kez ısıtın.'], tips: ['Ispanak çorbaya renk ve demir katar.'], storage: 'Buzdolabında 48 saat.'),
  BabyRecipe(id: 'be24_11', title: 'Fırında mücver çubukları', age: '24+', category: 'Fırın', ingredient: 'kabak', vegetable: 'havuç', ingredients: ['1 kabak', '1 havuç', '1 yumurta', '3 yemek kaşığı un', '2 yemek kaşığı lor'], steps: ['Ellerinizi, kesme tahtasını ve kapları sıcak sabunlu suyla yıkayın.', 'Fırını 190°C’ye ısıtın; küçük fırın kabına yağlı kâğıt serin.', 'Kabak ve havucu rendeleyip avuçlarınızla suyunu iyice sıkın.', 'Sebze, yumurta, un ve loru karıştırın.', 'Karışımı kaba 1,5 cm kalınlığında yayın.', '25 dakika, üstü kızarıp ortası sertleşene kadar pişirin.', 'Yumurtayı akı ve sarısı tamamen katılaşana kadar pişirin; akışkan bırakmayın.', '10 dakika dinlendirip çocuğun tutabileceği çubuklar halinde kesin.', 'Kaşar ve lor pastörize sütten olmalı; tuzlu peyniri 1 saat suda bekletip tuzunu alın.', 'Buz kalıplarında dondurup 1 ay saklayabilirsiniz; buzdolabında çözdürüp bir kez ısıtın.'], tips: ['Çubuklar çocuğun tutmasını kolaylaştırır.'], storage: 'Buzdolabında 48 saat.'),
  BabyRecipe(id: 'be24_12', title: 'Tavuklu sebzeli pilav (çocuk)', age: '24+', category: 'Tahıl', ingredient: 'pirinç', vegetable: 'bezelye', ingredients: ['Yarım su bardağı pirinç', '60 g haşlanmış tavuk', '2 yemek kaşığı bezelye', '1 çay kaşığı tereyağı', '1 su bardağı tavuk suyu (tuzsuz)'], steps: ['Ellerinizi, kesme tahtasını ve kapları sıcak sabunlu suyla yıkayın.', 'Pirinci suyu berraklaşana kadar yıkayıp süzün.', 'Tereyağını tencerede eritip pirinci 1 dakika çevirin.', 'Tavuk suyu ve bezelyeyi ekleyin; kaynayınca kapağı kapalı kısık ateşte 15 dakika pişirin.', 'Haşlanmış tavuğu ince didikleyip ekleyin.', 'Ocağı kapatıp kapağın altına kâğıt havlu koyarak 10 dakika demlendirin.', 'Yuvarlak ve sert parçaları (bezelye, nohut, üzüm gibi) ezin ya da dörde bölün.', 'Kalanını kapalı kapta buzdolabında 2 gün saklayın; yalnızca bir kez ısıtın.'], tips: ['Hazır bulyon kullanmayın.'], storage: 'Buzdolabında 48 saat.'),
  BabyRecipe(id: 'be24_13', title: 'Yoğurtlu meyveli dondurma (ev)', age: '24+', category: 'Tatlı', ingredient: 'yoğurt', vegetable: 'muz', ingredients: ['1 su bardağı yoğurt', '1 muz', '4 çilek'], steps: ['Ellerinizi, kesme tahtasını ve kapları sıcak sabunlu suyla yıkayın.', 'Çilekleri yıkayıp saplarını ayırın; muzu soyup dilimleyin.', 'Yoğurt, muz ve çilekleri blenderda pürüzsüz olana kadar çekin.', 'Kalıplara dökün ve dondurucuda en az 4 saat bekletin.', 'Servis etmeden 5 dakika önce çıkarın; kalıptan kolay çıkar.', 'Şeker eklemeyin; tatlılığı olgun meyveden gelsin.', 'Çözülen dondurmayı yeniden dondurmayın.'], tips: ['Şeker eklemeye gerek yoktur.'], storage: 'Dondurucuda 1 ay.'),
  BabyRecipe(id: 'be24_14', title: 'Domates soslu köfte (çocuk)', age: '24+', category: 'Et', ingredient: 'dana kıyma', vegetable: 'domates', ingredients: ['100 g kıyma', '1 yemek kaşığı galeta unu', '1 domates (rendelenmiş)', '1 çay kaşığı zeytinyağı'], steps: ['Ellerinizi, kesme tahtasını ve kapları sıcak sabunlu suyla yıkayın.', 'Kıyma ve galeta ununu yoğurun; ceviz büyüklüğünde, hafif yassı köfteler yapın ve ellerinizi yıkayın.', 'Zeytinyağını tavada ısıtıp köfteleri her yüzü 3 dakika kızartın.', 'Rendelenmiş domatesi ve 3 kaşık suyu ekleyin; kapağı kapalı kısık ateşte 10 dakika pişirin.', 'Köfte iç sıcaklığı 71°C olmalı; bir köfteyi ortadan bölün: içi pembe kalmamalı, suyu berrak akmalı.', 'Köfteleri ikiye bölüp pilavla servis edin.', 'Tuz eklemeyin; 1–3 yaş için günlük tuz 2 g’ı geçmemeli, peynir ve salça zaten tuz içerir.', 'Ilıtıp sıcaklığı bileğinizin iç kısmına damlatarak kontrol edin; ılık olmalı, sıcak değil.', 'Buz kalıplarında dondurup 1 ay saklayabilirsiniz; buzdolabında çözdürüp bir kez ısıtın.'], tips: ['Domates sosu köfteleri yumuşatır.'], storage: 'Buzdolabında 48 saat.'),
  BabyRecipe(id: 'be24_15', title: 'Sebzeli peynirli quesadilla (çocuk)', age: '24+', category: 'Fırın', ingredient: 'lavaş', vegetable: 'mısır', ingredients: ['1 küçük lavaş', '2 yemek kaşığı rendelenmiş kaşar', '1 yemek kaşığı mısır', '1 yemek kaşığı rendelenmiş kabak'], steps: ['Ellerinizi, kesme tahtasını ve kapları sıcak sabunlu suyla yıkayın.', 'Kabağı rendeleyip suyunu sıkın; mısırı ince kıyın.', 'Lavaşın yarısına kaşar, kabak ve mısırı yayın; diğer yarısını üstüne katlayın.', 'Kuru yapışmaz tavada orta ateşte her yüzü 2 dakika, kaşar eriyene kadar pişirin.', 'Erimiş peynir içi çok sıcak kalır; ılıtmadan vermeyin.', '5 dakika ılıtıp üçgenler halinde kesin.', 'Kaşar ve lor pastörize sütten olmalı; tuzlu peyniri 1 saat suda bekletip tuzunu alın.'], tips: ['Mısırı hafif ezin.'], storage: 'Hazırlandıktan hemen sonra tüketin.'),
  BabyRecipe(id: 'be24_16', title: 'Fırında elmalı tarçınlı yulaf barı', age: '24+', category: 'Kahvaltı', ingredient: 'yulaf', vegetable: 'elma', ingredients: ['1 su bardağı yulaf', '1 elma (rendelenmiş)', '1 yumurta', '2 yemek kaşığı süt', '1 tutam tarçın'], steps: ['Ellerinizi, kesme tahtasını ve kapları sıcak sabunlu suyla yıkayın.', 'Fırını 180°C’ye ısıtın; küçük fırın kabına yağlı kâğıt serin.', 'Elmayı soyup ince rendeleyin.', 'Yulaf, elma, yumurta, süt ve tarçını karıştırıp 10 dakika bekletin.', 'Karışımı kaba 1,5 cm kalınlığında bastırarak yayın.', '20 dakika, kenarları kızarana kadar pişirin.', 'Yumurtayı akı ve sarısı tamamen katılaşana kadar pişirin; akışkan bırakmayın.', 'Kapta tamamen soğutun, sonra çocuğun tutabileceği çubuklar halinde kesin.', 'Şeker eklemeyin; tatlılığı olgun meyveden gelsin.', 'Kapalı kapta buzdolabında 3 gün saklayın.'], tips: ['Atıştırmalık için uygundur.'], storage: 'Hava almayan kapta 3 gün.'),
  BabyRecipe(id: 'be24_17', title: 'Etli bezelye (çocuk)', age: '24+', category: 'Et', ingredient: 'dana eti', vegetable: 'bezelye', ingredients: ['60 g kuşbaşı', '1 su bardağı bezelye', '1 havuç', '1 çay kaşığı salça', '1 su bardağı su'], steps: ['Ellerinizi, kesme tahtasını ve kapları sıcak sabunlu suyla yıkayın.', 'Çiğ eti ve tavuğu ayrı tahtada doğrayın; ardından tahtayı ve ellerinizi yıkayın.', 'Eti küçük doğrayıp yağ ve sinirlerini ayıklayın; havucu küçük küp doğrayın.', 'Eti tencerede 10 dakika, kendi suyunu çekene kadar pişirin.', 'Salça ve havucu ekleyip 2 dakika çevirin.', 'Bezelye ve suyu ekleyin; kapağı kapalı kısık ateşte 25 dakika, et yumuşayana kadar pişirin.', 'Eti küçük lifler halinde ayırın; bezelyeleri hafif ezin.', 'Tuz eklemeyin; 1–3 yaş için günlük tuz 2 g’ı geçmemeli, peynir ve salça zaten tuz içerir.', 'Ilıtıp sıcaklığı bileğinizin iç kısmına damlatarak kontrol edin; ılık olmalı, sıcak değil.', 'Buz kalıplarında dondurup 1 ay saklayabilirsiniz; buzdolabında çözdürüp bir kez ısıtın.'], tips: ['Eti küçük doğrayın.'], storage: 'Buzdolabında 48 saat.'),
  BabyRecipe(id: 'be24_18', title: 'Peynirli sebzeli krep rulo', age: '24+', category: 'Kahvaltı', ingredient: 'un', vegetable: 'ıspanak', ingredients: ['1 yumurta', '4 yemek kaşığı un', '5 yemek kaşığı süt', '2 yemek kaşığı lor', '1 yemek kaşığı haşlanmış ıspanak'], steps: ['Ellerinizi, kesme tahtasını ve kapları sıcak sabunlu suyla yıkayın.', 'Yumurta, un ve sütü pürüzsüz çırpın; 5 dakika dinlendirin.', 'Haşlanmış ıspanağı iyice sıkıp ince kıyın; lorla karıştırın.', 'Yapışmaz tavayı kısık ateşte ısıtıp bir kepçe hamuru döküp yayın.', 'Altı pişince çevirip 1 dakika daha pişirin.', 'Krepin üzerine ıspanaklı loru yayıp rulo yapın.', 'Çocuğun tutabileceği dilimlere kesin.', 'Kaşar ve lor pastörize sütten olmalı; tuzlu peyniri 1 saat suda bekletip tuzunu alın.', 'Kalanını kapalı kapta buzdolabında 2 gün saklayın; yalnızca bir kez ısıtın.'], tips: ['Krepler önceden yapılabilir.'], storage: 'Buzdolabında 48 saat.'),
  BabyRecipe(id: 'be24_19', title: 'Fırında patates köftesi (çocuk)', age: '24+', category: 'Fırın', ingredient: 'patates', vegetable: 'havuç', ingredients: ['2 haşlanmış patates', '1 yemek kaşığı rendelenmiş havuç', '1 yumurta sarısı', '2 yemek kaşığı galeta unu'], steps: ['Ellerinizi, kesme tahtasını ve kapları sıcak sabunlu suyla yıkayın.', 'Fırını 200°C’ye ısıtın; tepsiye yağlı kâğıt serin.', 'Haşlanmış patatesleri sıcakken çatalla pürüzsüz ezin.', 'Ilıyınca havuç, yumurta sarısı ve galeta ununu ekleyip yoğurun.', 'Ceviz büyüklüğünde yassı köfteler yapıp tepsiye dizin.', '20 dakika, altları kızarana kadar pişirin.', 'Tepside 5 dakika dinlendirip ılıtın.', 'Yoğurdu buzdolabından 10 dakika önce çıkarın; çok soğuk vermeyin.', 'Yoğurtla servis edin.', 'Buz kalıplarında dondurup 1 ay saklayabilirsiniz; buzdolabında çözdürüp bir kez ısıtın.'], tips: ['Kızartmasız ve hafiftir.'], storage: 'Buzdolabında 48 saat.'),
  BabyRecipe(id: 'be24_20', title: 'Bulgurlu kabak dolması (çocuk)', age: '24+', category: 'Sebze', ingredient: 'bulgur', vegetable: 'kabak', ingredients: ['2 küçük kabak', '3 yemek kaşığı ince bulgur', '1 domates', '1 çay kaşığı zeytinyağı'], steps: ['Ellerinizi, kesme tahtasını ve kapları sıcak sabunlu suyla yıkayın.', 'Kabakları yıkayıp ikiye kesin; içlerini kaşıkla oyun, kabuk kalınlığı 0,5 cm kalsın.', 'Bulgur, rendelenmiş domates, zeytinyağı ve ince kıyılmış kabak içini karıştırın.', 'Kabakları harçla gevşek doldurun; bulgur pişince kabarır.', 'Tencereye dizin, yarısına kadar sıcak su ekleyin.', 'Kapağı kapalı kısık ateşte 30 dakika, kabaklar yumuşayıp bulgur pişene kadar pişirin.', 'Yoğurdu buzdolabından 10 dakika önce çıkarın; çok soğuk vermeyin.', 'Ilıyınca kabakları küçük parçalara bölüp yoğurtla servis edin.', 'Tuz eklemeyin; 1–3 yaş için günlük tuz 2 g’ı geçmemeli, peynir ve salça zaten tuz içerir.'], tips: ['Kabak içini harca katabilirsiniz.'], storage: 'Buzdolabında 48 saat.'),
  BabyRecipe(id: 'be24_21', title: 'Muzlu yulaflı smoothie kasesi', age: '24+', category: 'Kahvaltı', ingredient: 'yulaf', vegetable: 'muz', ingredients: ['1 muz', '3 yemek kaşığı yoğurt', '2 yemek kaşığı yulaf', 'Yarım su bardağı süt'], steps: ['Ellerinizi, kesme tahtasını ve kapları sıcak sabunlu suyla yıkayın.', 'Olgun muzu soyup dilimleyin.', 'Muz, yoğurt ve sütü blenderda pürüzsüz olana kadar çekin.', 'Kaseye alıp yulafı serpin.', 'Kaşıkla hemen servis edin.', 'Kalanını saklamayın; atın.', 'Şeker eklemeyin; tatlılığı olgun meyveden gelsin.'], tips: ['Kaşıkla yemek becerisini destekler.'], storage: 'Hazırlandıktan hemen sonra tüketin.'),
  BabyRecipe(id: 'be24_22', title: 'Sebzeli tavuk çorbası (parçalı)', age: '24+', category: 'Çorba', ingredient: 'tavuk', vegetable: 'havuç', ingredients: ['60 g tavuk göğsü', '1 havuç', '1 patates', '1 yemek kaşığı şehriye', '3 su bardağı su'], steps: ['Ellerinizi, kesme tahtasını ve kapları sıcak sabunlu suyla yıkayın.', 'Tavuğu suyla kaynatıp köpüğünü alın; kısık ateşte 20 dakika pişirin.', 'Tavuk iç sıcaklığı 74°C olmalı; en büyük parçayı bölüp pembe kalmadığını kontrol edin.', 'Tavuğu çıkarıp ince didikleyin.', 'Havuç ve patatesi küçük küp doğrayıp haşlama suyuna ekleyin; 10 dakika pişirin.', 'Şehriyeyi ekleyip 7 dakika pişirin.', 'Tavuğu geri ekleyip 1 dakika ısıtın.', 'İsterseniz birkaç damla limon sıkın.', 'Tuz eklemeyin; 1–3 yaş için günlük tuz 2 g’ı geçmemeli, peynir ve salça zaten tuz içerir.', 'Ilıtıp sıcaklığı bileğinizin iç kısmına damlatarak kontrol edin; ılık olmalı, sıcak değil.'], tips: ['Parçalı çorba çiğneme becerisini geliştirir.'], storage: 'Buzdolabında 48 saat.'),
  BabyRecipe(id: 'be24_23', title: 'Fırında sebzeli omlet dilimleri', age: '24+', category: 'Yumurta', ingredient: 'yumurta', vegetable: 'biber', ingredients: ['3 yumurta', '2 yemek kaşığı süt', '2 yemek kaşığı doğranmış kırmızı biber', '2 yemek kaşığı doğranmış kabak', '2 yemek kaşığı rendelenmiş kaşar'], steps: ['Ellerinizi, kesme tahtasını ve kapları sıcak sabunlu suyla yıkayın.', 'Fırını 180°C’ye ısıtın; küçük fırın kabına yağlı kâğıt serin.', 'Biber ve kabağı çok ince doğrayın.', 'Yumurta, süt, sebzeler ve kaşarı çırpın.', 'Karışımı kaba döküp 20 dakika, ortası tamamen katılaşana kadar pişirin.', 'Yumurtayı akı ve sarısı tamamen katılaşana kadar pişirin; akışkan bırakmayın.', '5 dakika dinlendirip çocuğun tutabileceği dilimlere kesin.', 'Kaşar ve lor pastörize sütten olmalı; tuzlu peyniri 1 saat suda bekletip tuzunu alın.', 'Kalanını kapalı kapta buzdolabında 2 gün saklayın; yalnızca bir kez ısıtın.'], tips: ['Kahvaltı ve beslenme çantası için uygundur.'], storage: 'Buzdolabında 48 saat.'),
  BabyRecipe(id: 'be24_24', title: 'Nohutlu ıspanak (çocuk)', age: '24+', category: 'Baklagil', ingredient: 'nohut', vegetable: 'ıspanak', ingredients: ['3 yemek kaşığı haşlanmış nohut', '1 su bardağı ıspanak', '1 çay kaşığı salça', '1 çay kaşığı zeytinyağı', 'Yarım su bardağı su'], steps: ['Ellerinizi, kesme tahtasını ve kapları sıcak sabunlu suyla yıkayın.', 'Ispanağı bol suda birkaç kez yıkayıp ince doğrayın.', 'Zeytinyağında salçayı 1 dakika çevirin.', 'Haşlanmış nohudu ekleyip 2 dakika karıştırın.', 'Ispanak ve suyu ekleyin; kapağı kapalı kısık ateşte 10 dakika pişirin.', 'Nohutları çatalla ezin ya da dörde bölün; bütün nohut boğulma riski taşır.', 'Tuz eklemeyin; 1–3 yaş için günlük tuz 2 g’ı geçmemeli, peynir ve salça zaten tuz içerir.', 'Ilıtıp sıcaklığı bileğinizin iç kısmına damlatarak kontrol edin; ılık olmalı, sıcak değil.', 'Kalanını kapalı kapta buzdolabında 2 gün saklayın; yalnızca bir kez ısıtın.'], tips: ['Nohut 4 yaşa kadar ezilerek verilmelidir.'], storage: 'Buzdolabında 48 saat.'),
  BabyRecipe(id: 'be24_25', title: 'Pirinçli sütlaç (az şekerli)', age: '24+', category: 'Tatlı', ingredient: 'pirinç', vegetable: 'süt', ingredients: ['2 yemek kaşığı pirinç', '2 su bardağı süt', '1 tatlı kaşığı şeker', '1 tutam tarçın'], steps: ['Ellerinizi, kesme tahtasını ve kapları sıcak sabunlu suyla yıkayın.', 'Pirinci yıkayıp yarım su bardağı suyla 15 dakika, suyunu çekip yumuşayana kadar pişirin.', 'Sütü ekleyip kaynatın.', 'Kısık ateşte ara ara karıştırarak 20 dakika, koyulaşana kadar pişirin.', 'Şekeri ekleyip 1 dakika karıştırın.', '2 yaş altında şeker eklemeyin; 2 yaştan sonra da günde en fazla 1–2 çay kaşığı ekli şeker yeterlidir.', 'Kaselere paylaştırıp yüzeyine streç film değdirerek örtün; soğutun.', 'Servis ederken tarçın serpin.', 'Kalanını kapalı kapta buzdolabında 2 gün saklayın; yalnızca bir kez ısıtın.'], tips: ['Şekeri en az düzeyde tutun.'], storage: 'Buzdolabında 3 gün.'),
  BabyRecipe(id: 'be24_26', title: 'Fırında karnabahar peynirli', age: '24+', category: 'Sebze', ingredient: 'karnabahar', vegetable: 'karnabahar', ingredients: ['1 su bardağı karnabahar çiçeği', '3 yemek kaşığı süt', '2 yemek kaşığı rendelenmiş kaşar'], steps: ['Ellerinizi, kesme tahtasını ve kapları sıcak sabunlu suyla yıkayın.', 'Fırını 200°C’ye ısıtın.', 'Karnabaharı küçük çiçeklere ayırıp 5 dakika haşlayın ve süzün.', 'Küçük fırın kabına alın; sütü dökün ve kaşarı serpin.', '15 dakika, kaşar kızarana kadar pişirin.', 'Karnabahar parmakla ezilecek kadar yumuşak olmalı.', 'Kapta 5 dakika dinlendirip ılıtın.', 'Kaşar ve lor pastörize sütten olmalı; tuzlu peyniri 1 saat suda bekletip tuzunu alın.', 'Kalanını kapalı kapta buzdolabında 2 gün saklayın; yalnızca bir kez ısıtın.'], tips: ['Peynir sebzeyi sevdirmeye yardımcı olur.'], storage: 'Buzdolabında 48 saat.'),
  BabyRecipe(id: 'be24_27', title: 'Mini pankek (yulaflı, ıspanaklı)', age: '24+', category: 'Kahvaltı', ingredient: 'yulaf', vegetable: 'ıspanak', ingredients: ['1 avuç ıspanak', '1 muz', '1 yumurta', '4 yemek kaşığı yulaf'], steps: ['Ellerinizi, kesme tahtasını ve kapları sıcak sabunlu suyla yıkayın.', 'Ispanağı bol suda yıkayıp saplarını ayıklayın.', 'Ispanak, muz, yumurta ve yulafı blenderda pürüzsüz çekin; 5 dakika bekletin.', 'Yapışmaz tavayı kısık ateşte ısıtın; kaşıkla küçük pankekler dökün.', 'Her yüzünü 2 dakika pişirin.', 'Bir tanesini ortadan bölün: içinde akışkan yumurta kalmamalı.', 'Tabakta 5 dakika dinlendirip ılıtın.', 'Buz kalıplarında dondurup 1 ay saklayabilirsiniz; buzdolabında çözdürüp bir kez ısıtın.'], tips: ['Yeşil renkli eğlenceli bir kahvaltı.'], storage: 'Hazırlandıktan hemen sonra tüketin.'),
  BabyRecipe(id: 'be24_28', title: 'Kuru köfte ve bulgur pilavı tabağı', age: '24+', category: 'Et', ingredient: 'dana kıyma', vegetable: 'domates', ingredients: ['100 g kıyma', '1 yemek kaşığı galeta unu', '3 yemek kaşığı bulgur', '1 çay kaşığı salça', 'Yarım su bardağı su'], steps: ['Ellerinizi, kesme tahtasını ve kapları sıcak sabunlu suyla yıkayın.', 'Kıyma ve galeta ununu yoğurup ceviz büyüklüğünde yassı köfteler yapın; ellerinizi yıkayın.', 'Köfteleri yapışmaz tavada orta ateşte her yüzü 4 dakika pişirin.', 'Köfte iç sıcaklığı 71°C olmalı; bir köfteyi ortadan bölün: içi pembe kalmamalı, suyu berrak akmalı.', 'Bulguru yıkayın; salçayı suyla açıp kaynatın, bulguru ekleyin.', 'Kapağı kapalı kısık ateşte 12 dakika pişirin; ocağı kapatıp 10 dakika demlendirin.', 'Köfteleri küçük parçalara bölüp pilavla tabağa dizin.', 'Tuz eklemeyin; 1–3 yaş için günlük tuz 2 g’ı geçmemeli, peynir ve salça zaten tuz içerir.', 'Kalanını kapalı kapta buzdolabında 2 gün saklayın; yalnızca bir kez ısıtın.'], tips: ['Aile yemeğinin çocuk porsiyonudur.'], storage: 'Buzdolabında 48 saat.'),
  BabyRecipe(id: 'be24_29', title: 'Elmalı havuçlu salata (çocuk)', age: '24+', category: 'Sebze', ingredient: 'havuç', vegetable: 'elma', ingredients: ['1 havuç', 'Yarım elma', '2 yemek kaşığı yoğurt', 'Birkaç damla limon (1 çay kaşığı)'], steps: ['Ellerinizi, kesme tahtasını ve kapları sıcak sabunlu suyla yıkayın.', 'Havuç ve elmayı yıkayıp soyun; çok ince rendeleyin.', 'Limonla karıştırın; elma kararmaz.', 'Yoğurdu buzdolabından 10 dakika önce çıkarın; çok soğuk vermeyin.', 'Yoğurdu ekleyip karıştırın.', 'Hemen servis edin.', 'Çiğ havucu kalın çubuk ya da iri parça halinde vermeyin; boğulma riski taşır.', 'Çocuk yerken yanında olun; dik otursun, yürürken ya da koşarken yemesin.'], tips: ['İnce rendelemek boğulma riskini azaltır.'], storage: 'Hazırlandıktan hemen sonra tüketin.'),
  BabyRecipe(id: 'be24_30', title: 'Fırında tatlı patates ve tavuk', age: '24+', category: 'Et', ingredient: 'tavuk', vegetable: 'tatlı patates', ingredients: ['80 g tavuk göğsü', '1 tatlı patates', '1 çay kaşığı zeytinyağı', '1 tutam kekik'], steps: ['Ellerinizi, kesme tahtasını ve kapları sıcak sabunlu suyla yıkayın.', 'Fırını 200°C’ye ısıtın; tepsiye yağlı kâğıt serin.', 'Çiğ eti ve tavuğu ayrı tahtada doğrayın; ardından tahtayı ve ellerinizi yıkayın.', 'Tatlı patatesi soyup tavuktan küçük küpler halinde doğrayın.', 'Tavuk ve tatlı patatesi zeytinyağı ve kekikle harmanlayıp tepsiye tek kat dizin.', '25 dakika pişirin; yarısında karıştırın.', 'Tavuk iç sıcaklığı 74°C olmalı; en büyük parçayı bölüp pembe kalmadığını kontrol edin.', 'Tepside 5 dakika dinlendirip ılıtın.', 'Kalanını kapalı kapta buzdolabında 2 gün saklayın; yalnızca bir kez ısıtın.'], tips: ['Tek tepside dengeli öğün.'], storage: 'Buzdolabında 48 saat.'),
  BabyRecipe(id: 'bf36_01', title: 'Fırında sebzeli lazanya (çocuk)', age: '36+', category: 'Makarna', ingredient: 'lazanya', vegetable: 'ıspanak', ingredients: ['4 lazanya yaprağı', '100 g kıyma', '1 su bardağı domates sosu', '1 su bardağı beşamel', '1 avuç ıspanak', '3 yemek kaşığı rendelenmiş kaşar'], steps: ['Ellerinizi, kesme tahtasını ve kapları sıcak sabunlu suyla yıkayın.', 'Kıymayı kaşıkla dağıtarak 5 dakika, rengi tamamen dönene kadar pişirin.', 'Domates sosunu ekleyip kısık ateşte 10 dakika pişirin.', 'Ispanağı yıkayıp ince doğrayın.', 'Fırını 180°C’ye ısıtın.', 'Kabın dibine biraz sos yayın; üzerine lazanya yaprağı, kıymalı sos, ıspanak ve beşamel dizin.', 'Katları tekrarlayıp en üste beşamel sürün ve kaşarı serpin.', 'Üzerini folyoyla kapatıp 20 dakika, folyoyu açıp 10 dakika daha pişirin.', 'Bıçak yapraklara kolayca batmalı.', '15 dakika dinlendirip küçük kareler halinde kesin; dinlenmeden kesilirse dağılır.', 'Buz kalıplarında dondurup 1 ay saklayabilirsiniz; buzdolabında çözdürüp bir kez ısıtın.'], tips: ['Sebzeyi katlar arasında saklamak işe yarar.'], storage: 'Buzdolabında 3 gün.'),
  BabyRecipe(id: 'bf36_02', title: 'Tavuklu sebzeli dürüm (çocuk)', age: '36+', category: 'Et', ingredient: 'tavuk', vegetable: 'havuç', ingredients: ['1 küçük lavaş', '60 g haşlanmış tavuk', '1 yemek kaşığı rendelenmiş havuç', '1 yemek kaşığı yoğurt', '1 marul yaprağı'], steps: ['Ellerinizi, kesme tahtasını ve kapları sıcak sabunlu suyla yıkayın.', 'Haşlanmış tavuğu ince didikleyin.', 'Marulu yıkayıp ince kıyın; havucu ince rendeleyin.', 'Lavaşı kuru tavada 30 saniye ısıtıp yumuşatın.', 'Lavaşa yoğurt sürün; tavuk, havuç ve marulu ortasına yerleştirin.', 'Alt kısmını katlayıp sıkıca sarın.', 'İkiye ya da 3 cm’lik dilimlere kesin.', 'Çocuk yerken yanında olun; dik otursun, yürürken ya da koşarken yemesin.'], tips: ['Beslenme çantası için uygundur.'], storage: 'Hazırlandıktan hemen sonra tüketin.'),
  BabyRecipe(id: 'bf36_03', title: 'Ev yapımı tavuk çorbası (şehriyeli)', age: '36+', category: 'Çorba', ingredient: 'tavuk', vegetable: 'havuç', ingredients: ['100 g tavuk', '1 havuç', '2 yemek kaşığı şehriye', '1 limon', '4 su bardağı su'], steps: ['Ellerinizi, kesme tahtasını ve kapları sıcak sabunlu suyla yıkayın.', 'Tavuğu suyla kaynatıp köpüğünü alın; kısık ateşte 25 dakika pişirin.', 'Tavuk iç sıcaklığı 74°C olmalı; en büyük parçayı bölüp pembe kalmadığını kontrol edin.', 'Tavuğu çıkarıp ince didikleyin.', 'Havucu küçük küp doğrayıp haşlama suyuna ekleyin; 5 dakika pişirin.', 'Şehriyeyi ekleyip 10 dakika pişirin.', 'Tavuğu geri ekleyip 1 dakika ısıtın.', 'Limonu servis ederken sıkın.', 'Tuz eklemeyin ya da çok az ekleyin; 1–3 yaşta günlük tuz 2 g’ı, 4–6 yaşta 3 g’ı geçmemeli.', 'Ilıtıp sıcaklığı bileğinizin iç kısmına damlatarak kontrol edin; ılık olmalı, sıcak değil.', 'Buz kalıplarında dondurup 1 ay saklayabilirsiniz; buzdolabında çözdürüp bir kez ısıtın.'], tips: ['Hastalıkta iyi gelen klasik bir çorbadır.'], storage: 'Buzdolabında 48 saat.'),
  BabyRecipe(id: 'bf36_04', title: 'Fırında köfte ve patates (aile)', age: '36+', category: 'Et', ingredient: 'dana kıyma', vegetable: 'patates', ingredients: ['200 g kıyma', '2 yemek kaşığı galeta unu', '2 patates', '1 domates', '1 yemek kaşığı zeytinyağı'], steps: ['Ellerinizi, kesme tahtasını ve kapları sıcak sabunlu suyla yıkayın.', 'Fırını 200°C’ye ısıtın; tepsiye yağlı kâğıt serin.', 'Kıyma ve galeta ununu yoğurun; ceviz büyüklüğünde yassı köfteler yapın ve ellerinizi yıkayın.', 'Patatesleri soyup ince dilimleyin; domatesi dilimleyin.', 'Patates ve domatesleri zeytinyağıyla harmanlayıp tepsiye dizin; köfteleri aralarına yerleştirin.', '30 dakika pişirin; yarısında köfteleri çevirin.', 'Köfte iç sıcaklığı 71°C olmalı; bir köfteyi ortadan bölün: içi pembe kalmamalı, suyu berrak akmalı.', 'Patates parmakla ezilecek kadar yumuşak olmalı.', 'Aile porsiyonundan çocuğa ayırırken tuzu ve acıyı eklemeden önce ayırın.', 'Çocuğun porsiyonunu küçük parçalara bölün.'], tips: ['Ailece paylaşılabilir.'], storage: 'Buzdolabında 48 saat.'),
  BabyRecipe(id: 'bf36_05', title: 'Peynirli makarna (fırında, çocuk)', age: '36+', category: 'Makarna', ingredient: 'makarna', vegetable: '—', ingredients: ['1 su bardağı makarna', '1 su bardağı beşamel', '4 yemek kaşığı rendelenmiş kaşar'], steps: ['Ellerinizi, kesme tahtasını ve kapları sıcak sabunlu suyla yıkayın.', 'Makarnayı tuzsuz kaynar suda paketteki süreden 2 dakika fazla, parmakla ezilecek kadar yumuşak haşlayın.', 'Süzülmüş makarnayı beşamelle karıştırın.', 'Fırını 200°C’ye ısıtın.', 'Karışımı fırın kabına alıp kaşarı serpin.', '15 dakika, üstü kızarana kadar pişirin.', '5 dakika dinlendirip servis edin.', 'Kaşar ve lor pastörize sütten olmalı; tuzlu peyniri 1 saat suda bekletip tuzunu alın.', 'Kalanını kapalı kapta buzdolabında 2 gün saklayın; yalnızca bir kez ısıtın.'], tips: ['Çocukların favori yemeklerindendir.'], storage: 'Buzdolabında 48 saat.'),
  BabyRecipe(id: 'bf36_06', title: 'Sebzeli pirinç topları (fırında)', age: '36+', category: 'Tahıl', ingredient: 'pirinç', vegetable: 'bezelye', ingredients: ['1 su bardağı pişmiş pirinç', '2 yemek kaşığı bezelye ve havuç', '1 yumurta', '2 yemek kaşığı rendelenmiş kaşar', '3 yemek kaşığı galeta unu'], steps: ['Ellerinizi, kesme tahtasını ve kapları sıcak sabunlu suyla yıkayın.', 'Fırını 200°C’ye ısıtın; tepsiye yağlı kâğıt serin.', 'Bezelye ve havucu 5 dakika haşlayıp süzün; bezelyeleri hafif ezin.', 'Pişmiş pirinç, sebzeler, yumurta ve kaşarı karıştırın.', 'Islak elle ceviz büyüklüğünde toplar yapıp hafifçe bastırın.', 'Galeta ununa bulayıp tepsiye dizin.', '20 dakika pişirin; yarısında çevirin.', 'Yumurtayı akı ve sarısı tamamen katılaşana kadar pişirin; akışkan bırakmayın.', 'Tepside 5 dakika dinlendirip ılıtın.', 'Buz kalıplarında dondurup 1 ay saklayabilirsiniz; buzdolabında çözdürüp bir kez ısıtın.'], tips: ['Artan pilavı değerlendirir.'], storage: 'Buzdolabında 48 saat.'),
  BabyRecipe(id: 'bf36_07', title: 'Mercimek köftesi (çocuk, acısız)', age: '36+', category: 'Baklagil', ingredient: 'kırmızı mercimek', vegetable: 'domates', ingredients: ['Yarım su bardağı kırmızı mercimek', 'Yarım su bardağı ince bulgur', '1 yemek kaşığı salça', '2 dal taze soğan', 'Yarım demet maydanoz', '1 yemek kaşığı zeytinyağı'], steps: ['Ellerinizi, kesme tahtasını ve kapları sıcak sabunlu suyla yıkayın.', 'Mercimeği yıkayıp 1,5 su bardağı suyla 15 dakika, dağılana kadar pişirin.', 'Ocağı kapatıp bulguru ekleyin; kapağı kapalı 20 dakika şişirin.', 'Zeytinyağında salçayı 1 dakika çevirip harca ekleyin.', 'Taze soğan ve maydanozu çok ince kıyıp ekleyin; ılıyınca 5 dakika yoğurun.', 'Avucunuzda sıkarak küçük köfteler yapın.', 'Marul yaprağıyla servis edin; yaprağı ince doğrayın.', 'Acı biber ve pul biber eklemeyin.', 'Tuz eklemeyin ya da çok az ekleyin; 1–3 yaşta günlük tuz 2 g’ı, 4–6 yaşta 3 g’ı geçmemeli.', 'Buzdolabında kapalı kapta 2 gün saklayın.'], tips: ['Acı biber kullanmayın.'], storage: 'Buzdolabında 48 saat.'),
  BabyRecipe(id: 'bf36_08', title: 'Yoğurtlu meyve parfe', age: '36+', category: 'Tatlı', ingredient: 'yoğurt', vegetable: 'çilek', ingredients: ['1 su bardağı yoğurt', 'Yarım su bardağı meyve', '3 yemek kaşığı granola'], steps: ['Ellerinizi, kesme tahtasını ve kapları sıcak sabunlu suyla yıkayın.', 'Meyveyi yıkayıp çocuğun çiğneyebileceği küçük parçalara doğrayın.', 'Üzüm, çeri domates ve benzeri yuvarlak besinleri 5 yaşına kadar dörde bölün.', 'Bardağın dibine yoğurt koyun; üzerine meyve ve granola ekleyin.', 'Katları bardak dolana kadar tekrarlayın.', 'Granolayı servis etmeden hemen önce ekleyin; bekleyince yumuşar.', 'Az şekerli, fındık-fıstık parçası içermeyen granola seçin; bütün kuruyemiş boğulma riski taşır.', 'Hemen servis edin; kalanını saklamayın.'], tips: ['Granolayı en son ekleyin.'], storage: 'Hazırlandıktan hemen sonra tüketin.'),
  BabyRecipe(id: 'bf36_09', title: 'Tavuklu sebzeli erişte', age: '36+', category: 'Makarna', ingredient: 'erişte', vegetable: 'brokoli', ingredients: ['Yarım su bardağı erişte', '60 g tavuk', '4 brokoli çiçeği', '1 havuç', '1 çay kaşığı soya sosu'], steps: ['Ellerinizi, kesme tahtasını ve kapları sıcak sabunlu suyla yıkayın.', 'Çiğ eti ve tavuğu ayrı tahtada doğrayın; ardından tahtayı ve ellerinizi yıkayın.', 'Tavuğu ince şeritler halinde doğrayın; brokoliyi küçük çiçeklere ayırın; havucu ince çubuklar halinde kesin.', 'Erişteyi tuzsuz kaynar suda 8–10 dakika haşlayıp süzün.', 'Tavayı ısıtıp tavuğu 6–7 dakika, beyazlayana kadar pişirin.', 'Sebzeleri ve 3 kaşık suyu ekleyin; kapağı kapalı 5 dakika yumuşatın.', 'Tavuk iç sıcaklığı 74°C olmalı; en büyük parçayı bölüp pembe kalmadığını kontrol edin.', 'Erişteyi ekleyip karıştırın.', 'Soya sosu çok tuzludur; az tuzlusunu seçin ve en fazla 1 çay kaşığı kullanın.', 'Uzun erişteleri kısa parçalara kesin.', 'Kalanını kapalı kapta buzdolabında 2 gün saklayın; yalnızca bir kez ısıtın.'], tips: ['Soya sosu tuzludur; az kullanın.'], storage: 'Buzdolabında 48 saat.'),
  BabyRecipe(id: 'bf36_10', title: 'Fırında balık parmakları (ev yapımı)', age: '36+', category: 'Balık', ingredient: 'mezgit', vegetable: '—', ingredients: ['150 g mezgit fileto', '1 yumurta', '4 yemek kaşığı galeta unu', '2 yemek kaşığı un', '1 çay kaşığı zeytinyağı'], steps: ['Ellerinizi, kesme tahtasını ve kapları sıcak sabunlu suyla yıkayın.', 'Fırını 210°C’ye ısıtın; tepsiye yağlı kâğıt serip zeytinyağıyla hafifçe yağlayın.', 'Mezgiti kâğıt havluyla kurulayın; parmaklarınızla kılçıkları yoklayıp ayıklayın.', 'Balığı çocuğun tutabileceği parmak şeklinde kesin.', 'Unu, çırpılmış yumurtayı ve galeta ununu üç ayrı kaba koyun.', 'Balıkları sırayla una, yumurtaya ve galeta ununa bulayıp tepsiye dizin.', '15 dakika pişirin; yarısında çevirin.', 'Balığı parmaklarınızla yoklayarak tüm kılçıkları ayıklayın; et opaklaşıp kolayca dağılıyorsa pişmiştir.', 'Yoğurda biraz dereotu karıştırıp sos olarak yanında verin.', 'Buz kalıplarında dondurup 1 ay saklayabilirsiniz; buzdolabında çözdürüp bir kez ısıtın.'], tips: ['Hazır balık parmaklarından daha az tuz içerir.'], storage: 'Hazırlandıktan hemen sonra tüketin.'),
  BabyRecipe(id: 'bf36_11', title: 'Sebzeli kinoa salatası (çocuk)', age: '36+', category: 'Tahıl', ingredient: 'kinoa', vegetable: 'mısır', ingredients: ['Yarım su bardağı pişmiş kinoa', '2 yemek kaşığı mısır', '1 salatalık', '4 çeri domates (dörde bölünmüş)', '1 yemek kaşığı zeytinyağı'], steps: ['Ellerinizi, kesme tahtasını ve kapları sıcak sabunlu suyla yıkayın.', 'Pişmiş kinoayı geniş bir kaba yayıp soğutun.', 'Salatalığı soyup küçük küp doğrayın; mısırı ince kıyın.', 'Çeri domatesleri dörde bölün.', 'Üzüm, çeri domates ve benzeri yuvarlak besinleri 5 yaşına kadar dörde bölün.', 'Kinoa ve sebzeleri karıştırıp zeytinyağını ekleyin.', 'Hemen servis edin; buzdolabında 1 gün saklayın.', 'Çocuk yerken yanında olun; dik otursun, yürürken ya da koşarken yemesin.'], tips: ['Çeri domatesleri mutlaka dörde bölün.'], storage: 'Buzdolabında 48 saat.'),
  BabyRecipe(id: 'bf36_12', title: 'Ev yapımı pizza (çocuklarla)', age: '36+', category: 'Fırın', ingredient: 'un', vegetable: 'mısır', ingredients: ['1 su bardağı un', 'Yarım çay kaşığı instant maya', 'Yarım su bardağı ılık su', '2 yemek kaşığı domates sosu', '4 yemek kaşığı rendelenmiş kaşar', '2 yemek kaşığı mısır'], steps: ['Ellerinizi, kesme tahtasını ve kapları sıcak sabunlu suyla yıkayın.', 'Unu, mayayı ve ılık suyu yoğurup pürüzsüz bir hamur yapın.', 'Üzerini örtüp ılık bir yerde 30 dakika dinlendirin.', 'Fırını 220°C’ye ısıtın; tepsiye yağlı kâğıt serin.', 'Hamuru 4 parçaya bölüp çocukla birlikte küçük yuvarlaklar halinde açın.', 'Domates sosunu sürün; kaşar ve ince kıyılmış mısırı serpin.', 'Çocuğunuz hamuru açma ya da malzeme dizme gibi işlerde yardım edebilir; sıcak fırına siz yaklaşın.', '12 dakika, kenarları kızarıp kaşar eriyene kadar pişirin.', 'Erimiş peynir içi çok sıcak kalır; ılıtmadan vermeyin.', 'Ilıtıp dilimleyin.', 'Kaşar ve lor pastörize sütten olmalı; tuzlu peyniri 1 saat suda bekletip tuzunu alın.'], tips: ['Mutfakta birlikte çalışmak yemeğe ilgiyi artırır.'], storage: 'Aynı gün.'),
  BabyRecipe(id: 'bf36_13', title: 'Kıymalı pide (çocuk porsiyonu)', age: '36+', category: 'Fırın', ingredient: 'pide', vegetable: 'domates', ingredients: ['1 küçük pide', '60 g kıyma', '1 yemek kaşığı rendelenmiş domates', '1 yemek kaşığı rendelenmiş kaşar'], steps: ['Ellerinizi, kesme tahtasını ve kapları sıcak sabunlu suyla yıkayın.', 'Kıymayı kaşıkla dağıtarak 5 dakika, rengi tamamen dönene kadar pişirin.', 'Rendelenmiş domatesi ekleyip 5 dakika suyunu çekene kadar pişirin.', 'Kıymada pembe kalmadığını kontrol edin.', 'Fırını 200°C’ye ısıtın.', 'Harcı pideye yayıp kaşarı serpin.', '8 dakika, kaşar eriyene kadar pişirin.', 'Erimiş peynir içi çok sıcak kalır; ılıtmadan vermeyin.', 'Ilıtıp çocuğun tutabileceği dilimlere kesin.', 'Tuz eklemeyin ya da çok az ekleyin; 1–3 yaşta günlük tuz 2 g’ı, 4–6 yaşta 3 g’ı geçmemeli.'], tips: ['Hazır pide ile pratik.'], storage: 'Hazırlandıktan hemen sonra tüketin.'),
  BabyRecipe(id: 'bf36_14', title: 'Sebze çorbası (alfabe makarnalı)', age: '36+', category: 'Çorba', ingredient: 'makarna', vegetable: 'havuç', ingredients: ['2 yemek kaşığı harf makarna', '1 havuç', '1 patates', '1 kabak', '3 su bardağı su', '1 çay kaşığı tereyağı'], steps: ['Ellerinizi, kesme tahtasını ve kapları sıcak sabunlu suyla yıkayın.', 'Havuç, patates ve kabağı küçük küp doğrayın.', 'Tereyağını tencerede eritip sebzeleri 3 dakika çevirin.', 'Suyu ekleyin; kısık ateşte 15 dakika pişirin.', 'Harf makarnayı ekleyip 8 dakika, yumuşayana kadar pişirin.', 'Kâsede harfleri birlikte bulmak çocuğun yemeğe ilgisini artırır.', 'Tuz eklemeyin ya da çok az ekleyin; 1–3 yaşta günlük tuz 2 g’ı, 4–6 yaşta 3 g’ı geçmemeli.', 'Ilıtıp sıcaklığı bileğinizin iç kısmına damlatarak kontrol edin; ılık olmalı, sıcak değil.', 'Kalanını kapalı kapta buzdolabında 2 gün saklayın; yalnızca bir kez ısıtın.'], tips: ['Harf makarna yemeği eğlenceli kılar.'], storage: 'Buzdolabında 48 saat.'),
  BabyRecipe(id: 'bf36_15', title: 'Peynirli omlet sandviç (çocuk)', age: '36+', category: 'Kahvaltı', ingredient: 'yumurta', vegetable: '—', ingredients: ['1 yumurta', '1 dilim kaşar', '2 dilim ekmek', '1 çay kaşığı tereyağı'], steps: ['Ellerinizi, kesme tahtasını ve kapları sıcak sabunlu suyla yıkayın.', 'Yumurtayı çırpıp tereyağlı tavada ince bir omlet yapın.', 'Yumurtayı akı ve sarısı tamamen katılaşana kadar pişirin; akışkan bırakmayın.', 'Omleti ekmek boyutunda katlayın.', 'Kaşarla birlikte iki ekmek arasına koyun.', 'Tavada orta ateşte her yüzü 2 dakika, kaşar eriyene kadar ısıtın.', 'Erimiş peynir içi çok sıcak kalır; ılıtmadan vermeyin.', 'Dört parçaya kesip servis edin.', 'Kaşar ve lor pastörize sütten olmalı; tuzlu peyniri 1 saat suda bekletip tuzunu alın.'], tips: ['Okul öncesi kahvaltı için pratik.'], storage: 'Hazırlandıktan hemen sonra tüketin.'),
  BabyRecipe(id: 'bf36_16', title: 'Etli sebzeli güveç (aile)', age: '36+', category: 'Et', ingredient: 'dana eti', vegetable: 'patates', ingredients: ['200 g kuşbaşı', '1 patates', '1 havuç', '1 kabak', '1 domates', '1 yemek kaşığı zeytinyağı'], steps: ['Ellerinizi, kesme tahtasını ve kapları sıcak sabunlu suyla yıkayın.', 'Çiğ eti ve tavuğu ayrı tahtada doğrayın; ardından tahtayı ve ellerinizi yıkayın.', 'Eti küçük kuşbaşı doğrayıp yağ ve sinirlerini ayıklayın.', 'Patates, havuç, kabak ve domatesi küp doğrayın.', 'Tüm malzemeyi zeytinyağıyla güvece alın ve 1 su bardağı su ekleyin.', 'Güveci soğuk fırına koyun; ani ısı farkı toprak güveci çatlatır.', '190°C’de 70 dakika, et yumuşayana kadar pişirin.', 'Güveci ahşap bir yüzeye koyun; çok sıcaktır, çocuğu uzak tutun.', 'Eti küçük doğrayıp sebzelerle servis edin; içi pembe kalmamalı.', 'Aile porsiyonundan çocuğa ayırırken tuzu ve acıyı eklemeden önce ayırın.', 'Buz kalıplarında dondurup 1 ay saklayabilirsiniz; buzdolabında çözdürüp bir kez ısıtın.'], tips: ['Çocuk porsiyonunu ayırıp küçük doğrayın.'], storage: 'Buzdolabında 3 gün.'),
  BabyRecipe(id: 'bf36_17', title: 'Fırında tatlı patates kızartması', age: '36+', category: 'Sebze', ingredient: 'tatlı patates', vegetable: 'tatlı patates', ingredients: ['1 tatlı patates', '1 çay kaşığı zeytinyağı', '1 tutam tatlı toz biber'], steps: ['Ellerinizi, kesme tahtasını ve kapları sıcak sabunlu suyla yıkayın.', 'Fırını 210°C’ye ısıtın; tepsiye yağlı kâğıt serin.', 'Tatlı patatesi iyice yıkayıp soyun; parmak kalınlığında çubuklar kesin.', 'Kâğıt havluyla kurulayın; kuru patates daha iyi kızarır.', 'Zeytinyağı ve tatlı toz biberle harmanlayıp tepsiye tek kat, aralıklı dizin.', '25 dakika pişirin; yarısında çevirin.', 'İçi yumuşak, dışı hafif kızarmış olmalı.', 'Tepside 5 dakika dinlendirip ılıtın.', 'Tuz eklemeyin ya da çok az ekleyin; 1–3 yaşta günlük tuz 2 g’ı, 4–6 yaşta 3 g’ı geçmemeli.'], tips: ['Kızartmaya sağlıklı alternatif.'], storage: 'Hazırlandıktan hemen sonra tüketin.'),
  BabyRecipe(id: 'bf36_18', title: 'Yulaflı kakaolu kurabiye (az şekerli)', age: '36+', category: 'Tatlı', ingredient: 'yulaf', vegetable: 'muz', ingredients: ['1 muz', '1 su bardağı yulaf', '1 yemek kaşığı kakao', '1 yemek kaşığı fıstık ezmesi'], steps: ['Ellerinizi, kesme tahtasını ve kapları sıcak sabunlu suyla yıkayın.', 'Fırını 180°C’ye ısıtın; tepsiye yağlı kâğıt serin.', 'Olgun muzu çatalla pürüzsüz ezin.', 'Yulaf, kakao ve fıstık ezmesini ekleyip karıştırın; 10 dakika bekletin.', 'Kaşıkla tepsiye küçük yuvarlaklar bırakıp 1 cm kalınlığa bastırın.', '15 dakika pişirin.', 'Tepside 10 dakika soğutun; sıcakken kolay dağılır.', 'Yer fıstığı alerjisi açısından ilk kez veriyorsanız az miktarla başlayıp gözlemleyin.', 'Kapalı kapta 3 gün saklayın.'], tips: ['Yer fıstığı alerjisine dikkat edin.'], storage: 'Hava almayan kapta 3 gün.'),
  BabyRecipe(id: 'bf36_19', title: 'Tavuk sote ve pilav tabağı', age: '36+', category: 'Et', ingredient: 'tavuk', vegetable: 'biber', ingredients: ['80 g tavuk göğsü', 'Yarım kırmızı biber', '1 yemek kaşığı rendelenmiş domates', 'Yarım su bardağı pişmiş pilav', '1 çay kaşığı zeytinyağı'], steps: ['Ellerinizi, kesme tahtasını ve kapları sıcak sabunlu suyla yıkayın.', 'Çiğ eti ve tavuğu ayrı tahtada doğrayın; ardından tahtayı ve ellerinizi yıkayın.', 'Tavuğu küçük doğrayın; biberin çekirdeklerini çıkarıp ince doğrayın.', 'Zeytinyağını tavada ısıtıp tavuğu 6–7 dakika, beyazlayana kadar pişirin.', 'Biber ve domatesi ekleyin; kapağı kapalı kısık ateşte 10 dakika pişirin.', 'Tavuk iç sıcaklığı 74°C olmalı; en büyük parçayı bölüp pembe kalmadığını kontrol edin.', 'Pişmiş pilavla tabağa alıp ılık servis edin.', 'Kalanını kapalı kapta buzdolabında 2 gün saklayın; yalnızca bir kez ısıtın.'], tips: ['Renkli tabaklar iştahı açar.'], storage: 'Buzdolabında 48 saat.'),
  BabyRecipe(id: 'bf36_20', title: 'Ispanaklı peynirli gözleme (çocuk)', age: '36+', category: 'Fırın', ingredient: 'yufka', vegetable: 'ıspanak', ingredients: ['1 yufka', '1 avuç ıspanak (haşlanmış)', '3 yemek kaşığı lor', '1 çay kaşığı tereyağı'], steps: ['Ellerinizi, kesme tahtasını ve kapları sıcak sabunlu suyla yıkayın.', 'Haşlanmış ıspanağı iyice sıkıp ince kıyın; lorla karıştırın.', 'Yufkayı tezgâha serin; harcı ortasına yayın.', 'Kenarları ortaya katlayarak kare bir paket yapın.', 'Tereyağını tavada eritip gözlemeyi orta ateşte her yüzü 3 dakika kızartın.', '5 dakika ılıtıp dilimleyin.', 'Kaşar ve lor pastörize sütten olmalı; tuzlu peyniri 1 saat suda bekletip tuzunu alın.', 'Kalanını kapalı kapta buzdolabında 2 gün saklayın; yalnızca bir kez ısıtın.'], tips: ['Ispanağın suyunu sıkın.'], storage: 'Hazırlandıktan hemen sonra tüketin.'),
  BabyRecipe(id: 'bf36_21', title: 'Mercimek çorbası (aile, çocuk porsiyonu)', age: '36+', category: 'Çorba', ingredient: 'kırmızı mercimek', vegetable: 'havuç', ingredients: ['Yarım su bardağı kırmızı mercimek', '1 havuç', '1 soğan', '1 çay kaşığı tereyağı', '4 su bardağı su'], steps: ['Ellerinizi, kesme tahtasını ve kapları sıcak sabunlu suyla yıkayın.', 'Soğanı ince doğrayın; havucu küçük doğrayın; mercimeği yıkayın.', 'Tereyağını tencerede eritip soğanı 3 dakika yumuşatın.', 'Mercimek, havuç ve suyu ekleyip kaynatın; köpüğünü alın.', 'Kısık ateşte 25 dakika, mercimek dağılana kadar pişirin.', 'Blenderdan geçirin; koyuysa sıcak su ekleyin.', 'Aile porsiyonundan çocuğa ayırırken tuzu ve acıyı eklemeden önce ayırın.', 'Limon ve ekmekle servis edin.', 'Ilıtıp sıcaklığı bileğinizin iç kısmına damlatarak kontrol edin; ılık olmalı, sıcak değil.', 'Buz kalıplarında dondurup 1 ay saklayabilirsiniz; buzdolabında çözdürüp bir kez ısıtın.'], tips: ['Aile sofrasıyla ortak yemek alışkanlığı kazandırır.'], storage: 'Buzdolabında 3 gün.'),
  BabyRecipe(id: 'bf36_22', title: 'Elmalı tarçınlı muffin (çocuk)', age: '36+', category: 'Tatlı', ingredient: 'un', vegetable: 'elma', ingredients: ['1 elma (rendelenmiş)', '1 yumurta', '3 yemek kaşığı yoğurt', '1 su bardağı tam buğday unu', '1 çay kaşığı kabartma tozu', '2 yemek kaşığı bal', '1 tutam tarçın'], steps: ['Ellerinizi, kesme tahtasını ve kapları sıcak sabunlu suyla yıkayın.', 'Fırını 180°C’ye ısıtın; mini muffin kalıbını yağlayın ya da kâğıt kapsül koyun.', 'Elmayı soyup ince rendeleyin.', 'Elma, yumurta, yoğurt ve balı çırpın.', 'Un, kabartma tozu ve tarçını ekleyip sadece karışana kadar karıştırın.', 'Kalıpları dörtte üçüne kadar doldurun.', '18 dakika pişirin; ortasına batırılan kürdan temiz çıkmalı.', 'Kalıpta 5 dakika bekletip ılıtın.', 'Bal yalnızca 1 yaşını doldurmuş çocuklara verilebilir.', 'Buz kalıplarında dondurup 1 ay saklayabilirsiniz; buzdolabında çözdürüp bir kez ısıtın.'], tips: ['Bal 1 yaşından sonra kullanılabilir.'], storage: 'Hava almayan kapta 2 gün.'),
  BabyRecipe(id: 'bf36_23', title: 'Fırında sebzeli tavuk köftesi (aile)', age: '36+', category: 'Et', ingredient: 'tavuk kıyma', vegetable: 'kabak', ingredients: ['200 g tavuk kıyma', '1 kabak (rendelenmiş)', '1 havuç (rendelenmiş)', '3 yemek kaşığı yulaf', '1 yumurta'], steps: ['Ellerinizi, kesme tahtasını ve kapları sıcak sabunlu suyla yıkayın.', 'Fırını 200°C’ye ısıtın; tepsiye yağlı kâğıt serin.', 'Kabak ve havucu rendeleyip avuçlarınızla suyunu iyice sıkın.', 'Tavuk kıyma, sebzeler, yulaf ve yumurtayı yoğurun; 10 dakika dinlendirin ve ellerinizi yıkayın.', 'Islak elle ceviz büyüklüğünde yassı köfteler yapıp tepsiye dizin.', '20 dakika pişirin; yarısında çevirin.', 'Tavuk iç sıcaklığı 74°C olmalı; bir köfteyi ortadan bölün: içi pembe kalmamalı, suyu berrak akmalı.', 'Yoğurdu buzdolabından 10 dakika önce çıkarın; çok soğuk vermeyin.', 'Yoğurtla servis edin.', 'Buz kalıplarında dondurup 1 ay saklayabilirsiniz; buzdolabında çözdürüp bir kez ısıtın.'], tips: ['Sebzeler köfteyi yumuşak tutar.'], storage: 'Buzdolabında 48 saat.'),
  BabyRecipe(id: 'bf36_24', title: 'Kuru fasulye (çocuk porsiyonu)', age: '36+', category: 'Baklagil', ingredient: 'kuru fasulye', vegetable: 'havuç', ingredients: ['Yarım su bardağı haşlanmış kuru fasulye', '1 havuç', '1 çay kaşığı salça', '1 çay kaşığı tereyağı', '1 su bardağı su'], steps: ['Ellerinizi, kesme tahtasını ve kapları sıcak sabunlu suyla yıkayın.', 'Havucu küçük küp doğrayın.', 'Tereyağını tencerede eritip salçayı 1 dakika çevirin.', 'Havuç ve haşlanmış fasulyeyi ekleyip 2 dakika karıştırın.', 'Suyu ekleyin; kapağı kapalı kısık ateşte 20 dakika pişirin.', 'Fasulyeleri hafif ezip pilavla servis edin.', 'Yoğurdu buzdolabından 10 dakika önce çıkarın; çok soğuk vermeyin.', 'Yanına yoğurt ekleyin.', 'Kuru baklagiller bebeklerde gaz yapabilir; ilk kez veriyorsanız az porsiyonla başlayın.', 'Tuz eklemeyin ya da çok az ekleyin; 1–3 yaşta günlük tuz 2 g’ı, 4–6 yaşta 3 g’ı geçmemeli.', 'Buz kalıplarında dondurup 1 ay saklayabilirsiniz; buzdolabında çözdürüp bir kez ısıtın.'], tips: ['Gaz yapabileceğinden az porsiyonla başlayın.'], storage: 'Buzdolabında 3 gün.'),
  BabyRecipe(id: 'bf36_25', title: 'Meyveli yoğurtlu buzlu çubuk', age: '36+', category: 'Tatlı', ingredient: 'yoğurt', vegetable: 'çilek', ingredients: ['1 su bardağı yoğurt', '1 su bardağı çilek', '1 muz'], steps: ['Ellerinizi, kesme tahtasını ve kapları sıcak sabunlu suyla yıkayın.', 'Çilekleri yıkayıp saplarını ayırın; muzu soyup dilimleyin.', 'Yoğurt, çilek ve muzu blenderda pürüzsüz olana kadar çekin.', 'Buzluk kalıplarına dökün ve çubukları takın.', 'Dondurucuda en az 5 saat bekletin.', 'Kalıbı birkaç saniye ılık su altında tutup çıkarın.', 'Şeker eklemeyin; tatlılığı olgun meyveden gelsin.', 'Çözülen dondurmayı yeniden dondurmayın.'], tips: ['Hazır dondurmaya şekersiz alternatif.'], storage: 'Dondurucuda 1 ay.'),
  BabyRecipe(id: 'bf36_26', title: 'Kabaklı peynirli krep', age: '36+', category: 'Kahvaltı', ingredient: 'un', vegetable: 'kabak', ingredients: ['1 yumurta', '4 yemek kaşığı un', '5 yemek kaşığı süt', '2 yemek kaşığı rendelenmiş kabak', '2 yemek kaşığı lor'], steps: ['Ellerinizi, kesme tahtasını ve kapları sıcak sabunlu suyla yıkayın.', 'Kabağı rendeleyip suyunu iyice sıkın.', 'Yumurta, un ve sütü pürüzsüz çırpın; kabağı ekleyin.', 'Yapışmaz tavayı kısık ateşte ısıtıp bir kepçe hamuru döküp yayın.', 'Altı pişince çevirip 1 dakika daha pişirin.', 'Krepin üzerine lor sürüp rulo yapın.', 'Çocuğun tutabileceği dilimlere kesin.', 'Kaşar ve lor pastörize sütten olmalı; tuzlu peyniri 1 saat suda bekletip tuzunu alın.', 'Kalanını kapalı kapta buzdolabında 2 gün saklayın; yalnızca bir kez ısıtın.'], tips: ['Sebzeyi krepe gizlemek pratik bir yöntemdir.'], storage: 'Buzdolabında 48 saat.'),
  BabyRecipe(id: 'bf36_27', title: 'Patatesli yumurtalı salata (çocuk)', age: '36+', category: 'Sebze', ingredient: 'patates', vegetable: 'yumurta', ingredients: ['2 haşlanmış patates', '1 haşlanmış yumurta', '2 yemek kaşığı yoğurt', 'Birkaç dal dereotu'], steps: ['Ellerinizi, kesme tahtasını ve kapları sıcak sabunlu suyla yıkayın.', 'Patatesleri kabuğuyla 20 dakika haşlayıp soğutun, soyun ve küp doğrayın.', 'Yumurtayı kaynar suda 10 dakika haşlayıp soğuk suya alın, soyup doğrayın.', 'Yumurtayı akı ve sarısı tamamen katılaşana kadar pişirin; akışkan bırakmayın.', 'Yoğurt ve ince kıyılmış dereotuyla karıştırın.', 'Hemen servis edin; buzdolabında en fazla 1 gün saklayın.', 'Yoğurtlu salatayı oda sıcaklığında 1 saatten fazla bırakmayın.'], tips: ['Doyurucu bir öğle yemeğidir.'], storage: 'Hazırlandıktan hemen sonra tüketin.'),
  BabyRecipe(id: 'bf36_28', title: 'Fırında sebzeli bulgur', age: '36+', category: 'Tahıl', ingredient: 'bulgur', vegetable: 'biber', ingredients: ['Yarım su bardağı bulgur', '1 kırmızı biber', '1 kabak', '1 domates', '1 yemek kaşığı zeytinyağı', '1 su bardağı sıcak su'], steps: ['Ellerinizi, kesme tahtasını ve kapları sıcak sabunlu suyla yıkayın.', 'Fırını 190°C’ye ısıtın.', 'Bulguru yıkayıp süzün.', 'Biber, kabak ve domatesi küçük küp doğrayın.', 'Sebzeler, bulgur, zeytinyağı ve sıcak suyu fırın kabına alıp karıştırın.', 'Üzerini folyoyla sıkıca kapatıp 30 dakika, bulgur suyunu çekene kadar pişirin.', 'Folyoyu açarken buhara dikkat edin; 10 dakika dinlendirip servis edin.', 'Tuz eklemeyin ya da çok az ekleyin; 1–3 yaşta günlük tuz 2 g’ı, 4–6 yaşta 3 g’ı geçmemeli.', 'Kalanını kapalı kapta buzdolabında 2 gün saklayın; yalnızca bir kez ısıtın.'], tips: ['Fırında pilav taneli olur.'], storage: 'Buzdolabında 48 saat.'),
  BabyRecipe(id: 'bf36_29', title: 'Hindi göğsü sandviç (ev yapımı)', age: '36+', category: 'Et', ingredient: 'hindi', vegetable: 'marul', ingredients: ['2 dilim tam buğday ekmeği', '40 g haşlanmış hindi göğsü (ince dilim)', '1 yemek kaşığı yoğurt', '1 marul yaprağı'], steps: ['Ellerinizi, kesme tahtasını ve kapları sıcak sabunlu suyla yıkayın.', 'Hindi göğsünü haşlayıp soğutun ve ince dilimleyin.', 'Marulu yıkayıp kurulayın.', 'Ekmeklere yoğurt sürün; hindi ve marulu yerleştirip kapatın.', 'Dört parçaya kesip servis edin.', 'Hazır şarküteri hindi yerine ev yapımı haşlanmış hindi kullanın; hazır olanlar çok tuz ve katkı içerir.', 'Çocuk yerken yanında olun; dik otursun, yürürken ya da koşarken yemesin.'], tips: ['Hazır şarküteri ürünleri yerine evde haşlanmış et tercih edin.'], storage: 'Hazırlandıktan hemen sonra tüketin.'),
  BabyRecipe(id: 'bf36_30', title: 'Fırında elma halkaları (tarçınlı)', age: '36+', category: 'Tatlı', ingredient: 'elma', vegetable: 'elma', ingredients: ['2 elma', '1 çay kaşığı tarçın'], steps: ['Ellerinizi, kesme tahtasını ve kapları sıcak sabunlu suyla yıkayın.', 'Fırını 120°C’ye ısıtın; tepsiye yağlı kâğıt serin.', 'Elmaları yıkayın; çekirdek evini çıkarıp 3 mm inceliğinde halkalar kesin.', 'Halkaları tepsiye üst üste gelmeyecek şekilde dizip tarçın serpin.', '90 dakika pişirin; 45. dakikada çevirin.', 'Fırını kapatıp kapağı aralık şekilde halkaları içeride soğutun; kurur ve çıtırlaşır.', 'Kurutulmuş elma sert ve yapışkan olabilir; küçük çocuklara küçük parçalar halinde, oturur durumda verin.', 'Kapalı kavanozda 1 hafta saklayın.'], tips: ['Cips yerine sağlıklı atıştırmalık.'], storage: 'Hava almayan kapta 1 hafta.'),
  BabyRecipe(id: 'bg6_01', title: 'Kabak ve patates püresi', age: '6+', category: 'Sebze', ingredient: 'kabak', vegetable: 'kabak', ingredients: ['1 küçük kabak', '1 küçük patates', '1 çay kaşığı zeytinyağı'], steps: ['Malzemeleri yıkayın, gerekiyorsa soyup küçük doğrayın.', 'Buharda 12 dakika pişirin.', 'Blender veya çatalla yaşa uygun kıvamda ezin.', 'Gerekirse haşlama suyu veya anne sütüyle kıvamı ayarlayın.', 'Ilıtıp servis edin.'], tips: ['Zeytinyağını servis öncesi ekleyin.'], storage: 'Buzdolabında 24 saat; buz kalıbında 1 ay dondurulabilir.'),
