  BabyRecipe(id: 'bg6_09', title: 'Erik püresi (pişmiş)', age: '6+', category: 'Meyve', ingredient: 'erik', vegetable: 'erik', ingredients: ['4 olgun mürdüm eriği', '2 yemek kaşığı içme suyu'], steps: ['Malzemeleri yıkayın, gerekiyorsa soyup küçük doğrayın.', 'Çekirdeklerini çıkarıp suyla 5 dakika pişirin.', 'Blender veya çatalla yaşa uygun kıvamda ezin.', 'Gerekirse haşlama suyu veya anne sütüyle kıvamı ayarlayın.', 'Ilıtıp servis edin.'], tips: ['Kabızlıkta yardımcı olabilir.'], storage: 'Buzdolabında 24 saat; buz kalıbında 1 ay dondurulabilir.'),
