  BabyRecipe(id: 'bg8_01', title: 'Tavuklu kabak püresi', age: '8+', category: 'Et', ingredient: 'tavuk', vegetable: 'kabak', ingredients: ['30 g tavuk göğsü', '1 küçük kabak', '1 çay kaşığı zeytinyağı'], steps: ['Malzemeleri yıkayın, gerekiyorsa soyup küçük doğrayın.', 'Tavuğu 15 dakika haşlayın, kabağı ekleyip 8 dakika daha pişirin.', 'Blender veya çatalla yaşa uygun kıvamda ezin.', 'Gerekirse haşlama suyu veya anne sütüyle kıvamı ayarlayın.', 'Ilıtıp servis edin.'], tips: ['Tavuk tamamen pişmeli.'], storage: 'Buzdolabında 24 saat; buz kalıbında 1 ay dondurulabilir.'),
  BabyRecipe(id: 'bg8_02', title: 'Hindili sebze püresi', age: '8+', category: 'Et', ingredient: 'hindi', vegetable: 'havuç', ingredients: ['30 g hindi göğsü', 'Yarım havuç', '1 küçük patates'], steps: ['Malzemeleri yıkayın, gerekiyorsa soyup küçük doğrayın.', 'Hepsini 20 dakika haşlayın.', 'Blender veya çatalla yaşa uygun kıvamda ezin.', 'Gerekirse haşlama suyu veya anne sütüyle kıvamı ayarlayın.', 'Ilıtıp servis edin.'], tips: ['Hindi az yağlı protein kaynağıdır.'], storage: 'Buzdolabında 24 saat; buz kalıbında 1 ay dondurulabilir.'),
  BabyRecipe(id: 'bg8_03', title: 'Yeşil mercimekli sebze püresi', age: '8+', category: 'Baklagil', ingredient: 'yeşil mercimek', vegetable: 'kabak', ingredients: ['2 yemek kaşığı yeşil mercimek (ıslatılmış)', 'Yarım kabak', 'Yarım havuç'], steps: ['Malzemeleri yıkayın, gerekiyorsa soyup küçük doğrayın.', 'Mercimeği 25 dakika, sebzeleri ekleyip 10 dakika pişirin.', 'Blender veya çatalla yaşa uygun kıvamda ezin.', 'Gerekirse haşlama suyu veya anne sütüyle kıvamı ayarlayın.', 'Ilıtıp servis edin.'], tips: ['Islatmak gaz yapıcı etkiyi azaltır.'], storage: 'Buzdolabında 24 saat; buz kalıbında 1 ay dondurulabilir.'),
  BabyRecipe(id: 'bg8_04', title: 'Dana etli patates püresi', age: '8+', category: 'Et', ingredient: 'dana eti', vegetable: 'patates', ingredients: ['30 g dana kuşbaşı', '1 küçük patates', 'Yarım havuç'], steps: ['Malzemeleri yıkayın, gerekiyorsa soyup küçük doğrayın.', 'Eti 40 dakika haşlayın, sebzeleri ekleyip 15 dakika pişirin.', 'Blender veya çatalla yaşa uygun kıvamda ezin.', 'Gerekirse haşlama suyu veya anne sütüyle kıvamı ayarlayın.', 'Ilıtıp servis edin.'], tips: ['Kırmızı et demir sağlar.'], storage: 'Buzdolabında 24 saat; buz kalıbında 1 ay dondurulabilir.'),
  BabyRecipe(id: 'bg8_05', title: 'Yoğurtlu muz ezmesi', age: '8+', category: 'Meyve', ingredient: 'yoğurt', vegetable: 'muz', ingredients: ['3 yemek kaşığı ev yoğurdu', 'Çeyrek muz'], steps: ['Malzemeleri yıkayın, gerekiyorsa soyup küçük doğrayın.', 'Pişirmeden muzu hazırlayın.', 'Blender veya çatalla yaşa uygun kıvamda ezin.', 'Gerekirse haşlama suyu veya anne sütüyle kıvamı ayarlayın.', 'Ilıtıp servis edin.'], tips: ['Yoğurt tam yağlı ve şekersiz olmalı.'], storage: 'Hazırlandıktan hemen sonra tüketin.'),
  BabyRecipe(id: 'bg9_01', title: 'Domatesli kabaklı bulgur lapası', age: '9+', category: 'Tahıl', ingredient: 'bulgur', vegetable: 'kabak', ingredients: ['2 yemek kaşığı ince bulgur', 'Yarım kabak', 'Yarım domates (kabuksuz)', '1 su bardağı içme suyu'], steps: ['Ellerinizi, kesme tahtasını ve kapları sıcak sabunlu suyla yıkayın.', 'Domatesin kabuğunu soyup çekirdeklerini ayıklayın; kabakla birlikte küçük doğrayın.', 'Sebzeler, bulgur ve suyu tencereye alıp kaynatın.', 'Kısık ateşte ara ara karıştırarak 15 dakika yumuşayana kadar pişirin.', 'Ocaktan alıp 5 dakika demlendirin.', 'Çatalla hafif ezin.', 'Tuz, şeker ve bal eklemeyin; 1 yaş altı bebeklere uygun değildir.', 'Ilıtıp sıcaklığı bileğinizin iç kısmına damlatarak kontrol edin; ılık olmalı, sıcak değil.', 'Kalanını bebeğin ağzı değmemiş kaşıkla ayırıp kapalı kapta buzdolabında 24 saat saklayın; tekrar ısıtmayı bir kez yapın.'], tips: ['Parçalı kıvam çiğnemeyi destekler.'], storage: 'Buzdolabında 24 saat; buz kalıbında 1 ay dondurulabilir.'),
  BabyRecipe(id: 'bg9_02', title: 'Somonlu patates ezmesi', age: '9+', category: 'Balık', ingredient: 'somon', vegetable: 'patates', ingredients: ['30 g kılçıksız somon', '1 küçük patates', '1 çay kaşığı tereyağı'], steps: ['Ellerinizi, kesme tahtasını ve kapları sıcak sabunlu suyla yıkayın.', 'Patatesi soyup küp doğrayın ve kaynar suda 12–15 dakika haşlayın.', 'Tencereye 2 parmak su koyup buhar sepetini yerleştirin; su kaynayınca sebzeyi sepete alıp kapağı kapatın.', 'Somonu buhar sepetinde 10 dakika pişirin.', 'Balığı parmaklarınızla yoklayarak tüm kılçıkları ayıklayın; et opaklaşıp kolayca dağılıyorsa pişmiştir.', 'Patates, somon ve tereyağını çatalla ezin.', 'Tuz, şeker ve bal eklemeyin; 1 yaş altı bebeklere uygun değildir.', 'Ilıtıp sıcaklığı bileğinizin iç kısmına damlatarak kontrol edin; ılık olmalı, sıcak değil.', 'Kalanını bebeğin ağzı değmemiş kaşıkla ayırıp kapalı kapta buzdolabında 24 saat saklayın; tekrar ısıtmayı bir kez yapın.'], tips: ['Kılçık kontrolünü iki kez yapın.'], storage: 'Hazırlandıktan hemen sonra tüketin.'),
  BabyRecipe(id: 'bg9_03', title: 'Yumurtalı ıspanak ezmesi', age: '9+', category: 'Yumurta', ingredient: 'yumurta', vegetable: 'ıspanak', ingredients: ['1 yumurta sarısı (katı haşlanmış)', '1 avuç ıspanak', '1 çay kaşığı tereyağı'], steps: ['Ellerinizi, kesme tahtasını ve kapları sıcak sabunlu suyla yıkayın.', 'Ispanağı bol suda yıkayın; 3 dakika haşlayıp süzün ve ince doğrayın.', 'Katı haşlanmış yumurta sarısını çatalla ezin.', 'Ispanak ve tereyağıyla karıştırın.', 'Kıvam koyuysa 1–2 kaşık haşlama suyu ekleyin.', 'Tuz, şeker ve bal eklemeyin; 1 yaş altı bebeklere uygun değildir.', 'Ilıtıp sıcaklığı bileğinizin iç kısmına damlatarak kontrol edin; ılık olmalı, sıcak değil.'], tips: ['Yumurta tamamen pişmiş olmalı.'], storage: 'Hazırlandıktan hemen sonra tüketin.'),
  BabyRecipe(id: 'bg9_04', title: 'Kabaklı pirinç lapası', age: '9+', category: 'Tahıl', ingredient: 'pirinç', vegetable: 'kabak', ingredients: ['2 yemek kaşığı pirinç', '1 küçük kabak', '1 çay kaşığı tereyağı', '1,5 su bardağı içme suyu'], steps: ['Ellerinizi, kesme tahtasını ve kapları sıcak sabunlu suyla yıkayın.', 'Pirinci yıkayın; kabağı ince rendeleyin.', 'Pirinç, kabak ve suyu tencereye alıp kaynatın.', 'Kısık ateşte ara ara karıştırarak 20 dakika, pirinç çok yumuşayana kadar pişirin.', 'Tereyağını ekleyin.', 'Çatalla hafif ezin.', 'Tuz, şeker ve bal eklemeyin; 1 yaş altı bebeklere uygun değildir.', 'Ilıtıp sıcaklığı bileğinizin iç kısmına damlatarak kontrol edin; ılık olmalı, sıcak değil.', 'Kalanını bebeğin ağzı değmemiş kaşıkla ayırıp kapalı kapta buzdolabında 24 saat saklayın; tekrar ısıtmayı bir kez yapın.'], tips: ['Taneli kıvama geçiş için idealdir.'], storage: 'Buzdolabında 24 saat; buz kalıbında 1 ay dondurulabilir.'),
  BabyRecipe(id: 'bg9_05', title: 'Tavuklu sebzeli şehriye', age: '9+', category: 'Et', ingredient: 'tavuk', vegetable: 'havuç', ingredients: ['2 yemek kaşığı tel şehriye', '30 g haşlanmış tavuk', 'Yarım havuç', '1 su bardağı tavuk haşlama suyu (tuzsuz)'], steps: ['Ellerinizi, kesme tahtasını ve kapları sıcak sabunlu suyla yıkayın.', 'Havucu ince rendeleyin; tavuğu çok ince didikleyin.', 'Tuzsuz haşlama suyunu kaynatıp havucu 5 dakika pişirin.', 'Şehriyeyi ekleyip 7 dakika, iyice yumuşayana kadar pişirin.', 'Tavuğu ekleyip 1 dakika ısıtın.', 'Gerekirse çatalla hafif ezin.', 'Tuz, şeker ve bal eklemeyin; 1 yaş altı bebeklere uygun değildir.', 'Ilıtıp sıcaklığı bileğinizin iç kısmına damlatarak kontrol edin; ılık olmalı, sıcak değil.', 'Kalanını bebeğin ağzı değmemiş kaşıkla ayırıp kapalı kapta buzdolabında 24 saat saklayın; tekrar ısıtmayı bir kez yapın.'], tips: ['Şehriye yumuşak pişmeli.'], storage: 'Hazırlandıktan hemen sonra tüketin.'),
  BabyRecipe(id: 'bg9_06', title: 'Lorlu kabak ezmesi', age: '9+', category: 'Süt ürünü', ingredient: 'lor', vegetable: 'kabak', ingredients: ['1 küçük kabak', '2 yemek kaşığı tuzsuz lor'], steps: ['Ellerinizi, kesme tahtasını ve kapları sıcak sabunlu suyla yıkayın.', 'Kabağı soyup küçük küp doğrayın.', 'Tencereye 2 parmak su koyup buhar sepetini yerleştirin; su kaynayınca sebzeyi sepete alıp kapağı kapatın.', 'Buhar sepetinde 8 dakika pişirin.', 'Çatalla kolayca eziliyorsa pişmiştir.', 'Blender ya da çatalla ezin; kıvamı ayarlamak için haşlama suyunu kaşık kaşık ekleyin.', 'Ilıyınca tuzsuz loru ekleyip karıştırın.', 'Tuz, şeker ve bal eklemeyin; 1 yaş altı bebeklere uygun değildir.', 'Ilıtıp sıcaklığı bileğinizin iç kısmına damlatarak kontrol edin; ılık olmalı, sıcak değil.', 'Kalanını bebeğin ağzı değmemiş kaşıkla ayırıp kapalı kapta buzdolabında 24 saat saklayın; tekrar ısıtmayı bir kez yapın.'], tips: ['Tuzsuz lor tercih edin.'], storage: 'Hazırlandıktan hemen sonra tüketin.'),
  BabyRecipe(id: 'bg9_07', title: 'Tarçınlı fırın elma dilimleri (bebek)', age: '9+', category: 'Meyve', ingredient: 'elma', vegetable: 'elma', ingredients: ['1 elma', '1 tutam tarçın'], steps: ['Fırını 180°C’ye ısıtın; tepsiye yağlı kâğıt serin.', 'Ellerinizi, kesme tahtasını ve kapları sıcak sabunlu suyla yıkayın.', 'Elmayı soyup çekirdek evini çıkarın; kalın dilimler kesin.', 'Dilimleri tepsiye aralıklı dizip tarçın serpin.', '20 dakika yumuşayana kadar pişirin.', 'Parmakla bastırınca ezilmiyorsa 5 dakika daha pişirin; sert elma boğulma riski taşır.', 'Ilıtıp sıcaklığı bileğinizin iç kısmına damlatarak kontrol edin; ılık olmalı, sıcak değil.', 'Bebek yerken mutlaka yanında, dik oturur durumda olsun; ağzına sığmayacak büyüklükte parçalar verin.'], tips: ['Parmakla yeme için uygundur; ezilecek kadar yumuşak olmalı.'], storage: 'Buzdolabında 48 saat.'),
  BabyRecipe(id: 'bg9_08', title: 'Sebzeli yulaf köftesi (bebek)', age: '9+', category: 'Tahıl', ingredient: 'yulaf', vegetable: 'havuç', ingredients: ['3 yemek kaşığı yulaf', '1 küçük havuç (rendelenmiş)', '1 yumurta sarısı'], steps: ['Fırını 180°C’ye ısıtın; tepsiye yağlı kâğıt serin.', 'Ellerinizi, kesme tahtasını ve kapları sıcak sabunlu suyla yıkayın.', 'Havucu ince rendeleyin.', 'Yulaf, havuç ve yumurta sarısını karıştırıp 5 dakika bekletin.', 'Küçük yassı köfteler yapıp tepsiye dizin.', '15 dakika pişirin; ortası kuru ve sıkı olmalı.', 'Ilıtıp sıcaklığı bileğinizin iç kısmına damlatarak kontrol edin; ılık olmalı, sıcak değil.', 'Bebek yerken mutlaka yanında, dik oturur durumda olsun; ağzına sığmayacak büyüklükte parçalar verin.'], tips: ['Yumuşak ve kolay tutulur.'], storage: 'Buzdolabında 48 saat.'),
  BabyRecipe(id: 'bg9_09', title: 'Mercimekli bulgur ezmesi', age: '9+', category: 'Baklagil', ingredient: 'kırmızı mercimek', vegetable: 'havuç', ingredients: ['2 yemek kaşığı kırmızı mercimek', '1 yemek kaşığı ince bulgur', 'Yarım havuç', '1 su bardağı içme suyu'], steps: ['Ellerinizi, kesme tahtasını ve kapları sıcak sabunlu suyla yıkayın.', 'Mercimeği yıkayın; havucu soyup ince rendeleyin.', 'Mercimek, havuç ve suyu tencereye alıp kaynatın; köpüğünü alın.', 'Kısık ateşte 15 dakika pişirin.', 'Bulguru ekleyip 5 dakika daha pişirin.', 'Ocaktan alıp kapağı kapalı 10 dakika demlendirin.', 'Çatalla hafif ezin; 9. aydan sonra küçük taneler kalabilir.', 'Tuz, şeker ve bal eklemeyin; 1 yaş altı bebeklere uygun değildir.', 'Ilıtıp sıcaklığı bileğinizin iç kısmına damlatarak kontrol edin; ılık olmalı, sıcak değil.', 'Kalanını bebeğin ağzı değmemiş kaşıkla ayırıp kapalı kapta buzdolabında 24 saat saklayın; tekrar ısıtmayı bir kez yapın.'], tips: ['Demir ve lif içerir.'], storage: 'Buzdolabında 24 saat; buz kalıbında 1 ay dondurulabilir.'),
  BabyRecipe(id: 'bg9_10', title: 'Kuzu etli sebze güveci (bebek)', age: '9+', category: 'Et', ingredient: 'kuzu eti', vegetable: 'patates', ingredients: ['30 g kuzu kuşbaşı', '1 küçük patates', 'Yarım kabak', '1 su bardağı içme suyu'], steps: ['Ellerinizi, kesme tahtasını ve kapları sıcak sabunlu suyla yıkayın.', 'Eti küçük doğrayın; yağ ve sinirlerini ayıklayın.', 'Et ve suyu tencereye alıp kaynatın; köpüğünü alın.', 'Kapağı kapalı kısık ateşte 40 dakika pişirin.', 'Patates ve kabağı küçük küp doğrayıp ekleyin; 15 dakika daha pişirin.', 'Eti ortadan bölüp kontrol edin: içi pembe kalmamalı, suyu berrak akmalı.', 'Eti ince didikleyip sebzelerle birlikte ezin.', 'Tuz, şeker ve bal eklemeyin; 1 yaş altı bebeklere uygun değildir.', 'Ilıtıp sıcaklığı bileğinizin iç kısmına damlatarak kontrol edin; ılık olmalı, sıcak değil.', 'Kalanını bebeğin ağzı değmemiş kaşıkla ayırıp kapalı kapta buzdolabında 24 saat saklayın; tekrar ısıtmayı bir kez yapın.'], tips: ['Et çok iyi pişmiş ve didiklenmiş olmalı.'], storage: 'Buzdolabında 24 saat; buz kalıbında 1 ay dondurulabilir.'),
  BabyRecipe(id: 'bg9_11', title: 'Yoğurtlu kabak çorbası (bebek)', age: '9+', category: 'Çorba', ingredient: 'yoğurt', vegetable: 'kabak', ingredients: ['1 küçük kabak', '2 yemek kaşığı yoğurt', '1 yemek kaşığı pirinç unu', '1 su bardağı içme suyu'], steps: ['Ellerinizi, kesme tahtasını ve kapları sıcak sabunlu suyla yıkayın.', 'Kabağı ince rendeleyin.', 'Pirinç ununu soğuk suyla topaksız açın; kabakla birlikte tencereye alın.', 'Sürekli karıştırarak 10 dakika pişirin.', 'Ocaktan alıp 5 dakika soğutun.', 'Yoğurdu buzdolabından 10 dakika önce çıkarın; çok soğuk vermeyin.', 'Yoğurdu ekleyip karıştırın; kaynatmayın, kesilir.', 'Tuz, şeker ve bal eklemeyin; 1 yaş altı bebeklere uygun değildir.', 'Ilıtıp sıcaklığı bileğinizin iç kısmına damlatarak kontrol edin; ılık olmalı, sıcak değil.'], tips: ['Yoğurdu kaynarken eklemeyin.'], storage: 'Hazırlandıktan hemen sonra tüketin.'),
  BabyRecipe(id: 'bg9_12', title: 'Brokolili patates köftesi (bebek)', age: '9+', category: 'Sebze', ingredient: 'patates', vegetable: 'brokoli', ingredients: ['1 haşlanmış patates', '3 haşlanmış brokoli çiçeği', '1 yemek kaşığı yulaf'], steps: ['Fırını 180°C’ye ısıtın; tepsiye yağlı kâğıt serin.', 'Ellerinizi, kesme tahtasını ve kapları sıcak sabunlu suyla yıkayın.', 'Patates ve brokoliyi çatalla iyice ezin.', 'Yulafı ekleyip yoğurun; çok yumuşaksa 1 kaşık yulaf daha ekleyin.', 'Küçük yassı köfteler yapıp tepsiye dizin.', '15 dakika pişirin.', 'Ilıtıp sıcaklığı bileğinizin iç kısmına damlatarak kontrol edin; ılık olmalı, sıcak değil.', 'Tuz, şeker ve bal eklemeyin; 1 yaş altı bebeklere uygun değildir.', 'Bebek yerken mutlaka yanında, dik oturur durumda olsun; ağzına sığmayacak büyüklükte parçalar verin.'], tips: ['Parmakla yeme becerisini destekler.'], storage: 'Buzdolabında 48 saat.'),
  BabyRecipe(id: 'bg9_13', title: 'Hurmalı yulaf lapası', age: '10+', category: 'Tahıl', ingredient: 'yulaf', vegetable: 'hurma', ingredients: ['3 yemek kaşığı yulaf', '1 çekirdeksiz hurma (ince doğranmış)', '1 su bardağı içme suyu'], steps: ['Ellerinizi, kesme tahtasını ve kapları sıcak sabunlu suyla yıkayın.', 'Hurmanın çekirdeğini kontrol edip çıkarın; ince doğrayın.', 'Hurmayı 5 dakika sıcak suda bekletip ezin.', 'Yulaf, hurma ve suyu küçük tencereye alın.', 'Kısık ateşte sürekli karıştırarak 6 dakika pişirin.', 'Kıvamı kaynamış su ya da anne sütüyle ayarlayın.', 'Hurma tatlandırır; ayrıca şeker eklemeyin.', 'Ilıtıp sıcaklığı bileğinizin iç kısmına damlatarak kontrol edin; ılık olmalı, sıcak değil.'], tips: ['Hurma şeker eklemeden tat verir; az kullanın.'], storage: 'Hazırlandıktan hemen sonra tüketin.'),
  BabyRecipe(id: 'bg9_14', title: 'Ispanaklı omlet şeritleri', age: '10+', category: 'Yumurta', ingredient: 'yumurta', vegetable: 'ıspanak', ingredients: ['1 yumurta', '1 yemek kaşığı ince doğranmış ıspanak', '1 çay kaşığı tereyağı'], steps: ['Ellerinizi, kesme tahtasını ve kapları sıcak sabunlu suyla yıkayın.', 'Ispanağı yıkayıp çok ince doğrayın.', 'Yumurtayı çırpıp ıspanağı ekleyin.', 'Küçük tavada tereyağını kısık ateşte eritin; karışımı dökün.', 'Kapağı kapalı 3–4 dakika pişirin; ters çevirip 1–2 dakika daha pişirin.', 'Yumurtayı akı ve sarısı tamamen katılaşana kadar pişirin; akışkan bırakmayın.', 'Ilıtıp şeritler halinde kesin.', 'Bebek yerken mutlaka yanında, dik oturur durumda olsun; ağzına sığmayacak büyüklükte parçalar verin.'], tips: ['Akışkan kısım kalmamalı.'], storage: 'Hazırlandıktan hemen sonra tüketin.'),
  BabyRecipe(id: 'bg9_15', title: 'Avokadolu tavuk ezmesi', age: '10+', category: 'Et', ingredient: 'tavuk', vegetable: 'avokado', ingredients: ['30 g haşlanmış tavuk', 'Çeyrek avokado'], steps: ['Ellerinizi, kesme tahtasını ve kapları sıcak sabunlu suyla yıkayın.', 'Haşlanmış tavuğu çok ince didikleyin.', 'Avokadoyu çatalla ezin.', 'Tavuk ve avokadoyu karıştırın.', 'Kıvam koyuysa tavuk haşlama suyuyla yumuşatın.', 'Tuz, şeker ve bal eklemeyin; 1 yaş altı bebeklere uygun değildir.', 'Hemen servis edin; kalanını saklamayın.'], tips: ['Avokado tavuğu yumuşak tutar.'], storage: 'Hazırlandıktan hemen sonra tüketin.'),
  BabyRecipe(id: 'bh12_01', title: 'Sebzeli peynirli makarna (küçük)', age: '12+', category: 'Makarna', ingredient: 'makarna', vegetable: 'brokoli', ingredients: ['3 yemek kaşığı küçük makarna', '3 brokoli çiçeği', '1 yemek kaşığı rendelenmiş kaşar', '1 çay kaşığı tereyağı'], steps: ['Ellerinizi, kesme tahtasını ve kapları sıcak sabunlu suyla yıkayın.', 'Makarnayı tuzsuz kaynar suda paketteki süreden 2 dakika fazla, parmakla ezilecek kadar yumuşak haşlayın.', 'Brokoliyi ince doğrayıp 6 dakika haşlayın.', 'Süzülmüş makarna ve brokoliyi tereyağıyla karıştırın.', 'Kaşarı ekleyip sıcakken eriyene kadar karıştırın.', 'Kaşar ve lor pastörize sütten olmalı; tuzlu peyniri 1 saat suda bekletip tuzunu alın.', 'Ilıtıp sıcaklığı bileğinizin iç kısmına damlatarak kontrol edin; ılık olmalı, sıcak değil.', 'Kalanını kapalı kapta buzdolabında 2 gün saklayın; yalnızca bir kez ısıtın.'], tips: ['Kaşar az tuzlu olmalı.'], storage: 'Hazırlandıktan hemen sonra tüketin.'),
  BabyRecipe(id: 'bh12_02', title: 'Muzlu yumurtalı pankek (bebek)', age: '12+', category: 'Kahvaltı', ingredient: 'yumurta', vegetable: 'muz', ingredients: ['1 muz', '1 yumurta', '2 yemek kaşığı yulaf'], steps: ['Ellerinizi, kesme tahtasını ve kapları sıcak sabunlu suyla yıkayın.', 'Muzu çatalla pürüzsüz ezin.', 'Yumurta ve yulafı ekleyip çırpın; 5 dakika bekletin.', 'Yapışmaz tavayı kısık ateşte ısıtın; kaşıkla küçük pankekler dökün.', 'Altı kızarınca çevirip diğer yüzünü 1–2 dakika pişirin.', 'Bir tanesini ortadan bölün: içinde akışkan yumurta kalmamalı.', 'Ilıtıp sıcaklığı bileğinizin iç kısmına damlatarak kontrol edin; ılık olmalı, sıcak değil.', 'Kalanını kapalı kapta buzdolabında 2 gün saklayın; yalnızca bir kez ısıtın.'], tips: ['Şekersiz kahvaltı seçeneği.'], storage: 'Hazırlandıktan hemen sonra tüketin.'),
  BabyRecipe(id: 'bh12_03', title: 'Kabaklı tavuk köftesi (yumuşak)', age: '12+', category: 'Et', ingredient: 'tavuk kıyma', vegetable: 'kabak', ingredients: ['80 g tavuk kıyma', '2 yemek kaşığı rendelenmiş kabak', '1 yemek kaşığı yulaf'], steps: ['Ellerinizi, kesme tahtasını ve kapları sıcak sabunlu suyla yıkayın.', 'Fırını 190°C’ye ısıtın; tepsiye yağlı kâğıt serin.', 'Kabağı rendeleyip avuçlarınızla suyunu iyice sıkın.', 'Tavuk kıyma, kabak ve yulafı yoğurun; 5 dakika dinlendirin.', 'Islak elle küçük köfteler yapıp tepsiye dizin; 18 dakika pişirin.', 'Tavuk iç sıcaklığı 74°C olmalı; bir köfteyi ortadan bölün: içi pembe kalmamalı, suyu berrak akmalı.', 'Tepside 5 dakika dinlendirip ılıtın.', 'Buz kalıplarında dondurup 1 ay saklayabilirsiniz; buzdolabında çözdürüp bir kez ısıtın.'], tips: ['Yumuşak doku çiğnemeyi kolaylaştırır.'], storage: 'Buzdolabında 48 saat.'),
  BabyRecipe(id: 'bh12_04', title: 'Kabaklı yoğurtlu bulgur', age: '12+', category: 'Tahıl', ingredient: 'bulgur', vegetable: 'kabak', ingredients: ['3 yemek kaşığı ince bulgur', '1 küçük kabak', '2 yemek kaşığı yoğurt', '1 su bardağı su'], steps: ['Ellerinizi, kesme tahtasını ve kapları sıcak sabunlu suyla yıkayın.', 'Kabağı yıkayıp küçük küp doğrayın.', 'Bulgur, kabak ve suyu tencereye alıp kaynatın.', 'Kısık ateşte kapağı kapalı 12 dakika pişirin.', 'Ocağı kapatıp 10 dakika demlendirin.', 'Yoğurdu buzdolabından 10 dakika önce çıkarın; çok soğuk vermeyin.', 'Ilıyınca yoğurtla servis edin.', 'Ilıtıp sıcaklığı bileğinizin iç kısmına damlatarak kontrol edin; ılık olmalı, sıcak değil.', 'Kalanını kapalı kapta buzdolabında 2 gün saklayın; yalnızca bir kez ısıtın.'], tips: ['Yoğurt sindirimi destekler.'], storage: 'Buzdolabında 48 saat.'),
  BabyRecipe(id: 'bh12_05', title: 'Dereotlu levrek köftesi (fırında)', age: '12+', category: 'Balık', ingredient: 'levrek', vegetable: 'patates', ingredients: ['60 g levrek fileto', '1 haşlanmış patates', '1 yemek kaşığı ince doğranmış dereotu'], steps: ['Ellerinizi, kesme tahtasını ve kapları sıcak sabunlu suyla yıkayın.', 'Fırını 190°C’ye ısıtın; tepsiye yağlı kâğıt serin.', 'Levreği buhar sepetinde 8 dakika pişirin.', 'Balığı parmaklarınızla yoklayarak tüm kılçıkları ayıklayın; et opaklaşıp kolayca dağılıyorsa pişmiştir.', 'Balığı haşlanmış patatesle çatalla ezip dereotunu ekleyin.', 'Küçük yassı köfteler yapıp tepsiye dizin; 15 dakika, üstü hafif kızarana kadar pişirin.', 'Tepside 5 dakika dinlendirip ılıtın.', 'Çocuk yerken yanında olun; dik otursun, yürürken ya da koşarken yemesin.', 'Kalanını kapalı kapta buzdolabında 2 gün saklayın; yalnızca bir kez ısıtın.'], tips: ['Kılçık kontrolü çok önemlidir.'], storage: 'Hazırlandıktan hemen sonra tüketin.'),
  BabyRecipe(id: 'bh12_06', title: 'Kabaklı mercimek çorbası (parçalı)', age: '12+', category: 'Çorba', ingredient: 'kırmızı mercimek', vegetable: 'kabak', ingredients: ['3 yemek kaşığı kırmızı mercimek', 'Yarım kabak', 'Yarım havuç', '1 çay kaşığı tereyağı', '2 su bardağı su'], steps: ['Ellerinizi, kesme tahtasını ve kapları sıcak sabunlu suyla yıkayın.', 'Mercimeği yıkayın; kabak ve havucu küçük doğrayın.', 'Mercimek, sebzeler ve suyu tencereye alıp kaynatın; köpüğünü alın.', 'Kısık ateşte ara ara karıştırarak 20 dakika pişirin.', 'Çatalla hafifçe ezin; küçük parçalar kalabilir.', 'Tereyağını ekleyip karıştırın.', 'Tuz eklemeyin; 1–3 yaş için günlük tuz 2 g’ı geçmemeli, peynir ve salça zaten tuz içerir.', 'Ilıtıp sıcaklığı bileğinizin iç kısmına damlatarak kontrol edin; ılık olmalı, sıcak değil.', 'Buz kalıplarında dondurup 1 ay saklayabilirsiniz; buzdolabında çözdürüp bir kez ısıtın.'], tips: ['Parçalı bırakmak çiğneme pratiği sağlar.'], storage: 'Buzdolabında 48 saat.'),
  BabyRecipe(id: 'bh12_07', title: 'Peynirli patates topları', age: '12+', category: 'Sebze', ingredient: 'patates', vegetable: 'patates', ingredients: ['1 haşlanmış patates', '1 yemek kaşığı rendelenmiş kaşar', '1 yumurta sarısı'], steps: ['Ellerinizi, kesme tahtasını ve kapları sıcak sabunlu suyla yıkayın.', 'Fırını 190°C’ye ısıtın; tepsiye yağlı kâğıt serin.', 'Haşlanmış patatesi sıcakken çatalla pürüzsüz ezin.', 'Ilıyınca kaşar ve yumurta sarısını ekleyip yoğurun.', 'Ceviz büyüklüğünde toplar yapıp hafifçe bastırın.', '15 dakika, altları hafif kızarana kadar pişirin.', 'Kaşar ve lor pastörize sütten olmalı; tuzlu peyniri 1 saat suda bekletip tuzunu alın.', 'Tepside 5 dakika dinlendirip ılıtın.', 'Buz kalıplarında dondurup 1 ay saklayabilirsiniz; buzdolabında çözdürüp bir kez ısıtın.'], tips: ['Topları hafif yassı yaparak boğulma riskini azaltın.'], storage: 'Buzdolabında 48 saat.'),
  BabyRecipe(id: 'bh12_08', title: 'Etli kabak yemeği (bebek)', age: '12+', category: 'Et', ingredient: 'dana kıyma', vegetable: 'kabak', ingredients: ['40 g kıyma', '1 kabak', '1 yemek kaşığı rendelenmiş domates', '1 çay kaşığı zeytinyağı'], steps: ['Ellerinizi, kesme tahtasını ve kapları sıcak sabunlu suyla yıkayın.', 'Kabağı soyup küçük küp doğrayın.', 'Zeytinyağını tencerede ısıtın; kıymayı kaşıkla dağıtarak 5 dakika, rengi tamamen dönene kadar pişirin.', 'Rendelenmiş domatesi ekleyip 2 dakika pişirin.', 'Kabakları ve yarım su bardağı suyu ekleyin; kapağı kapalı kısık ateşte 15 dakika pişirin.', 'Kıymada pembe kalmadığını kontrol edin.', 'Yoğurdu buzdolabından 10 dakika önce çıkarın; çok soğuk vermeyin.', 'Ilıyınca yoğurtla servis edin; gerekirse kabakları çatalla ezin.', 'Kalanını kapalı kapta buzdolabında 2 gün saklayın; yalnızca bir kez ısıtın.'], tips: ['Aile yemeğinin tuzsuz versiyonudur.'], storage: 'Buzdolabında 48 saat.'),
  BabyRecipe(id: 'bh12_09', title: 'Yulaflı elmalı kurabiye (şekersiz)', age: '12+', category: 'Tatlı', ingredient: 'yulaf', vegetable: 'elma', ingredients: ['1 su bardağı yulaf', '1 elma (rendelenmiş)', '1 muz'], steps: ['Ellerinizi, kesme tahtasını ve kapları sıcak sabunlu suyla yıkayın.', 'Fırını 180°C’ye ısıtın; tepsiye yağlı kâğıt serin.', 'Olgun muzu çatalla pürüzsüz ezin.', 'Elmayı soyup ince rendeleyin; muza ekleyin.', 'Yulafı ekleyip karıştırın; 10 dakika bekletin, yulaf nemi çeker.', 'Kaşıkla küçük yuvarlaklar bırakıp 1 cm kalınlığa bastırın.', '15 dakika, altları hafif kızarana kadar pişirin.', 'Tepside 10 dakika soğutun; sıcakken kolay dağılır.', 'Şeker eklemeyin; tatlılığı olgun meyveden gelsin.', 'Kapalı kapta 2 gün saklayın.'], tips: ['Şekersiz atıştırmalık.'], storage: 'Hava almayan kapta 3 gün.'),
  BabyRecipe(id: 'bh12_10', title: 'Sebzeli irmik çorbası', age: '12+', category: 'Çorba', ingredient: 'irmik', vegetable: 'havuç', ingredients: ['1 yemek kaşığı irmik', 'Yarım havuç', '1 çay kaşığı tereyağı', '2 su bardağı su'], steps: ['Ellerinizi, kesme tahtasını ve kapları sıcak sabunlu suyla yıkayın.', 'Havucu soyup ince rendeleyin.', 'Tereyağını küçük tencerede eritip irmiği 2 dakika, kokusu çıkana kadar kavurun.', 'Havucu ekleyip 1 dakika çevirin.', 'Suyu yavaşça ekleyin; topaklanmasın diye sürekli karıştırın.', 'Kısık ateşte ara ara karıştırarak 10 dakika pişirin.', 'Tuz eklemeyin; 1–3 yaş için günlük tuz 2 g’ı geçmemeli, peynir ve salça zaten tuz içerir.', 'Ilıtıp sıcaklığı bileğinizin iç kısmına damlatarak kontrol edin; ılık olmalı, sıcak değil.', 'Kalanını kapalı kapta buzdolabında 2 gün saklayın; yalnızca bir kez ısıtın.'], tips: ['Topaklanmaması için sürekli karıştırın.'], storage: 'Buzdolabında 48 saat.'),
  BabyRecipe(id: 'bh12_11', title: 'Tavuklu sebzeli orzo', age: '12+', category: 'Makarna', ingredient: 'arpa şehriye', vegetable: 'bezelye', ingredients: ['3 yemek kaşığı arpa şehriye', '30 g haşlanmış tavuk', '2 yemek kaşığı bezelye', '1 su bardağı tavuk suyu (tuzsuz)'], steps: ['Ellerinizi, kesme tahtasını ve kapları sıcak sabunlu suyla yıkayın.', 'Tuzsuz tavuk suyunu küçük tencerede kaynatın.', 'Arpa şehriyeyi ekleyip karıştırın.', 'Bezelyeyi ekleyin; kısık ateşte ara ara karıştırarak 10 dakika pişirin.', 'Haşlanmış tavuğu ince didikleyip ekleyin; 1 dakika ısıtın.', 'Yuvarlak ve sert parçaları (bezelye, nohut, üzüm gibi) ezin ya da dörde bölün.', 'Ilıtıp sıcaklığı bileğinizin iç kısmına damlatarak kontrol edin; ılık olmalı, sıcak değil.', 'Kalanını kapalı kapta buzdolabında 2 gün saklayın; yalnızca bir kez ısıtın.'], tips: ['Bezelyeleri hafif ezin.'], storage: 'Buzdolabında 48 saat.'),
  BabyRecipe(id: 'bh12_12', title: 'Fırında kabak çubukları (peynirli)', age: '12+', category: 'Sebze', ingredient: 'kabak', vegetable: 'kabak', ingredients: ['1 kabak', '1 yemek kaşığı rendelenmiş kaşar', '1 çay kaşığı zeytinyağı'], steps: ['Ellerinizi, kesme tahtasını ve kapları sıcak sabunlu suyla yıkayın.', 'Fırını 200°C’ye ısıtın; tepsiye yağlı kâğıt serin.', 'Kabağı yıkayıp çocuğun tutabileceği parmak kalınlığında çubuklar kesin.', 'Zeytinyağıyla harmanlayıp tepsiye dizin; üzerine kaşar serpin.', '15 dakika, kabak yumuşayıp kaşar eriyene kadar pişirin.', 'Parmakla bastırınca kolayca ezilmeli.', 'Kaşar ve lor pastörize sütten olmalı; tuzlu peyniri 1 saat suda bekletip tuzunu alın.', 'Tepside 5 dakika dinlendirip ılıtın.'], tips: ['Yumuşak olmalı; sert kalırsa daha pişirin.'], storage: 'Hazırlandıktan hemen sonra tüketin.'),
  BabyRecipe(id: 'bh12_13', title: 'Muhallebi (şekersiz, meyveli)', age: '12+', category: 'Tatlı', ingredient: 'süt', vegetable: 'muz', ingredients: ['1 su bardağı süt', '1 yemek kaşığı pirinç unu', 'Yarım muz (ezilmiş)'], steps: ['Ellerinizi, kesme tahtasını ve kapları sıcak sabunlu suyla yıkayın.', 'Soğuk süt ve pirinç ununu tencerede topaksız karıştırın.', 'Kısık ateşte sürekli karıştırarak 8–10 dakika, kaşığın arkasını kaplayana kadar pişirin.', 'Ocaktan alıp 5 dakika ılıtın.', 'Ezilmiş muzu ekleyip karıştırın.', 'Kaselere paylaştırıp üzeri kabuk bağlamasın diye streç filmi yüzeyine değdirerek örtün.', 'Buzdolabında 1 saat soğutup servis edin.', 'İnek sütü 1 yaştan sonra içecek olarak verilebilir; tam yağlı tercih edin.', 'Şeker eklemeyin; tatlılığı olgun meyveden gelsin.', 'Kalanını kapalı kapta buzdolabında 2 gün saklayın; yalnızca bir kez ısıtın.'], tips: ['Tatlılığı muzdan gelir.'], storage: 'Buzdolabında 48 saat.'),
  BabyRecipe(id: 'bh15_01', title: 'Fırında sebzeli tavuk butu', age: '15+', category: 'Et', ingredient: 'tavuk', vegetable: 'tatlı patates', ingredients: ['1 kemiksiz tavuk butu', 'Yarım tatlı patates', 'Yarım kabak', '1 çay kaşığı zeytinyağı'], steps: ['Ellerinizi, kesme tahtasını ve kapları sıcak sabunlu suyla yıkayın.', 'Fırını 200°C’ye ısıtın.', 'Tavuğu ayrı tahtada küp doğrayın; ardından tahtayı ve ellerinizi yıkayın.', 'Tatlı patates ve kabağı soyup tavuktan küçük küpler halinde doğrayın.', 'Zeytinyağıyla harmanlayıp tepsiye tek kat dizin.', '25 dakika pişirin; yarısında karıştırın.', 'Tavuk iç sıcaklığı 74°C olmalı; en büyük parçayı bölüp pembe kalmadığını kontrol edin.', 'Çocuğun çiğneyebileceği küçük parçalara doğrayın.', 'Ilıtıp sıcaklığı bileğinizin iç kısmına damlatarak kontrol edin; ılık olmalı, sıcak değil.', 'Kalanını kapalı kapta buzdolabında 2 gün saklayın; yalnızca bir kez ısıtın.'], tips: ['But eti göğüsten daha yumuşaktır.'], storage: 'Buzdolabında 48 saat.'),
  BabyRecipe(id: 'bh15_02', title: 'Yumurtalı ekmek (fırında)', age: '15+', category: 'Kahvaltı', ingredient: 'ekmek', vegetable: '—', ingredients: ['1 dilim tam buğday ekmeği', '1 yumurta', '2 yemek kaşığı süt', '1 tutam tarçın'], steps: ['Ellerinizi, kesme tahtasını ve kapları sıcak sabunlu suyla yıkayın.', 'Fırını 180°C’ye ısıtın; tepsiye yağlı kâğıt serin.', 'Yumurta, süt ve tarçını çırpın.', 'Ekmeği çocuğun tutabileceği şeritler halinde kesin.', 'Şeritleri karışıma her iki yüzü ıslanacak şekilde batırıp tepsiye dizin.', '12 dakika pişirin; yarısında çevirin.', 'Yumurtayı akı ve sarısı tamamen katılaşana kadar pişirin; akışkan bırakmayın.', 'Tepside 5 dakika dinlendirip ılıtın.', 'Şeker eklemeyin; tatlılığı olgun meyveden gelsin.'], tips: ['Tavaya göre daha az yağlıdır.'], storage: 'Hazırlandıktan hemen sonra tüketin.'),
  BabyRecipe(id: 'bh15_03', title: 'Nohutlu sebze yemeği (ezilmiş)', age: '15+', category: 'Baklagil', ingredient: 'nohut', vegetable: 'havuç', ingredients: ['3 yemek kaşığı haşlanmış nohut', '1 havuç', '1 küçük patates', '1 çay kaşığı salça', '1 su bardağı su'], steps: ['Ellerinizi, kesme tahtasını ve kapları sıcak sabunlu suyla yıkayın.', 'Havuç ve patatesi soyup küçük küp doğrayın.', 'Salçayı tencerede suyla açıp kaynatın.', 'Nohut ve sebzeleri ekleyin; kapağı kapalı kısık ateşte 20 dakika pişirin.', 'Sebzeler parmakla ezilecek kadar yumuşamalı.', 'Nohutları çatalla ezin ya da dörde bölün; bütün nohut boğulma riski taşır.', 'Tuz eklemeyin; 1–3 yaş için günlük tuz 2 g’ı geçmemeli, peynir ve salça zaten tuz içerir.', 'Ilıtıp sıcaklığı bileğinizin iç kısmına damlatarak kontrol edin; ılık olmalı, sıcak değil.', 'Buz kalıplarında dondurup 1 ay saklayabilirsiniz; buzdolabında çözdürüp bir kez ısıtın.'], tips: ['Nohut bütün verilmemeli; ezin.'], storage: 'Buzdolabında 48 saat.'),
  BabyRecipe(id: 'bh15_04', title: 'Ispanaklı peynirli börek (yumuşak)', age: '15+', category: 'Fırın', ingredient: 'yufka', vegetable: 'ıspanak', ingredients: ['1 yufka', '1 avuç haşlanmış ıspanak', '2 yemek kaşığı lor', '3 yemek kaşığı süt', '1 yumurta'], steps: ['Ellerinizi, kesme tahtasını ve kapları sıcak sabunlu suyla yıkayın.', 'Fırını 180°C’ye ısıtın; küçük fırın kabını yağlayın.', 'Haşlanmış ıspanağı iyice sıkıp ince kıyın; loru ekleyip karıştırın.', 'Süt ve yumurtayı çırpın.', 'Yufkayı elle parçalayıp yarısını kaba yayın ve sosun yarısıyla ıslatın.', 'Ispanaklı harcı yayıp kalan yufkayı üstüne koyun; kalan sosu dökün.', '25 dakika, üstü kızarıp ortası katılaşana kadar pişirin.', 'Yumurtayı akı ve sarısı tamamen katılaşana kadar pişirin; akışkan bırakmayın.', 'Kaşar ve lor pastörize sütten olmalı; tuzlu peyniri 1 saat suda bekletip tuzunu alın.', '10 dakika dinlendirip küçük kareler halinde kesin.', 'Kalanını kapalı kapta buzdolabında 2 gün saklayın; yalnızca bir kez ısıtın.'], tips: ['Yufkayı iyice ıslatmak yumuşak doku verir.'], storage: 'Buzdolabında 48 saat.'),
  BabyRecipe(id: 'bh15_05', title: 'Mevsim meyveli yoğurt kasesi', age: '15+', category: 'Kahvaltı', ingredient: 'yoğurt', vegetable: 'çilek', ingredients: ['4 yemek kaşığı yoğurt', '3 çilek (ince doğranmış)', '1 yemek kaşığı yulaf'], steps: ['Ellerinizi, kesme tahtasını ve kapları sıcak sabunlu suyla yıkayın.', 'Çilekleri bol suda yıkayıp saplarını ayırın.', 'Çilekleri çocuğun çiğneyebileceği küçük parçalara doğrayın.', 'Yoğurdu buzdolabından 10 dakika önce çıkarın; çok soğuk vermeyin.', 'Yoğurdu kaseye alın; çilekleri ekleyin.', 'Yulafı üzerine serpin.', 'Şeker eklemeyin; tatlılığı olgun meyveden gelsin.', 'Hemen servis edin; kalanını saklamayın.'], tips: ['Yulaf hafif ıslanınca daha kolay yenir.'], storage: 'Hazırlandıktan hemen sonra tüketin.'),
  BabyRecipe(id: 'bi18_01', title: 'Sebzeli köfteli çorba', age: '18+', category: 'Çorba', ingredient: 'dana kıyma', vegetable: 'havuç', ingredients: ['50 g kıyma', '1 yemek kaşığı pirinç', '1 havuç', '1 patates', '2 su bardağı su'], steps: ['Ellerinizi, kesme tahtasını ve kapları sıcak sabunlu suyla yıkayın.', 'Kıyma ve yıkanmış pirinci yoğurup nohut büyüklüğünde yumuşak köfteler yapın; ardından ellerinizi yıkayın.', 'Havuç ve patatesi soyup küçük küp doğrayın.', 'Sebzeleri suyla kaynatıp 10 dakika pişirin.', 'Köfteleri ekleyin; kısık ateşte 15 dakika, pirinç yumuşayana kadar pişirin.', 'Bir köfteyi ortadan bölün: içi pembe kalmamalı.', 'Köfteleri servis ederken ikiye bölün; yuvarlak ve bütün köfte boğazda takılabilir.', 'İsterseniz birkaç damla limon sıkın.', 'Tuz eklemeyin; 1–3 yaş için günlük tuz 2 g’ı geçmemeli, peynir ve salça zaten tuz içerir.', 'Ilıtıp sıcaklığı bileğinizin iç kısmına damlatarak kontrol edin; ılık olmalı, sıcak değil.'], tips: ['Köfteleri küçük ve yumuşak tutun.'], storage: 'Buzdolabında 48 saat.'),
  BabyRecipe(id: 'bi18_02', title: 'Fırında karnabahar köftesi', age: '18+', category: 'Sebze', ingredient: 'karnabahar', vegetable: 'karnabahar', ingredients: ['1 su bardağı haşlanmış karnabahar', '1 yumurta', '3 yemek kaşığı galeta unu', '1 yemek kaşığı rendelenmiş kaşar'], steps: ['Ellerinizi, kesme tahtasını ve kapları sıcak sabunlu suyla yıkayın.', 'Fırını 200°C’ye ısıtın; tepsiye yağlı kâğıt serin.', 'Haşlanmış karnabaharı iyice süzüp çatalla ezin.', 'Yumurta, galeta unu ve kaşarı ekleyip yoğurun; 5 dakika dinlendirin.', 'Islak elle küçük yassı köfteler yapıp tepsiye dizin.', '20 dakika pişirin; yarısında çevirin.', 'Yumurtayı akı ve sarısı tamamen katılaşana kadar pişirin; akışkan bırakmayın.', 'Tepside 5 dakika dinlendirip ılıtın.', 'Buz kalıplarında dondurup 1 ay saklayabilirsiniz; buzdolabında çözdürüp bir kez ısıtın.'], tips: ['Karnabaharın suyunu iyice süzün.'], storage: 'Buzdolabında 48 saat.'),
  BabyRecipe(id: 'bi18_03', title: 'Tavuklu yoğurtlu makarna', age: '18+', category: 'Makarna', ingredient: 'makarna', vegetable: '—', ingredients: ['Yarım su bardağı makarna', '40 g haşlanmış tavuk', '3 yemek kaşığı yoğurt', '1 çay kaşığı tereyağı'], steps: ['Ellerinizi, kesme tahtasını ve kapları sıcak sabunlu suyla yıkayın.', 'Makarnayı tuzsuz kaynar suda paketteki süreden 2 dakika fazla, parmakla ezilecek kadar yumuşak haşlayın.', 'Haşlanmış tavuğu ince didikleyin.', 'Süzülmüş makarna ve tavuğu karıştırın.', 'Yoğurdu buzdolabından 10 dakika önce çıkarın; çok soğuk vermeyin.', 'Makarna ılıyınca yoğurdu ekleyin; sıcakken eklerseniz yoğurt kesilir.', 'Tereyağını eritip üzerine gezdirin.', 'Ilıtıp sıcaklığı bileğinizin iç kısmına damlatarak kontrol edin; ılık olmalı, sıcak değil.', 'Kalanını kapalı kapta buzdolabında 2 gün saklayın; yalnızca bir kez ısıtın.'], tips: ['Pratik ve doyurucudur.'], storage: 'Hazırlandıktan hemen sonra tüketin.'),
  BabyRecipe(id: 'bi18_04', title: 'Sebzeli kıymalı bulgur', age: '18+', category: 'Tahıl', ingredient: 'bulgur', vegetable: 'biber', ingredients: ['3 yemek kaşığı bulgur', '40 g kıyma', 'Yarım kırmızı biber', '1 çay kaşığı salça', '1 su bardağı su'], steps: ['Ellerinizi, kesme tahtasını ve kapları sıcak sabunlu suyla yıkayın.', 'Biberin çekirdeklerini çıkarıp çok ince doğrayın; bulguru yıkayın.', 'Kıymayı kaşıkla dağıtarak 5 dakika, rengi tamamen dönene kadar pişirin.', 'Biber ve salçayı ekleyip 2 dakika çevirin.', 'Bulgur ve suyu ekleyin; kaynayınca kapağı kapalı kısık ateşte 15 dakika pişirin.', 'Ocağı kapatıp 10 dakika demlendirin.', 'Kıymada pembe kalmadığını kontrol edin.', 'Tuz eklemeyin; 1–3 yaş için günlük tuz 2 g’ı geçmemeli, peynir ve salça zaten tuz içerir.', 'Ilıtıp sıcaklığı bileğinizin iç kısmına damlatarak kontrol edin; ılık olmalı, sıcak değil.', 'Kalanını kapalı kapta buzdolabında 2 gün saklayın; yalnızca bir kez ısıtın.'], tips: ['Biberi çok küçük doğrayın.'], storage: 'Buzdolabında 48 saat.'),
  BabyRecipe(id: 'bi18_05', title: 'Fırında yumurtalı patates', age: '18+', category: 'Yumurta', ingredient: 'yumurta', vegetable: 'patates', ingredients: ['1 patates', '1 yumurta', '1 yemek kaşığı rendelenmiş kaşar'], steps: ['Fırını 190 °C\'ye ısıtın.', 'Patatesi küçük küp doğrayıp 15 dakika pişirin.', 'Yumurtayı üzerine kırın.', 'Yumurta tamamen pişene kadar 12 dakika pişirin.', 'Kaşar serpip verin.'], tips: ['Sarısı tamamen katılaşmalı.'], storage: 'Hazırlandıktan hemen sonra tüketin.'),
  BabyRecipe(id: 'bi18_06', title: 'Mısırlı tavuk çorbası', age: '18+', category: 'Çorba', ingredient: 'tavuk', vegetable: 'mısır', ingredients: ['40 g tavuk', '2 yemek kaşığı mısır', '1 havuç', '1 yemek kaşığı un', '2 su bardağı su'], steps: ['Ellerinizi, kesme tahtasını ve kapları sıcak sabunlu suyla yıkayın.', 'Tavuğu suyla kaynatıp köpüğünü alın; kısık ateşte 20 dakika pişirin.', 'Tavuk iç sıcaklığı 74°C olmalı; en büyük parçayı bölüp pembe kalmadığını kontrol edin.', 'Tavuğu çıkarıp ince didikleyin.', 'Havucu ince rendeleyip haşlama suyuna ekleyin; 5 dakika pişirin.', 'Mısırı blenderda hafifçe çekip ekleyin.', 'Mısır taneleri boğulma riski taşır; ince kıyın ya da hafifçe ezin.', 'Unu yarım su bardağı soğuk suyla topaksız açıp tencereye ekleyin.', 'Sürekli karıştırarak 10 dakika pişirin; tavuğu ekleyin.', 'Tuz eklemeyin; 1–3 yaş için günlük tuz 2 g’ı geçmemeli, peynir ve salça zaten tuz içerir.', 'Ilıtıp sıcaklığı bileğinizin iç kısmına damlatarak kontrol edin; ılık olmalı, sıcak değil.'], tips: ['Mısırı çekmek boğulma riskini azaltır.'], storage: 'Buzdolabında 48 saat.'),
  BabyRecipe(id: 'bi18_07', title: 'Sebzeli peynirli kek (tuzlu)', age: '18+', category: 'Fırın', ingredient: 'un', vegetable: 'havuç', ingredients: ['1 yumurta', '3 yemek kaşığı yoğurt', '1 yemek kaşığı zeytinyağı', '5 yemek kaşığı un', '1 çay kaşığı kabartma tozu', '2 yemek kaşığı rendelenmiş havuç', '2 yemek kaşığı beyaz peynir'], steps: ['Ellerinizi, kesme tahtasını ve kapları sıcak sabunlu suyla yıkayın.', 'Fırını 180°C’ye ısıtın; mini kalıpları yağlayın.', 'Beyaz peyniri 1 saat suda bekletip tuzunu alın ve ufalayın.', 'Yumurta, yoğurt ve zeytinyağını çırpın.', 'Un ve kabartma tozunu ekleyip sadece karışana kadar karıştırın.', 'Havuç ve peyniri ekleyip kalıplara paylaştırın.', '20 dakika pişirin; kürdan temiz çıkmalı.', 'Yumurtayı akı ve sarısı tamamen katılaşana kadar pişirin; akışkan bırakmayın.', 'Kalıpta 5 dakika bekletip ılıtın.', 'Buz kalıplarında dondurup 1 ay saklayabilirsiniz; buzdolabında çözdürüp bir kez ısıtın.'], tips: ['Beyaz peyniri suda bekleterek tuzunu azaltın.'], storage: 'Buzdolabında 48 saat.'),
  BabyRecipe(id: 'bi18_08', title: 'Ispanaklı mantı (pratik, yufkadan)', age: '18+', category: 'Makarna', ingredient: 'yufka', vegetable: 'ıspanak', ingredients: ['1 yufka', '40 g kıyma', '1 yemek kaşığı ıspanak (ince doğranmış)', '3 yemek kaşığı yoğurt'], steps: ['Ellerinizi, kesme tahtasını ve kapları sıcak sabunlu suyla yıkayın.', 'Kıymayı kaşıkla dağıtarak 5 dakika, rengi tamamen dönene kadar pişirin.', 'İnce doğranmış ıspanağı ekleyip 2 dakika pişirin; soğutun.', 'Yufkayı 4 cm’lik kareler halinde kesin.', 'Her karenin ortasına az harç koyup köşelerini birleştirerek kapatın.', 'Kaynar suda 8 dakika, hamur yumuşayana kadar haşlayın; süzün.', 'Yoğurdu buzdolabından 10 dakika önce çıkarın; çok soğuk vermeyin.', 'Ilıyınca yoğurtla servis edin; gerekirse mantıları ikiye kesin.', 'Tuz eklemeyin; 1–3 yaş için günlük tuz 2 g’ı geçmemeli, peynir ve salça zaten tuz içerir.', 'Kalanını kapalı kapta buzdolabında 2 gün saklayın; yalnızca bir kez ısıtın.'], tips: ['Sarımsaksız yoğurt kullanın.'], storage: 'Hazırlandıktan hemen sonra tüketin.'),
  BabyRecipe(id: 'bi18_09', title: 'Elmalı havuçlu kek (şekersiz)', age: '18+', category: 'Tatlı', ingredient: 'un', vegetable: 'havuç', ingredients: ['1 yumurta', '1 muz', '1 elma (rendelenmiş)', '1 havuç (rendelenmiş)', '1 su bardağı tam buğday unu', '1 çay kaşığı kabartma tozu'], steps: ['Ellerinizi, kesme tahtasını ve kapları sıcak sabunlu suyla yıkayın.', 'Fırını 180°C’ye ısıtın; küçük kek kalıbına yağlı kâğıt serin.', 'Olgun muzu ezip yumurtayla çırpın.', 'Elma ve havucu ince rendeleyip ekleyin.', 'Un ve kabartma tozunu ekleyip sadece karışana kadar karıştırın.', 'Kalıba döküp 30 dakika pişirin; ortasına batırdığınız kürdan temiz çıkmalı.', 'Kalıpta 10 dakika, tel ızgarada tamamen soğutun.', 'Şeker eklemeyin; tatlılığı olgun meyveden gelsin.', 'Kapalı kapta 2 gün saklayın ya da dilimleyip 1 ay dondurun.'], tips: ['Tatlılığı meyvelerden gelir.'], storage: 'Hava almayan kapta 2 gün.'),
  BabyRecipe(id: 'bi18_10', title: 'Fırında sebzeli somon', age: '18+', category: 'Balık', ingredient: 'somon', vegetable: 'kabak', ingredients: ['60 g somon', 'Yarım kabak', 'Yarım havuç', '1 çay kaşığı zeytinyağı'], steps: ['Ellerinizi, kesme tahtasını ve kapları sıcak sabunlu suyla yıkayın.', 'Fırını 200°C’ye ısıtın; tepsiye yağlı kâğıt serin.', 'Kabak ve havucu ince çubuklar halinde doğrayın; havuç ince olmalı ki zamanında yumuşasın.', 'Sebzeleri zeytinyağıyla harmanlayıp tepsiye dizin; somonu ortalarına koyun.', '15 dakika, somon opaklaşıp kolayca dağılana kadar pişirin.', 'Balığı parmaklarınızla yoklayarak tüm kılçıkları ayıklayın; et opaklaşıp kolayca dağılıyorsa pişmiştir.', 'Havuç parmakla ezilecek kadar yumuşak olmalı; değilse 5 dakika daha pişirin.', 'Somonu ufalayıp sebzelerle servis edin.', 'Ilıtıp sıcaklığı bileğinizin iç kısmına damlatarak kontrol edin; ılık olmalı, sıcak değil.', 'Kalanını kapalı kapta buzdolabında 2 gün saklayın; yalnızca bir kez ısıtın.'], tips: ['Haftada 1–2 balık önerilir.'], storage: 'Hazırlandıktan hemen sonra tüketin.'),
  BabyRecipe(id: 'bi18_11', title: 'Taze fasulye (çocuk)', age: '18+', category: 'Sebze', ingredient: 'taze fasulye', vegetable: 'domates', ingredients: ['1 avuç taze fasulye', '1 domates (rendelenmiş)', '1 çay kaşığı zeytinyağı', 'Yarım su bardağı su'], steps: ['Ellerinizi, kesme tahtasını ve kapları sıcak sabunlu suyla yıkayın.', 'Fasulyelerin uçlarını ve kılçıklarını ayıklayıp yıkayın; 1 cm boyunda doğrayın.', 'Zeytinyağında rendelenmiş domatesi 2 dakika çevirin.', 'Fasulye ve suyu ekleyin; kapağı kapalı kısık ateşte 25 dakika pişirin.', 'Fasulyeler parmakla ezilecek kadar yumuşamalı.', 'Yoğurdu buzdolabından 10 dakika önce çıkarın; çok soğuk vermeyin.', 'Ilıyınca yoğurtla servis edin.', 'Ilıtıp sıcaklığı bileğinizin iç kısmına damlatarak kontrol edin; ılık olmalı, sıcak değil.', 'Kalanını kapalı kapta buzdolabında 2 gün saklayın; yalnızca bir kez ısıtın.'], tips: ['Fasulyeler çok yumuşak olmalı.'], storage: 'Buzdolabında 48 saat.'),
  BabyRecipe(id: 'bi18_12', title: 'Yulaflı muz smoothie (çocuk)', age: '18+', category: 'İçecek', ingredient: 'muz', vegetable: 'muz', ingredients: ['1 muz', '1 su bardağı süt', '2 yemek kaşığı yulaf'], steps: ['Ellerinizi, kesme tahtasını ve kapları sıcak sabunlu suyla yıkayın.', 'Yulafı sütte 5 dakika bekletip yumuşatın.', 'Olgun muzu soyup dilimleyerek ekleyin.', 'Blenderda 30–40 saniye, pürüzsüz olana kadar çekin.', 'Bardağa alıp hemen servis edin.', 'Şeker eklemeyin; tatlılığı olgun meyveden gelsin.', 'İnek sütü 1 yaştan sonra içecek olarak verilebilir; tam yağlı tercih edin.'], tips: ['Kahvaltı yerine geçmez, ara öğündür.'], storage: 'Hazırlandıktan hemen sonra tüketin.'),
  BabyRecipe(id: 'bi18_13', title: 'Peynirli sebzeli makarna salatası', age: '18+', category: 'Makarna', ingredient: 'makarna', vegetable: 'salatalık', ingredients: ['Yarım su bardağı haşlanmış makarna', 'Çeyrek salatalık', '2 yemek kaşığı beyaz peynir (küp)', '1 çay kaşığı zeytinyağı'], steps: ['Ellerinizi, kesme tahtasını ve kapları sıcak sabunlu suyla yıkayın.', 'Haşlanmış makarnayı soğuk suyla durulayıp süzün.', 'Salatalığı yıkayıp soyun ve küçük küp doğrayın.', 'Beyaz peyniri 1 saat suda bekletip tuzunu alın; küçük küp doğrayın.', 'Makarna, salatalık ve peyniri zeytinyağıyla karıştırın.', 'Hemen servis edin ya da buzdolabında 1 gün saklayın.', 'Kaşar ve lor pastörize sütten olmalı; tuzlu peyniri 1 saat suda bekletip tuzunu alın.', 'Çocuk yerken yanında olun; dik otursun, yürürken ya da koşarken yemesin.'], tips: ['Yaz günleri için serin bir öğün.'], storage: 'Hazırlandıktan hemen sonra tüketin.'),
  BabyRecipe(id: 'bi18_14', title: 'Fırında patates ve köfte (mini)', age: '18+', category: 'Et', ingredient: 'dana kıyma', vegetable: 'patates', ingredients: ['80 g kıyma', '1 yemek kaşığı galeta unu', '1 patates', '1 çay kaşığı zeytinyağı'], steps: ['Ellerinizi, kesme tahtasını ve kapları sıcak sabunlu suyla yıkayın.', 'Fırını 200°C’ye ısıtın; tepsiye yağlı kâğıt serin.', 'Kıymayı galeta unuyla yoğurun; çiğ ete dokunduktan sonra ellerinizi yıkayın.', 'Islak elle ceviz büyüklüğünde, hafif yassı köfteler yapın.', 'Patatesi soyup küçük küp doğrayın ve zeytinyağıyla harmanlayın.', 'Köfte ve patatesleri tepsiye aralıklı dizip 25 dakika pişirin; yarısında çevirin.', 'Köfte iç sıcaklığı 71°C olmalı; bir köfteyi ortadan bölün: içi pembe kalmamalı, suyu berrak akmalı.', 'Patates parmakla ezilecek kadar yumuşak olmalı.', 'Köfteleri küçük parçalara bölüp ılık servis edin.', 'Buz kalıplarında dondurup 1 ay saklayabilirsiniz; buzdolabında çözdürüp bir kez ısıtın.'], tips: ['İçinin piştiğinden emin olun.'], storage: 'Buzdolabında 48 saat.'),
  BabyRecipe(id: 'bi18_15', title: 'Pirinçli tavuk çorbası (parçalı)', age: '18+', category: 'Çorba', ingredient: 'tavuk', vegetable: 'havuç', ingredients: ['40 g tavuk', '2 yemek kaşığı pirinç', '1 havuç', '2 su bardağı su', '1 çay kaşığı tereyağı'], steps: ['Ellerinizi, kesme tahtasını ve kapları sıcak sabunlu suyla yıkayın.', 'Tavuğu suyla kaynatıp köpüğünü alın; kısık ateşte 15 dakika pişirin.', 'Pirinci yıkayın; havucu küçük doğrayın.', 'Pirinç ve havucu ekleyin; 20 dakika, pirinç çok yumuşayana kadar pişirin.', 'Tavuk iç sıcaklığı 74°C olmalı; en büyük parçayı bölüp pembe kalmadığını kontrol edin.', 'Tavuğu çıkarıp ince didikleyin ve geri ekleyin.', 'Tereyağını ekleyip karıştırın.', 'İsterseniz birkaç damla limon sıkın.', 'Tuz eklemeyin; 1–3 yaş için günlük tuz 2 g’ı geçmemeli, peynir ve salça zaten tuz içerir.', 'Ilıtıp sıcaklığı bileğinizin iç kısmına damlatarak kontrol edin; ılık olmalı, sıcak değil.', 'Buz kalıplarında dondurup 1 ay saklayabilirsiniz; buzdolabında çözdürüp bir kez ısıtın.'], tips: ['Hastalık dönemlerinde iyi gelir.'], storage: 'Buzdolabında 48 saat.'),
  BabyRecipe(id: 'bj24_01', title: 'Ton balıklı makarna (çocuk)', age: '24+', category: 'Makarna', ingredient: 'ton balığı', vegetable: 'mısır', ingredients: ['Yarım su bardağı makarna', '2 yemek kaşığı suda ton balığı', '1 yemek kaşığı mısır', '2 yemek kaşığı yoğurt'], steps: ['Ellerinizi, kesme tahtasını ve kapları sıcak sabunlu suyla yıkayın.', 'Makarnayı tuzsuz kaynar suda paketteki süreden 2 dakika fazla, parmakla ezilecek kadar yumuşak haşlayın.', 'Ton balığını süzüp çatalla ufalayın; kılçık parçası varsa ayıklayın.', 'Mısırı ince kıyın.', 'Mısır taneleri boğulma riski taşır; ince kıyın ya da hafifçe ezin.', 'Ilımış makarna, ton balığı, mısır ve yoğurdu karıştırın.', 'Çocuklar için konserve ton balığını haftada 1 porsiyonla sınırlayın; zeytinyağlı yerine suda olanı ve az tuzlusunu seçin.', 'Kalanını kapalı kapta buzdolabında 1 gün saklayın; yalnızca bir kez ısıtın.'], tips: ['Suda ton balığı daha az yağlıdır; haftada 1 kez yeterli.'], storage: 'Hazırlandıktan hemen sonra tüketin.'),
  BabyRecipe(id: 'bj24_02', title: 'Sebzeli peynirli omlet rulo', age: '24+', category: 'Yumurta', ingredient: 'yumurta', vegetable: 'biber', ingredients: ['2 yumurta', '1 yemek kaşığı süt', '1 yemek kaşığı doğranmış biber', '1 dilim kaşar'], steps: ['Ellerinizi, kesme tahtasını ve kapları sıcak sabunlu suyla yıkayın.', 'Biberin çekirdeklerini çıkarıp çok ince doğrayın.', 'Yumurta ve sütü çırpıp biberi ekleyin.', 'Yapışmaz tavayı kısık ateşte ısıtıp karışımı ince bir tabaka halinde dökün.', 'Kapağı kapalı 3–4 dakika, üst yüzey tamamen katılaşana kadar pişirin.', 'Yumurtayı akı ve sarısı tamamen katılaşana kadar pişirin; akışkan bırakmayın.', 'Kaşarı yerleştirip rulo yapın; 1 dakika daha ısıtın.', 'Ilıyınca dilimleyin.', 'Kaşar ve lor pastörize sütten olmalı; tuzlu peyniri 1 saat suda bekletip tuzunu alın.'], tips: ['Renkli kahvaltı tabağı.'], storage: 'Hazırlandıktan hemen sonra tüketin.'),
  BabyRecipe(id: 'bj24_03', title: 'Fırında brokolili peynirli pirinç', age: '24+', category: 'Tahıl', ingredient: 'pirinç', vegetable: 'brokoli', ingredients: ['1 su bardağı pişmiş pirinç', '4 brokoli çiçeği', '3 yemek kaşığı süt', '2 yemek kaşığı rendelenmiş kaşar'], steps: ['Ellerinizi, kesme tahtasını ve kapları sıcak sabunlu suyla yıkayın.', 'Fırını 190°C’ye ısıtın; küçük fırın kabını yağlayın.', 'Brokoliyi küçük çiçeklere ayırıp 6 dakika haşlayın ve ince doğrayın.', 'Pişmiş pirinç, brokoli ve sütü karıştırıp kaba yayın.', 'Kaşarı serpip 15 dakika, üstü kızarana kadar pişirin.', 'Kapta 5 dakika dinlendirip ılıtın.', 'Kaşar ve lor pastörize sütten olmalı; tuzlu peyniri 1 saat suda bekletip tuzunu alın.', 'Kalanını kapalı kapta buzdolabında 2 gün saklayın; yalnızca bir kez ısıtın.'], tips: ['Artan pilavı değerlendirir.'], storage: 'Buzdolabında 48 saat.'),
  BabyRecipe(id: 'bj24_04', title: 'Patatesli mercimek yemeği', age: '24+', category: 'Baklagil', ingredient: 'yeşil mercimek', vegetable: 'patates', ingredients: ['3 yemek kaşığı yeşil mercimek', '1 patates', '1 havuç', '1 çay kaşığı salça', '2 su bardağı su'], steps: ['Ellerinizi, kesme tahtasını ve kapları sıcak sabunlu suyla yıkayın.', 'Yeşil mercimeği yıkayıp ayıklayın; suyla 20 dakika haşlayın.', 'Patates ve havucu soyup küçük küp doğrayın.', 'Salçayı ve sebzeleri mercimeğe ekleyin; kapağı kapalı kısık ateşte 20 dakika pişirin.', 'Sebzeler parmakla ezilecek kadar yumuşamalı.', 'Yoğurdu buzdolabından 10 dakika önce çıkarın; çok soğuk vermeyin.', 'Ilıyınca yoğurtla servis edin.', 'Tuz eklemeyin; 1–3 yaş için günlük tuz 2 g’ı geçmemeli, peynir ve salça zaten tuz içerir.', 'Buz kalıplarında dondurup 1 ay saklayabilirsiniz; buzdolabında çözdürüp bir kez ısıtın.'], tips: ['Doyurucu bir kış yemeği.'], storage: 'Buzdolabında 3 gün.'),
  BabyRecipe(id: 'bj24_05', title: 'Kaşarlı tavuk nugget (fırında)', age: '24+', category: 'Et', ingredient: 'tavuk', vegetable: '—', ingredients: ['100 g tavuk göğsü', '1 yumurta', '4 yemek kaşığı galeta unu', '1 yemek kaşığı rendelenmiş kaşar'], steps: ['Ellerinizi, kesme tahtasını ve kapları sıcak sabunlu suyla yıkayın.', 'Fırını 200°C’ye ısıtın; tepsiye yağlı kâğıt serin.', 'Çiğ eti ve tavuğu ayrı tahtada doğrayın; ardından tahtayı ve ellerinizi yıkayın.', 'Tavuğu çocuğun tutabileceği küçük şeritler halinde kesin.', 'Yumurtayı bir kapta çırpın; galeta unu ve kaşarı başka bir kapta karıştırın.', 'Tavukları önce yumurtaya, sonra galeta unu karışımına bulayıp tepsiye aralıklı dizin.', '15 dakika pişirin; yarısında çevirin.', 'Tavuk iç sıcaklığı 74°C olmalı; en büyük parçayı bölüp pembe kalmadığını kontrol edin.', 'Tepside 5 dakika dinlendirip ılıtın.', 'Buz kalıplarında dondurup 1 ay saklayabilirsiniz; buzdolabında çözdürüp bir kez ısıtın.'], tips: ['Hazır nuggetlara göre daha az tuz ve katkı içerir.'], storage: 'Hazırlandıktan hemen sonra tüketin.'),
  BabyRecipe(id: 'bj24_06', title: 'Kabak çorbası (kremalı, çocuk)', age: '24+', category: 'Çorba', ingredient: 'kabak', vegetable: 'kabak', ingredients: ['2 kabak', '1 patates', '1 çay kaşığı tereyağı', '3 yemek kaşığı süt', '2 su bardağı su'], steps: ['Ellerinizi, kesme tahtasını ve kapları sıcak sabunlu suyla yıkayın.', 'Kabak ve patatesi soyup küçük doğrayın.', 'Tereyağını tencerede eritip sebzeleri 3 dakika çevirin.', 'Suyu ekleyin; kısık ateşte 15 dakika yumuşayana kadar pişirin.', 'Blenderdan geçirin.', 'Sütü ekleyip 1 dakika ısıtın; kaynatmayın.', 'Tuz eklemeyin; 1–3 yaş için günlük tuz 2 g’ı geçmemeli, peynir ve salça zaten tuz içerir.', 'Ilıtıp sıcaklığı bileğinizin iç kısmına damlatarak kontrol edin; ılık olmalı, sıcak değil.', 'Kalanını kapalı kapta buzdolabında 2 gün saklayın; yalnızca bir kez ısıtın.'], tips: ['Hafif ve sindirimi kolay.'], storage: 'Buzdolabında 48 saat.'),
  BabyRecipe(id: 'bj24_07', title: 'Muzlu fıstık ezmeli tost', age: '24+', category: 'Kahvaltı', ingredient: 'ekmek', vegetable: 'muz', ingredients: ['1 dilim tam buğday ekmeği', '1 çay kaşığı fıstık ezmesi', 'Yarım muz'], steps: ['Ellerinizi, kesme tahtasını ve kapları sıcak sabunlu suyla yıkayın.', 'Ekmeği tost makinesinde ya da tavada hafifçe kızartın.', 'Fıstık ezmesini çok ince bir tabaka halinde sürün; kalın tabaka damağa yapışıp boğulma riski taşır.', 'Muzu ince dilimleyip ekmeğin üzerine dizin.', 'Dört parçaya kesip servis edin.', 'Yer fıstığı sık görülen bir alerjendir; ilk kez veriyorsanız az miktarla başlayıp gözlemleyin.', 'Bütün ya da iri parçalı fıstık 5 yaştan önce verilmez.', 'Çocuk yerken yanında olun; dik otursun, yürürken ya da koşarken yemesin.'], tips: ['Fıstık ezmesini ince sürün; alerjiye dikkat.'], storage: 'Hazırlandıktan hemen sonra tüketin.'),
  BabyRecipe(id: 'bj24_08', title: 'Etli patates yemeği (çocuk)', age: '24+', category: 'Et', ingredient: 'dana eti', vegetable: 'patates', ingredients: ['60 g kuşbaşı', '2 patates', '1 çay kaşığı salça', '1 su bardağı su'], steps: ['Ellerinizi, kesme tahtasını ve kapları sıcak sabunlu suyla yıkayın.', 'Çiğ eti ve tavuğu ayrı tahtada doğrayın; ardından tahtayı ve ellerinizi yıkayın.', 'Eti küçük doğrayıp yağ ve sinirlerini ayıklayın.', 'Eti tencerede 10 dakika, kendi suyunu çekene kadar pişirin.', 'Salçayı ekleyip 1 dakika çevirin.', 'Patatesleri soyup küp doğrayın ve suyla birlikte ekleyin.', 'Kapağı kapalı kısık ateşte 25 dakika, et ve patates yumuşayana kadar pişirin.', 'Eti küçük doğrayıp servis edin; içi pembe kalmamalı.', 'Tuz eklemeyin; 1–3 yaş için günlük tuz 2 g’ı geçmemeli, peynir ve salça zaten tuz içerir.', 'Ilıtıp sıcaklığı bileğinizin iç kısmına damlatarak kontrol edin; ılık olmalı, sıcak değil.', 'Buz kalıplarında dondurup 1 ay saklayabilirsiniz; buzdolabında çözdürüp bir kez ısıtın.'], tips: ['Klasik ev yemeğinin çocuk porsiyonu.'], storage: 'Buzdolabında 3 gün.'),
  BabyRecipe(id: 'bj24_09', title: 'Sebzeli pirinç salatası', age: '24+', category: 'Tahıl', ingredient: 'pirinç', vegetable: 'mısır', ingredients: ['Yarım su bardağı pişmiş pirinç', '1 yemek kaşığı mısır', '1 yemek kaşığı bezelye', 'Çeyrek salatalık', '1 çay kaşığı zeytinyağı'], steps: ['Ellerinizi, kesme tahtasını ve kapları sıcak sabunlu suyla yıkayın.', 'Pişmiş pirinci geniş bir kaba yayıp hızla soğutun; buzdolabında saklayın.', 'Bezelye ve mısırı 5 dakika haşlayıp soğuk suya alın.', 'Mısırı ince kıyın; bezelyeleri hafif ezin.', 'Salatalığı soyup küçük küp doğrayın.', 'Hepsini zeytinyağıyla karıştırıp hemen servis edin.', 'Pişmiş pirinç oda sıcaklığında uzun kalırsa bozulabilir; 1 saatten fazla dışarıda bırakmayın ve 1 günde tüketin.'], tips: ['Beslenme çantası için uygundur.'], storage: 'Hazırlandıktan hemen sonra tüketin.'),
  BabyRecipe(id: 'bj24_10', title: 'Kakaolu muzlu pankek', age: '24+', category: 'Kahvaltı', ingredient: 'un', vegetable: 'muz', ingredients: ['1 muz', '1 yumurta', '4 yemek kaşığı un', '1 çay kaşığı kakao', '3 yemek kaşığı süt'], steps: ['Ellerinizi, kesme tahtasını ve kapları sıcak sabunlu suyla yıkayın.', 'Olgun muzu çatalla pürüzsüz ezin.', 'Yumurta, un, kakao ve sütü ekleyip çırpın; 5 dakika dinlendirin.', 'Yapışmaz tavayı kısık ateşte ısıtın; kaşıkla küçük pankekler dökün.', 'Altı pişince çevirip diğer yüzünü 1–2 dakika pişirin.', 'Bir tanesini ortadan bölün: içinde akışkan yumurta kalmamalı.', 'Doğranmış meyveyle servis edin.', 'Kakao kafein benzeri teobromin içerir; az kullanın ve akşam saatlerinde vermeyin.', 'Buz kalıplarında dondurup 1 ay saklayabilirsiniz; buzdolabında çözdürüp bir kez ısıtın.'], tips: ['Şeker eklemeyin.'], storage: 'Hazırlandıktan hemen sonra tüketin.'),
  BabyRecipe(id: 'bj24_11', title: 'Fırında havuçlu köfte', age: '24+', category: 'Et', ingredient: 'dana kıyma', vegetable: 'havuç', ingredients: ['100 g kıyma', '1 havuç (rendelenmiş)', '1 yemek kaşığı galeta unu'], steps: ['Ellerinizi, kesme tahtasını ve kapları sıcak sabunlu suyla yıkayın.', 'Fırını 200°C’ye ısıtın; tepsiye yağlı kâğıt serin.', 'Havucu ince rendeleyip suyunu iyice sıkın.', 'Kıyma, havuç ve galeta ununu yoğurun; ardından ellerinizi yıkayın.', 'Ceviz büyüklüğünde yassı köfteler yapıp tepsiye dizin.', '20 dakika pişirin; yarısında çevirin.', 'Köfte iç sıcaklığı 71°C olmalı; bir köfteyi ortadan bölün: içi pembe kalmamalı, suyu berrak akmalı.', 'Tepside 5 dakika dinlendirip ılıtın.', 'Buz kalıplarında dondurup 1 ay saklayabilirsiniz; buzdolabında çözdürüp bir kez ısıtın.'], tips: ['Havuç köfteyi yumuşak ve tatlımsı yapar.'], storage: 'Buzdolabında 48 saat.'),
  BabyRecipe(id: 'bj24_12', title: 'Sütlü irmik tatlısı (az şekerli)', age: '24+', category: 'Tatlı', ingredient: 'irmik', vegetable: '—', ingredients: ['2 yemek kaşığı irmik', '1 su bardağı süt', '1 çay kaşığı şeker', '1 çay kaşığı tereyağı'], steps: ['Ellerinizi, kesme tahtasını ve kapları sıcak sabunlu suyla yıkayın.', 'Tereyağını küçük tencerede eritip irmiği 2 dakika, kokusu çıkana kadar kavurun.', 'Sütü yavaşça ekleyin; topaklanmasın diye sürekli karıştırın.', 'Kısık ateşte sürekli karıştırarak 5–6 dakika, koyulaşana kadar pişirin.', 'Şekeri ekleyip karıştırın.', '2 yaş altında şeker eklemeyin; 2 yaştan sonra da günde en fazla 1–2 çay kaşığı ekli şeker yeterlidir.', 'Ilıtıp sıcaklığı bileğinizin iç kısmına damlatarak kontrol edin; ılık olmalı, sıcak değil.', 'Kalanını kapalı kapta buzdolabında 2 gün saklayın; yalnızca bir kez ısıtın.'], tips: ['Şekeri en az düzeyde tutun.'], storage: 'Buzdolabında 48 saat.'),
  BabyRecipe(id: 'bj24_13', title: 'Bezelyeli tavuk sote', age: '24+', category: 'Et', ingredient: 'tavuk', vegetable: 'bezelye', ingredients: ['80 g tavuk göğsü', '3 yemek kaşığı bezelye', '1 havuç', '1 çay kaşığı zeytinyağı'], steps: ['Ellerinizi, kesme tahtasını ve kapları sıcak sabunlu suyla yıkayın.', 'Çiğ eti ve tavuğu ayrı tahtada doğrayın; ardından tahtayı ve ellerinizi yıkayın.', 'Tavuğu küçük doğrayın; havucu tavuktan küçük küpler halinde doğrayın.', 'Zeytinyağını tavada ısıtıp tavuğu 6–7 dakika, beyazlayana kadar pişirin.', 'Havuç ve bezelyeyi ekleyin; 3–4 kaşık su ilave edin.', 'Kapağı kapalı kısık ateşte 15 dakika, sebzeler yumuşayana kadar pişirin.', 'Tavuk iç sıcaklığı 74°C olmalı; en büyük parçayı bölüp pembe kalmadığını kontrol edin.', 'Bezelyeleri hafif ezip pilavla servis edin.', 'Kalanını kapalı kapta buzdolabında 2 gün saklayın; yalnızca bir kez ısıtın.'], tips: ['Renkli ve dengeli tabak.'], storage: 'Buzdolabında 48 saat.'),
  BabyRecipe(id: 'bj24_14', title: 'Ispanaklı yumurtalı pide (mini)', age: '24+', category: 'Fırın', ingredient: 'pide', vegetable: 'ıspanak', ingredients: ['1 küçük pide hamuru', '1 avuç ıspanak', '1 yumurta', '1 yemek kaşığı rendelenmiş kaşar'], steps: ['Ellerinizi, kesme tahtasını ve kapları sıcak sabunlu suyla yıkayın.', 'Fırını 220°C’ye ısıtın; tepsiye yağlı kâğıt serin.', 'Ispanağı yıkayıp ince doğrayın; tavada 2 dakika suyunu çekene kadar pişirin.', 'Pide hamurunu küçük bir oval şeklinde açıp kenarlarını içe kıvırın.', 'Ispanağı yayın, ortasına yumurtayı kırın ve kaşarı serpin.', '12 dakika, yumurtanın akı ve sarısı tamamen katılaşana kadar pişirin.', 'Yumurtayı akı ve sarısı tamamen katılaşana kadar pişirin; akışkan bırakmayın.', '5 dakika ılıtıp küçük dilimlere kesin.', 'Kaşar ve lor pastörize sütten olmalı; tuzlu peyniri 1 saat suda bekletip tuzunu alın.'], tips: ['Yumurta tam pişmeli.'], storage: 'Hazırlandıktan hemen sonra tüketin.'),
  BabyRecipe(id: 'bj24_15', title: 'Fırında elmalı yulaf (crumble)', age: '24+', category: 'Tatlı', ingredient: 'yulaf', vegetable: 'elma', ingredients: ['2 elma', '4 yemek kaşığı yulaf', '1 yemek kaşığı tereyağı', '1 tutam tarçın'], steps: ['Ellerinizi, kesme tahtasını ve kapları sıcak sabunlu suyla yıkayın.', 'Fırını 180°C’ye ısıtın; küçük fırın kabını yağlayın.', 'Elmaları soyup çekirdek evini çıkarın; küçük küpler halinde doğrayıp kaba yayın.', 'Tarçını elmaların üzerine serpin.', 'Yulaf ve soğuk tereyağını parmak uçlarınızla ovarak kum gibi bir karışım elde edin.', 'Karışımı elmaların üzerine serpin.', '25 dakika, elmalar yumuşayıp üstü kızarana kadar pişirin.', 'Elma parmakla ezilecek kadar yumuşak olmalı.', 'Kapta 5 dakika dinlendirip ılıtın.', 'Şeker eklemeyin; tatlılığı olgun meyveden gelsin.'], tips: ['Şeker eklemeden de tatlıdır.'], storage: 'Buzdolabında 48 saat.'),
  BabyRecipe(id: 'bk36_01', title: 'Tavuklu sebzeli wrap (fırında)', age: '36+', category: 'Et', ingredient: 'tavuk', vegetable: 'biber', ingredients: ['1 lavaş', '60 g haşlanmış tavuk', '1 yemek kaşığı doğranmış biber', '2 yemek kaşığı rendelenmiş kaşar'], steps: ['Ellerinizi, kesme tahtasını ve kapları sıcak sabunlu suyla yıkayın.', 'Fırını 200°C’ye ısıtın; tepsiye yağlı kâğıt serin.', 'Haşlanmış tavuğu ince didikleyin; biberin çekirdeklerini çıkarıp ince doğrayın.', 'Lavaşa tavuk, biber ve kaşarı yayın.', 'Sıkıca sarıp birleşme yeri altta kalacak şekilde tepsiye koyun.', '8 dakika, kaşar eriyip lavaş hafif kızarana kadar pişirin.', 'Erimiş peynir içi çok sıcak kalır; ılıtmadan vermeyin.', '5 dakika ılıtıp dilimleyin.', 'Kaşar ve lor pastörize sütten olmalı; tuzlu peyniri 1 saat suda bekletip tuzunu alın.'], tips: ['Okul öncesi beslenme için uygundur.'], storage: 'Hazırlandıktan hemen sonra tüketin.'),
  BabyRecipe(id: 'bk36_02', title: 'Ev yapımı domates çorbası (çocuk)', age: '36+', category: 'Çorba', ingredient: 'domates', vegetable: 'domates', ingredients: ['3 domates', '1 yemek kaşığı un', '1 çay kaşığı tereyağı', '3 yemek kaşığı süt', '2 su bardağı su'], steps: ['Ellerinizi, kesme tahtasını ve kapları sıcak sabunlu suyla yıkayın.', 'Domatesleri yıkayıp rendeleyin; kabukları atın.', 'Tereyağını tencerede eritip unu 2 dakika, kokusu çıkana kadar kavurun.', 'Domatesi ekleyip 2 dakika karıştırın.', 'Suyu yavaşça ekleyin; topaklanmasın diye karıştırın.', 'Kısık ateşte 15 dakika pişirin.', 'Sütü ekleyip 1 dakika ısıtın; kaynatmayın.', 'Üzerine az rendelenmiş kaşar serperek servis edin.', 'Tuz eklemeyin ya da çok az ekleyin; 1–3 yaşta günlük tuz 2 g’ı, 4–6 yaşta 3 g’ı geçmemeli.', 'Ilıtıp sıcaklığı bileğinizin iç kısmına damlatarak kontrol edin; ılık olmalı, sıcak değil.'], tips: ['Hazır çorbalara göre daha az tuzludur.'], storage: 'Buzdolabında 48 saat.'),
  BabyRecipe(id: 'bk36_03', title: 'Fırında sebzeli makarna (aile)', age: '36+', category: 'Makarna', ingredient: 'makarna', vegetable: 'kabak', ingredients: ['1 su bardağı makarna', '1 kabak', '1 havuç', '1 su bardağı domates sosu', '3 yemek kaşığı rendelenmiş kaşar'], steps: ['Ellerinizi, kesme tahtasını ve kapları sıcak sabunlu suyla yıkayın.', 'Makarnayı tuzsuz kaynar suda paketteki süreden 2 dakika fazla, parmakla ezilecek kadar yumuşak haşlayın.', 'Kabak ve havucu küçük küp doğrayın.', 'Sebzeleri tavada 1 kaşık zeytinyağıyla 5 dakika yumuşatın.', 'Domates sosu ve süzülmüş makarnayı ekleyip karıştırın.', 'Fırını 200°C’ye ısıtın.', 'Karışımı fırın kabına alıp kaşarı serpin.', '15 dakika, üstü kızarana kadar pişirin.', '5 dakika dinlendirip servis edin.', 'Buz kalıplarında dondurup 1 ay saklayabilirsiniz; buzdolabında çözdürüp bir kez ısıtın.'], tips: ['Aileyle aynı sofrada.'], storage: 'Buzdolabında 3 gün.'),
  BabyRecipe(id: 'bk36_04', title: 'Izgara köfte ve piyaz tabağı', age: '36+', category: 'Et', ingredient: 'dana kıyma', vegetable: 'fasulye', ingredients: ['100 g kıyma', '1 yemek kaşığı galeta unu', '3 yemek kaşığı haşlanmış kuru fasulye', '1 çay kaşığı zeytinyağı', 'Birkaç dal maydanoz'], steps: ['Ellerinizi, kesme tahtasını ve kapları sıcak sabunlu suyla yıkayın.', 'Kıyma ve galeta ununu yoğurun; ceviz büyüklüğünde yassı köfteler yapın ve ellerinizi yıkayın.', 'Köfteleri ızgara tavada orta ateşte her yüzü 4 dakika pişirin.', 'Köfte iç sıcaklığı 71°C olmalı; bir köfteyi ortadan bölün: içi pembe kalmamalı, suyu berrak akmalı.', 'Haşlanmış fasulyeyi zeytinyağı ve ince kıyılmış maydanozla karıştırın; fasulyeleri hafif ezin.', 'Tabağa köfte ve piyazı yerleştirin.', 'Köfteleri küçük parçalara kesip servis edin.', 'Kuru baklagiller bebeklerde gaz yapabilir; ilk kez veriyorsanız az porsiyonla başlayın.', 'Tuz eklemeyin ya da çok az ekleyin; 1–3 yaşta günlük tuz 2 g’ı, 4–6 yaşta 3 g’ı geçmemeli.'], tips: ['Acı ve soğan eklemeyin.'], storage: 'Buzdolabında 48 saat.'),
  BabyRecipe(id: 'bk36_05', title: 'Meyveli yulaf barı (fırında)', age: '36+', category: 'Tatlı', ingredient: 'yulaf', vegetable: 'muz', ingredients: ['2 muz', '1,5 su bardağı yulaf', '3 yemek kaşığı kuru üzüm (ince doğranmış)', '1 tutam tarçın'], steps: ['Ellerinizi, kesme tahtasını ve kapları sıcak sabunlu suyla yıkayın.', 'Fırını 180°C’ye ısıtın; küçük fırın kabına yağlı kâğıt serin.', 'Olgun muzları çatalla pürüzsüz ezin.', 'Yulaf, ince kıyılmış kuru üzüm ve tarçını ekleyip karıştırın; 5 dakika bekletin.', 'Karışımı kaba 1,5 cm kalınlığında bastırarak yayın.', '20 dakika, kenarları kızarana kadar pişirin.', 'Kapta tamamen soğutun, sonra çubuklar halinde kesin.', 'Şeker eklemeyin; tatlılığı olgun meyveden gelsin.', 'Kapalı kapta buzdolabında 3 gün saklayın.'], tips: ['Kuru üzümü doğramak yapışmayı azaltır.'], storage: 'Hava almayan kapta 4 gün.'),
  BabyRecipe(id: 'bk36_06', title: 'Sebzeli tavuk şiş (fırında)', age: '36+', category: 'Et', ingredient: 'tavuk', vegetable: 'biber', ingredients: ['100 g tavuk göğsü', 'Yarım kırmızı biber', 'Yarım kabak', '1 yemek kaşığı yoğurt'], steps: ['Ellerinizi, kesme tahtasını ve kapları sıcak sabunlu suyla yıkayın.', 'Çiğ eti ve tavuğu ayrı tahtada doğrayın; ardından tahtayı ve ellerinizi yıkayın.', 'Tavuğu küp doğrayıp yoğurtla buzdolabında 30 dakika marine edin.', 'Fırını 200°C’ye ısıtın; tepsiye yağlı kâğıt serin.', 'Biber ve kabağı tavuk büyüklüğünde doğrayın.', 'Tavuk ve sebzeleri sırayla şişlere dizip tepsiye koyun.', '20 dakika pişirin; yarısında çevirin.', 'Tavuk iç sıcaklığı 74°C olmalı; en büyük parçayı bölüp pembe kalmadığını kontrol edin.', 'Çocuğa vermeden önce tüm parçaları şişten çıkarın.', 'Küçük parçalara bölüp servis edin.'], tips: ['Şişleri çocuğa vermeyin; tabağa çıkarın.'], storage: 'Hazırlandıktan hemen sonra tüketin.'),
  BabyRecipe(id: 'bk36_07', title: 'Patatesli peynirli börek (çocuk)', age: '36+', category: 'Fırın', ingredient: 'yufka', vegetable: 'patates', ingredients: ['2 yufka', '1 haşlanmış patates', '2 yemek kaşığı beyaz peynir', 'Yarım su bardağı süt', '1 yumurta'], steps: ['Ellerinizi, kesme tahtasını ve kapları sıcak sabunlu suyla yıkayın.', 'Fırını 190°C’ye ısıtın; tepsiye yağlı kâğıt serin.', 'Beyaz peyniri 1 saat suda bekletip tuzunu alın.', 'Haşlanmış patates ve peyniri çatalla ezip karıştırın.', 'Süt ve yumurtayı çırpın; 2 kaşığını üstü için ayırın.', 'Yufkayı serip sosla ıslatın; harcı kenarına uzunlamasına koyup rulo yapın.', 'Ruloları tepsiye dizip ayırdığınız sosu sürün.', '30 dakika, üstü kızarana kadar pişirin.', 'Yumurtayı akı ve sarısı tamamen katılaşana kadar pişirin; akışkan bırakmayın.', '10 dakika dinlendirip dilimleyin.', 'Buz kalıplarında dondurup 1 ay saklayabilirsiniz; buzdolabında çözdürüp bir kez ısıtın.'], tips: ['Beslenme çantasına uygundur.'], storage: 'Buzdolabında 48 saat.'),
  BabyRecipe(id: 'bk36_08', title: 'Havuçlu kinoa köftesi', age: '36+', category: 'Tahıl', ingredient: 'kinoa', vegetable: 'havuç', ingredients: ['1 su bardağı pişmiş kinoa', '1 havuç (rendelenmiş)', '1 yumurta', '2 yemek kaşığı galeta unu'], steps: ['Ellerinizi, kesme tahtasını ve kapları sıcak sabunlu suyla yıkayın.', 'Fırını 200°C’ye ısıtın; tepsiye yağlı kâğıt serin.', 'Havucu ince rendeleyip suyunu sıkın.', 'Pişmiş kinoa, havuç, yumurta ve galeta ununu karıştırın; 10 dakika dinlendirin.', 'Islak elle küçük yassı köfteler yapıp tepsiye dizin.', '20 dakika pişirin; yarısında çevirin.', 'Yumurtayı akı ve sarısı tamamen katılaşana kadar pişirin; akışkan bırakmayın.', 'Yoğurdu buzdolabından 10 dakika önce çıkarın; çok soğuk vermeyin.', 'Yoğurtla servis edin.', 'Buz kalıplarında dondurup 1 ay saklayabilirsiniz; buzdolabında çözdürüp bir kez ısıtın.'], tips: ['Glutensiz alternatif için galeta yerine yulaf unu kullanın.'], storage: 'Buzdolabında 48 saat.'),
  BabyRecipe(id: 'bk36_09', title: 'Fırında balık ve patates (çocuk)', age: '36+', category: 'Balık', ingredient: 'levrek', vegetable: 'patates', ingredients: ['100 g levrek fileto', '2 patates', '1 yemek kaşığı zeytinyağı', 'Birkaç damla limon (1 çay kaşığı)'], steps: ['Ellerinizi, kesme tahtasını ve kapları sıcak sabunlu suyla yıkayın.', 'Fırını 200°C’ye ısıtın; tepsiye yağlı kâğıt serin.', 'Patatesleri soyup parmak kalınlığında çubuklar halinde kesin.', 'Zeytinyağıyla harmanlayıp tepsiye dizin; 15 dakika pişirin.', 'Levreği tepsiye ekleyin; 15 dakika daha pişirin.', 'Balığı parmaklarınızla yoklayarak tüm kılçıkları ayıklayın; et opaklaşıp kolayca dağılıyorsa pişmiştir.', 'Limonu gezdirip balığı ufalayın; patatesle ılık servis edin.', 'Kalanını kapalı kapta buzdolabında 2 gün saklayın; yalnızca bir kez ısıtın.'], tips: ['Kızartmasız klasik.'], storage: 'Hazırlandıktan hemen sonra tüketin.'),
  BabyRecipe(id: 'bk36_10', title: 'Ispanaklı pirinç pilavı', age: '36+', category: 'Tahıl', ingredient: 'pirinç', vegetable: 'ıspanak', ingredients: ['Yarım su bardağı pirinç', '1 su bardağı ıspanak', '1 çay kaşığı tereyağı', '1 su bardağı su'], steps: ['Ellerinizi, kesme tahtasını ve kapları sıcak sabunlu suyla yıkayın.', 'Pirinci 20 dakika ılık suda bekletip süzün.', 'Ispanağı bol suda birkaç kez yıkayıp ince doğrayın.', 'Tereyağını tencerede eritip ıspanağı 2 dakika çevirin.', 'Pirinci ekleyip 1 dakika kavurun; suyu ilave edin.', 'Kaynayınca kapağı kapalı kısık ateşte 15 dakika, suyunu çekene kadar pişirin.', 'Ocağı kapatıp kapağın altına kâğıt havlu koyarak 10 dakika demlendirin.', 'Yoğurdu buzdolabından 10 dakika önce çıkarın; çok soğuk vermeyin.', 'Yoğurtla servis edin.'], tips: ['Yeşil pilav çocukların ilgisini çeker.'], storage: 'Buzdolabında 48 saat.'),
  BabyRecipe(id: 'bk36_11', title: 'Yoğurtlu meyve salatası', age: '36+', category: 'Tatlı', ingredient: 'yoğurt', vegetable: 'elma', ingredients: ['Yarım elma', 'Yarım muz', '4 üzüm (dörde bölünmüş)', '3 yemek kaşığı yoğurt'], steps: ['Ellerinizi, kesme tahtasını ve kapları sıcak sabunlu suyla yıkayın.', 'Meyveleri yıkayın; elma ve muzu soyup küçük küp doğrayın.', 'Üzümleri uzunlamasına dörde bölün.', 'Üzüm, çeri domates ve benzeri yuvarlak besinleri 5 yaşına kadar dörde bölün.', 'Meyveleri kaseye alın.', 'Yoğurdu buzdolabından 10 dakika önce çıkarın; çok soğuk vermeyin.', 'Yoğurdu ekleyip karıştırın.', 'Hemen servis edin; elma ve muz kararır.', 'Çocuk yerken yanında olun; dik otursun, yürürken ya da koşarken yemesin.'], tips: ['Bütün üzüm 5 yaşa kadar dörde bölünmelidir.'], storage: 'Hazırlandıktan hemen sonra tüketin.'),
  BabyRecipe(id: 'bk36_12', title: 'Kıymalı sebzeli lahmacun (ev, acısız)', age: '36+', category: 'Fırın', ingredient: 'lavaş', vegetable: 'domates', ingredients: ['1 lavaş', '50 g kıyma', '1 domates (rendelenmiş)', 'Birkaç dal maydanoz'], steps: ['Ellerinizi, kesme tahtasını ve kapları sıcak sabunlu suyla yıkayın.', 'Fırını 220°C’ye ısıtın; tepsiye yağlı kâğıt serin.', 'Kıyma, rendelenmiş domates ve ince kıyılmış maydanozu iyice yoğurun; ardından ellerinizi yıkayın.', 'Harcı lavaşa çok ince bir tabaka halinde yayın; kalın harç tam pişmeyebilir.', '10 dakika, kıyma tamamen pişip kenarlar kızarana kadar pişirin.', 'Kıymada pembe kalmadığını kontrol edin.', 'Acı biber eklemeyin; ılıtıp dilimleyin.', 'Tuz eklemeyin ya da çok az ekleyin; 1–3 yaşta günlük tuz 2 g’ı, 4–6 yaşta 3 g’ı geçmemeli.'], tips: ['Acı biber eklemeyin.'], storage: 'Hazırlandıktan hemen sonra tüketin.'),
  BabyRecipe(id: 'bk36_13', title: 'Havuçlu portakallı muffin', age: '36+', category: 'Tatlı', ingredient: 'un', vegetable: 'havuç', ingredients: ['1 havuç (rendelenmiş)', '1 yumurta', 'Yarım su bardağı portakal suyu', '1 su bardağı tam buğday unu', '1 çay kaşığı kabartma tozu', '1 yemek kaşığı bal'], steps: ['Ellerinizi, kesme tahtasını ve kapları sıcak sabunlu suyla yıkayın.', 'Fırını 180°C’ye ısıtın; muffin kalıbını yağlayın ya da kâğıt kapsül koyun.', 'Havucu ince rendeleyin.', 'Havuç, yumurta, portakal suyu ve balı çırpın.', 'Un ve kabartma tozunu ekleyip sadece karışana kadar karıştırın.', 'Kalıpları dörtte üçüne kadar doldurun.', '20 dakika pişirin; kürdan temiz çıkmalı.', 'Kalıpta 5 dakika bekletip ılıtın.', 'Bal yalnızca 1 yaşını doldurmuş çocuklara verilebilir.', 'Buz kalıplarında dondurup 1 ay saklayabilirsiniz; buzdolabında çözdürüp bir kez ısıtın.'], tips: ['Bal 1 yaşından sonra kullanılabilir.'], storage: 'Hava almayan kapta 2 gün.'),
  BabyRecipe(id: 'bk36_14', title: 'Sebzeli tavuk güveç (çocuk)', age: '36+', category: 'Et', ingredient: 'tavuk', vegetable: 'patates', ingredients: ['100 g tavuk', '1 patates', '1 havuç', 'Yarım biber', '1 domates'], steps: ['Ellerinizi, kesme tahtasını ve kapları sıcak sabunlu suyla yıkayın.', 'Çiğ eti ve tavuğu ayrı tahtada doğrayın; ardından tahtayı ve ellerinizi yıkayın.', 'Tavuk, patates, havuç, biber ve domatesi küp doğrayın; sebzeleri tavuktan küçük kesin.', 'Hepsini güvece alıp yarım su bardağı su ekleyin.', 'Güveci soğuk fırına koyun; 190°C’de 45 dakika pişirin.', 'Tavuk iç sıcaklığı 74°C olmalı; en büyük parçayı bölüp pembe kalmadığını kontrol edin.', 'Havuç parmakla ezilecek kadar yumuşak olmalı.', 'Güveci ahşap bir yüzeye koyun; çok sıcaktır, çocuğu uzak tutun.', 'Ilıtıp sıcaklığı bileğinizin iç kısmına damlatarak kontrol edin; ılık olmalı, sıcak değil.', 'Kalanını kapalı kapta buzdolabında 2 gün saklayın; yalnızca bir kez ısıtın.'], tips: ['Tek kapta pratik aile yemeği.'], storage: 'Buzdolabında 3 gün.'),
  BabyRecipe(id: 'bk36_15', title: 'Peynirli mısır ekmeği (çocuk)', age: '36+', category: 'Fırın', ingredient: 'mısır unu', vegetable: 'mısır', ingredients: ['1 su bardağı mısır unu', 'Yarım su bardağı un', '1 yumurta', '1 su bardağı yoğurt', '2 yemek kaşığı beyaz peynir', '1 çay kaşığı kabartma tozu'], steps: ['Ellerinizi, kesme tahtasını ve kapları sıcak sabunlu suyla yıkayın.', 'Fırını 190°C’ye ısıtın; küçük kek kalıbını yağlayın.', 'Beyaz peyniri 1 saat suda bekletip tuzunu alın ve ufalayın.', 'Yumurta ve yoğurdu çırpın.', 'Mısır unu, un ve kabartma tozunu ekleyip sadece karışana kadar karıştırın; peyniri ekleyin.', 'Kalıba döküp 30 dakika pişirin; ortasına batırdığınız kürdan temiz çıkmalı.', '10 dakika dinlendirip dilimleyin.', 'Buz kalıplarında dondurup 1 ay saklayabilirsiniz; buzdolabında çözdürüp bir kez ısıtın.'], tips: ['Kahvaltıda çorbayla iyi gider.'], storage: 'Hava almayan kapta 2 gün.'),
  BabyRecipe(id: 'be6_01', title: 'Patates püresi (sade)', age: '6+', category: 'Sebze', ingredient: 'patates', vegetable: 'patates', ingredients: ['1 küçük patates (yaklaşık 100 g)', '1 çay kaşığı tereyağı veya zeytinyağı'], steps: ['Malzemeleri iyice yıkayın; gerekiyorsa soyup küçük doğrayın.', 'Küp doğrayıp buharda 15 dakika pişirin.', 'Blender veya çatalla yaşa uygun kıvamda ezin.', 'Gerekirse haşlama suyu, anne sütü veya mamayla kıvamı ayarlayın.', 'Ilıtıp sıcaklığını bileğinizde kontrol ederek servis edin.'], tips: ['Patatesi blenderda uzun çekmeyin; zamk gibi olur, çatalla ezin.'], storage: 'Buzdolabında 24 saat; buz kalıbında 1 ay dondurulabilir.'),
  BabyRecipe(id: 'be6_02', title: 'Karnabahar püresi', age: '6+', category: 'Sebze', ingredient: 'karnabahar', vegetable: 'karnabahar', ingredients: ['5–6 karnabahar çiçeği', '1 çay kaşığı zeytinyağı'], steps: ['Malzemeleri iyice yıkayın; gerekiyorsa soyup küçük doğrayın.', 'Buharda 10 dakika pişirin.', 'Blender veya çatalla yaşa uygun kıvamda ezin.', 'Gerekirse haşlama suyu, anne sütü veya mamayla kıvamı ayarlayın.', 'Ilıtıp sıcaklığını bileğinizde kontrol ederek servis edin.'], tips: ['Gaz yapabilir; ilk denemede 1–2 kaşıkla başlayın.'], storage: 'Buzdolabında 24 saat; buz kalıbında 1 ay dondurulabilir.'),
  BabyRecipe(id: 'be6_03', title: 'Yeşil fasulye püresi', age: '6+', category: 'Sebze', ingredient: 'yeşil fasulye', vegetable: 'yeşil fasulye', ingredients: ['1 avuç taze fasulye (uçları ve lifleri alınmış)', '1 çay kaşığı zeytinyağı'], steps: ['Malzemeleri iyice yıkayın; gerekiyorsa soyup küçük doğrayın.', 'Buharda 15 dakika pişirin.', 'Blender veya çatalla yaşa uygun kıvamda ezin.', 'Gerekirse haşlama suyu, anne sütü veya mamayla kıvamı ayarlayın.', 'Ilıtıp sıcaklığını bileğinizde kontrol ederek servis edin.'], tips: ['Lifli kabuklar kalırsa ince süzgeçten geçirin.'], storage: 'Buzdolabında 24 saat; buz kalıbında 1 ay dondurulabilir.'),
  BabyRecipe(id: 'be6_04', title: 'Ayva püresi (pişmiş)', age: '6+', category: 'Meyve', ingredient: 'ayva', vegetable: 'ayva', ingredients: ['Yarım ayva', '3 yemek kaşığı içme suyu'], steps: ['Malzemeleri iyice yıkayın; gerekiyorsa soyup küçük doğrayın.', 'Soyup çekirdek yatağını çıkarın, suyla 15 dakika yumuşayana kadar pişirin.', 'Blender veya çatalla yaşa uygun kıvamda ezin.', 'Gerekirse haşlama suyu, anne sütü veya mamayla kıvamı ayarlayın.', 'Ilıtıp sıcaklığını bileğinizde kontrol ederek servis edin.'], tips: ['Ayva sertleşmeye eğilimli dışkıda dikkatli kullanılmalı.'], storage: 'Buzdolabında 24 saat; buz kalıbında 1 ay dondurulabilir.'),
  BabyRecipe(id: 'be6_05', title: 'Şeftali ve armut püresi', age: '6+', category: 'Meyve', ingredient: 'şeftali', vegetable: 'armut', ingredients: ['Yarım şeftali', 'Yarım armut'], steps: ['Malzemeleri iyice yıkayın; gerekiyorsa soyup küçük doğrayın.', 'Soyup 5 dakika buharda pişirin.', 'Blender veya çatalla yaşa uygun kıvamda ezin.', 'Gerekirse haşlama suyu, anne sütü veya mamayla kıvamı ayarlayın.', 'Ilıtıp sıcaklığını bileğinizde kontrol ederek servis edin.'], tips: ['Mevsiminde olgun meyve seçin.'], storage: 'Buzdolabında 24 saat; buz kalıbında 1 ay dondurulabilir.'),
  BabyRecipe(id: 'be6_06', title: 'Kavun ezmesi', age: '6+', category: 'Meyve', ingredient: 'kavun', vegetable: 'kavun', ingredients: ['1 dilim çok olgun kavun'], steps: ['Malzemeleri iyice yıkayın; gerekiyorsa soyup küçük doğrayın.', 'Kabuğunu ve çekirdeğini ayırıp pişirmeden hazırlayın.', 'Blender veya çatalla yaşa uygun kıvamda ezin.', 'Gerekirse haşlama suyu, anne sütü veya mamayla kıvamı ayarlayın.', 'Ilıtıp sıcaklığını bileğinizde kontrol ederek servis edin.'], tips: ['Sulu meyvelerde kıvam için az miktar bebek mamasıyla koyulaştırabilirsiniz.'], storage: 'Hazırlandıktan hemen sonra tüketin.'),
  BabyRecipe(id: 'be6_07', title: 'Tatlı patates ve elma püresi', age: '6+', category: 'Sebze', ingredient: 'tatlı patates', vegetable: 'elma', ingredients: ['Yarım tatlı patates', 'Yarım elma'], steps: ['Malzemeleri iyice yıkayın; gerekiyorsa soyup küçük doğrayın.', 'Buharda 12 dakika pişirin.', 'Blender veya çatalla yaşa uygun kıvamda ezin.', 'Gerekirse haşlama suyu, anne sütü veya mamayla kıvamı ayarlayın.', 'Ilıtıp sıcaklığını bileğinizde kontrol ederek servis edin.'], tips: ['Elma, tatlı patatese tazelik katar.'], storage: 'Buzdolabında 24 saat; buz kalıbında 1 ay dondurulabilir.'),
  BabyRecipe(id: 'be6_08', title: 'Kabak ve havuç püresi', age: '6+', category: 'Sebze', ingredient: 'kabak', vegetable: 'havuç', ingredients: ['Yarım kabak', 'Yarım havuç', '1 çay kaşığı zeytinyağı'], steps: ['Malzemeleri iyice yıkayın; gerekiyorsa soyup küçük doğrayın.', 'Havucu 5 dakika önce koyarak toplam 15 dakika buharda pişirin.', 'Blender veya çatalla yaşa uygun kıvamda ezin.', 'Gerekirse haşlama suyu, anne sütü veya mamayla kıvamı ayarlayın.', 'Ilıtıp sıcaklığını bileğinizde kontrol ederek servis edin.'], tips: ['Havuç daha geç piştiği için önce koyulur.'], storage: 'Buzdolabında 24 saat; buz kalıbında 1 ay dondurulabilir.'),
  BabyRecipe(id: 'be6_09', title: 'Balkabağı ve tatlı patates püresi', age: '6+', category: 'Sebze', ingredient: 'balkabağı', vegetable: 'tatlı patates', ingredients: ['80 g balkabağı', 'Yarım tatlı patates'], steps: ['Malzemeleri iyice yıkayın; gerekiyorsa soyup küçük doğrayın.', 'Buharda 15 dakika pişirin.', 'Blender veya çatalla yaşa uygun kıvamda ezin.', 'Gerekirse haşlama suyu, anne sütü veya mamayla kıvamı ayarlayın.', 'Ilıtıp sıcaklığını bileğinizde kontrol ederek servis edin.'], tips: ['Dondurmaya çok uygundur; buz kalıbında porsiyonlayın.'], storage: 'Buzdolabında 24 saat; buz kalıbında 1 ay dondurulabilir.'),
  BabyRecipe(id: 'be6_10', title: 'Pirinç unu lapası (sade)', age: '6+', category: 'Tahıl', ingredient: 'pirinç unu', vegetable: 'pirinç', ingredients: ['1 yemek kaşığı pirinç unu', '1 su bardağı içme suyu veya anne sütü/mama'], steps: ['Malzemeleri iyice yıkayın; gerekiyorsa soyup küçük doğrayın.', 'Pirinç ununu soğuk suda eritip sürekli karıştırarak 6–7 dakika pişirin.', 'Blender veya çatalla yaşa uygun kıvamda ezin.', 'Gerekirse haşlama suyu, anne sütü veya mamayla kıvamı ayarlayın.', 'Ilıtıp sıcaklığını bileğinizde kontrol ederek servis edin.'], tips: ['Anne sütü veya mama pişirmeden sonra, ılıyınca eklenir.'], storage: 'Hazırlandıktan hemen sonra tüketin.'),
  BabyRecipe(id: 'be6_11', title: 'Yulaf lapası (sade, bebek)', age: '6+', category: 'Tahıl', ingredient: 'yulaf', vegetable: 'yulaf', ingredients: ['2 yemek kaşığı ince yulaf ezmesi', 'Yarım su bardağı içme suyu'], steps: ['Malzemeleri iyice yıkayın; gerekiyorsa soyup küçük doğrayın.', 'Suyla 5 dakika pişirin.', 'Blender veya çatalla yaşa uygun kıvamda ezin.', 'Gerekirse haşlama suyu, anne sütü veya mamayla kıvamı ayarlayın.', 'Ilıtıp sıcaklığını bileğinizde kontrol ederek servis edin.'], tips: ['Yulafı blenderda toz hâline getirmek ilk aylarda pürüzsüzlük sağlar.'], storage: 'Hazırlandıktan hemen sonra tüketin.'),
  BabyRecipe(id: 'be6_12', title: 'Avokado ve armut ezmesi', age: '6+', category: 'Meyve', ingredient: 'avokado', vegetable: 'armut', ingredients: ['Çeyrek avokado', 'Çeyrek armut (buharda pişmiş)'], steps: ['Malzemeleri iyice yıkayın; gerekiyorsa soyup küçük doğrayın.', 'Armudu 5 dakika buharda pişirin, avokadoyu çiğ ekleyin.', 'Blender veya çatalla yaşa uygun kıvamda ezin.', 'Gerekirse haşlama suyu, anne sütü veya mamayla kıvamı ayarlayın.', 'Ilıtıp sıcaklığını bileğinizde kontrol ederek servis edin.'], tips: ['Avokado kararmasın diye hemen servis edin.'], storage: 'Hazırlandıktan hemen sonra tüketin.'),
  BabyRecipe(id: 'be6_13', title: 'Kırmızı mercimek ve havuç püresi', age: '6+', category: 'Baklagil', ingredient: 'kırmızı mercimek', vegetable: 'havuç', ingredients: ['2 yemek kaşığı kırmızı mercimek', 'Yarım havuç', '1 su bardağı içme suyu', '1 çay kaşığı zeytinyağı'], steps: ['Malzemeleri iyice yıkayın; gerekiyorsa soyup küçük doğrayın.', 'Mercimek ve havucu 20 dakika pişirin.', 'Blender veya çatalla yaşa uygun kıvamda ezin.', 'Gerekirse haşlama suyu, anne sütü veya mamayla kıvamı ayarlayın.', 'Ilıtıp sıcaklığını bileğinizde kontrol ederek servis edin.'], tips: ['Mercimek demir ve protein için iyi bir başlangıçtır.'], storage: 'Buzdolabında 24 saat; buz kalıbında 1 ay dondurulabilir.'),
  BabyRecipe(id: 'be6_14', title: 'Yumurta sarılı patates püresi', age: '6+', category: 'Yumurta', ingredient: 'yumurta', vegetable: 'patates', ingredients: ['1 haşlanmış yumurtanın sarısı (10 dakika haşlanmış)', '1 küçük patates'], steps: ['Malzemeleri iyice yıkayın; gerekiyorsa soyup küçük doğrayın.', 'Patatesi buharda 15 dakika pişirin; yumurtayı katı haşlayın.', 'Blender veya çatalla yaşa uygun kıvamda ezin.', 'Gerekirse haşlama suyu, anne sütü veya mamayla kıvamı ayarlayın.', 'Ilıtıp sıcaklığını bileğinizde kontrol ederek servis edin.'], tips: ['Yumurtayı alerji takibi için tek başına denedikten sonra karışımlarda kullanın.'], storage: 'Buzdolabında 24 saat; buz kalıbında 1 ay dondurulabilir.'),
  BabyRecipe(id: 'be6_15', title: 'Ispanaklı patates püresi', age: '6+', category: 'Sebze', ingredient: 'patates', vegetable: 'ıspanak', ingredients: ['1 küçük patates', '4–5 yaprak ıspanak'], steps: ['Malzemeleri iyice yıkayın; gerekiyorsa soyup küçük doğrayın.', 'Patatesi 12 dakika, ıspanağı son 3 dakika ekleyerek buharda pişirin.', 'Blender veya çatalla yaşa uygun kıvamda ezin.', 'Gerekirse haşlama suyu, anne sütü veya mamayla kıvamı ayarlayın.', 'Ilıtıp sıcaklığını bileğinizde kontrol ederek servis edin.'], tips: ['Nitrat nedeniyle ıspanağı haftada 1–2 kez ile sınırlayın; pişmiş ıspanaklı püreyi bekletmeyin.'], storage: 'Hazırlandıktan hemen sonra tüketin.'),
  BabyRecipe(id: 'be7_01', title: 'Somonlu patates püresi', age: '7+', category: 'Balık', ingredient: 'somon', vegetable: 'patates', ingredients: ['30 g kılçıksız somon', '1 küçük patates', '1 çay kaşığı zeytinyağı'], steps: ['Malzemeleri iyice yıkayın; gerekiyorsa soyup küçük doğrayın.', 'Patatesi 12 dakika, somonu son 8 dakika ekleyerek buharda pişirin; kılçıkları elle kontrol edin.', 'Blender veya çatalla yaşa uygun kıvamda ezin.', 'Gerekirse haşlama suyu, anne sütü veya mamayla kıvamı ayarlayın.', 'Ilıtıp sıcaklığını bileğinizde kontrol ederek servis edin.'], tips: ['Somon omega-3 kaynağıdır; kılçığı parmaklarınızla tek tek kontrol edin.'], storage: 'Buzdolabında 24 saat; buz kalıbında 1 ay dondurulabilir.'),
