  BabyRecipe(id: 'be7_03', title: 'Kuzu etli kabak püresi', age: '7+', category: 'Et', ingredient: 'kuzu eti', vegetable: 'kabak', ingredients: ['30 g yağsız kuzu eti', '1 küçük kabak', '1 küçük patates'], steps: ['Malzemeleri iyice yıkayın; gerekiyorsa soyup küçük doğrayın.', 'Eti 40 dakika haşlayın, sebzeleri ekleyip 12 dakika daha pişirin.', 'Blender veya çatalla yaşa uygun kıvamda ezin.', 'Gerekirse haşlama suyu, anne sütü veya mamayla kıvamı ayarlayın.', 'Ilıtıp sıcaklığını bileğinizde kontrol ederek servis edin.'], tips: ['Eti haşlama suyuyla birlikte pürüzsüz çekin.'], storage: 'Buzdolabında 24 saat; buz kalıbında 1 ay dondurulabilir.'),
  BabyRecipe(id: 'be7_04', title: 'Tavuklu pirinç lapası', age: '7+', category: 'Et', ingredient: 'tavuk', vegetable: 'havuç', ingredients: ['30 g tavuk göğsü', '1 yemek kaşığı pirinç', 'Yarım havuç', '1,5 su bardağı içme suyu'], steps: ['Malzemeleri iyice yıkayın; gerekiyorsa soyup küçük doğrayın.', 'Tavuk ve pirinci 25 dakika pişirin, havucu ekleyip 10 dakika daha pişirin.', 'Blender veya çatalla yaşa uygun kıvamda ezin.', 'Gerekirse haşlama suyu, anne sütü veya mamayla kıvamı ayarlayın.', 'Ilıtıp sıcaklığını bileğinizde kontrol ederek servis edin.'], tips: ['Pirinç iyice dağılmalı.'], storage: 'Buzdolabında 24 saat; buz kalıbında 1 ay dondurulabilir.'),
  BabyRecipe(id: 'be7_05', title: 'Nohut ve kabak püresi', age: '7+', category: 'Baklagil', ingredient: 'nohut', vegetable: 'kabak', ingredients: ['2 yemek kaşığı iyi pişmiş nohut (kabukları ayıklanmış)', 'Yarım kabak', '1 çay kaşığı zeytinyağı'], steps: ['Malzemeleri iyice yıkayın; gerekiyorsa soyup küçük doğrayın.', 'Kabağı 10 dakika buharda pişirip nohutla birlikte ezin.', 'Blender veya çatalla yaşa uygun kıvamda ezin.', 'Gerekirse haşlama suyu, anne sütü veya mamayla kıvamı ayarlayın.', 'Ilıtıp sıcaklığını bileğinizde kontrol ederek servis edin.'], tips: ['Nohut kabuklarını ayırmak gazı azaltır.'], storage: 'Buzdolabında 24 saat; buz kalıbında 1 ay dondurulabilir.'),
  BabyRecipe(id: 'be7_06', title: 'Lor peynirli kabak püresi', age: '7+', category: 'Süt ürünü', ingredient: 'lor peyniri', vegetable: 'kabak', ingredients: ['1 yemek kaşığı tuzsuz lor peyniri', 'Yarım kabak'], steps: ['Malzemeleri iyice yıkayın; gerekiyorsa soyup küçük doğrayın.', 'Kabağı buharda 10 dakika pişirin, ılıyınca loru ekleyip ezin.', 'Blender veya çatalla yaşa uygun kıvamda ezin.', 'Gerekirse haşlama suyu, anne sütü veya mamayla kıvamı ayarlayın.', 'Ilıtıp sıcaklığını bileğinizde kontrol ederek servis edin.'], tips: ['Tuzsuz lor seçin; beyaz peynir 12 aydan önce tuzu nedeniyle önerilmez.'], storage: 'Hazırlandıktan hemen sonra tüketin.'),
  BabyRecipe(id: 'be7_07', title: 'Bulgurlu sebze lapası', age: '8+', category: 'Tahıl', ingredient: 'bulgur', vegetable: 'kabak', ingredients: ['1 yemek kaşığı ince bulgur', 'Yarım kabak', 'Yarım havuç', '1 su bardağı içme suyu'], steps: ['Malzemeleri iyice yıkayın; gerekiyorsa soyup küçük doğrayın.', 'Hepsini 15 dakika pişirin.', 'Blender veya çatalla yaşa uygun kıvamda ezin.', 'Gerekirse haşlama suyu, anne sütü veya mamayla kıvamı ayarlayın.', 'Ilıtıp sıcaklığını bileğinizde kontrol ederek servis edin.'], tips: ['Bulgur bebeğe daha dokulu kıvam tanıtır.'], storage: 'Buzdolabında 24 saat; buz kalıbında 1 ay dondurulabilir.'),
  BabyRecipe(id: 'be7_08', title: 'Yoğurtlu kabak ezmesi', age: '8+', category: 'Yoğurt', ingredient: 'yoğurt', vegetable: 'kabak', ingredients: ['Yarım kabak', '2 yemek kaşığı ev yoğurdu'], steps: ['Malzemeleri iyice yıkayın; gerekiyorsa soyup küçük doğrayın.', 'Kabağı buharda 10 dakika pişirip soğutun; yoğurtla ezin.', 'Blender veya çatalla yaşa uygun kıvamda ezin.', 'Gerekirse haşlama suyu, anne sütü veya mamayla kıvamı ayarlayın.', 'Ilıtıp sıcaklığını bileğinizde kontrol ederek servis edin.'], tips: ['Sarımsak ve tuz eklemeyin.'], storage: 'Hazırlandıktan hemen sonra tüketin.'),
  BabyRecipe(id: 'be7_09', title: 'Dana ciğerli sebze püresi', age: '8+', category: 'Et', ingredient: 'dana ciğeri', vegetable: 'patates', ingredients: ['20 g dana ciğeri', '1 küçük patates', 'Yarım havuç'], steps: ['Malzemeleri iyice yıkayın; gerekiyorsa soyup küçük doğrayın.', 'Ciğeri zarından ayırıp sebzelerle 15 dakika, içi pembe kalmayana kadar haşlayın.', 'Blender veya çatalla yaşa uygun kıvamda ezin.', 'Gerekirse haşlama suyu, anne sütü veya mamayla kıvamı ayarlayın.', 'Ilıtıp sıcaklığını bileğinizde kontrol ederek servis edin.'], tips: ['A vitamini çok yüksek olduğundan haftada en fazla 1 kez verin.'], storage: 'Buzdolabında 24 saat; buz kalıbında 1 ay dondurulabilir.'),
  BabyRecipe(id: 'be7_10', title: 'Elmalı kabak püresi', age: '6+', category: 'Sebze', ingredient: 'kabak', vegetable: 'elma', ingredients: ['Yarım kabak', 'Yarım elma'], steps: ['Malzemeleri iyice yıkayın; gerekiyorsa soyup küçük doğrayın.', 'Buharda 10 dakika pişirin.', 'Blender veya çatalla yaşa uygun kıvamda ezin.', 'Gerekirse haşlama suyu, anne sütü veya mamayla kıvamı ayarlayın.', 'Ilıtıp sıcaklığını bileğinizde kontrol ederek servis edin.'], tips: ['Meyveli sebze püresi yeni sebzelerin kabulünü kolaylaştırabilir.'], storage: 'Buzdolabında 24 saat; buz kalıbında 1 ay dondurulabilir.'),
  BabyRecipe(id: 'be8_01', title: 'Buharda havuç çubukları', age: '8+', category: 'Sebze', ingredient: 'havuç', vegetable: 'havuç', ingredients: ['1 havuç'], steps: ['Ellerinizi, kesme tahtasını ve kapları sıcak sabunlu suyla yıkayın.', 'Havucu soyup serçe parmak uzunluğunda ve kalınlığında çubuklar kesin.', 'Tencereye 2 parmak su koyup buhar sepetini yerleştirin; su kaynayınca sebzeyi sepete alıp kapağı kapatın.', 'Çubukları 15–18 dakika pişirin.', 'Parmaklarınızla bastırın: kolayca eziliyorsa hazırdır; sert havuç boğulma riski taşır.', 'Ilıtıp sıcaklığı bileğinizin iç kısmına damlatarak kontrol edin; ılık olmalı, sıcak değil.', 'Bebeğin önüne 2–3 çubuk koyun.', 'Bebek yerken mutlaka yanında, dik oturur durumda olsun; ağzına sığmayacak büyüklükte parçalar verin.'], tips: ['Parmak yiyecekleri bebeğin avucuna sığacak, serçe parmak uzunluğunda ve dişsiz damakla ezilebilecek yumuşaklıkta olmalı; yemek boyunca bebeğin yanında kalın.'], storage: 'Buzdolabında 48 saat.'),
  BabyRecipe(id: 'be8_02', title: 'Fırında tatlı patates dilimleri', age: '8+', category: 'Sebze', ingredient: 'tatlı patates', vegetable: 'tatlı patates', ingredients: ['1 tatlı patates', '1 tatlı kaşığı zeytinyağı'], steps: ['Fırını 190 °C\'ye ısıtın.', 'Tatlı patatesi soyup kalın parmak dilimler kesin.', 'Zeytinyağıyla harmanlayıp yağlı kâğıda dizin.', '25–30 dakika, içi yumuşayana kadar pişirin.', 'Ilıtıp servis edin.'], tips: ['Parmak yiyecekleri bebeğin avucuna sığacak, serçe parmak uzunluğunda ve dişsiz damakla ezilebilecek yumuşaklıkta olmalı; yemek boyunca bebeğin yanında kalın.'], storage: 'Buzdolabında 48 saat.'),
  BabyRecipe(id: 'be8_03', title: 'Brokoli ağaççıkları (buharda)', age: '8+', category: 'Sebze', ingredient: 'brokoli', vegetable: 'brokoli', ingredients: ['5–6 brokoli çiçeği (sapıyla)'], steps: ['Ellerinizi, kesme tahtasını ve kapları sıcak sabunlu suyla yıkayın.', 'Brokoliyi bebeğin tutabileceği uzunlukta sapıyla birlikte kesin; yıkayın.', 'Tencereye 2 parmak su koyup buhar sepetini yerleştirin; su kaynayınca sebzeyi sepete alıp kapağı kapatın.', '8–10 dakika pişirin.', 'Çiçek kısmı parmakla ezilecek kadar yumuşak olmalı.', 'Ilıtıp sıcaklığı bileğinizin iç kısmına damlatarak kontrol edin; ılık olmalı, sıcak değil.', 'Bebeğin sapından tutup yemesine izin verin.', 'Bebek yerken mutlaka yanında, dik oturur durumda olsun; ağzına sığmayacak büyüklükte parçalar verin.'], tips: ['Parmak yiyecekleri bebeğin avucuna sığacak, serçe parmak uzunluğunda ve dişsiz damakla ezilebilecek yumuşaklıkta olmalı; yemek boyunca bebeğin yanında kalın.'], storage: 'Buzdolabında 48 saat.'),
  BabyRecipe(id: 'be8_04', title: 'Yumurtalı ıspanaklı omlet şeritleri', age: '8+', category: 'Yumurta', ingredient: 'yumurta', vegetable: 'ıspanak', ingredients: ['1 yumurta', '2 yemek kaşığı ince kıyılmış ıspanak', '1 çay kaşığı tereyağı'], steps: ['Yumurtayı ıspanakla çırpın.', 'Tavada tereyağını eritip karışımı ince yayın.', 'Kapağı kapalı kısık ateşte iki yüzü tamamen pişene kadar pişirin.', 'Parmak şeritler hâlinde kesin.', 'Ilıtıp servis edin.'], tips: ['Yumurtada akışkan kısım kalmamalı.'], storage: 'Hazırlandıktan hemen sonra tüketin.'),
  BabyRecipe(id: 'be8_05', title: 'Muzlu yulaf parmak kekleri', age: '8+', category: 'Tahıl', ingredient: 'yulaf', vegetable: 'muz', ingredients: ['1 olgun muz', '4 yemek kaşığı ince yulaf', '1 yumurta'], steps: ['Fırını 180 °C\'ye ısıtın.', 'Muzu ezip yulaf ve yumurtayla karıştırın.', 'Yağlı kâğıt serili kalıba 1 cm kalınlıkta yayın.', '20 dakika pişirin.', 'Soğuyunca parmak dilimler kesin.'], tips: ['Şeker eklemeyin; muz yeterli tatlılık verir.'], storage: 'Buzdolabında kapalı kapta 3 gün.'),
  BabyRecipe(id: 'be8_06', title: 'Kabak mücveri (bebek, tuzsuz)', age: '9+', category: 'Sebze', ingredient: 'kabak', vegetable: 'kabak', ingredients: ['1 kabak', '1 yumurta', '2 yemek kaşığı un', 'Yarım demet dereotu (ince kıyılmış)'], steps: ['Kabağı rendeleyip suyunu iyice sıkın.', 'Yumurta, un ve dereotuyla karıştırın.', 'Yağlı kâğıt serilmiş tepsiye küçük yassı köfteler dökün; 190 °C fırında 20 dakika pişirin.', 'Ilıtıp şeritler hâlinde verin.', 'Yumurtayı akı ve sarısı tamamen katılaşana kadar pişirin; akışkan bırakmayın.'], tips: ['Fırında pişirmek kızartmaya göre daha uygundur. Tuz eklemeyin.'], storage: 'Buzdolabında 48 saat.'),
  BabyRecipe(id: 'be8_07', title: 'Bebek köftesi (fırında)', age: '9+', category: 'Et', ingredient: 'dana kıyma', vegetable: 'havuç', ingredients: ['100 g yağsız dana kıyma', '2 yemek kaşığı rendelenmiş havuç', '1 yemek kaşığı ince yulaf', '1 çay kaşığı kuru kekik'], steps: ['Fırını 190 °C\'ye ısıtın.', 'Tüm malzemeyi yoğurun.', 'Parmak şeklinde küçük köfteler yapın.', 'Yağlı kâğıt üzerinde 18–20 dakika, içi pembe kalmayana kadar pişirin.', 'Ilıtıp servis edin.'], tips: ['Tuz ve acı biber eklemeyin.'], storage: 'Buzdolabında 24 saat; pişmiş hâlde 1 ay dondurulabilir.'),
  BabyRecipe(id: 'be8_08', title: 'Somon köftesi (bebek)', age: '9+', category: 'Balık', ingredient: 'somon', vegetable: 'patates', ingredients: ['80 g pişmiş kılçıksız somon', '1 haşlanmış patates', '1 yemek kaşığı ince kıyılmış dereotu'], steps: ['Somonu kılçık kontrolü yaparak ezin.', 'Patates ve dereotuyla karıştırın.', 'Küçük yassı köfteler yapın.', 'Yağlı kâğıtta 190 °C fırında 15 dakika pişirin.', 'Ilıtıp servis edin.'], tips: ['Kılçıkları parmaklarınızla iki kez kontrol edin.'], storage: 'Buzdolabında 48 saat.'),
  BabyRecipe(id: 'be8_09', title: 'Avokado dilimleri (yulafa bulanmış)', age: '8+', category: 'Meyve', ingredient: 'avokado', vegetable: 'avokado', ingredients: ['Yarım olgun avokado', '2 yemek kaşığı toz yulaf'], steps: ['Ellerinizi, kesme tahtasını ve kapları sıcak sabunlu suyla yıkayın.', 'Olgun ama dağılmayan bir avokado seçin.', 'Avokadoyu soyup bebeğin avucuna sığacak, parmak kalınlığında uzun dilimler kesin.', 'Toz yulafı bir tabağa yayın; dilimleri yuvarlayarak bulayın; kaygan olmaz, kavraması kolaylaşır.', 'Bebeğin önüne 2–3 dilim koyun.', 'Bebek yerken mutlaka yanında, dik oturur durumda olsun; ağzına sığmayacak büyüklükte parçalar verin.', 'Hemen servis edin; kalanını saklamayın.'], tips: ['Parmak yiyecekleri bebeğin avucuna sığacak, serçe parmak uzunluğunda ve dişsiz damakla ezilebilecek yumuşaklıkta olmalı; yemek boyunca bebeğin yanında kalın.'], storage: 'Hazırlandıktan hemen sonra tüketin.'),
  BabyRecipe(id: 'be8_10', title: 'Haşlanmış armut dilimleri', age: '8+', category: 'Meyve', ingredient: 'armut', vegetable: 'armut', ingredients: ['1 armut'], steps: ['Ellerinizi, kesme tahtasını ve kapları sıcak sabunlu suyla yıkayın.', 'Armudu yıkayıp soyun ve çekirdek evini çıkarın.', 'Bebeğin avucuna sığacak kalın dilimler kesin.', 'Tencereye 2 parmak su koyup buhar sepetini yerleştirin; su kaynayınca sebzeyi sepete alıp kapağı kapatın.', 'Dilimleri 5–6 dakika, parmaklarınızla bastırınca kolayca ezilene kadar pişirin.', 'Ilıtıp sıcaklığı bileğinizin iç kısmına damlatarak kontrol edin; ılık olmalı, sıcak değil.', 'Bebeğin önüne 2–3 dilim koyun.', 'Bebek yerken mutlaka yanında, dik oturur durumda olsun; ağzına sığmayacak büyüklükte parçalar verin.'], tips: ['Parmak yiyecekleri bebeğin avucuna sığacak, serçe parmak uzunluğunda ve dişsiz damakla ezilebilecek yumuşaklıkta olmalı; yemek boyunca bebeğin yanında kalın.'], storage: 'Buzdolabında 48 saat.'),
  BabyRecipe(id: 'be8_11', title: 'Ev yapımı tuzsuz bebek peyniri (lor)', age: '8+', category: 'Süt ürünü', ingredient: 'süt', vegetable: 'süt', ingredients: ['1 litre tam yağlı pastörize süt', '2 yemek kaşığı limon suyu'], steps: ['Sütü kaynamaya yakın ısıtın (yaklaşık 85 °C).', 'Limon suyunu ekleyip ateşi kapatın, 10 dakika bekletin.', 'Kesilen sütü tülbentten süzün.', '30 dakika asılı bırakıp suyunu akıtın.', 'Tuz eklemeden buzdolabında saklayın.'], tips: ['Süt pişirildiği için 8 aydan itibaren peynir olarak verilebilir.'], storage: 'Buzdolabında 48 saat.'),
  BabyRecipe(id: 'be8_12', title: 'Fırında yumurtalı sebze muffin (bebek)', age: '9+', category: 'Yumurta', ingredient: 'yumurta', vegetable: 'brokoli', ingredients: ['2 yumurta', '3 yemek kaşığı ince doğranmış brokoli', '2 yemek kaşığı rendelenmiş havuç', '1 yemek kaşığı tuzsuz lor'], steps: ['Fırını 180 °C\'ye ısıtın.', 'Yumurtayı çırpıp sebzeler ve lorla karıştırın.', 'Mini muffin kalıplarına paylaştırın.', '18 dakika, ortası tamamen pişene kadar pişirin.', 'Ilıtıp ikiye bölerek servis edin.'], tips: ['Kahvaltıda ve dışarıda pratik bir öğündür.'], storage: 'Buzdolabında 48 saat.'),
  BabyRecipe(id: 'be8_13', title: 'Mercimek köftesi (bebek, acısız)', age: '10+', category: 'Baklagil', ingredient: 'kırmızı mercimek', vegetable: 'soğan', ingredients: ['Yarım su bardağı kırmızı mercimek', 'Yarım su bardağı ince bulgur', '1 yemek kaşığı zeytinyağı', '1 küçük soğan (ince kıyılmış)', 'Yarım demet maydanoz (ince kıyılmış)'], steps: ['Mercimeği 2 su bardağı suyla dağılana kadar pişirin.', 'Ocaktan alıp bulguru ekleyin, kapağı kapalı 20 dakika bekletin.', 'Soğanı zeytinyağında yumuşatıp ekleyin, maydanozu katın.', 'Yoğurup küçük parmak köfteler yapın.', 'Tuz, şeker ve bal eklemeyin; 1 yaş altı bebeklere uygun değildir.'], tips: ['Salça, pul biber ve tuz eklemeyin.'], storage: 'Buzdolabında 48 saat.'),
  BabyRecipe(id: 'be8_14', title: 'Tavuklu sebzeli küp köfte', age: '9+', category: 'Et', ingredient: 'tavuk', vegetable: 'kabak', ingredients: ['100 g tavuk kıyma', '2 yemek kaşığı rendelenmiş kabak (suyu sıkılmış)', '1 yemek kaşığı ince yulaf'], steps: ['Tüm malzemeyi yoğurun.', 'Küçük köfteler yapın.', 'Yağlı kâğıtta 190 °C fırında 18 dakika pişirin.', 'İçinin tamamen piştiğini kontrol edip ılıtın.', 'Eti ortadan bölüp kontrol edin: içi pembe kalmamalı, suyu berrak akmalı.'], tips: ['Tavuk iyi pişmeli; kesince pembe görünmemeli.'], storage: 'Buzdolabında 48 saat.'),
  BabyRecipe(id: 'bey_01', title: 'Ev yoğurdu (bebek için)', age: '6+', category: 'Yoğurt', ingredient: 'süt', vegetable: 'süt', ingredients: ['1 litre tam yağlı pastörize süt', '1 yemek kaşığı tam yağlı yoğurt (maya)'], steps: ['Tencereyi ve saklama kabını kaynar suyla çalkalayın; temiz kap mayalanmayı sağlar.', 'Sütü sürekli karıştırarak kaynatın ve ocaktan alın.', '45°C’ye kadar soğutun: serçe parmağınızı 10 saniye tutabilmelisiniz.', 'Mayayı bir kepçe ılık sütle pürüzsüz açın ve tencereye ekleyip karıştırın.', 'Kabın üzerini örtüp bir battaniyeye sarın; sıcak ve sarsılmayan bir yerde 6–8 saat bekletin.', 'Kıvam alınca buzdolabına kaldırın; 4–5 gün içinde tüketin.', 'Bebeğe 6. aydan itibaren tam yağlı, sade yoğurt verilebilir; içme sütü olarak inek sütü 1 yaştan sonra verilir.'], tips: ['Yoğurt 6 aydan itibaren tamamlayıcı besin olarak verilebilir; şeker eklemeyin.'], storage: 'Buzdolabında kapalı kapta 3 gün.'),
  BabyRecipe(id: 'bey_02', title: 'Yoğurtlu meyve ezmesi (şeftalili)', age: '8+', category: 'Yoğurt', ingredient: 'yoğurt', vegetable: 'şeftali', ingredients: ['3 yemek kaşığı ev yoğurdu', 'Yarım olgun şeftali'], steps: ['Ellerinizi, kesme tahtasını ve kapları sıcak sabunlu suyla yıkayın.', 'Şeftaliyi yıkayıp soyun ve çekirdeğini çıkarın.', 'Sertse buharda 3 dakika yumuşatın.', 'Çatalla ezin.', 'Yoğurdu buzdolabından 10 dakika önce çıkarın; çok soğuk vermeyin.', 'Yoğurtla karıştırın.', 'Tuz, şeker ve bal eklemeyin; 1 yaş altı bebeklere uygun değildir.', 'Hemen servis edin; kalanını saklamayın.'], tips: ['Meyve yoğurda doğal tatlılık verir.'], storage: 'Hazırlandıktan hemen sonra tüketin.'),
  BabyRecipe(id: 'bey_03', title: 'Yoğurtlu yulaf (gece bekletmeli, bebek)', age: '9+', category: 'Yoğurt', ingredient: 'yoğurt', vegetable: 'elma', ingredients: ['3 yemek kaşığı ince yulaf', '4 yemek kaşığı ev yoğurdu', '2 yemek kaşığı rendelenmiş elma'], steps: ['Ellerinizi, kesme tahtasını ve kapları sıcak sabunlu suyla yıkayın.', 'Elmayı soyup ince rendeleyin.', 'Yulaf, yoğurt ve elmayı kapaklı bir kapta karıştırın.', 'Kapalı kapta buzdolabında bir gece bekletin; yulaf yumuşar.', 'Sabah 15 dakika oda sıcaklığına getirin.', 'Koyulaşmışsa 1–2 kaşık anne sütü ekleyin.', 'Kaşıkla servis edin; 24 saat içinde tüketin.'], tips: ['Yulaf yumuşayarak kolay yenir.'], storage: 'Hazırlandıktan hemen sonra tüketin.'),
  BabyRecipe(id: 'bey_04', title: 'Yoğurt çorbası (bebek, tuzsuz)', age: '9+', category: 'Yoğurt', ingredient: 'yoğurt', vegetable: 'pirinç', ingredients: ['2 yemek kaşığı pirinç', '4 yemek kaşığı ev yoğurdu', '1 yumurta sarısı', '1 su bardağı içme suyu', '1 çay kaşığı tereyağı'], steps: ['Ellerinizi, kesme tahtasını ve kapları sıcak sabunlu suyla yıkayın.', 'Pirinci yıkayın; suyla tencereye alıp kısık ateşte 20 dakika çok yumuşayana kadar pişirin.', 'Yoğurdu ve yumurta sarısını ayrı kapta pürüzsüz çırpın.', 'Sıcak çorbadan birkaç kaşık alıp yoğurda azar azar ekleyerek ılıştırın.', 'Karışımı sürekli karıştırarak tencereye dökün.', 'Sürekli karıştırarak bir taşım kaynatın; yumurta sarısı tamamen pişmeli.', 'Tereyağını ekleyip ocaktan alın.', 'Tuz, şeker ve bal eklemeyin; 1 yaş altı bebeklere uygun değildir.', 'Ilıtıp sıcaklığı bileğinizin iç kısmına damlatarak kontrol edin; ılık olmalı, sıcak değil.'], tips: ['Tuz ve nane eklemeyin.'], storage: 'Buzdolabında 48 saat.'),
  BabyRecipe(id: 'bey_05', title: 'Yoğurtlu tavuk ezmesi', age: '9+', category: 'Yoğurt', ingredient: 'tavuk', vegetable: 'kabak', ingredients: ['30 g haşlanmış tavuk', 'Yarım haşlanmış kabak', '2 yemek kaşığı ev yoğurdu'], steps: ['Ellerinizi, kesme tahtasını ve kapları sıcak sabunlu suyla yıkayın.', 'Haşlanmış tavuğu çok ince didikleyip kıyın.', 'Haşlanmış kabağı çatalla ezin.', 'Yoğurdu buzdolabından 10 dakika önce çıkarın; çok soğuk vermeyin.', 'Tavuk, kabak ve yoğurdu birleştirin.', 'Kıvam koyuysa tavuk haşlama suyuyla yumuşatın.', 'Tuz, şeker ve bal eklemeyin; 1 yaş altı bebeklere uygun değildir.', 'Hemen servis edin; kalanını saklamayın.'], tips: ['Yoğurt tavuğu nemlendirir, yutmayı kolaylaştırır.'], storage: 'Hazırlandıktan hemen sonra tüketin.'),
  BabyRecipe(id: 'bey_06', title: 'Lorlu armut ezmesi', age: '8+', category: 'Süt ürünü', ingredient: 'lor peyniri', vegetable: 'armut', ingredients: ['2 yemek kaşığı tuzsuz lor', 'Yarım haşlanmış armut'], steps: ['Ellerinizi, kesme tahtasını ve kapları sıcak sabunlu suyla yıkayın.', 'Armudu soyup buharda 5 dakika pişirin ve ılıtın.', 'Armudu çatalla ezin.', 'Tuzsuz loru ekleyip karıştırın.', 'Kıvamı koyuysa biraz anne sütü ya da mama ekleyin.', 'Lor pastörize sütten ve tuzsuz olmalı.', 'Hemen servis edin; kalanını saklamayın.'], tips: ['Tuzsuz lor protein ve kalsiyum sağlar.'], storage: 'Hazırlandıktan hemen sonra tüketin.'),
  BabyRecipe(id: 'bey_07', title: 'Sütlü irmik lapası (12+ ay)', age: '12+', category: 'Süt ürünü', ingredient: 'süt', vegetable: 'irmik', ingredients: ['1 su bardağı süt', '1 yemek kaşığı irmik', 'Yarım muz'], steps: ['Ellerinizi, kesme tahtasını ve kapları sıcak sabunlu suyla yıkayın.', 'Sütü küçük tencerede orta ateşte ısıtın; kaynamaya yakın kısın.', 'İrmiği yağmur gibi serperek ekleyin; topaklanmasın diye sürekli karıştırın.', 'Kısık ateşte sürekli karıştırarak 5 dakika pişirin.', 'Muzu çatalla ezip ocaktan aldığınız lapaya karıştırın.', 'İnek sütü 1 yaştan sonra içecek olarak verilebilir; tam yağlı tercih edin.', 'Şeker eklemeyin; tatlılığı olgun meyveden gelsin.', 'Ilıtıp sıcaklığı bileğinizin iç kısmına damlatarak kontrol edin; ılık olmalı, sıcak değil.', 'Kalanını kapalı kapta buzdolabında 2 gün saklayın; yalnızca bir kez ısıtın.'], tips: ['12 aydan önce inek sütü yerine anne sütü veya mamayla yapılmalı; şeker eklemeyin.'], storage: 'Hazırlandıktan hemen sonra tüketin.'),
  BabyRecipe(id: 'bey_08', title: 'Sütlaç (şekersiz, çocuk)', age: '12+', category: 'Süt ürünü', ingredient: 'süt', vegetable: 'pirinç', ingredients: ['2 yemek kaşığı pirinç', '2 su bardağı süt', '1 tatlı kaşığı pirinç unu', 'Yarım muz veya 2 hurma (çekirdeksiz, ezilmiş)'], steps: ['Pirinci yarım su bardağı suyla yumuşayana kadar pişirin.', 'Sütü ekleyip kaynatın.', 'Pirinç ununu biraz sütle açıp ekleyin, 10 dakika karıştırarak pişirin.', 'Muz veya hurma ezmesiyle tatlandırıp kaselere alın.', 'Kalanını kapalı kapta buzdolabında 2 gün saklayın; yalnızca bir kez ısıtın.'], tips: ['Tatlandırıcı olarak şeker yerine meyve kullanın.'], storage: 'Buzdolabında kapalı kapta 3 gün.'),
  BabyRecipe(id: 'bey_09', title: 'Kefirli muz ezmesi (12+ ay)', age: '12+', category: 'Süt ürünü', ingredient: 'kefir', vegetable: 'muz', ingredients: ['3 yemek kaşığı sade kefir', 'Yarım muz'], steps: ['Ellerinizi, kesme tahtasını ve kapları sıcak sabunlu suyla yıkayın.', 'Olgun muzu çatalla pürüzsüz ezin.', 'Sade kefiri ekleyip karıştırın.', 'Aromalı ve şekerli kefir kullanmayın.', 'Hemen servis edin; kefir muzu kısa sürede karartır.', 'İnek sütü 1 yaştan sonra içecek olarak verilebilir; tam yağlı tercih edin.'], tips: ['Sade kefir probiyotik içerir.'], storage: 'Hazırlandıktan hemen sonra tüketin.'),
  BabyRecipe(id: 'bey_10', title: 'Peynirli yumurta ezmesi (12+ ay)', age: '12+', category: 'Süt ürünü', ingredient: 'beyaz peynir', vegetable: 'yumurta', ingredients: ['1 katı haşlanmış yumurta', '1 yemek kaşığı az tuzlu beyaz peynir (suda bekletilmiş)', '1 tatlı kaşığı zeytinyağı'], steps: ['Ellerinizi, kesme tahtasını ve kapları sıcak sabunlu suyla yıkayın.', 'Peyniri 1 saat suda bekletip tuzunu alın; suyu bir kez değiştirin.', 'Yumurtayı kaynar suda 10 dakika haşlayıp soğuk suya alın ve soyun.', 'Yumurtayı akı ve sarısı tamamen katılaşana kadar pişirin; akışkan bırakmayın.', 'Yumurtayı çatalla ezin.', 'Süzülmüş peynir ve zeytinyağıyla karıştırın.', 'İnce ekmek dilimine sürüp çocuğun tutabileceği şeritler halinde kesin.', 'Kaşar ve lor pastörize sütten olmalı; tuzlu peyniri 1 saat suda bekletip tuzunu alın.', 'Kalanını kapalı kapta buzdolabında 2 gün saklayın; yalnızca bir kez ısıtın.'], tips: ['Peyniri suda bekletmek tuzu azaltır.'], storage: 'Hazırlandıktan hemen sonra tüketin.'),
  BabyRecipe(id: 'bei_01', title: 'Ayran (çocuk, tuzsuz)', age: '12+', category: 'İçecek', ingredient: 'yoğurt', vegetable: 'yoğurt', ingredients: ['3 yemek kaşığı ev yoğurdu', 'Yarım su bardağı içme suyu'], steps: ['Ellerinizi, kesme tahtasını ve kapları sıcak sabunlu suyla yıkayın.', 'Soğuk içme suyunu ve yoğurdu bir kaba alın.', 'Çırpma teliyle ya da blenderda 30 saniye köpürene kadar çırpın.', 'Bardağa alıp hemen servis edin.', 'Tuz eklemeyin; çocukların böbrekleri için gereksizdir.', 'Açık bardakla içmeyi öğrenmek için iyi bir fırsattır.'], tips: ['Tuzsuz ayran yemekle iyi gider.'], storage: 'Hazırlandıktan hemen sonra tüketin.'),
  BabyRecipe(id: 'bei_02', title: 'Muzlu yoğurt smoothie (çocuk)', age: '12+', category: 'İçecek', ingredient: 'yoğurt', vegetable: 'muz', ingredients: ['Yarım muz', '4 yemek kaşığı yoğurt', 'Yarım su bardağı süt'], steps: ['Ellerinizi, kesme tahtasını ve kapları sıcak sabunlu suyla yıkayın.', 'Olgun muzu soyup dilimleyin.', 'Muz, yoğurt ve sütü blenderda pürüzsüz olana kadar çekin.', 'Bardağa alıp hemen servis edin.', 'Bal veya şeker eklemeyin.', 'İnek sütü 1 yaştan sonra içecek olarak verilebilir; tam yağlı tercih edin.'], tips: ['Kalın pipetle içmek kas gelişimini destekler.'], storage: 'Hazırlandıktan hemen sonra tüketin.'),
  BabyRecipe(id: 'bei_03', title: 'Çilekli süt (şekersiz)', age: '12+', category: 'İçecek', ingredient: 'süt', vegetable: 'çilek', ingredients: ['1 su bardağı süt', '4 olgun çilek'], steps: ['Ellerinizi, kesme tahtasını ve kapları sıcak sabunlu suyla yıkayın.', 'Çilekleri bol suda yıkayıp saplarını ayırın.', 'Süt ve çilekleri blenderda pürüzsüz olana kadar çekin.', 'Çekirdek istemiyorsanız ince süzgeçten süzün.', 'Hemen servis edin.', 'Çilek bazı çocuklarda ağız çevresinde kızarıklık yapabilir; ilk kez veriyorsanız gözlemleyin.', 'Şeker eklemeyin; tatlılığı olgun meyveden gelsin.', 'İnek sütü 1 yaştan sonra içecek olarak verilebilir; tam yağlı tercih edin.'], tips: ['Çilek alerjisi açısından ilk kez veriliyorsa gözlemleyin.'], storage: 'Hazırlandıktan hemen sonra tüketin.'),
  BabyRecipe(id: 'bei_04', title: 'Ev yapımı elma suyu (seyreltilmiş)', age: '12+', category: 'İçecek', ingredient: 'elma', vegetable: 'elma', ingredients: ['1 elma', '1 su bardağı içme suyu'], steps: ['Ellerinizi, kesme tahtasını ve kapları sıcak sabunlu suyla yıkayın.', 'Elmayı yıkayıp soyun, çekirdek evini çıkarıp doğrayın.', 'Elma ve suyu küçük tencerede kaynatın; kısık ateşte 10 dakika pişirin.', 'İnce süzgeçten süzüp soğutun.', 'Meyve suyu yerine bütün meyve tercih edin; meyve suyunu bardakta ve öğünle verin, günde 120 ml’yi geçmeyin.', 'Kalan elmayı ezip püre olarak kullanabilirsiniz.', 'Buzdolabında 1 gün saklayın.'], tips: ['Meyve suyu yerine bütün meyve tercih edilmeli; günlük miktarı sınırlı tutun.'], storage: 'Buzdolabında 48 saat.'),
  BabyRecipe(id: 'bei_05', title: 'Kayısı kompostosu (şekersiz)', age: '12+', category: 'İçecek', ingredient: 'kuru kayısı', vegetable: 'kayısı', ingredients: ['6 kuru kayısı (kükürtsüz)', '2 su bardağı içme suyu'], steps: ['Ellerinizi, kesme tahtasını ve kapları sıcak sabunlu suyla yıkayın.', 'Kükürtsüz (koyu renkli) kuru kayısıları yıkayın.', '2 saat içme suyunda bekletin.', 'Aynı suyla kaynatın; kısık ateşte 15 dakika pişirin.', 'Soğutun; kayısıları çocuğun çiğneyebileceği küçük parçalara doğrayın.', 'Suyuyla birlikte kaşıkla servis edin.', 'Şeker eklemeyin; tatlılığı olgun meyveden gelsin.', 'Buzdolabında 2 gün saklayın.'], tips: ['Kükürtsüz (koyu renkli) kayısı seçin.'], storage: 'Buzdolabında 48 saat.'),
  BabyRecipe(id: 'bei_06', title: 'Yulaf sütü (ev yapımı, 12+ ay)', age: '12+', category: 'İçecek', ingredient: 'yulaf', vegetable: 'yulaf', ingredients: ['Yarım su bardağı yulaf', '3 su bardağı soğuk içme suyu'], steps: ['Ellerinizi, kesme tahtasını ve kapları sıcak sabunlu suyla yıkayın.', 'Yulafı 15 dakika suda bekletip süzün; ıslatma suyunu dökün.', 'Yulafı 3 su bardağı soğuk içme suyuyla blenderda en fazla 30 saniye çekin; uzun çekmek kıvamı sümüksü yapar.', 'Tülbent ya da çok ince süzgeçten süzün.', 'Cam şişede buzdolabında 3 gün saklayın; kullanmadan önce çalkalayın.', 'Yulaf sütü inek sütünün yerine geçmez; protein ve kalsiyumu düşüktür, ana içecek yapmayın.'], tips: ['Bitkisel sütler inek sütünün yerini tutmaz; ana içecek olarak verilmemeli.'], storage: 'Buzdolabında 48 saat.'),
  BabyRecipe(id: 'bei_07', title: 'Ihlamur (çocuk, şekersiz)', age: '24+', category: 'İçecek', ingredient: 'ıhlamur', vegetable: 'ıhlamur', ingredients: ['1 tatlı kaşığı ıhlamur', '1 su bardağı su'], steps: ['Ellerinizi, kesme tahtasını ve kapları sıcak sabunlu suyla yıkayın.', 'Suyu kaynatın.', 'Ihlamuru ekleyip ocağı kapatın; kapağı kapalı 5 dakika demleyin.', 'İnce süzgeçten süzün.', 'Ilıtıp en fazla yarım çay bardağı verin.', 'Şeker ya da bal eklemeyin.', 'Bitki çaylarını çocuğa düzenli vermeden önce doktorunuza danışın; su ve sütün yerine geçmez.'], tips: ['Bitki çaylarını küçük çocuklara sık ve fazla vermeyin; ilaç kullanıyorsa doktora danışın.'], storage: 'Hazırlandıktan hemen sonra tüketin.'),
  BabyRecipe(id: 'bef_01', title: 'Tuzsuz menemen (çocuk)', age: '12+', category: 'Yumurta', ingredient: 'yumurta', vegetable: 'domates', ingredients: ['1 yumurta', '1 domates (kabuksuz)', 'Çeyrek yeşil biber', '1 çay kaşığı tereyağı'], steps: ['Ellerinizi, kesme tahtasını ve kapları sıcak sabunlu suyla yıkayın.', 'Domatesin kabuğunu soyup rendeleyin; biberin çekirdeklerini çıkarıp çok ince doğrayın.', 'Tereyağını tavada kısık ateşte eritip biberi 3 dakika yumuşatın.', 'Domatesi ekleyip suyunu biraz çekene kadar 5 dakika pişirin.', 'Yumurtayı kırıp karıştırarak pişirin.', 'Yumurtayı akı ve sarısı tamamen katılaşana kadar pişirin; akışkan bırakmayın.', 'Ilıtıp yumuşak ekmekle servis edin.', 'Tuz eklemeyin; 1–3 yaş için günlük tuz 2 g’ı geçmemeli, peynir ve salça zaten tuz içerir.'], tips: ['Yumurta tamamen pişmeli; tuz eklemeyin.'], storage: 'Hazırlandıktan hemen sonra tüketin.'),
  BabyRecipe(id: 'bef_02', title: 'Kabaklı domatesli bulgur pilavı (çocuk)', age: '12+', category: 'Tahıl', ingredient: 'bulgur', vegetable: 'domates', ingredients: ['Yarım su bardağı pilavlık bulgur', '1 domates', 'Yarım kabak', '1 çay kaşığı tereyağı', '1 su bardağı su'], steps: ['Ellerinizi, kesme tahtasını ve kapları sıcak sabunlu suyla yıkayın.', 'Bulguru yıkayıp süzün; kabağı küçük doğrayın.', 'Domatesin kabuğunu soyup rendeleyin.', 'Tereyağını tencerede eritip kabağı 2 dakika çevirin.', 'Domatesi ekleyip 2 dakika pişirin.', 'Bulgur ve suyu ekleyin; kaynayınca kısık ateşte kapağı kapalı 12–15 dakika suyunu çekene kadar pişirin.', 'Ocağı kapatıp 10 dakika demlendirin.', 'Tuz eklemeyin; 1–3 yaş için günlük tuz 2 g’ı geçmemeli, peynir ve salça zaten tuz içerir.', 'Ilıtıp sıcaklığı bileğinizin iç kısmına damlatarak kontrol edin; ılık olmalı, sıcak değil.', 'Kalanını kapalı kapta buzdolabında 2 gün saklayın; yalnızca bir kez ısıtın.'], tips: ['Tuz eklemeden aileye ayrıca tuzlanabilir.'], storage: 'Buzdolabında 48 saat.'),
  BabyRecipe(id: 'bef_03', title: 'Fırında tavuk ve sebze (çocuk)', age: '12+', category: 'Et', ingredient: 'tavuk', vegetable: 'patates', ingredients: ['1 tavuk but (kemiksiz)', '1 patates', '1 havuç', '1 tatlı kaşığı zeytinyağı', '1 çay kaşığı kekik'], steps: ['Ellerinizi, kesme tahtasını ve kapları sıcak sabunlu suyla yıkayın.', 'Fırını 190°C’ye ısıtın.', 'Tavuğu ayrı tahtada küçük doğrayın; ardından tahtayı ve ellerinizi yıkayın.', 'Patates ve havucu soyup tavuktan küçük küpler halinde doğrayın.', 'Hepsini zeytinyağı ve kekikle harmanlayıp fırın kabına alın.', 'Kabın üzerini folyoyla kapatıp 35 dakika pişirin; folyoyu açıp 5 dakika daha pişirin.', 'Tavuk iç sıcaklığı 74°C olmalı; en büyük parçayı ortadan bölün: içi pembe kalmamalı, suyu berrak akmalı.', 'Havuç parmakla ezilecek kadar yumuşak olmalı.', 'Ilıtıp sıcaklığı bileğinizin iç kısmına damlatarak kontrol edin; ılık olmalı, sıcak değil.', 'Kalanını kapalı kapta buzdolabında 2 gün saklayın; yalnızca bir kez ısıtın.'], tips: ['Kapalı pişirmek etin yumuşak kalmasını sağlar.'], storage: 'Buzdolabında 48 saat.'),
  BabyRecipe(id: 'bef_04', title: 'Mini sebzeli pizza (çocuk)', age: '18+', category: 'Fırın', ingredient: 'tam buğday lavaş', vegetable: 'domates', ingredients: ['1 tam buğday lavaş', '2 yemek kaşığı rendelenmiş domates', '2 yemek kaşığı rendelenmiş kaşar', '1 yemek kaşığı ince doğranmış biber ve mantar'], steps: ['Ellerinizi, kesme tahtasını ve kapları sıcak sabunlu suyla yıkayın.', 'Fırını 200°C’ye ısıtın; tepsiye yağlı kâğıt serin.', 'Lavaşı bir bardak yardımıyla yuvarlak kesin.', 'Biber ve mantarı çok ince doğrayın; mantarı tavada 2 dakika suyunu çekene kadar pişirin.', 'Lavaşlara rendelenmiş domates sürün; sebze ve kaşarı serpin.', '8 dakika, kaşar eriyene kadar pişirin.', 'Ilıtıp çocuğun tutabileceği dilimlere kesin.', 'Kaşar ve lor pastörize sütten olmalı; tuzlu peyniri 1 saat suda bekletip tuzunu alın.'], tips: ['Sucuk ve salam gibi işlenmiş etleri eklemeyin.'], storage: 'Hazırlandıktan hemen sonra tüketin.'),
  BabyRecipe(id: 'bef_05', title: 'Ev yapımı tam buğday krakeri', age: '18+', category: 'Fırın', ingredient: 'tam buğday unu', vegetable: 'susam', ingredients: ['1 su bardağı tam buğday unu', '2 yemek kaşığı zeytinyağı', '4 yemek kaşığı su', '1 tatlı kaşığı susam'], steps: ['Ellerinizi, kesme tahtasını ve kapları sıcak sabunlu suyla yıkayın.', 'Fırını 180°C’ye ısıtın; tepsiye yağlı kâğıt serin.', 'Un, zeytinyağı ve suyu yoğurup pürüzsüz bir hamur yapın; 10 dakika dinlendirin.', 'Hamuru yağlı kâğıdın üzerinde 2–3 mm inceliğinde açın; susamı serpip merdaneyle bastırın.', 'Küçük kareler kesip her birini çatalla delin; kabarmaz.', '15 dakika, kenarları hafif kızarana kadar pişirin.', 'Tepside tamamen soğutun; soğudukça çıtırlaşır.', 'Susam alerjisi açısından ilk kez veriyorsanız az miktarla başlayıp gözlemleyin.', 'Kapalı kavanozda 5 gün saklayın.'], tips: ['Tuzsuz krakerler atıştırmalık için uygundur.'], storage: 'Buzdolabında kapalı kapta 3 gün.'),
  // Ayrıntılı bebek tarifleri (13. tur).
  BabyRecipe(id: 'bd13_01', title: 'Avokadolu muz püresi', age: '6+', category: 'Meyve', ingredient: 'avokado', vegetable: 'muz', ingredients: ['Yarım olgun avokado', 'Yarım olgun muz', '1–2 yemek kaşığı anne sütü ya da bebeğin mamasıyla hazırlanmış süt'], steps: ['Ellerinizi ve kullanacağınız kapları iyice yıkayın.', 'Avokadoyu ikiye kesip çekirdeğini çıkarın, yarısının içini kaşıkla alın.', 'Muzu soyup avokadoyla birlikte çatalla pürüzsüz olana kadar ezin.', 'Anne sütü ya da mamayla kıvamı bebeğin kaşıktan alabileceği yumuşaklığa getirin.', 'Hemen servis edin; avokado bekledikçe kararır.'], variants: ['armut', 'şeftali'], tips: ['Avokado sağlıklı yağlar içerir; ilk denemelerde tek başına da verilebilir.', 'Şeker, bal veya tuz eklemeyin.'], storage: 'Bekletmeden tüketin; kalanı saklamayın.'),
  BabyRecipe(id: 'bd13_02', title: 'Balkabaklı mercimek çorbası', age: '8+', category: 'Çorba', ingredient: 'mercimek', vegetable: 'balkabağı', ingredients: ['2 yemek kaşığı kırmızı mercimek', '1 dilim balkabağı (yaklaşık 80 g)', '1 küçük havuç', '1 çay kaşığı zeytinyağı', '1,5 su bardağı içme suyu'], steps: ['Mercimeği birkaç kez yıkayın; balkabağını ve havucu soyup küçük küp doğrayın.', 'Tüm malzemeleri suyla tencereye alıp kaynatın; köpüğünü alın.', 'Kısık ateşte mercimek dağılana ve sebzeler yumuşayana kadar 20–25 dakika pişirin.', 'Blenderdan geçirip kıvamı kaşıktan akacak yoğunlukta ayarlayın.', 'Zeytinyağını ekleyip ılıtın; sıcaklığı bileğinizin iç kısmında kontrol edin.'], variants: ['havuç', 'kabak', 'patates'], tips: ['Mercimek demir ve protein kaynağıdır; yanında C vitamini içeren bir meyve emilimi artırır.', 'Tuz eklemeyin.'], storage: 'Buzdolabında 24 saat; buz kalıbında 1 ay dondurulabilir.'),
  BabyRecipe(id: 'bd13_03', title: 'Elmalı yulaf lapası (bebek)', age: '6+', category: 'Tahıl', ingredient: 'yulaf', vegetable: 'elma', ingredients: ['3 yemek kaşığı ince yulaf ezmesi', '1 küçük elma', 'Yarım su bardağı içme suyu', '3–4 yemek kaşığı anne sütü ya da mama'], steps: ['Elmayı soyup çekirdek evini çıkarın ve ince rendeleyin.', 'Yulaf, elma ve suyu küçük bir tencereye alın.', 'Kısık ateşte sürekli karıştırarak 5–6 dakika, yulaf yumuşayana kadar pişirin.', 'Ocaktan alıp anne sütü ya da mamayı ekleyerek kıvamı ayarlayın.', 'İlk aylarda blenderdan geçirerek pürüzsüz verin; sonra çatalla ezmek yeterlidir.'], variants: ['armut', 'muz', 'şeftali'], tips: ['Yulaf glüten içerebilir; ilk kez verirken 3 gün başka yeni besin eklemeyin.', 'Şeker eklemeyin; elma tatlandırır.'], storage: 'Taze tüketin; kalanı buzdolabında 24 saat saklayın.'),
  BabyRecipe(id: 'bd13_04', title: 'Brokolili patates püresi', age: '6+', category: 'Sebze', ingredient: 'patates', vegetable: 'brokoli', ingredients: ['1 küçük patates', '4–5 brokoli çiçeği', '1 çay kaşığı zeytinyağı', 'Haşlama suyundan 2–4 yemek kaşığı'], steps: ['Patatesi soyup küp doğrayın; brokoliyi yıkayıp küçük çiçeklere ayırın.', 'Patatesi buharda 10 dakika pişirin, brokoliyi ekleyip 5–6 dakika daha pişirin.', 'Sebzeler çatalla kolayca eziliyorsa buharın suyunu ayırın.', 'Blender ya da çatalla ezin; haşlama suyunu kaşık kaşık ekleyerek kıvamı ayarlayın.', 'Zeytinyağını karıştırıp ılık servis edin.'], variants: ['karnabahar', 'kabak', 'bezelye'], tips: ['Buharda pişirmek vitamin kaybını azaltır.', 'Bebek büyüdükçe ezme kıvamını kademeli olarak iri bırakın.'], storage: 'Buzdolabında 24 saat; buz kalıbında 1 ay dondurulabilir.'),
  BabyRecipe(id: 'bd13_05', title: 'Armutlu kinoa lapası', age: '8+', category: 'Tahıl', ingredient: 'kinoa', vegetable: 'armut', ingredients: ['2 yemek kaşığı kinoa', '1 olgun armut', '1 su bardağı içme suyu', 'Yarım çay kaşığı tarçın (isteğe bağlı)'], steps: ['Kinoayı ince süzgeçte bol suyla iyice yıkayın; acı tadı giderir.', 'Kinoayı suyla kaynatıp kısık ateşte 15 dakika yumuşayana kadar pişirin.', 'Armudu soyup küçük doğrayın ve son 5 dakika tencereye ekleyin.', 'Blenderdan geçirip kıvamı kaynamış suyla ayarlayın.', 'İsterseniz bir tutam tarçın ekleyip ılık servis edin.'], variants: ['elma', 'muz', 'şeftali'], tips: ['Kinoa glütensizdir ve protein içerir.', 'Yeni besinleri birer birer tanıtın.'], storage: 'Buzdolabında 24 saat saklanır.'),
  BabyRecipe(id: 'bd13_06', title: 'Tavuklu kabaklı pirinç lapası', age: '8+', category: 'Et', ingredient: 'tavuk', vegetable: 'kabak', ingredients: ['50 g derisiz tavuk göğsü', '1 yemek kaşığı pirinç', '1 küçük kabak', '1 küçük havuç', '1,5 su bardağı içme suyu', '1 çay kaşığı zeytinyağı'], steps: ['Tavuğu küçük parçalara, kabak ve havucu küp doğrayın; pirinci yıkayın.', 'Tavuk ve suyu tencereye alıp kaynatın, köpüğünü alın.', 'Pirinç ve havucu ekleyip kısık ateşte 15 dakika pişirin.', 'Kabağı ekleyin ve tavuk tamamen pişip pirinç dağılana kadar 10 dakika daha pişirin.', 'Bebeğin yaşına göre blenderdan geçirin ya da çatalla ezin; zeytinyağını ekleyin.'], variants: ['patates', 'balkabağı', 'brokoli'], tips: ['Tavuğun içinde pembe kısım kalmamalıdır.', 'Tuz ve et suyu tableti kullanmayın.'], storage: 'Buzdolabında 24 saat; buz kalıbında 1 ay dondurulabilir.'),
  BabyRecipe(id: 'bd13_07', title: 'Fırında havuç ve kabak çubukları', age: '8+', category: 'Sebze', ingredient: 'havuç', vegetable: 'kabak', ingredients: ['1 havuç', '1 kabak', '1 tatlı kaşığı zeytinyağı', '1 tutam kimyon (isteğe bağlı)'], steps: ['Fırını 190°C’ye ısıtın, tepsiye pişirme kâğıdı serin.', 'Havuç ve kabağı soyup bebeğin avucuna sığacak, parmak kalınlığında çubuklar hâlinde kesin.', 'Zeytinyağı ve isteğe bağlı kimyonla harmanlayın.', 'Tepsiye aralıklı dizin ve 20–25 dakika, parmaklarınızla kolayca ezilecek kadar yumuşayana kadar pişirin.', 'Ilıyınca bebeğin kendi kendine tutup yemesi için servis edin.'], variants: ['tatlı patates', 'patates', 'balkabağı'], tips: ['Parmak besinlerin, baş ve işaret parmağı arasında kolayca ezilecek kadar yumuşak olması gerekir.', 'Yemek sırasında bebeğinizi her zaman dik oturtun ve yanında olun.'], storage: 'Buzdolabında 24 saat saklanır.'),
  BabyRecipe(id: 'bd13_08', title: 'Yumurtalı sebze omleti (bebek)', age: '9+', category: 'Yumurta', ingredient: 'yumurta', vegetable: 'ıspanak', ingredients: ['1 yumurta', '1 yemek kaşığı ince kıyılmış ıspanak', '1 yemek kaşığı rendelenmiş kabak', '1 yemek kaşığı anne sütü ya da su', '1 çay kaşığı tereyağı'], steps: ['Kabağın fazla suyunu sıkın.', 'Yumurtayı süt ya da suyla çırpıp ıspanak ve kabağı ekleyin.', 'Küçük yapışmaz tavada tereyağını kısık ateşte eritip karışımı dökün.', 'Kapağı kapalı olarak her iki yüzü toplam 5–6 dakika, yumurta tamamen pişene kadar pişirin.', 'Ilıyınca parmak kalınlığında şeritler hâlinde kesip servis edin.'], variants: ['kabak', 'havuç', 'brokoli'], tips: ['Bebeklerde yumurta tamamen pişmiş olmalıdır; akışkan kısım kalmamalıdır.', 'Yumurta alerjen besindir; ilk kez sabah verip sonraki saatleri gözlemleyin.'], storage: 'Taze tüketin.'),
  BabyRecipe(id: 'bd13_09', title: 'Somonlu patates köftesi', age: '10+', category: 'Balık', ingredient: 'somon', vegetable: 'patates', ingredients: ['80 g kılçıksız somon', '1 orta boy patates', '1 yemek kaşığı ince kıyılmış dereotu', '1 yumurta sarısı', '1 tatlı kaşığı zeytinyağı'], steps: ['Fırını 190°C’ye ısıtın.', 'Patatesi haşlayıp ezin.', 'Somonu buharda 10–12 dakika tamamen pişirin; elinizle kontrol ederek kılçık kalmadığından emin olun.', 'Somonu didikleyip patates, dereotu ve yumurta sarısıyla karıştırın.', 'Küçük, yassı köfteler yapıp yağlı kâğıt serili tepsiye dizin; üzerlerine zeytinyağı sürün.', 'Fırında 15 dakika, hafifçe kızarana kadar pişirin.'], variants: ['tatlı patates', 'kabak', 'havuç'], tips: ['Balıkta kılçık kontrolünü mutlaka elle yapın.', 'Haftada 1–2 kez yağlı balık önerilir.'], storage: 'Buzdolabında 24 saat; pişmiş köfteler 1 ay dondurulabilir.'),
  BabyRecipe(id: 'bd13_10', title: 'Ispanaklı lor topları', age: '10+', category: 'Süt ürünü', ingredient: 'lor', vegetable: 'ıspanak', ingredients: ['3 yemek kaşığı tuzsuz lor peyniri', '2 yemek kaşığı haşlanıp ince kıyılmış ıspanak', '2 yemek kaşığı ince yulaf ezmesi', '1 yumurta sarısı'], steps: ['Fırını 180°C’ye ısıtın, tepsiye pişirme kâğıdı serin.', 'Ispanağın suyunu iyice sıkın.', 'Lor, ıspanak, yulaf ve yumurta sarısını yoğurun.', 'Ceviz büyüklüğünde toplar yapıp tepsiye dizin.', 'Fırında 12–15 dakika, içi tamamen pişene kadar pişirin.', 'Ilıyınca ikiye bölerek servis edin.'], variants: ['kabak', 'havuç', 'brokoli'], tips: ['Tuzsuz lor tercih edin; bebek peynirleri genellikle tuzludur.', 'Ispanağı haftada 1–2 kezle sınırlayın.'], storage: 'Buzdolabında 24 saat saklanır.'),
  BabyRecipe(id: 'bd13_11', title: 'Muzlu yulaflı mini pankek', age: '9+', category: 'Kahvaltı', ingredient: 'muz', vegetable: 'muz', ingredients: ['1 olgun muz', '1 yumurta', '3 yemek kaşığı ince yulaf ezmesi', '1 tutam tarçın', '1 çay kaşığı tereyağı'], steps: ['Muzu çatalla pürüzsüz olana kadar ezin.', 'Yumurta, yulaf ve tarçını ekleyip karıştırın; 5 dakika bekletin.', 'Yapışmaz tavayı kısık ateşte ısıtıp tereyağıyla hafifçe yağlayın.', 'Tavaya tatlı kaşığıyla küçük porsiyonlar dökün.', 'Her yüzünü 2–3 dakika, içi tamamen pişene kadar pişirin.', 'Ilıyınca bebeğin tutabileceği büyüklükte servis edin.'], variants: ['elma', 'armut', 'balkabağı'], tips: ['Şeker ve bal eklemeyin.', 'Yumurtanın tamamen pişmesi için ateşi kısık tutun.'], storage: 'Buzdolabında 24 saat; pankekler 1 ay dondurulabilir.'),
  BabyRecipe(id: 'bd13_12', title: 'Mercimekli havuç köftesi', age: '10+', category: 'Baklagil', ingredient: 'mercimek', vegetable: 'havuç', ingredients: ['3 yemek kaşığı kırmızı mercimek', '2 yemek kaşığı ince bulgur', '1 küçük havuç', '1 çay kaşığı zeytinyağı', '1 su bardağı içme suyu', '1 tutam kimyon'], steps: ['Mercimeği yıkayıp rendelenmiş havuçla birlikte suda 15 dakika, dağılana kadar pişirin.', 'Ocaktan alıp bulguru ekleyin, kapağı kapalı 15 dakika bekletin.', 'Zeytinyağı ve kimyonu ekleyip yoğurun.', 'Bebeğin avucuna sığacak küçük köfteler yapın.', 'Ilık servis edin.'], variants: ['kabak', 'balkabağı', 'ıspanak'], tips: ['Tuz ve salça eklemeyin.', 'Bulgur glüten içerir.'], storage: 'Buzdolabında 2 gün saklanır.'),
  BabyRecipe(id: 'bd13_13', title: 'Yoğurtlu meyve kasesi', age: '8+', category: 'Yoğurt', ingredient: 'yoğurt', vegetable: 'muz', ingredients: ['4 yemek kaşığı tam yağlı sade yoğurt', 'Yarım muz', '2 çilek', '1 tatlı kaşığı ince yulaf ezmesi'], steps: ['Ellerinizi, kesme tahtasını ve kapları sıcak sabunlu suyla yıkayın.', 'Meyveleri bol suda yıkayın.', 'Muzu ezin; çilekleri çok küçük doğrayın ya da ezin.', 'Yoğurdu buzdolabından 10 dakika önce çıkarın; çok soğuk vermeyin.', 'Yoğurdu kaseye alın.', 'Meyveleri ve yulafı ekleyip karıştırın.', 'Çilek bazı bebeklerde ağız çevresinde kızarıklık yapabilir; ilk kez veriyorsanız gözlemleyin.', 'Tuz, şeker ve bal eklemeyin; 1 yaş altı bebeklere uygun değildir.', 'Hemen servis edin; kalanını saklamayın.'], tips: ['Meyveli hazır yoğurt yerine sade yoğurt tercih edin; şeker içermez.', 'Çilek bazı bebeklerde kızarıklık yapabilir; ilk kez az miktarda verin.'], storage: 'Taze tüketin.'),
  BabyRecipe(id: 'bd13_14', title: 'Kabaklı bulgur pilavı (bebek)', age: '10+', category: 'Tahıl', ingredient: 'bulgur', vegetable: 'kabak', ingredients: ['2 yemek kaşığı ince pilavlık bulgur', '1 küçük kabak', '1 küçük domates', '1 çay kaşığı zeytinyağı', 'Yarım su bardağı sıcak su'], steps: ['Kabağı rendeleyin, domatesin kabuğunu soyup rendeleyin.', 'Zeytinyağında kabağı 2 dakika soteleyin, domatesi ekleyin.', 'Bulguru ve sıcak suyu ekleyip kısık ateşte 12–15 dakika suyunu çekene kadar pişirin.', 'Kapağı kapalı 10 dakika demlendirin.', 'Ilık servis edin; gerekirse çatalla biraz ezin.'], variants: ['havuç', 'bezelye', 'biber'], tips: ['Tuz eklemeyin.', 'Bulgur demir ve lif içerir.'], storage: 'Buzdolabında 24 saat saklanır.'),
  BabyRecipe(id: 'bd13_15', title: 'Nohutlu kabak humusu (bebek)', age: '10+', category: 'Baklagil', ingredient: 'nohut', vegetable: 'kabak', ingredients: ['3 yemek kaşığı iyice haşlanmış nohut', '1 küçük kabak', '1 çay kaşığı tahin', '1 çay kaşığı zeytinyağı', 'Birkaç damla limon suyu'], steps: ['Kabağı küp doğrayıp buharda 8 dakika yumuşatın.', 'Nohudu kabuklarını ayıklayarak kabakla birlikte blendera alın.', 'Tahin, zeytinyağı ve limon suyunu ekleyin.', 'Pürüzsüz olana kadar çekin; gerekirse kaynamış su ekleyin.', 'Kaşıkla ya da yumuşak buharda pişmiş sebze çubuklarına sürerek servis edin.'], variants: ['havuç', 'balkabağı', 'pancar'], tips: ['Tahin susam içerir; susam alerjen bir besindir.', 'Konserve nohut kullanacaksanız tuzunu iyice durulayın.'], storage: 'Buzdolabında 2 gün saklanır.'),
  BabyRecipe(id: 'bd13_16', title: 'Ev yapımı tam buğday grissini', age: '12+', category: 'Fırın', ingredient: 'un', vegetable: 'kabak', ingredients: ['1 su bardağı tam buğday unu', 'Yarım su bardağı un', 'Yarım çay kaşığı instant maya', '1 yemek kaşığı zeytinyağı', 'Yarım su bardağı ılık su'], steps: ['Unları, mayayı, zeytinyağını ve ılık suyu karıştırıp yumuşak bir hamur yoğurun.', 'Üzerini örtüp 30 dakika mayalandırın.', 'Fırını 190°C’ye ısıtın.', 'Hamuru 12 parçaya bölüp kalem kalınlığında çubuklar hâlinde yuvarlayın.', 'Pişirme kâğıdı serili tepsiye dizip 15–18 dakika, açık altın rengi olana kadar pişirin.', 'Tamamen soğutup servis edin.'], variants: ['havuç', 'ıspanak', 'balkabağı'], tips: ['Tuz eklenmemiştir; diş çıkaran çocuklar için uygundur ancak yerken yanında durun.', 'Hamura rendelenmiş havuç ya da ıspanak püresi ekleyebilirsiniz.'], storage: 'Kapalı kapta 3 gün saklanır.'),
  BabyRecipe(id: 'bd13_17', title: 'Hindili sebzeli mini köfte', age: '12+', category: 'Et', ingredient: 'hindi', vegetable: 'havuç', ingredients: ['150 g hindi kıyma', '1 küçük havuç', '1 küçük kabak', '2 yemek kaşığı ince yulaf ezmesi', '1 yumurta sarısı', '1 çay kaşığı kekik'], steps: ['Fırını 190°C’ye ısıtın, tepsiye pişirme kâğıdı serin.', 'Havuç ve kabağı ince rendeleyip suyunu sıkın.', 'Tüm malzemeleri 2–3 dakika yoğurun.', 'Fındıktan biraz büyük köfteler yapıp tepsiye dizin.', 'Fırında 15–18 dakika, köftelerin içi tamamen pişene kadar pişirin.', 'Ilıyınca ikiye bölerek kontrol edip servis edin.'], variants: ['kabak', 'ıspanak', 'patates'], tips: ['Kıymanın içinde pembe yer kalmamalıdır.', 'Tuz eklemeyin; kekik lezzet verir.'], storage: 'Buzdolabında 24 saat; pişmiş köfteler 1 ay dondurulabilir.'),
  BabyRecipe(id: 'bd13_18', title: 'Şeftalili yoğurt muhallebisi', age: '12+', category: 'Tatlı', ingredient: 'süt', vegetable: 'şeftali', ingredients: ['1 su bardağı süt', '1 yemek kaşığı pirinç unu', '1 olgun şeftali', '2 yemek kaşığı yoğurt'], steps: ['Şeftaliyi soyup çekirdeğini çıkarın ve püre hâline getirin.', 'Sütü ve pirinç ununu soğukken çırpın.', 'Orta ateşte sürekli karıştırarak koyulaşana kadar 6–7 dakika pişirin.', 'Ocaktan alıp ılıyınca şeftali püresini karıştırın.', 'Kaselere paylaştırıp üzerine yoğurt koyarak servis edin.'], variants: ['armut', 'elma', 'muz'], tips: ['İnek sütü 12 aydan önce ana içecek olarak verilmez; tarifte pişirerek kullanılır.', 'Şeker eklemeyin; meyve tatlandırır.'], storage: 'Buzdolabında 24 saat saklanır.'),
  BabyRecipe(id: 'bd13_19', title: 'Fırında sebzeli makarna (çocuk)', age: '18+', category: 'Makarna', ingredient: 'makarna', vegetable: 'brokoli', ingredients: ['100 g küçük makarna', '4–5 brokoli çiçeği', '1 küçük havuç', '1 su bardağı süt', '1 yemek kaşığı un', '1 yemek kaşığı tereyağı', '3 yemek kaşığı rendelenmiş tuzsuz peynir'], steps: ['Fırını 190°C’ye ısıtın.', 'Makarnayı tuzsuz suda paket süresince haşlayın; son 4 dakika küçük doğranmış brokoli ve havucu ekleyin, süzün.', 'Tereyağını eritip unu 1 dakika kavurun; sütü azar azar ekleyip koyulaşana kadar karıştırın.', 'Sosu makarna ve sebzelerle karıştırıp küçük bir fırın kabına alın.', 'Peyniri serpip 15 dakika, üstü kızarana kadar pişirin.', 'Ilıtıp servis edin.'], variants: ['kabak', 'bezelye', 'mısır'], tips: ['Sebzeleri küçük doğrayın; çocuklar seçip ayıramasın.', 'Tuz eklemeyin; peynirin tuzu yeterlidir.'], storage: 'Buzdolabında 2 gün saklanır.'),
  BabyRecipe(id: 'bd13_20', title: 'Elmalı havuçlu mini muffin', age: '12+', category: 'Fırın', ingredient: 'elma', vegetable: 'havuç', ingredients: ['1 küçük elma', '1 küçük havuç', '1 yumurta', '3 yemek kaşığı yoğurt', '2 yemek kaşığı zeytinyağı', '6 yemek kaşığı tam buğday unu', '1 çay kaşığı kabartma tozu', '1 tutam tarçın'], steps: ['Fırını 180°C’ye ısıtın, mini muffin kalıbını yağlayın.', 'Elma ve havucu ince rendeleyin.', 'Yumurta, yoğurt ve zeytinyağını çırpın; elma ve havucu ekleyin.', 'Un, kabartma tozu ve tarçını ekleyip birkaç kez karıştırın.', 'Kalıplara paylaştırıp 15–18 dakika, kürdan kuru çıkana kadar pişirin.', 'Tamamen soğutup servis edin.'], variants: ['armut', 'kabak', 'muz'], tips: ['Şeker içermez; tatlılık meyveden gelir.', 'Seyahat ve kreş çantası için pratiktir.'], storage: 'Kapalı kapta 2 gün; dondurucuda 1 ay saklanır.'),
